def _build_source_picker_menu(media_type='movie', canonical_id='', title='', season='', episode='', video_id='', resume_seconds='', preferred_provider_name='', source_provider_id='', source_mode=''):
    url = _source_picker_url(media_type=media_type, canonical_id=canonical_id, title=title, season=season, episode=episode, video_id=video_id, resume_seconds=resume_seconds, preferred_provider_name=preferred_provider_name, source_provider_id=source_provider_id, source_mode=source_mode)
    if not url:
        return []
    is_series_root = _is_series_media(media_type) and season in (None, '', 0, '0') and episode in (None, '', 0, '0')
    # v5.10.236: an episode's entry says what it does (Choose add-on read as
    # picking an add-on); it always opens the sources page (force_picker)
    label = tr('فتح المواسم') if is_series_root else tr('عرض الروابط')
    menu = [(label, 'Container.Update(%s)' % url)]
    if source_provider_id and not is_series_root:
        same_url = _source_picker_url(media_type=media_type, canonical_id=canonical_id, title=title, season=season, episode=episode, video_id=video_id, resume_seconds=resume_seconds, preferred_provider_name=preferred_provider_name, source_provider_id=source_provider_id, source_mode='only')
        if same_url:
            menu.append(('اختيار مصدر من نفس السورس فقط', 'Container.Update(%s)' % same_url))
        play_args = {
            'action': 'play_item',
            'media_type': 'series' if _is_series_media(media_type) else (media_type or 'movie'),
            'canonical_id': canonical_id,
            'title': title or canonical_id,
            'source_provider_id': source_provider_id,
            'source_mode': 'only',
        }
        if video_id:
            play_args['video_id'] = video_id
        if season not in (None, '', 0, '0'):
            play_args['season'] = str(season)
        if episode not in (None, '', 0, '0'):
            play_args['episode'] = str(episode)
        if resume_seconds not in (None, '', 0, '0'):
            play_args['resume_seconds'] = str(resume_seconds)
        menu.append(('تشغيل مباشر من نفس السورس', 'RunPlugin(%s)' % build_url(**play_args)))
    return menu


# ─── Cross-invocation dispatch de-dup ──────────────────────────────────
# Kodi spawns a fresh plugin process for every click. A fast double-click
# therefore launches two processes that both try to open the source picker
# / TMDb Helper / start playback — the user sees stacked modals or
# TMDb Helper opens twice in a row. SourcesWindow has its own action guard
# for clicks within the same process; this is the cross-process backstop.
# Stored on Window(WINDOW_ID) as 'key|timestamp'.
_DISPATCH_PROP = 'dexhub.dispatch.in_flight'


def _dispatch_in_flight(key, window_seconds=2.5):
    """Return True if another plugin invocation just claimed `key`.

    Stamps `key` with the current timestamp on a miss, so a second
    invocation within `window_seconds` is suppressed.

    v3.9.17: window dropped from 6s to 2.5s. The original 6-second clamp made
    legitimate retries (user picked the wrong source, backed out, clicked the
    same item again) silently fail. 2.5s is long enough to catch double-tap
    bouncing but short enough that a deliberate retry feels responsive.
    """
    if not key:
        return False
    now = time.time()
    try:
        win = xbmcgui.Window(WINDOW_ID)
        raw = win.getProperty(_DISPATCH_PROP) or ''
        if raw and '|' in raw:
            prev_key, prev_ts = raw.split('|', 1)
            try:
                prev_ts_f = float(prev_ts)
            except Exception:
                prev_ts_f = 0.0
            if prev_key == key and (now - prev_ts_f) < window_seconds:
                return True
        win.setProperty(_DISPATCH_PROP, '%s|%.3f' % (key, now))
    except Exception:
        return False
    return False



