def _mark_tmdbh_handoff(seconds=45):
    """Mark a TMDb Helper -> Dex Hub handoff across plugin invocations.

    TMDb Helper can immediately re-open its player route if Kodi receives a
    second click/resolve event while our source dialog is still active. A short
    scoped cooldown keeps every internal Dex Hub click on the Dex path until
    playback starts, cancel/no-source occurs, or the cooldown expires.
    """
    try:
        until = time.time() + max(8, int(seconds or 45))
        for win_id in (WINDOW_ID, 10000):  # v5.10.321: 12005 exists only in full screen (Kodi logged "Window id does not exist")
            try:
                xbmcgui.Window(win_id).setProperty(_TMDBH_HANDOFF_UNTIL_PROP, '%.3f' % until)
            except Exception:
                pass
    except Exception:
        pass


def _tmdbh_handoff_active():
    try:
        now = time.time()
        for win_id in (WINDOW_ID, 10000):  # v5.10.321: 12005 exists only in full screen (Kodi logged "Window id does not exist")
            try:
                win = xbmcgui.Window(win_id)
                if (win.getProperty('dexhub.invoked_by_tmdbh') or '').strip() == '1':
                    return True
                raw_until = win.getProperty(_TMDBH_HANDOFF_UNTIL_PROP) or ''
                if raw_until:
                    try:
                        if float(raw_until) > now:
                            return True
                    except Exception:
                        pass
            except Exception:
                continue
    except Exception:
        pass
    return False


def _clear_tmdbh_transient():
    """Clear TMDb Helper handoff flags/seeds after cancel/error/no-source paths."""
    for win_id in (WINDOW_ID, 10000):  # v5.10.321: 12005 exists only in full screen (Kodi logged "Window id does not exist")
        try:
            win = xbmcgui.Window(win_id)
        except Exception:
            continue
        for key in _TMDBH_TRANSIENT_PROPS:
            try:
                win.clearProperty(key)
            except Exception:
                pass


def _clear_source_transient_props(clear_global=False):
    """Clear source/window artwork that can leak from the previous item."""
    if clear_global:
        try:
            if _player_has_real_media():
                clear_global = False
        except Exception:
            clear_global = False
    for win_id in (WINDOW_ID, 10000):
        try:
            win = xbmcgui.Window(win_id)
        except Exception:
            continue
        for key in _SOURCE_TRANSIENT_PROPS:
            try:
                win.clearProperty(key)
            except Exception:
                pass
        if clear_global:
            for key in _GLOBAL_ART_TRANSIENT_PROPS:
                try:
                    win.clearProperty(key)
                except Exception:
                    pass


def _mark_interactive_busy():
    """Give source/search/playback work priority over account maintenance."""
    try:
        xbmcgui.Window(10000).setProperty('dexhub.interactive_busy', '%.3f' % time.time())
    except Exception:
        pass




def _source_art_identity_key(payload=None):
    """Best-effort identity for source/search artwork.

    Kodi/skins keep Window(10000) properties alive longer than the plugin
    invocation. Never reuse those properties unless they belong to the same
    title/id; otherwise the previous playback poster/clearlogo leaks into the
    next source picker or search page.
    """
    data = payload or {}
    try:
        media_type = str(data.get('media_type') or data.get('type') or '').strip().lower()
        canonical = str(data.get('canonical_id') or data.get('id') or '').strip()
        video_id = str(data.get('video_id') or '').strip()
        tmdb_id = str(data.get('tmdb_id') or '').strip()
        imdb_id = str(data.get('imdb_id') or '').strip()
        tvdb_id = str(data.get('tvdb_id') or '').strip()
        season = str(data.get('season') or '').strip()
        episode = str(data.get('episode') or '').strip()
        title = str(data.get('show_title') or data.get('originaltitle') or data.get('title') or data.get('name') or '').strip().lower()
        return '|'.join([media_type, canonical, video_id, tmdb_id, imdb_id, tvdb_id, season, episode, title])
    except Exception:
        return ''


def _home_source_props_match(meta, home=None):
    try:
        home = home or xbmcgui.Window(10000)
        current = home.getProperty('dexhub.source.key') or ''
    except Exception:
        return False
    wanted = _source_art_identity_key(meta)
    return bool(current and wanted and current == wanted)

def play_item(media_type='', canonical_id='', title='', video_id='', season='', episode='', resume_seconds='0', resume_percent='', preferred_provider_name='', tmdb_id='', imdb_id='', tvdb_id='', source_provider_id='', source_mode='', ui_poster='', ui_fanart='', ui_clearlogo='', ui_seed_key=''):
    media_type = str(media_type or 'movie').strip().lower()
    _dispatch_key = 'play_item|%s|%s|%s|%s|%s' % (
        media_type, canonical_id or '', video_id or '',
        str(season or ''), str(episode or ''),
    )
    if _dispatch_in_flight(_dispatch_key):
        # v3.9.17: surface a brief toast so the user knows the click registered.
        # Before, a duplicate dispatch returned silently and looked like a
        # broken UI ("I press OK and nothing happens").
        try:
            xbmc.log('[DexHub] play_item: duplicate dispatch suppressed (%s)' % _dispatch_key, xbmc.LOGINFO)
            xbmcgui.Dialog().notification(
                'Dex Hub',
                tr('جاري التحميل…'),
                xbmcgui.NOTIFICATION_INFO, 1500, sound=False
            )
        except Exception:
            pass
        return
    if not _quick_same_source_enabled(source_provider_id, preferred_provider_name) and _maybe_redirect_default_player(media_type=media_type, canonical_id=canonical_id, title=title or canonical_id, season=season, episode=episode, tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id):
        return
    return _dispatch_dexhub_play(
        media_type=media_type,
        canonical_id=canonical_id,
        title=title or canonical_id,
        video_id=video_id,
        season=season,
        episode=episode,
        resume_seconds=resume_seconds,
        resume_percent=resume_percent,
        preferred_provider_name=preferred_provider_name,
        tmdb_id=tmdb_id,
        imdb_id=imdb_id,
        tvdb_id=tvdb_id,
        source_provider_id=source_provider_id,
        source_mode=source_mode,
        ui_seed=_ui_seed_from_route(ui_poster=ui_poster, ui_fanart=ui_fanart, ui_clearlogo=ui_clearlogo, ui_seed_key=ui_seed_key),
    )


def _remember_source_choice(ctx):
    if not _get_bool_setting('remember_last_source', False):
        return
    if not isinstance(ctx, dict):
        return
    scope = _source_scope_key(ctx.get('media_type'), ctx.get('canonical_id'), ctx.get('video_id'))
    if not scope.strip('|'):
        return
    payload = {
        'provider_name': str(ctx.get('provider_name') or '').strip(),
        'provider_id': str(ctx.get('provider_id') or '').strip(),
        'stream_url_host': (urlparse(str(ctx.get('stream_url') or '')).netloc or '').lower(),
        'saved_at': int(time.time()),
    }
    data = _load_source_pref_map()
    data[scope] = payload
    items = sorted(data.items(), key=lambda kv: int(((kv[1] or {}).get('saved_at') or 0)), reverse=True)[:600]
    _save_source_pref_map(dict(items))


def _last_source_choice(media_type='', canonical_id='', video_id=''):
    if not _get_bool_setting('remember_last_source', False):
        return {}
    return _load_source_pref_map().get(_source_scope_key(media_type, canonical_id, video_id), {}) or {}


def _invalidate_nextup_cache():
    try:
        _nextup_invalidate_cache(xbmcgui.Window(WINDOW_ID))
    except Exception:
        pass


# v3.9.44: page size memoization removed. The performance gain was
# marginal because Kodi caches recent settings reads internally; the
# memoization introduced module-level mutable state across threads that
# could not be ruled out as a source of the v3.9.43 home-button issue,
# so the conservative move is to revert to the original stateless form.
_SEARCH_RESULT_CACHE = {}
_SEARCH_RESULT_CACHE_ORDER = []
_SEARCH_RESULT_CACHE_MAX = 32
_SEARCH_RESULT_TTL = 600
# reuselanguageinvoker=true keeps this module resident across invocations and
# background daemon threads (prefetch, SWR, stream-session refresh) read/write
# these caches concurrently. Without a lock, a mutating dict can be iterated by
# another thread ("dict changed size during iteration") or lose entries.
_SEARCH_RESULT_CACHE_LOCK = threading.Lock()



def _search_cache_get(key):
    with _SEARCH_RESULT_CACHE_LOCK:
        entry = _SEARCH_RESULT_CACHE.get(key)
        if not entry:
            return None
        expires_at, value = entry
        if expires_at < time.time():
            _SEARCH_RESULT_CACHE.pop(key, None)
            try:
                _SEARCH_RESULT_CACHE_ORDER.remove(key)
            except ValueError:
                pass
            return None
        return value


def _search_cache_put(key, value):
    with _SEARCH_RESULT_CACHE_LOCK:
        _SEARCH_RESULT_CACHE[key] = (time.time() + _SEARCH_RESULT_TTL, value)
        if key not in _SEARCH_RESULT_CACHE_ORDER:
            _SEARCH_RESULT_CACHE_ORDER.append(key)
        while len(_SEARCH_RESULT_CACHE_ORDER) > _SEARCH_RESULT_CACHE_MAX:
            old = _SEARCH_RESULT_CACHE_ORDER.pop(0)
            _SEARCH_RESULT_CACHE.pop(old, None)


def _playback_provider_signature(ctx=None):
    ctx = ctx or {}
    bits = []
    for key in ('server_type', 'provider_id', 'provider_name', 'provider_base_url', 'stream_url'):
        value = str((ctx or {}).get(key) or '').strip().lower()
        if value:
            bits.append(value)
    return ' '.join(bits)


def _is_plex_like_playback(ctx=None):
    sig = _playback_provider_signature(ctx)
    if not sig:
        return False
    return any(marker in sig for marker in ('plex', 'plexio', 'emby', 'jellyfin',
                                            'silo', 'streambridge', 'dexbridge'))


def _is_cancellable_plex_selector(ctx=None, stream_url=''):
    """True for PlexBridge/Plexio plugin URLs that open a second picker.

    Kodi treats cancelling a plugin URL that was handed to Player.play as a
    failed media resolve and shows a scary playback-error dialog.  The bridge
    did not fail in that case; the user simply backed out of its nested list.
    """
    sig = '%s %s' % (_playback_provider_signature(ctx), str(stream_url or '').lower())
    return (str(stream_url or '').lower().startswith('plugin://') and
            any(marker in sig for marker in ('plexbridge', 'plexio')))


def _guard_cancellable_selector_failure(ctx, stream_url):
    """Close only the false Kodi error created after cancelling a nested picker.

    The guard arms only after a select dialog was actually observed, so normal
    playback failures and direct Plex/Emby errors remain visible and logged.
    """
    if not _is_cancellable_plex_selector(ctx, stream_url):
        return

    def _worker():
        saw_selector = False
        selector_closed_at = 0.0
        for _ in range(900):  # at most 90 seconds while the picker is open
            xbmc.sleep(100)
            try:
                player = xbmc.Player()
                if _player_has_real_media(player):
                    return
                active = bool(
                    xbmc.getCondVisibility('Window.IsActive(selectdialog)') or
                    xbmc.getCondVisibility('Dialog.IsActive(selectdialog)'))
                if active:
                    saw_selector = True
                    selector_closed_at = 0.0
                    continue
                if saw_selector and not selector_closed_at:
                    selector_closed_at = time.monotonic()
                if saw_selector and selector_closed_at and time.monotonic() - selector_closed_at >= 0.8:
                    if (xbmc.getCondVisibility('Window.IsActive(okdialog)') or
                            xbmc.getCondVisibility('Dialog.IsActive(okdialog)')):
                        xbmc.executebuiltin('Dialog.Close(okdialog,true)')
                        xbmc.log('[DexHub] suppressed false playback failure after Plex selector cancel',
                                 xbmc.LOGINFO)
                        return
                    # Give Kodi a short window to create the error dialog.
                    if time.monotonic() - selector_closed_at > 4.0:
                        return
            except Exception:
                return

    # This is optional error-dialog polish. Keep it in the shared bounded lane
    # so repeated selector opens cannot accumulate 90-second native threads.
    _submit_optional(
        _worker,
        key='selector-cancel:%s' % abs(hash(str(stream_url or ''))),
    )



def _force_remote_posters_enabled(value=''):
    return str(value or '').strip().lower() in ('1', 'true', 'yes', 'remote', 'tmdb', 'trakt')


def _force_remote_query(force_remote=False):
    return {'force_remote': '1'} if force_remote else {}


def _page_slice(rows, page='0'):
    try:
        page_num = max(0, int(page or 0))
    except Exception:
        page_num = 0
    size = _listing_page_size()
    start = page_num * size
    end = start + size
    total = len(rows or [])
    return page_num, size, (rows or [])[start:end], end < total


def _apply_unique_ids(item, ids, info=None):
    ids = ids or {}
    imdb_id = ids.get('imdb_id') or ''
    tmdb_id = ids.get('tmdb_id') or ''
    tvdb_id = ids.get('tvdb_id') or ''
    if info is not None and imdb_id and not info.get('imdbnumber'):
        info['imdbnumber'] = imdb_id
    try:
        if imdb_id:
            item.setProperty('imdb_id', imdb_id)
            item.setProperty('IMDBNumber', imdb_id)
        if tmdb_id:
            item.setProperty('tmdb_id', tmdb_id)
        if tvdb_id:
            item.setProperty('tvdb_id', tvdb_id)
        unique_ids = {}
        if imdb_id:
            unique_ids['imdb'] = imdb_id
        if tmdb_id:
            unique_ids['tmdb'] = tmdb_id
        if tvdb_id:
            unique_ids['tvdb'] = tvdb_id
        if unique_ids:
            # v3.9.71: prefer the modern InfoTag.setUniqueIDs on Kodi 20+;
            # the legacy ListItem.setUniqueIDs is removed in Kodi 22 and
            # appears to native-crash instead of raising on some alpha
            # builds — same root cause as the deprecated setInfo path.
            _applied_via_tag = False
            try:
                _km = _KODI_MAJOR
            except Exception:
                _km = 19
            if _km >= 20:
                try:
                    _tag = item.getVideoInfoTag()
                    _tag.setUniqueIDs(unique_ids, 'imdb' if imdb_id else ('tmdb' if tmdb_id else 'tvdb'))
                    _applied_via_tag = True
                except Exception:
                    _applied_via_tag = False
            if (not _applied_via_tag) and hasattr(item, 'setUniqueIDs'):
                item.setUniqueIDs(unique_ids, 'imdb' if imdb_id else ('tmdb' if tmdb_id else 'tvdb'))
    except Exception:
        pass


# Module-level buffer for the current plugin invocation. Each entry is
# (url, ListItem, isFolder). We flush via addDirectoryItems() in end_dir()
# to make ONE IPC call to Kodi instead of N separate addDirectoryItem calls
# — significantly faster for catalog pages with 30+ items.
_PENDING_ITEMS = []
_META_MEM = {}
_META_MEM_ORDER = []
_META_MEM_MAX = 384
# Written from background threads (catalog prefetch, art enrichment, search
# workers) as well as the foreground render path — guard all access.
_META_MEM_LOCK = threading.Lock()


def _meta_mem_key(media_type, canonical_id, source_provider_id=''):
    return '%s:%s:%s' % (media_type or '', canonical_id or '', _meta_cache_discriminator(source_provider_id))


def _meta_mem_get(media_type, canonical_id, source_provider_id=''):
    key = _meta_mem_key(media_type, canonical_id, source_provider_id)
    ttl = max(60, int(meta_ttl() or 3600))
    with _META_MEM_LOCK:
        row = _META_MEM.get(key)
        if not row:
            return None
        saved_at, payload = row
        if (time.time() - saved_at) > ttl:
            _META_MEM.pop(key, None)
            try:
                _META_MEM_ORDER.remove(key)
            except ValueError:
                pass
            return None
        return dict(payload or {})


def _meta_mem_put(media_type, canonical_id, payload, source_provider_id=''):
    if not payload:
        return
    key = _meta_mem_key(media_type, canonical_id, source_provider_id)
    with _META_MEM_LOCK:
        if key not in _META_MEM:
            _META_MEM_ORDER.append(key)
        _META_MEM[key] = (time.time(), dict(payload))
        while len(_META_MEM_ORDER) > _META_MEM_MAX:
            old = _META_MEM_ORDER.pop(0)
            _META_MEM.pop(old, None)


def _favorite_properties(is_favorite=None):
    # Skin quirk fix: some skins draw a heart overlay if the standard
    # IsFavorite/IsFavourite property EXISTS at all, even when its value is
    # 'false'. Only publish the standard properties for real favorites.
    if not bool(is_favorite):
        return {}
    return {
        'IsFavorite': 'true',
        'IsFavourite': 'true',
        'DexHub.IsFavorite': 'true',
        'DexHub.IsFavourite': 'true',
    }





def _art_value_looks_rating_proxy(value):
    text = str(value or '').lower()
    return any(token in text for token in (
        'easyratingsdb.com', 'easyratingsdb', 'erdb',
        'ratingposterdb.com', 'rating-poster', 'ratingposter', 'rpdb',
        'poster-ratings', 'ratings-poster',
        # v3.9.21: modern poster-decoration services
        'btttr.cc', 'betterposters',
        'top-streaming.stream', 'top-posters', 'topposters',
        'aiometadata', 'aioratings',
        'mdblist.com/poster',
    ))


def _art_value_looks_overlay_proxy(value):
    text = str(value or '').lower()
    return _art_value_looks_rating_proxy(text) or any(token in text for token in (
        'plexio', 'plexbridge', 'plex.dexworld', 'plexio.dexworld',
        'sb.dexworld', 'dexbridge',
        '/:/transcode', 'composite', 'overlay', 'photo/:/transcode',
        '/photo/', '/composite/',
        '/items/', '/emby/', '/jellyfin/',
    ))


def _normalize_kodi_item_art(art):
    """Mirror fragile overlay posters to the art keys Kodi skins commonly read.

    Important: do not mirror poster into fanart. ERDB/Plexio may provide a
    separate backdrop, and copying the vertical poster there changes the
    background. Only fill poster-like slots.
    """
    if not art:
        return art

    # Kodi callers historically pass either an art mapping or a single image
    # path.  The providers/accounts menus use media_path(...), which returns a
    # string.  Calling dict(string) raises ValueError and crashes the directory.
    # Normalize scalar paths to Kodi's standard art mapping first.
    if isinstance(art, (str, bytes)):
        value = art.decode('utf-8', 'replace') if isinstance(art, bytes) else art
        value = str(value or '').strip()
        if not value:
            return {}
        art = {
            'icon': value,
            'thumb': value,
            'poster': value,
        }
    elif not isinstance(art, dict):
        try:
            art = dict(art)
        except (TypeError, ValueError):
            value = str(art or '').strip()
            if not value:
                return {}
            art = {'icon': value, 'thumb': value, 'poster': value}

    out = dict(art)
    poster = out.get('poster') or out.get('tvshow.poster') or out.get('season.poster') or out.get('thumb') or out.get('icon')
    if poster:
        out.setdefault('poster', poster)
        out.setdefault('tvshow.poster', poster)
        out.setdefault('season.poster', poster)
        out.setdefault('thumbnail', poster)
        out.setdefault('cover', poster)
        out.setdefault('image', poster)
        out.setdefault('tvshow.thumb', poster)
        if _art_value_looks_overlay_proxy(poster):
            out['thumb'] = poster
            out['icon'] = poster
            out['thumbnail'] = poster
            out['cover'] = poster
            out['image'] = poster
            out['tvshow.thumb'] = poster
        else:
            out.setdefault('thumb', poster)
            out.setdefault('icon', poster)
    return out


# ─────────────────────────────────────────────────────────────────────
# v3.9.21: Poster overlay handling — reliability over decoration.
#
# Background:
#   Services like BetterPosters (btttr.cc), TOP Posters, RPDB, AIOratings,
#   etc. work by wrapping the original poster URL in a decoration proxy:
#       https://btttr.cc/poster/<encoded-original>?rating=8.5&badge=4k
#   The proxy fetches the source poster, draws badges (ratings, 4K/HDR
#   indicators, watched state), and returns the decorated image. Great
#   when the proxy is healthy. Catastrophic when it isn't:
#     - rate limits (free tiers cap at ~100 reqs/hour)
#     - slow response (Kodi's image loader gives up around 5s)
#     - 502/504 from proxy upstream
#     - SSL/redirect issues with some providers
#   The user sees an empty card with no poster.
#
# The fix:
#   Stremio's official CDN already hosts the *undecorated* source poster
#   for every IMDb-id'd title at a predictable URL:
#       https://images.metahub.space/poster/medium/<imdb_id>/img
#   This is what Cinemeta serves and what every decoration proxy is
#   ultimately wrapping. So when a poster URL is detected as decorated,
#   we can fall back to this direct CDN URL with no API call needed.
# ─────────────────────────────────────────────────────────────────────

_METAHUB_POSTER = 'https://images.metahub.space/poster/large/%s/img'
_METAHUB_BG     = 'https://images.metahub.space/background/large/%s/img'
_METAHUB_LOGO   = 'https://images.metahub.space/logo/medium/%s/img'


# ─────────────────────────────────────────────────────────────────────
# v3.9.23: proxy health probe with TTL cache.
#
# Why this is needed: many Kodi skins (Estuary, Confluence, and a chunk
# of community skins) DO NOT fall back from a failed `poster` URL to
# `thumb`. They render an empty card when the primary URL 404s or
# times out, regardless of what we put in the secondary slots. The v3.9.22
# strategy ("decorated on poster, clean on thumb") only worked for
# fallback-aware skins like Aura, Arctic Fuse, and Estuary MOD V2.
#
# To make the addon robust across every skin, we now do a tiny HEAD
# probe on the proxy domain the FIRST time we see it (1.5s budget),
# cache the result for 5 minutes, and decide on the user's behalf:
#   - probe succeeds → decorated URL on `poster` (badges render)
#   - probe fails    → clean metahub URL on `poster` (skin-agnostic)
#
# The cache is keyed by domain (not full URL) so an 80-item catalog from
# btttr.cc triggers at most one HEAD probe, not 80.
# ─────────────────────────────────────────────────────────────────────

_PROXY_HEALTH = {}                # domain → (is_healthy: bool, expires_at: float)
_PROXY_HEALTH_LOCK = threading.Lock()
_PROXY_HEALTH_TTL = 300.0         # 5 minutes — short enough to recover quickly
_PROXY_PROBE_TIMEOUT = 1.5        # 1.5s budget per probe; cheap


def _proxy_url_domain(url):
    try:
        return (urlparse(url).netloc or '').lower()
    except Exception:
        return ''


def _probe_proxy_health(url):
    """Single HEAD probe with a tight timeout. Returns True if the server
    answered with a non-error status; False on any failure."""
    try:
        from urllib.request import Request, urlopen
        req = Request(url, method='HEAD',
                      headers={'User-Agent': 'DexHub-poster-probe/1.0'})
        with urlopen(req, timeout=_PROXY_PROBE_TIMEOUT) as resp:
            code = getattr(resp, 'status', None) or resp.getcode()
            return 200 <= int(code) < 400
    except Exception:
        return False


def _is_proxy_healthy(url):
    """Decide if a poster proxy domain is currently usable.

    Looks the domain up in the TTL cache; on miss, probes once and
    caches the result. Subsequent items from the same domain pay zero
    probe cost.
    """
    domain = _proxy_url_domain(url)
    if not domain:
        return True
    now = time.time()
    with _PROXY_HEALTH_LOCK:
        cached = _PROXY_HEALTH.get(domain)
        if cached and now < cached[1]:
            return cached[0]
    # v3.9.154: mirror the verdict in a Window property so every warm
    # reuselanguageinvoker interpreter shares ONE probe per TTL instead of
    # each paying the 1.5s HEAD on its first catalog — badges show with the
    # results instead of after them.
    _prop_key = 'dexhub.proxyhealth.%s' % domain
    try:
        _raw = xbmcgui.Window(WINDOW_ID).getProperty(_prop_key) or ''
        if _raw:
            _verdict, _expiry = _raw.split('|', 1)
            if now < float(_expiry):
                _h = (_verdict == '1')
                with _PROXY_HEALTH_LOCK:
                    _PROXY_HEALTH[domain] = (_h, float(_expiry))
                return _h
    except Exception:
        pass
    healthy = _probe_proxy_health(url)
    _until = now + _PROXY_HEALTH_TTL
    with _PROXY_HEALTH_LOCK:
        _PROXY_HEALTH[domain] = (healthy, _until)
    try:
        xbmcgui.Window(WINDOW_ID).setProperty(_prop_key, '%s|%s' % ('1' if healthy else '0', _until))
    except Exception:
        pass
    xbmc.log(
        '[DexHub] poster-proxy %s probed: %s' %
        (domain, 'healthy' if healthy else 'UNREACHABLE — falling back to clean'),
        xbmc.LOGINFO,
    )
    return healthy


def _extract_imdb_id(meta):
    """Return the imdb id (tt1234567) for a meta dict, if derivable."""
    raw = meta or {}
    for key in ('imdb_id', 'imdb', 'id'):
        candidate = str(raw.get(key) or '').strip()
        if candidate.startswith('tt'):
            # For series episodes the id is "tt0123:season:episode" — strip
            # to the bare series id; the poster is the series poster anyway.
            return candidate.split(':')[0]
    return ''


def _clean_meta_art(meta):
    """Return a dict of clean (no-overlay) art URLs derived from metahub.space.

    Only fills slots where we can compute a reliable URL — the caller
    decides whether to use these as primary or fallback.
    """
    imdb = _extract_imdb_id(meta)
    if not imdb:
        return {}
    return {
        'poster':    _METAHUB_POSTER % imdb,
        'thumb':     _METAHUB_POSTER % imdb,
        'fanart':    _METAHUB_BG     % imdb,
        'landscape': _METAHUB_BG     % imdb,
        'clearlogo': _METAHUB_LOGO   % imdb,
    }


def _poster_reliability_mode():
    """Return the user's choice for handling decorated/overlay poster URLs.

    Values:
      'auto'      — default: detect decoration proxies and substitute
                    metahub.space clean URLs for any poster that looks
                    overlay-wrapped. Trades rating badges for reliability.
      'clean'     — force clean URLs everywhere, even when the proxy is
                    healthy. Disables all rating overlays.
      'decorated' — preserve current behavior; use whatever the catalog
                    provided, even if it's an overlay-decorated URL. Best
                    when the user really wants badges and accepts that
                    some posters won't load.
    """
    try:
        raw = (ADDON.getSetting('poster_reliability_mode') or 'Always clean (no badges)').strip()
    except Exception:
        raw = 'Smart fallback (recommended)'
    # Map the human-readable Kodi label to an internal mode constant.
    # Done with substring matches so future label rewording (e.g. minor
    # translation tweaks) doesn't break the routing.
    low = raw.lower()
    if ('clean' in low and 'no badges' in low) or 'نظيف' in low:
        return 'clean'
    if ('decorated' in low and 'keep' in low) or 'مزي' in low or 'مزخرف' in low:
        return 'decorated'
    return 'auto'


def _apply_poster_reliability(art, meta):
    """Final poster pass — decorated URL stays primary, clean URL goes in
    fallback slots only.

    The default mode is "Auto (badges + fallback)" — we keep the catalog's
    decorated URL on the `poster` key (so RPDB ratings, BetterPosters badges,
    4K/HDR pills all render when the proxy is healthy) and put a clean
    metahub.space URL on `thumb`/`icon`/`thumbnail`/`cover`/`image`. Most
    Kodi skins (Aura, Estuary MOD V2, Arctic Fuse, Estouchy) walk this
    fallback chain when the primary `poster` 404s or times out, so the
    user still sees a usable poster even if the proxy is down.

    Modes:
      'auto'      — decorated stays primary; clean fills thumb-family
                    slots as a safety net. (default)
      'clean'     — strip every decoration even when proxy works. No
                    badges anywhere. For users who explicitly don't want
                    ratings overlays.
      'decorated' — preserve current behavior exactly; no fallback. Badge
                    URLs are mirrored to every slot (matches v3.9.20 and
                    earlier). Use only if a skin has explicit issues with
                    differing poster/thumb URLs.
    """
    if not art:
        return art
    mode = _poster_reliability_mode()
    poster = (art.get('poster') or '').strip()
    if not poster:
        return art

    looks_decorated = _art_value_looks_overlay_proxy(poster)

    # 'clean' mode: always strip if a clean URL is derivable.
    if mode == 'clean':
        clean = _clean_meta_art(meta or {})
        if not clean.get('poster'):
            return art
        out = dict(art)
        for key in ('poster', 'thumb', 'thumbnail', 'cover', 'image',
                    'tvshow.poster', 'season.poster', 'tvshow.thumb', 'icon'):
            if out.get(key):
                out[key] = clean['poster']
            else:
                out.setdefault(key, clean['poster'])
        if not out.get('fanart') and clean.get('fanart'):
            out['fanart'] = clean['fanart']
            out.setdefault('landscape', clean['fanart'])
        return out

    # 'decorated' mode: legacy — leave everything as-is.
    if mode == 'decorated':
        return art

    # 'auto' mode (default): build a local-proxy URL when the poster
    # proxy server (service.py) is up. The proxy hands Kodi a single URL
    # that transparently falls back decorated → clean upstream, so even
    # skins that don't honour Kodi's poster→thumb fallback chain
    # (Estuary, Confluence, etc.) get a working poster in every case.
    #
    # When the proxy is unavailable (port couldn't bind, service not yet
    # up), we degrade to the v3.9.23 HEAD-probe heuristic: probe the
    # proxy domain once, cache for 5 min, decide decorated-vs-clean for
    # this and subsequent items from the same domain.
    if not looks_decorated:
        return art
    clean = _clean_meta_art(meta or {})
    if not clean.get('poster'):
        return art

    out = dict(art)

    # Path A: local image proxy is alive — use it.
    try:
        from . import poster_proxy as _proxy
        proxy_url = _proxy.build_url(poster, clean['poster'])
    except Exception:
        proxy_url = ''

    if proxy_url:
        # All poster-family slots point at the proxy URL. Kodi loads a
        # single endpoint that always responds; the proxy decides
        # decorated-vs-clean internally with a 3s upstream budget.
        out['poster']        = proxy_url
        out['tvshow.poster'] = proxy_url
        out['season.poster'] = proxy_url
        # Thumb stays clean so the artwork cache for thumb is separately
        # warm — and any code path that explicitly reads `thumb` (like
        # picture-in-picture overlays) still gets a usable image even
        # if the proxy is briefly slow.
        out['thumb']         = clean['poster']
        out['thumbnail']     = clean['poster']
        out['cover']         = clean['poster']
        out['image']         = clean['poster']
        out['icon']          = clean['poster']
        out['tvshow.thumb']  = clean['poster']
        if not out.get('fanart') and clean.get('fanart'):
            out['fanart'] = clean['fanart']
            out.setdefault('landscape', clean['fanart'])
        return out

    # Path B: no proxy available — fall back to HEAD-probe heuristic.
    proxy_alive = _is_proxy_healthy(poster)
    if proxy_alive:
        out['poster']        = poster
        out['tvshow.poster'] = poster
        out['season.poster'] = poster
        out['thumb']         = clean['poster']
        out['thumbnail']     = clean['poster']
        out['cover']         = clean['poster']
        out['image']         = clean['poster']
        out['icon']          = clean['poster']
        out['tvshow.thumb']  = clean['poster']
    else:
        for key in ('poster', 'thumb', 'thumbnail', 'cover', 'image',
                    'tvshow.poster', 'season.poster', 'tvshow.thumb', 'icon'):
            out[key] = clean['poster']
    if not out.get('fanart') and clean.get('fanart'):
        out['fanart'] = clean['fanart']
        out.setdefault('landscape', clean['fanart'])
    return out

# ─────────────────────────────────────────────────────────────────────
# v3.9.27: Fast Index Mode integration helpers.
#
# Three modes available via setting `index_mode` (slider):
#   'live'   — current behaviour: every folder open hits N HTTP catalogs.
#              Default for safety — won't change behaviour on upgrade.
#   'hybrid' — use index when it has data; live aggregator otherwise.
#   'fast'   — same as hybrid for now (a future tier could skip the
#              live fallback even when index is empty, but that gives a
#              worse first-run experience so we don't enable it yet).
#
# The actual data layer lives in resources/lib/dexhub/index.py and the
# sync engine in dexhub/sync_engine.py. service.py runs the scheduler.
# ─────────────────────────────────────────────────────────────────────

def _index_mode():
    raw = (ADDON.getSetting('index_mode') or 'Live (current)').strip()
    low = raw.lower()
    if 'fast' in low or 'سريع' in low:
        return 'fast'
    if 'hybrid' in low or 'هجين' in low:
        return 'hybrid'
    return 'live'


def _index_mode_active():
    """True when the user has opted in to either hybrid or fast mode."""
    return _index_mode() in ('fast', 'hybrid')


def _try_index_render(bucket, page_num, page_size, fetch_limit, entries):
    """Bridge between the index_render module and the existing render loop.

    Returns a list of (provider, catalog, media_type, meta_id, meta)
    tuples (matching what the live aggregator produces) when the index
    has data for the bucket, or None if the index is empty (caller
    must fall back).

    v3.9.45: two related fixes applied here.

    1. User filters are now propagated to the index query. Previously
       only the sort key was honoured, so applying Genre or Year or
       Language filters in Hybrid mode produced an unfiltered listing —
       the user thought the filter was broken when in fact the Index
       layer simply did not see it.

    2. Each rendered row now carries its REAL (provider, catalog)
       attribution from the item_sources join, not a fake "first
       installed provider" placeholder. The play path consumes this
       attribution to route the user's click to a provider that
       actually has the item, fixing the v3.9.40 "same source" mode.
       The entries[0] fallback is used only when the index couldn't
       identify the source (very rare; orphaned item_sources rows).
    """
    from . import index_render
    if not index_render.bucket_has_data(bucket):
        return None

    # Read the user's active filter state for this bucket so the
    # index query reflects what the user chose. Falls back to no-
    # filter cleanly when the helpers are unavailable or the user
    # has not applied anything.
    filter_genre = None
    filter_year = None
    filter_language = None
    try:
        extras = _folder_filtered_extra_for_catalog(bucket, '', '', {}) or {}
        filter_genre = (extras.get('genre') or '').strip() or None
        if extras.get('year'):
            try:
                filter_year = int(str(extras.get('year')).strip())
            except (TypeError, ValueError):
                filter_year = None
        filter_language = (extras.get('language') or '').strip() or None
    except Exception:
        pass

    metas = index_render.query_bucket_metas(
        bucket,
        sort=_folder_sort_for_bucket(bucket),
        media_type=_hub_bucket_media_type(bucket),
        genre=filter_genre,
        year=filter_year,
        language=filter_language,
        limit=fetch_limit,
        offset=page_num * page_size,
    )
    if not metas:
        return None

    # Build provider/catalog lookup tables once, indexed by id, so each
    # item's attribution from the index can be resolved to the real
    # provider/catalog dicts the renderer expects.
    provider_by_id = {}
    catalog_by_id = {}
    for prov, cat, _b, _pin in (entries or []):
        if prov and prov.get('id'):
            provider_by_id[prov.get('id')] = prov
        if cat and cat.get('id'):
            catalog_by_id[cat.get('id')] = cat

    fallback_provider = entries[0][0] if entries else {}
    fallback_catalog  = entries[0][1] if entries else {}

    rows = []
    media_type_default = _hub_bucket_media_type(bucket) or 'movie'
    for meta in metas:
        if not isinstance(meta, dict):
            continue
        media_type = meta.get('type') or media_type_default
        meta_id = meta.get('id') or meta.get('imdb_id')
        if not meta_id:
            continue
        # Use the real attribution from the index query if available,
        # falling back to the first installed entry when the index
        # couldn't determine it (a degenerate case).
        real_provider_id = meta.get('_dexhub_provider_id') or ''
        real_catalog_id = meta.get('_dexhub_catalog_id') or ''
        provider = provider_by_id.get(real_provider_id, fallback_provider)
        catalog  = catalog_by_id.get(real_catalog_id,  fallback_catalog)
        rows.append((provider, catalog, media_type, meta_id, meta))
    return rows


def _folder_sort_for_bucket(bucket):
    """Map the user's catalog filter sort to an IndexDB sort key.
    Falls back to 'release_date' (newest released first) when no
    explicit sort is configured for the folder."""
    try:
        extras = _folder_filtered_extra_for_catalog(bucket, '', '', {}) or {}
        sort_raw = (extras.get('sort') or '').lower()
        if 'rating' in sort_raw or 'popular' in sort_raw:
            return 'rating'
        if 'name' in sort_raw or 'title' in sort_raw or 'a-z' in sort_raw:
            return 'title'
        if 'year' in sort_raw:
            return 'year'
        if 'last_added' in sort_raw or 'added' in sort_raw:
            return 'added_date'
    except Exception:
        pass
    return 'release_date'


def _index_engine():
    """Lazy-singleton accessor for the sync engine. Re-imports each call
    so a fresh schema (after schema_migrate) is picked up without
    restarting Kodi."""
    from . import index_render
    from .dexhub import sync_engine
    db = index_render.get_db()

    def _pinned():
        return _hub_catalog_entries(bucket=None) or []

    return sync_engine.SyncEngine(db, pinned_entries_provider=_pinned)


def index_refresh_all():
    """User-triggered: re-sync every pinned catalog into the index."""
    try:
        xbmcgui.Dialog().notification('Dex Hub',
            tr('بدء مزامنة المكتبة...'),
            xbmcgui.NOTIFICATION_INFO, 2000, sound=False)
        eng = _index_engine()
        def _run():
            try:
                result = eng.sync_all()
                xbmcgui.Dialog().notification('Dex Hub',
                    tr('انتهت المزامنة: %d كتالوج') % (result.get('ok') or 0),
                    xbmcgui.NOTIFICATION_INFO, 3500, sound=False)
            except Exception as exc:
                xbmc.log('[DexHub] refresh_all failed: %s' % exc, xbmc.LOGWARNING)
        if not _submit_optional(_run, key='manual-index-sync'):
            notify(tr('المزامنة تعمل بالفعل أو الجهاز مشغول'))
    except Exception as exc:
        xbmc.log('[DexHub] index_refresh_all error: %s' % exc, xbmc.LOGWARNING)


def index_refresh_bucket(bucket=''):
    """User-triggered: re-sync one home folder's catalogs only."""
    bucket = bucket or ''
    if not bucket:
        return
    try:
        xbmcgui.Dialog().notification('Dex Hub',
            tr('مزامنة %s...') % _hub_bucket_title(bucket),
            xbmcgui.NOTIFICATION_INFO, 2000, sound=False)
        eng = _index_engine()
        def _run():
            try:
                result = eng.sync_bucket(bucket)
                xbmcgui.Dialog().notification('Dex Hub',
                    tr('انتهى: %d / %d كتالوج') % (
                        result.get('ok') or 0, result.get('total') or 0),
                    xbmcgui.NOTIFICATION_INFO, 3500, sound=False)
            except Exception as exc:
                xbmc.log('[DexHub] refresh_bucket failed: %s' % exc, xbmc.LOGWARNING)
        if not _submit_optional(_run, key='bucket-index-sync:%s' % bucket):
            notify(tr('مزامنة هذا القسم تعمل بالفعل'))
    except Exception as exc:
        xbmc.log('[DexHub] index_refresh_bucket error: %s' % exc, xbmc.LOGWARNING)


def index_clear():
    """User-triggered: wipe the library index. Prompts for confirmation."""
    if not xbmcgui.Dialog().yesno(
        'Dex Hub',
        tr('سيتم حذف المكتبة المحلية بالكامل. هل أنت متأكد؟')):
        return
    try:
        from . import index_render
        index_render.get_db().clear_all()
        xbmcgui.Dialog().notification('Dex Hub',
            tr('تم مسح المكتبة'),
            xbmcgui.NOTIFICATION_INFO, 2000, sound=False)
    except Exception as exc:
        xbmc.log('[DexHub] index_clear failed: %s' % exc, xbmc.LOGWARNING)


def index_status():
    """Render a status page showing index stats and catalog sync state."""
    from . import index_render
    s = index_render.stats()
    db = index_render.get_db()
    sync_rows = db.get_sync_state()

    # Header summary card
    size_mb = (s.get('db_size') or 0) / (1024.0 * 1024.0)
    last_sync_ts = s.get('last_sync') or 0
    if last_sync_ts:
        age_min = int((time.time() - last_sync_ts) / 60)
        age_text = '%d min ago' % age_min if age_min < 60 else '%d hr ago' % (age_min // 60)
    else:
        age_text = 'never'

    add_item('[B]%s[/B]: %d  •  [B]%s[/B]: %d catalogs  •  [B]%s[/B]: %.1f MB  •  [B]%s[/B]: %s' % (
        tr('عناصر'), s.get('items') or 0,
        tr('مزامنات'), len(sync_rows),
        tr('الحجم'), size_mb,
        tr('آخر مزامنة'), age_text),
        build_url(action='index_status'), is_folder=False,
        art=root_art('catalogs'),
        info={'title': tr('حالة المكتبة'),
              'plot': tr('إحصائيات الفهرس المحلي.')})

    # Manual refresh actions
    add_item('[COLOR cyan]↻ %s[/COLOR]' % tr('مزامنة الكل الآن'),
        build_url(action='index_refresh_all'),
        is_folder=False, art=root_art('add'),
        info={'title': tr('مزامنة الكل')})

    add_item('[COLOR red]✖ %s[/COLOR]' % tr('مسح المكتبة'),
        build_url(action='index_clear'),
        is_folder=False, art=root_art('remove'),
        info={'title': tr('مسح المكتبة')})

    # Per-catalog status rows
    for row in sync_rows[:50]:
        status = row.get('status') or 'unknown'
        emoji = '✓' if status == 'ok' else ('✗' if status == 'error' else '•')
        ts = row.get('last_sync') or 0
        age = int((time.time() - ts) / 60) if ts else 0
        age_text = '%dm' % age if age < 60 else '%dh' % (age // 60)
        label = '[COLOR %s]%s[/COLOR]  %s/%s  (%s • %d items • %s)' % (
            'lime' if status == 'ok' else ('red' if status == 'error' else 'gray'),
            emoji,
            row.get('provider_id') or '?',
            row.get('catalog_id') or '?',
            row.get('bucket') or '-',
            row.get('item_count') or 0,
            age_text,
        )
        info_plot = (row.get('error_message') or '')[:300]
        add_item(label, build_url(action='index_refresh_bucket',
                                  bucket=row.get('bucket') or ''),
                 is_folder=False,
                 info={'title': label, 'plot': info_plot or tr('اضغط للمزامنة')})

    return end_dir(content='files', cache=False)


# Kodi major version detection — VideoInfoTag API is the modern way to set
# metadata (Kodi 20+). It's required for skins like Estuary MOD V2, Arctic
# Fuse 2 and Aura to render cast posters, ratings, and tags correctly.
# Older setInfo('video', dict) is silently ignored for several fields on K20+.
def _kodi_major_version():
    try:
        ver = xbmc.getInfoLabel('System.BuildVersion') or ''
        return int(str(ver).split('.', 1)[0])
    except Exception:
        return 19

_KODI_MAJOR = _kodi_major_version()


def _safe_playback_handoff_enabled():
    """Kodi 22/CoreELEC safe playback mode.

    Piers alpha builds can native-crash during the transition from a custom
    source dialog into fullscreen playback when the handoff ListItem carries
    too many skin-specific/global artwork aliases. Keep the source picker rich,
    but make the actual player item closer to TMDb Helper/Kodi defaults.
    """
    try:
        raw = (ADDON.getSetting('safe_playback_handoff') or 'true').strip().lower()
        enabled = raw in ('true', '1', 'yes', 'on')
    except Exception:
        enabled = True
    return bool(_KODI_MAJOR >= 22 and enabled)




def _kodi22_playlist_handoff_enabled():
    """Use an EmbyCon-style playlist handoff on Kodi 22/CoreELEC.

    Kodi 22 alpha/CoreELEC has shown native crashes with direct URL
    Player.play(url, listitem) and with large playback ListItems. EmbyCon is
    stable on the same systems because it builds a one-item PlayList and calls
    Player.play(playlist). Keep this behind the existing safe handoff setting
    so older Kodi versions and advanced users are unaffected.
    """
    try:
        return _KODI_MAJOR >= 22 and _safe_playback_handoff_enabled()
    except Exception:
        return False


def _kodi22_minimal_item_enabled():
    """Strip EVERY VideoInfoTag mutation from the playback handoff on Kodi 22.

    v3.9.192 — the crash that restarts the box on play.

    The existing safe mode only skipped InfoTag.setArtwork(). Two other native
    InfoTag mutations still ran on the exact same handoff:

        _videoinfotag_apply(...)      full tag: title, plot, genres, CAST...
        getVideoInfoTag().setUniqueIDs(...)   the "re-assert" pass

    Kodi 22 BETA on CoreELEC can die inside those native calls before the first
    frame is drawn — Kodi is then restarted by the system, which is exactly the
    "device restarts when I press play" report. ListItem.setArt() and the
    ListItem properties are NOT part of that native path and stay in place, so
    skins keep their artwork and Dex Hub's own subtitle bridge keeps the IDs.

    Turn this off to get the rich InfoTag back on builds that tolerate it.
    """
    try:
        # v5.10.94: default OFF. DPlex proved the full ListItem/InfoTag path
        # safe on the Kodi 22 devices this addon targets, and the minimal item
        # hides title and ids from Kodi's own subtitle dialog and every
        # subtitle addon. The setting stays as an opt-in crash guard.
        raw = (ADDON.getSetting('kodi22_minimal_item') or 'false').strip().lower()
        enabled = raw in ('true', '1', 'yes', 'on')
    except Exception:
        enabled = False
    return bool(_kodi22_playlist_handoff_enabled() and enabled)


def _native_resume_hint_allowed():
    """Whether Kodi may receive a native ResumeTime/InfoTag resume point.

    Kodi 22 alpha can crash in its native resume-dialog path when a playlist
    resolves back into a plugin URL (see CVideoPlayActionProcessor::
    OnResumeSelected in the crash report).  Dex Hub already applies the same
    position after real media starts, so suppress only the redundant native
    hint on the safe Kodi 22 playlist route.
    """
    return not _kodi22_playlist_handoff_enabled()


def _videoinfotag_apply(item, info, ids=None, cast=None):
    """Map a flat info dict + ids + cast list onto the modern VideoInfoTag API.

    Skins on Kodi 20+ render rich items (cast posters, ratings, votes, premiere
    dates, MPAA chips, IMDB number) only when this API is used. Old setInfo
    drops or hides several of those fields. Falls back gracefully on any
    individual setter that raises.

    cast format: [{'name': 'Actor', 'role': 'Character', 'thumbnail': 'url'},...]
    """
    try:
        tag = item.getVideoInfoTag(offscreen=True)
    except Exception:
        return False

    def _try(fn, *args):
        try:
            fn(*args)
        except Exception:
            pass

    # Media type sets the icons & rendering mode in the skin. Always set first.
    mt = (info or {}).get('mediatype') or ''
    if mt:
        _try(tag.setMediaType, mt)

    if (info or {}).get('title') is not None:
        _try(tag.setTitle, str(info['title']))
    if (info or {}).get('originaltitle') is not None:
        _try(tag.setOriginalTitle, str(info['originaltitle']))
    if (info or {}).get('plot') is not None:
        _try(tag.setPlot, str(info['plot']))
    if (info or {}).get('plotoutline') is not None:
        _try(tag.setPlotOutline, str(info['plotoutline']))
    if (info or {}).get('tagline') is not None:
        _try(tag.setTagLine, str(info['tagline']))
    if (info or {}).get('mpaa') is not None:
        _try(tag.setMpaa, str(info['mpaa']))
    if (info or {}).get('studio') is not None:
        s = info['studio']
        _try(tag.setStudios, s if isinstance(s, (list, tuple)) else (str(s),))
    if (info or {}).get('country') is not None:
        c = info['country']
        _try(tag.setCountries, c if isinstance(c, (list, tuple)) else [str(c)])
    if (info or {}).get('director') is not None:
        d = info['director']
        if isinstance(d, str):
            d = [x.strip() for x in d.split(',') if x.strip()]
        _try(tag.setDirectors, list(d) if d else [])
    if (info or {}).get('writer') is not None:
        w = info['writer']
        if isinstance(w, str):
            w = [x.strip() for x in w.split(',') if x.strip()]
        _try(tag.setWriters, list(w) if w else [])
    if (info or {}).get('genre') is not None:
        g = info['genre']
        if isinstance(g, str):
            g = [x.strip() for x in re.split(r'[,/]', g) if x.strip()]
        _try(tag.setGenres, list(g) if g else [])
    if (info or {}).get('year') is not None:
        try:
            _try(tag.setYear, int(info['year']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('premiered') is not None:
        _try(tag.setPremiered, str(info['premiered']))
    if (info or {}).get('rating') is not None:
        try:
            _try(tag.setRating, float(info['rating']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('votes') is not None:
        try:
            _try(tag.setVotes, int(info['votes']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('duration') is not None:
        try:
            _try(tag.setDuration, int(info['duration']))
        except (ValueError, TypeError):
            pass
    # POV-style resume support for Kodi 20+: put the resume point on
    # the VideoInfoTag, not only on ListItem properties, so home widgets
    # and skins render/play continued items correctly.
    if (info or {}).get('resumetime') is not None or (info or {}).get('totaltime') is not None:
        try:
            _rt = float((info or {}).get('resumetime') or 0.0)
            _tt = float((info or {}).get('totaltime') or (info or {}).get('duration') or 0.0)
            if _rt > 0 and _tt > 0:
                _try(tag.setResumePoint, _rt, _tt)
        except Exception:
            pass
    if (info or {}).get('trailer') is not None:
        _try(tag.setTrailer, str(info['trailer']))
    if (info or {}).get('imdbnumber') is not None:
        _try(tag.setIMDBNumber, str(info['imdbnumber']))
    if (info or {}).get('playcount') is not None:
        try:
            _try(tag.setPlaycount, int(info['playcount']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('tvshowtitle') is not None:
        _try(tag.setTvShowTitle, str(info['tvshowtitle']))
    if (info or {}).get('season') is not None:
        try:
            _try(tag.setSeason, int(info['season']))
        except (ValueError, TypeError):
            pass
    if (info or {}).get('episode') is not None:
        try:
            _try(tag.setEpisode, int(info['episode']))
        except (ValueError, TypeError):
            pass

    # Unique IDs — modern keys (no _id suffix), default IMDb when present
    if ids:
        clean_ids = {}
        if ids.get('imdb_id'):
            clean_ids['imdb'] = str(ids['imdb_id'])
        if ids.get('tmdb_id'):
            clean_ids['tmdb'] = str(ids['tmdb_id'])
        if ids.get('tvdb_id'):
            clean_ids['tvdb'] = str(ids['tvdb_id'])
        if clean_ids:
            mt_key = str((info or {}).get('mediatype') or '').strip().lower()
            if mt_key in ('episode', 'tvshow', 'season'):
                # TMDb Helper's playerstring reads tvshow.* unique IDs for
                # episodes; keep the plain keys too for a4k/OpenSubtitles.
                if 'imdb' in clean_ids:
                    clean_ids.setdefault('tvshow.imdb', clean_ids['imdb'])
                if 'tmdb' in clean_ids:
                    clean_ids.setdefault('tvshow.tmdb', clean_ids['tmdb'])
                if 'tvdb' in clean_ids:
                    clean_ids.setdefault('tvshow.tvdb', clean_ids['tvdb'])
            default_key = 'imdb' if 'imdb' in clean_ids else ('tmdb' if 'tmdb' in clean_ids else 'tvdb')
            _try(tag.setUniqueIDs, clean_ids, default_key)

    # Stream details — many skins show codec/runtime chips from InfoTag.
    stream_details = (info or {}).get('streamdetails') or {}
    if isinstance(stream_details, dict):
        try:
            if hasattr(tag, 'addVideoStream') and isinstance(stream_details.get('video'), dict):
                v = stream_details.get('video') or {}
                _try(tag.addVideoStream, int(v.get('width') or 0), int(v.get('height') or 0), float(v.get('aspect') or 0), int(v.get('duration') or 0), str(v.get('codec') or ''), str(v.get('stereomode') or ''))
        except Exception:
            pass

    # Cast with thumbnails — this is what makes the right-side panel
    # in modern skins look "TMDb Helper-grade" instead of an empty list.
    if cast:
        try:
            actor_objects = []
            for entry in cast:
                if not isinstance(entry, dict):
                    continue
                name = str(entry.get('name') or '').strip()
                if not name:
                    continue
                role = str(entry.get('role') or entry.get('character') or '').strip()
                thumb = str(entry.get('thumbnail') or entry.get('photo') or entry.get('profile_path') or '').strip()
                order = entry.get('order')
                try:
                    order_int = int(order) if order is not None else len(actor_objects)
                except (ValueError, TypeError):
                    order_int = len(actor_objects)
                try:
                    actor_objects.append(xbmc.Actor(name, role, order_int, thumb))
                except Exception:
                    # Older Kodi 20 builds had Actor signature variants.
                    try:
                        actor_objects.append(xbmc.Actor(name=name, role=role, order=order_int, thumbnail=thumb))
                    except Exception:
                        pass
            if actor_objects:
                _try(tag.setCast, actor_objects)
        except Exception:
            pass
    return True


def _apply_sort_methods(content=None, sortable=True):
    # Issue #8 fix: Kodi remembers the user's last sort choice for a path. If
    # they accidentally tap "Sort by name" once, every catalog page in the
    # addon opens alphabetical from then on. Solution: don't register the
    # alphabetical sort at all on listing pages — Kodi can only fall back to
    # one of OUR registered methods. UNSORTED is first → it becomes the
    # default and the addon's natural order (newest-first for almost every
    # Stremio catalog) is preserved as "last release" feel.
    methods = [xbmcplugin.SORT_METHOD_UNSORTED]
    # v4.6.9: recency listings (search history) must register UNSORTED ONLY.
    # content=None used to append the alphabetical method, and Kodi's
    # per-path sort memory then showed the history "from letter A" instead
    # of most-recent-first — burying the word the user just searched.
    if not sortable:
        try:
            xbmcplugin.addSortMethod(HANDLE, xbmcplugin.SORT_METHOD_UNSORTED)
        except Exception:
            pass
        return
    if content in ('movies', 'tvshows', 'episodes', 'seasons'):
        methods.extend([
            xbmcplugin.SORT_METHOD_VIDEO_YEAR,
            xbmcplugin.SORT_METHOD_VIDEO_RATING,
            xbmcplugin.SORT_METHOD_DATE,
            xbmcplugin.SORT_METHOD_DURATION,
        ])
    # Allow alphabetical only on non-media listings (provider/category menus).
    if content in (None, 'files', 'addons'):
        methods.append(xbmcplugin.SORT_METHOD_LABEL_IGNORE_THE)
    seen = set()
    for method in methods:
        if method in seen:
            continue
        seen.add(method)
        try:
            xbmcplugin.addSortMethod(HANDLE, method)
        except Exception:
            pass


def _flush_pending_items():
    """Push all buffered items to Kodi in ONE IPC call."""
    global _PENDING_ITEMS
    if not _PENDING_ITEMS:
        return
    # v5.10.120: a widget of Arctic Fuse 3 opens a series on Dex Hub's
    # title page in the skin, not in the add-on's seasons listing
    try:
        from .skinui import widgetclick as _widgetclick
        _PENDING_ITEMS = _widgetclick.adapt(_PENDING_ITEMS)
    except Exception:
        pass
    try:
        xbmcplugin.addDirectoryItems(HANDLE, _PENDING_ITEMS, len(_PENDING_ITEMS))
    except Exception:
        # Fall back to per-item add if the batch path fails (very rare).
        for path, item, is_folder in _PENDING_ITEMS:
            try:
                xbmcplugin.addDirectoryItem(HANDLE, path, item, isFolder=is_folder)
            except Exception:
                pass
    _PENDING_ITEMS = []


def _meta_mem_clear():
    """Drop ALL cached metas from the in-memory layer.

    Called after the user changes a meta-source mapping so subsequent
    catalog/details renders rebuild the cache with the new source. The disk
    HTTP cache is also flushed by meta_source.set_meta_source_for via
    purge_meta_cache(); this complements that for the post-override layer.
    """
    try:
        _META_MEM.clear()
        _META_MEM_ORDER[:] = []
    except Exception:
        pass


def _provider_catalogs(provider, media_type=None):
    catalogs = []
    if (provider or {}).get('enabled') is False:
        return catalogs
    rows = list((provider or {}).get('manifest', {}).get('catalogs', []) or [])
    rows.sort(key=lambda c: int((c or {}).get('order', 0) or 0))
    for catalog in rows:
        if not isinstance(catalog, dict):
            continue
        if catalog.get('enabled') is False or catalog.get('hidden') is True:
            continue
        if media_type and catalog.get('type') != media_type:
            continue
        catalogs.append(catalog)
    return catalogs


def _available_types(provider):
    types = []
    for media_type in provider.get('manifest', {}).get('types') or []:
        if _provider_catalogs(provider, media_type):
            types.append(media_type)
    if types:
        return types
    seen = []
    for catalog in _provider_catalogs(provider):
        media_type = catalog.get('type')
        if media_type and media_type not in seen:
            seen.append(media_type)
    return seen


def _provider_supports_search(provider, media_type=None):
    for catalog in _provider_catalogs(provider, media_type):
        for extra in catalog.get('extra') or []:
            if isinstance(extra, str) and extra.strip().lower() == 'search':
                return True
            if isinstance(extra, dict) and extra.get('name') == 'search':
                return True
    return False




def _provider_is_rating_proxy(provider):
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    haystack = ' '.join([
        str(provider.get('name') or ''),
        str(provider.get('id') or ''),
        str(provider.get('base_url') or ''),
        str(provider.get('manifest_url') or ''),
        str(manifest.get('name') or ''),
        str(manifest.get('id') or ''),
        str(manifest.get('description') or ''),
    ]).lower()
    return any(h in haystack for h in (
        'easyratingsdb.com', 'easyratingsdb', 'erdb proxy', 'erdb',
        'ratingposterdb.com', 'rating poster', 'ratingposter', 'rpdb'
    ))

def _provider_is_plexio(provider):
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    haystack = ' '.join([
        str(provider.get('name') or ''),
        str(provider.get('id') or ''),
        str(provider.get('base_url') or ''),
        str(provider.get('manifest_url') or ''),
        str(manifest.get('name') or ''),
        str(manifest.get('id') or ''),
        str(manifest.get('description') or ''),
    ]).lower()
    return any(h in haystack for h in ('plexio', 'plexbridge', 'com.stremio.plexio', 'com.stremio.plexbridge', 'sb.dexworld', 'dexbridge'))


def _provider_prefers_native_art(provider):
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    haystack = ' '.join([
        str(provider.get('name') or ''),
        str(provider.get('id') or ''),
        str(provider.get('base_url') or ''),
        str(provider.get('manifest_url') or ''),
        str(manifest.get('name') or ''),
        str(manifest.get('id') or ''),
        str(manifest.get('description') or ''),
    ]).lower()
    # Plex / Emby / Plexio / DexBridge all build poster URLs that include
    # auth tokens or session-bound paths. Kodi's image loader strips query
    # strings, expires the cache aggressively, and chokes on long URLs —
    # so for ANY of these providers we prefer remote (TMDb-based) art.
    return any(h in haystack for h in ('plex', 'plexio', 'emby', 'jellyfin', 'silo', 'dexbridge'))


_ART_URL_KEYS = (
    'poster', 'thumbnail', 'thumb', 'image', 'posterUrl', 'posterURL',
    'imageUrl', 'imageURL', 'thumbUrl', 'thumbURL', 'background', 'fanart',
    'landscape', 'banner', 'backdrop', 'clearlogo', 'logo', 'clearart',
    'parentThumb', 'grandparentThumb', 'art', 'key'
)


def _safe_http_origin(raw):
    """Keep only scheme + host so configured manifest tokens never reach UI."""
    try:
        parsed = urlparse(str(raw or '').strip())
        host = (parsed.netloc or '').split('@')[-1]
        if parsed.scheme.lower() in ('http', 'https') and host:
            return '%s://%s' % (parsed.scheme.lower(), host)
    except Exception:
        pass
    return ''


def _provider_origin(provider):
    provider = provider or {}
    for raw in (provider.get('base_url'), provider.get('manifest_url')):
        origin = _safe_http_origin(raw)
        if origin:
            return origin
    return ''


def _resolve_provider_art_value(provider, value):
    text = str(value or '').strip()
    if not text:
        return text
    lower = text.lower()
    if lower.startswith(('image://', 'special://', 'file://', 'plugin://', 'smb://', 'nfs://')):
        return text
    if lower.startswith(('http://', 'https://')):
        return text
    origin = _provider_origin(provider)
    if text.startswith('/') and origin:
        try:
            return urljoin(origin + '/', text.lstrip('/'))
        except Exception:
            return origin + text
    return text


def _plex_image_token_from_url(value):
    try:
        qs = parse_qs(urlparse(str(value or '')).query or '')
        return (qs.get('X-Plex-Token') or qs.get('x-plex-token') or qs.get('token') or [''])[0]
    except Exception:
        return ''


def _append_plex_token(url, token):
    text = str(url or '').strip()
    token = str(token or '').strip()
    if not text or not token or 'x-plex-token=' in text.lower():
        return text
    return '%s%sX-Plex-Token=%s' % (text, '&' if '?' in text else '?', token)


def _plex_transcode_original_art(provider, value):
    """Extract the original poster path from Plex /photo/:/transcode URLs.

    PlexMod avoids blank composite posters by decoding Plex's /photo/:/transcode
    wrapper and keeping the original image path as a fallback. Dex Hub does the
    same here, preserving auth tokens when present.
    """
    text = str(value or '').strip()
    if not text:
        return ''
    lower = text.lower()
    if '/:/transcode' not in lower and 'transcode' not in lower and 'composite' not in lower and 'overlay' not in lower:
        return ''
    try:
        parsed = urlparse(text)
        qs = parse_qs(parsed.query or '')
        src = (qs.get('url') or qs.get('thumb') or qs.get('path') or [''])[0]
        if not src:
            return ''
        src = _resolve_provider_art_value(provider, src)
        return _append_plex_token(src, _plex_image_token_from_url(text))
    except Exception:
        return ''


def _looks_like_direct_plex_art(value):
    text = str(value or '').strip()
    lower = text.lower()
    if not text:
        return False
    if any(bad in lower for bad in ('themoviedb.org', 'image.tmdb.org', 'fanart.tv', 'trakt.tv', 'cinemeta')):
        return False
    return any(token in lower for token in (
        '/library/metadata/', '/library/collections/', '/metadata/',
        '/thumb/', '/art/', '/photo/:/transcode', '/:/transcode',
        'x-plex-token=', 'plex.direct', 'plex.tv', 'plexapp.com'
    ))


def _art_value_looks_composed_poster(value):
    text = str(value or '').lower()
    return _art_value_looks_rating_proxy(text) or any(token in text for token in (
        'overlay', 'composite', 'ratingposter', 'rating-poster', 'rpdb', 'erdb',
        '/photo/:/transcode', '/:/transcode', '/collection-image/',
        '/composite/', '/overlay/'
    ))


def _plexmod_transcode_url(provider, value, width=500, height=750):
    """Build a PlexMod-style photo transcode URL for a poster candidate.

    Direct Plex/Plexio thumbnails without overlays are more reliable in Kodi
    when requested through Plex's /photo/:/transcode endpoint. If Plexio
    returns the real Plex host instead of the add-on host, use that same host
    as the transcode origin, but never wrap TMDb/Cinemeta/external artwork.
    """
    text = _resolve_provider_art_value(provider, value)
    if not text:
        return ''
    lower = text.lower()
    if lower.startswith(('image://', 'special://', 'file://', 'plugin://', 'smb://', 'nfs://')):
        return text
    # v5.10.118: only Plex's own pictures go through Plex's transcoder. An
    # add-on that serves its posters from its own address (/img/poster.jpg)
    # had them rewritten to <its address>/photo/:/transcode?url=..., a page
    # it does not have: every poster of its catalogs came out blank.
    if not _looks_like_direct_plex_art(text):
        return ''
    origin = _provider_origin(provider)
    transcode_origin = origin
    try:
        parsed = urlparse(text)
        url_host = parsed.netloc.lower()
        prov_host = urlparse(origin).netloc.lower() if origin else ''
        if parsed.scheme and parsed.netloc:
            text_origin = '%s://%s' % (parsed.scheme, parsed.netloc)
            if prov_host and url_host and url_host != prov_host:
                if not _looks_like_direct_plex_art(text):
                    return ''
                transcode_origin = text_origin
            elif not transcode_origin:
                if not _looks_like_direct_plex_art(text):
                    return ''
                transcode_origin = text_origin
    except Exception:
        return ''
    if not transcode_origin:
        return ''
    token = _plex_image_token_from_url(text)
    original = _plex_transcode_original_art(provider, text) or text
    original = _resolve_provider_art_value(provider, original)
    if token:
        original = _append_plex_token(original, token)
    path = '/photo/:/transcode?url=%s&width=%s&height=%s&minSize=1&upscale=1' % (
        quote_plus(original), int(width), int(height)
    )
    if token and 'x-plex-token=' not in path.lower():
        path += '&X-Plex-Token=%s' % token
    return urljoin(transcode_origin + '/', path.lstrip('/'))

def _normalize_meta_art_urls(provider, meta):
    """Resolve relative Plex/Emby/Plexio artwork paths and add fallback art.

    Some Stremio-compatible Plex/Plexio catalogs expose images as relative
    paths like /photo/:/transcode?... or as long overlay/composite URLs. Kodi can
    fail those when the origin/query/token is not preserved. This normalizes the
    common fields before they reach the art resolver.
    """
    if not isinstance(meta, dict):
        return meta
    # Bug fix (3.7.89): if the meta has been replaced by an explicit user-picked
    # source (Cinemeta, TMDb Helper, Trakt, etc.), do NOT rewrite its URLs through
    # the provider's host. Otherwise we'd wrap a TMDb/Cinemeta poster inside
    # /photo/:/transcode?url=... which Plex/Plexio cannot resolve, producing
    # broken posters every time the user changes the metadata source.
    sid = str(meta.get('_dexhub_meta_source_id') or '').strip().lower()
    strict = str(meta.get('_dexhub_art_strict') or '').strip().lower() in ('1', 'true', 'yes', 'on')
    if (strict and sid != 'native') or (sid and sid not in ('auto', 'native')):
        return meta
    out = dict(meta)
    for key in _ART_URL_KEYS:
        if key in out and out.get(key):
            out[key] = _resolve_provider_art_value(provider, out.get(key))

    for container_key in ('images', 'behaviorHints'):
        node = out.get(container_key)
        if isinstance(node, dict):
            new_node = dict(node)
            for key, value in list(new_node.items()):
                if isinstance(value, dict):
                    child = dict(value)
                    for ckey, cval in list(child.items()):
                        if isinstance(cval, str) and cval.strip():
                            child[ckey] = _resolve_provider_art_value(provider, cval)
                    new_node[key] = child
                elif isinstance(value, str) and value.strip():
                    new_node[key] = _resolve_provider_art_value(provider, value)
            out[container_key] = new_node

    primary = out.get('poster') or out.get('thumbnail') or out.get('thumb') or out.get('image') or ''

    # Plexio/DexWorld rule: never replace the poster that came from the
    # metadata payload. Version 3.8.8 rewrote plain no-overlay Plexio posters
    # into a synthetic /photo/:/transcode URL; on some Kodi/Plexio setups that
    # makes every poster blank. Keep the original primary artwork exactly like
    # Stremio/Composite, and store alternate candidates only as non-standard
    # fallback fields for future/debug use.
    if _provider_is_plexio(provider):
        if primary:
            out['poster'] = primary
            out['thumb'] = primary
            out['thumbnail'] = primary
            out['icon'] = primary
            out['image'] = primary
            out.setdefault('tvshow.poster', primary)
            out.setdefault('season.poster', primary)
            out.setdefault('tvshow.thumb', primary)
        fallback = _plex_transcode_original_art(provider, primary)
        if fallback:
            out.setdefault('plex_original_poster', fallback)
            out.setdefault('thumb_fallback', fallback)
            out.setdefault('thumbnail_fallback', fallback)
        if primary and not _art_value_looks_composed_poster(primary):
            transcode = _plexmod_transcode_url(provider, primary)
            if transcode and transcode != primary:
                out.setdefault('plex_transcode_poster', transcode)
        return out

    # Rating/overlay add-ons (ERDB/RPDB) already return a composed
    # Stremio-ready poster. Re-wrapping it through Plex /photo/:/transcode can
    # make Kodi show a blank poster or the add-on logo. Keep the supplied
    # vertical poster as the primary image and mirror only to poster-like keys.
    if _provider_is_rating_proxy(provider) or _art_value_looks_composed_poster(primary):
        if primary:
            out['poster'] = primary
            out['thumb'] = primary
            out['thumbnail'] = primary
            out['icon'] = primary
            out['image'] = primary
            out.setdefault('tvshow.poster', primary)
            out.setdefault('season.poster', primary)
            out.setdefault('tvshow.thumb', primary)
        fallback = _plex_transcode_original_art(provider, primary)
        if fallback:
            out.setdefault('plex_original_poster', fallback)
            out.setdefault('thumb_fallback', fallback)
            out.setdefault('thumbnail_fallback', fallback)
        return out

    fallback = _plex_transcode_original_art(provider, primary)
    transcode = _plexmod_transcode_url(provider, primary)
    if fallback:
        out.setdefault('thumb', fallback)
        out.setdefault('thumbnail', fallback)
        out.setdefault('icon', fallback)
        out.setdefault('plex_original_poster', fallback)
    if transcode:
        if primary:
            out.setdefault('plex_overlay_poster', primary)
        out['poster'] = transcode
        out.setdefault('thumbnail', fallback or transcode)
        out.setdefault('thumb', fallback or transcode)
    return out


def _provider_meta_source_id(provider):
    try:
        provider_id = (provider or {}).get('id') or ''
        source_id = (_meta_source.get_meta_source_for(provider_id) if provider_id else 'auto') or 'auto'
        # Plexio auto must mean Plexio/native artwork, not a hidden TMDb/Cinemeta
        # swap. Explicit picks (TMDb Helper / another metadata addon / native)
        # are still honored below by meta_source.override_* and _resolve_meta_art.
        if source_id == 'auto' and _provider_is_plexio(provider):
            return 'native'
        return source_id
    except Exception:
        return 'auto'


def _provider_uses_explicit_meta_art(provider):
    source_id = _provider_meta_source_id(provider)
    return source_id not in ('', 'auto')


def _meta_art_is_strict(meta):
    return str((meta or {}).get('_dexhub_art_strict') or '').strip().lower() in ('1', 'true', 'yes', 'on')


def _meta_source_id_from_meta(meta):
    return str((meta or {}).get('_dexhub_meta_source_id') or '').strip()


def _target_meta_source_id(target_key):
    try:
        return (_meta_source.get_meta_source_for(target_key) if target_key else 'auto') or 'auto'
    except Exception:
        return 'auto'


def _target_meta_source_is_explicit(target_key):
    return _target_meta_source_id(target_key) not in ('', 'auto')


def _is_virtual_meta_target(target_key):
    return str(target_key or '').strip().startswith('virtual.')


def _source_context_requires_exact_meta(source_provider_id):
    sid = str(source_provider_id or '').strip()
    if not sid:
        return False
    if _is_virtual_meta_target(sid):
        return _target_meta_source_is_explicit(sid)
    try:
        provider = store.get_provider(sid)
    except Exception:
        provider = None
    return _provider_uses_explicit_meta_art(provider or {'id': sid})



def _meta_cache_discriminator(source_provider_id=''):
    try:
        source_map = ADDON.getSetting('provider_meta_map') or '{}'
    except Exception:
        source_map = '{}'
    return '|'.join([
        str(source_provider_id or ''),
        str(source_map or '{}'),
        str(ADDON.getSetting('global_meta_source_id') or ''),
        str(ADDON.getSetting('global_meta_source_all') or ''),
        str(ADDON.getSetting('global_poster_source_id') or ''),
        str(ADDON.getSetting('metadata_generation') or ''),
        str(_tmdb_art_db.helper_language() or ''),
        str(poster_source_mode() or ''),
    ])


def _meta_provider_first(providers, source_provider_id=''):
    providers = [p for p in (providers or []) if p]
    sid = str(source_provider_id or '').strip()
    if not sid:
        return providers
    head = []
    tail = []
    seen = set()
    for p in providers:
        pid = str((p or {}).get('id') or '')
        if not pid or pid in seen:
            continue
        seen.add(pid)
        if pid == sid:
            head.append(p)
        else:
            tail.append(p)
    if not head:
        try:
            p = store.get_provider(sid)
        except Exception:
            p = None
        if p:
            head.append(p)
    return head + tail


def _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=''):
    return _meta_provider_first(_provider_order_for_id(media_type, canonical_id), source_provider_id=source_provider_id)


def _resolve_meta_art(provider, media_type, meta, fallback_art=None, force_remote=False, lazy=False):
    # v3.9.21 wrapper — runs the existing resolver, then applies the user's
    # poster reliability filter (auto/clean/decorated) so decorated overlay
    # URLs from RPDB/BetterPosters/TOP Posters get swapped for direct
    # metahub.space CDN URLs when needed. The wrapper preserves every
    # existing source-priority code path below; it only post-processes
    # the final art dict.
    #
    # v3.9.31 — lazy mode: when `lazy=True`, skip the heavy enrichment
    # passes (TMDB/Fanart cross-lookup, meta_cache deep reads, bucket
    # art priority HTTP-free fallback). Used for items past the visible
    # threshold (#13+) in folder renders. They still get correct
    # poster/fanart from the meta dict itself, just not the cross-source
    # enrichment that costs 5-15ms per item.
    if lazy:
        return _resolve_meta_art_fast(provider, media_type, meta, fallback_art)
    art = _resolve_meta_art_inner(provider, media_type, meta,
                                    fallback_art=fallback_art,
                                    force_remote=force_remote)
    if _meta_art_is_strict(meta):
        return art
    try:
        art = _apply_poster_reliability(art, meta)
    except Exception as exc:
        xbmc.log('[DexHub] poster reliability filter failed: %s' % exc, xbmc.LOGDEBUG)
    # Global artwork policy applies everywhere. A folder-specific policy is
    # applied afterwards and therefore acts as an intentional exception.
    try:
        art = _apply_global_art_priority(art, media_type, meta, provider)
    except Exception as exc:
        xbmc.log('[DexHub] global art priority failed: %s' % exc, xbmc.LOGDEBUG)
    try:
        art = _apply_bucket_art_priority(art, media_type, meta, provider)
    except Exception as exc:
        xbmc.log('[DexHub] bucket art priority failed: %s' % exc, xbmc.LOGDEBUG)
    try:
        art = _better_posters.apply(
            art, (extract_ids(meta or {}) or {}).get('imdb_id') or '',
            media_type, ADDON)
    except Exception as exc:
        xbmc.log('[DexHub] BetterPosters URL pass failed: %s' % exc, xbmc.LOGDEBUG)
    return art


def _resolve_meta_art_fast(provider, media_type, meta, fallback_art=None):
    """v3.9.31 — minimal art resolution for items past the visible
    threshold in a folder render.

    Skipped vs full path:
      - TMDB enrichment (HTTP)
      - Fanart.tv enrichment (HTTP)
      - meta_cache cross-provider lookups
      - bucket art priority resolution
      - meta_source override negotiation

    Kept:
      - poster reliability filter (cheap regex, prevents decorated URL leaks)
      - poster_proxy wrapping (preserves the local CDN handle)

    The trade-off is calibrated: most catalog responses already carry a
    poster URL in meta.poster. Skipping enrichment loses the "promoted"
    Fanart.tv hi-res poster, but for the 60+ items past the visible
    fold the user will scroll past most without ever seeing them.
    Items that DO come into view via scroll keep this lazy art (no
    container refresh trigger), which is an explicit trade-off — the
    speed gain is large enough to justify it.
    """
    fb = fallback_art or {}
    poster = (meta or {}).get('poster') or fb.get('poster') or fb.get('thumb') or ''
    fanart = ((meta or {}).get('background')
              or (meta or {}).get('fanart')
              or fb.get('fanart') or '')
    # v5.10.97: never the provider's logo (see _without_title_logo)
    logo   = (meta or {}).get('clearlogo') or (meta or {}).get('logo') or ''
    if not logo and _meta_art_is_strict(meta):
        # v5.10.302: Like Nuvio: no logo where Nuvio has none (its title text)
        try:
            from .meta_policy import nuvio_parity as _nv_parity
            if _nv_parity():
                logo = None
        except Exception:
            pass
    if logo is None:
        logo = ''
    elif not logo:
        # v5.10.297: collections and Nuvio rows take this path; the title's
        # logo from TMDb Helper's local art database (no network)
        try:
            _ids = extract_ids(meta or {})
            if _ids.get('tmdb_id') or _ids.get('imdb_id'):
                logo = (_tmdb_art_db.get_art_bundle_from_db(
                    tmdb_id=_ids.get('tmdb_id') or '',
                    media_type='tv' if str(media_type or '').lower() in ('series', 'tv', 'show', 'anime') else 'movie',
                    imdb_id=_ids.get('imdb_id') or '') or {}).get('clearlogo') or ''
        except Exception:
            logo = ''
    art = {
        'poster':   poster,
        'fanart':   fanart,
        'thumb':    poster,
        'icon':     poster,
        'banner':   fanart,
        # v5.10.302: the Nuvio profile's landscape pattern when it has one
        'landscape': ((meta or {}).get('landscape') if ((meta or {}).get('_nuvio_custom_poster') and (meta or {}).get('landscape')) else fanart),
        'clearlogo': logo,
    }
    if logo:
        art['logo'] = logo
        art['tvshow.clearlogo'] = logo
    if not _meta_art_is_strict(meta):
        try:
            art = _apply_poster_reliability(art, meta)
        except Exception:
            pass
    if _meta_art_is_strict(meta):
        return art
    try:
        art = _better_posters.apply(
            art, (extract_ids(meta or {}) or {}).get('imdb_id') or '',
            media_type, ADDON)
    except Exception:
        pass
    return art


def _art_slot_targets():
    return {
        'poster': ['poster', 'thumb', 'icon', 'tvshow.poster', 'season.poster'],
        'background': ['fanart'],
        'landscape': ['landscape'],
        'banner': ['banner'],
        'clearlogo': ['clearlogo', 'logo', 'tvshow.clearlogo'],
        'clearart': ['clearart', 'tvshow.clearart'],
    }


def _apply_global_art_priority(art, media_type, meta, current_provider):
    if _meta_art_is_strict(meta):
        return art
    try:
        from . import meta_source as _ms
    except Exception:
        return art
    if _ms.art_configuration_mode() != 'unified':
        return art
    out = None
    meta_id = (meta or {}).get('id') or (meta or {}).get('imdb_id') or ''
    for art_type, slot_keys in _art_slot_targets().items():
        priority = _ms.get_global_art_priority(art_type)
        if not priority:
            continue
        chosen_url = _pick_art_by_priority(
            art_type, priority, media_type, meta_id, meta, current_provider,
        )
        if not chosen_url:
            continue
        if out is None:
            out = dict(art)
        for key in slot_keys:
            out[key] = chosen_url
    return out if out is not None else art


def _apply_bucket_art_priority(art, media_type, meta, current_provider):
    """Walk the configured per-bucket priority list for each art type
    (poster, background, clearlogo) and replace the slot if a higher-
    priority provider has the art available.

    Reads the active bucket from the Window property
    ``dexhub.render_bucket`` set by _hub_render_media_rows().
    """
    if _meta_art_is_strict(meta):
        return art
    try:
        bucket = xbmcgui.Window(WINDOW_ID).getProperty('dexhub.render_bucket') or ''
    except Exception:
        bucket = ''
    if not bucket:
        return art       # no bucket context = not in a folder render → no-op
    try:
        from . import meta_source as _ms
    except Exception:
        return art
    if _ms.art_configuration_mode() != 'custom':
        return art

    # Map our internal art-type names to the keys we set on Kodi ListItems.
    # Multiple keys may correspond to one art type (poster has 5-6 mirrors).
    art_slot_targets = _art_slot_targets()
    # For each art type with a configured priority list, walk it.
    out = None
    meta_id = (meta or {}).get('id') or (meta or {}).get('imdb_id') or ''

    for art_type, slot_keys in art_slot_targets.items():
        priority = _ms.get_bucket_art_priority(bucket, art_type)
        if not priority:
            continue
        chosen_url = _pick_art_by_priority(
            art_type, priority, media_type, meta_id, meta, current_provider,
        )
        if not chosen_url:
            continue
        # Lazy-init the output dict the first time we actually change something
        # — keeps the no-config no-op case allocation-free.
        if out is None:
            out = dict(art)
        for k in slot_keys:
            out[k] = chosen_url
    return out if out is not None else art


def _pick_art_by_priority(art_type, priority_pids, media_type, meta_id, meta, current_provider):
    """For the given art_type, try each provider in priority order until
    one yields a usable URL. Returns '' when nothing matches.

    Resolution order per provider:
      1) The meta we already have on hand (cheapest — zero HTTP cost)
         IF it came from this provider.
      2) The meta_cache for this provider — single SQLite lookup.
      3) Skipped if neither has art (no synchronous HTTP fetch on
         render — we'd be introducing 5-10 round trips per row).

    We accept the trade-off that a provider higher in priority that
    hasn't been fetched yet will silently miss. The bucket prefetch +
    catalog sync paths warm the cache for pinned providers, so for the
    user's actually-configured priority list this is rarely a miss.
    """
    # Map our art_type to the field name in a Stremio meta dict.
    field_map = {
        'poster': 'poster',
        'background': 'background',
        'landscape': 'landscape',
        'banner': 'banner',
        'clearlogo': 'logo',
        'clearart': 'clearart',
    }
    field = field_map.get(art_type)
    if not field:
        return ''

    current_pid = (current_provider or {}).get('id') or ''

    for pid in priority_pids:
        if not pid:
            continue

        # Built-in sources are valid artwork providers too.
        if pid == 'native':
            native_field = {
                'poster': 'poster', 'background': 'background',
                'landscape': 'landscape', 'banner': 'banner',
                'clearlogo': 'clearlogo', 'clearart': 'clearart',
            }.get(art_type, field)
            value = str((meta or {}).get(native_field) or '').strip()
            if not value and art_type == 'background':
                value = str((meta or {}).get('fanart') or '').strip()
            if not value and art_type == 'clearlogo':
                value = str((meta or {}).get('logo') or '').strip()
            if value:
                return value
            continue
        if pid == 'tmdb_helper':
            try:
                from . import meta_source as _ms
                ids = _ms.extract_ids(meta or {})
                helper_meta = _ms._fetch_from_tmdb_helper(ids, meta or {}, media_type) or {}
                aliases = {
                    'poster': ('poster', 'thumbnail', 'thumb'),
                    'background': ('background', 'fanart'),
                    'landscape': ('landscape', 'background', 'fanart'),
                    'banner': ('banner', 'landscape', 'background'),
                    'clearlogo': ('clearlogo', 'logo'),
                    'clearart': ('clearart',),
                }.get(art_type, (field,))
                for alias in aliases:
                    value = str(helper_meta.get(alias) or '').strip()
                    if value:
                        return value
            except Exception:
                pass
            continue

        # ─── Tier 1: meta we already have, if it's from this provider ───
        if pid == current_pid and isinstance(meta, dict):
            url = str(meta.get(field) or '').strip()
            if url:
                return url

        # ─── Tier 2: meta_cache lookup for this provider ───
        try:
            from . import meta_cache as _mc
            cached = _mc.get_one(media_type, pid, meta_id) if meta_id else None
            if cached and isinstance(cached, dict):
                url = str(cached.get(field) or '').strip()
                if url:
                    return url
        except Exception:
            pass

    return ''


def _resolve_meta_art_inner(provider, media_type, meta, fallback_art=None, force_remote=False):
    # If the user explicitly selected a metadata source, the artwork resolver
    # must NOT re-enrich from TMDb/direct afterwards. The meta object reaching
    # this function has already been replaced by meta_source.override_*; render
    # its own artwork exactly as-is. This is what makes "Plexio → Cinemeta",
    # "Plexio → Trakt", or "Plexio → TMDb Helper" affect posters 100%.
    meta_source_id = _meta_source_id_from_meta(meta)
    if _meta_art_is_strict(meta) or (meta_source_id and meta_source_id not in ('auto', 'native')):
        # Strict explicit source: the poster/thumb/icon must come only from the
        # selected metadata payload, including its own background and logo.
        return native_meta_art(meta, media_type, fallback_art={})
    source_id = _provider_meta_source_id(provider)
    if source_id == 'native':
        if _provider_is_plexio(provider):
            return composite_style_meta_art(meta, media_type, fallback_art=fallback_art)
        return native_meta_art(meta, media_type, fallback_art=fallback_art)
    if source_id not in ('', 'auto'):
        return native_meta_art(meta, media_type, fallback_art={})

    if _provider_is_rating_proxy(provider):
        native = native_meta_art(meta, media_type, fallback_art=fallback_art)
        enriched = enrich_meta_art(meta, media_type, fallback_art=fallback_art)
        # ERDB/RPDB must own the vertical poster, while the backdrop should not
        # be replaced by the vertical overlay poster when a better fanart exists.
        for key in ('poster', 'thumb', 'icon', 'thumbnail', 'cover', 'image', 'tvshow.poster', 'season.poster', 'tvshow.thumb'):
            if native.get(key):
                enriched[key] = native.get(key)
        if native.get('clearlogo'):
            for key in ('clearlogo', 'logo', 'tvshow.clearlogo', 'clearart'):
                if native.get(key):
                    enriched[key] = native.get(key)
        has_native_backdrop = any((meta or {}).get(k) for k in ('background', 'fanart', 'backdrop', 'landscape'))
        if has_native_backdrop:
            for key in ('fanart', 'landscape', 'banner'):
                if native.get(key):
                    enriched[key] = native.get(key)
        return enriched

    if force_remote:
        return enrich_meta_art(meta, media_type, fallback_art=fallback_art)
    # Plexio already returns Stremio-ready poster/background URLs from the
    # configured manifest/catalog/meta route. Treat it like Stremio does and
    # render the addon's native artwork in auto mode; otherwise Kodi may swap
    # to TMDb/Helper or leave the tokenized Plex image unwrapped.
    # However, when the poster is NOT an overlay/composite URL (e.g. plain
    # TMDb poster from catalog), use hybrid art so fanart/clearlogo can still
    # be enriched from remote sources.
    if _provider_is_plexio(provider):
        # DPlex/Composite visual behavior: keep the active metadata poster,
        # but fill clearlogo/background from item-native/TMDb Helper artwork.
        return composite_style_meta_art(meta, media_type, fallback_art=fallback_art)
    # Preserve native Plex/Plexio/Emby posters when the user selected
    # "محلي فقط". Their local posters often carry collection/status overlays
    # that disappear when we swap to TMDb art. Tokenized URLs are already
    # wrapped with image:// in native_meta_art(), so they can load reliably.
    if _provider_prefers_native_art(provider):
        if posters_prefer_local():
            return native_meta_art(meta, media_type, fallback_art=fallback_art)
        return enrich_meta_art(meta, media_type, fallback_art=fallback_art)
    if posters_prefer_local():
        return hybrid_meta_art(meta, media_type, fallback_art=fallback_art)
    return enrich_meta_art(meta, media_type, fallback_art=fallback_art)


def _prefer_item_art(art, meta, media_type='movie', fallback_art=None):
    """Merge item-native artwork without breaking the selected art source.

    Remote/TMDb/Trakt art wins when local posters are not preferred; native
    provider art then only fills missing fields. When local posters are enabled,
    native Plex/Emby/Plexio art may override.
    """
    if _meta_art_is_strict(meta):
        merged = dict(art or {})
        if merged.get('clearlogo'):
            merged['logo'] = merged.get('clearlogo')
            merged['tvshow.clearlogo'] = merged.get('clearlogo')
            merged['clearart'] = merged.get('clearlogo')
        return merged
    merged = dict(art or {})
    try:
        native = native_meta_art(meta or {}, media_type, fallback_art=fallback_art or {}) or {}
    except Exception:
        native = {}
    prefer_native = posters_prefer_local()
    for key in ('poster', 'thumb', 'icon', 'fanart', 'landscape', 'banner', 'clearlogo', 'logo', 'tvshow.clearlogo', 'clearart'):
        value = native.get(key)
        if not value:
            continue
        if prefer_native or not merged.get(key):
            merged[key] = value
    if merged.get('clearlogo'):
        merged['logo'] = merged.get('clearlogo')
        merged['tvshow.clearlogo'] = merged.get('clearlogo')
        merged['clearart'] = merged.get('clearlogo')
    if merged.get('poster') and not merged.get('fanart'):
        merged['fanart'] = merged.get('poster')
    if merged.get('fanart') and not merged.get('landscape'):
        merged['landscape'] = merged.get('fanart')
    return merged


def _provider_summary(provider):
    manifest = provider.get('manifest') or {}
    catalogs = _provider_catalogs(provider)
    movie_count = len(_provider_catalogs(provider, 'movie'))
    series_count = len(_provider_catalogs(provider, 'series'))
    parts = []
    if movie_count:
        parts.append('%d Movies catalogs' % movie_count)
    if series_count:
        parts.append('%d Series catalogs' % series_count)
    if _provider_supports_search(provider, 'movie'):
        parts.append('Movie Search')
    if _provider_supports_search(provider, 'series'):
        parts.append('Series Search')
    if not parts and catalogs:
        parts.append('%d catalogs' % len(catalogs))
    return ' • '.join(parts) or (manifest.get('description') or provider.get('manifest_url') or '')


def _group_title(media_type):
    return 'أفلام' if media_type == 'movie' else 'مسلسلات' if media_type == 'series' else media_type


def _item_fallback_art(provider=None, media_type='movie', catalog=None, name=''):
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    pname = provider.get('name') or manifest.get('name') or 'Provider'
    base_art = provider_art(pname, manifest, base_url=provider.get('base_url') or '')
    # Use the addon/provider poster for catalog items when item art is missing.
    # Category icons like 4K/search are fine for catalog folders, but not for movie/series posters.
    if catalog:
        cat_art = catalog_art(name or catalog.get('name') or catalog.get('id') or media_type, media_type, manifest, catalog)
        merged = dict(base_art)
        # Keep fanart/background hints from the catalog when available, but poster/icon from provider.
        for key in ('fanart', 'landscape', 'banner'):
            if cat_art.get(key):
                merged[key] = cat_art.get(key)
        return _without_title_logo(merged)
    return _without_title_logo(base_art)


def _without_title_logo(art):
    """v5.10.97: an item never inherits its add-on's logo as its title logo.

    Fallback art stands in for a movie or show that has none of its own; the
    provider's logo in the clearlogo slot made every such title (and the
    source search screen opened for it) show the add-on's logo instead of
    the title's own logo or name.
    """
    art = dict(art or {})
    for key in ('clearlogo', 'tvshow.clearlogo', 'logo', 'clearart'):
        art.pop(key, None)
    return art


def _content_background(art=None, fallback=None):
    art = art or {}
    fallback = fallback or {}
    return (
        art.get('fanart') or art.get('landscape') or art.get('banner') or art.get('poster') or art.get('thumb') or
        fallback.get('fanart') or fallback.get('landscape') or fallback.get('poster') or fallback.get('thumb') or
        addon_fanart()
    )


# ═════════════ Stremio hub home / source sections ═════════════

def _hub_text_blob(*values):
    parts = []
    for value in values:
        if isinstance(value, dict):
            for sub in value.values():
                if isinstance(sub, (str, int, float)):
                    parts.append(str(sub))
                elif isinstance(sub, (list, tuple)):
                    parts.extend([str(x) for x in sub if isinstance(x, (str, int, float))])
        elif isinstance(value, (list, tuple)):
            parts.extend([str(x) for x in value if isinstance(x, (str, int, float))])
        elif value is not None:
            parts.append(str(value))
    try:
        return unicodedata.normalize('NFKD', ' '.join(parts)).lower()
    except Exception:
        return ' '.join(parts).lower()


def _hub_catalog_blob(provider, catalog):
    manifest = (provider or {}).get('manifest') or {}
    return _hub_text_blob(
        (provider or {}).get('name'), (provider or {}).get('manifest_url'),
        manifest.get('name'), manifest.get('id'), manifest.get('description'), manifest.get('types'),
        (catalog or {}).get('name'), (catalog or {}).get('id'), (catalog or {}).get('type'),
        (catalog or {}).get('description'), (catalog or {}).get('genres'), (catalog or {}).get('extra'),
    )


def _hub_catalog_bucket(provider, catalog):
    catalog = catalog or {}
    media_type = str(catalog.get('type') or '').strip().lower()
    blob = _hub_catalog_blob(provider, catalog)
    live_words = (
        'live', 'iptv', 'channel', 'channels', 'tv channel', 'television',
        'قنوات', 'قناة', 'بث مباشر', 'مباشر', 'تلفزيون', 'رياضة مباشرة'
    )
    anime_words = (
        'anime', 'animu', 'anilist', 'kitsu', 'crunchyroll', 'myanimelist',
        'مانجا', 'انمي', 'أنمي', 'انيمي', 'أنيمي', 'كرتون ياباني'
    )
    turkish_words = (
        'turkish', 'turkey', 'turk', 'turkiye', 'türkiye', 'dizi', 'diziler',
        'turkish series', 'turkish drama', 'مسلسلات تركية', 'تركي', 'تركية', 'تركيا'
    )
    korean_words = (
        'korean', 'korea', 'k-drama', 'kdrama', 'k drama', 'korean drama',
        'drakor', 'korean series', 'مسلسلات كورية', 'كوري', 'كورية', 'كوريا'
    )
    arabic_words = (
        'arabic', 'arab', 'middle east', 'mena', 'egyptian', 'saudi', 'levant', 'gulf',
        'عربي', 'عربية', 'عرب', 'مصري', 'مصرية', 'خليجي', 'خليجية', 'سعودي', 'سعودية',
        'شامي', 'لبناني', 'سوري', 'افلام عربية', 'أفلام عربية', 'مسلسلات عربية'
    )
    if media_type in ('tv', 'channel', 'channels', 'live', 'iptv') or any(w in blob for w in live_words):
        return 'live'
    if any(w in blob for w in arabic_words):
        return 'arabic'
    if any(w in blob for w in turkish_words):
        return 'turkish'
    if any(w in blob for w in korean_words):
        return 'korean'
    if any(w in blob for w in anime_words):
        return 'anime'
    if media_type == 'movie':
        return 'movies'
    if media_type in ('series', 'show', 'tvshow', 'anime'):
        return 'series'
    if media_type in ('video', 'videos') and any(w in blob for w in live_words):
        return 'live'
    return 'other'


def _hub_bucket_title(bucket):
    # Arabic-canonical labels — i18n.tr() translates to English when ui_language=English.
    # Turkish/Korean previously returned English in both modes, breaking single-language UX.
    return {
        'movies': 'أفلام',
        'series': 'مسلسلات',
        'anime': 'أنمي',
        'arabic': 'عربي',
        'turkish': 'تركي',
        'korean': 'كوري',
        'live': 'IPTV',
        'other': 'كتالوجات أخرى',
    }.get(str(bucket or ''), _subfolder_title(bucket) or _custom_home_bucket_title(bucket) or str(bucket or 'كتالوجات'))


def _hub_bucket_media_type(bucket):
    if _is_subfolder_bucket(bucket):
        return _hub_bucket_media_type(_subfolder_parent(bucket))
    if bucket == 'movies':
        return 'movie'
    if bucket in ('series', 'anime', 'turkish', 'korean'):
        return 'series'
    return ''


def _hub_directory_content(bucket):
    """Kodi content contract for a rendered hub folder (not fetch typing)."""
    if _is_subfolder_bucket(bucket):
        bucket = _subfolder_parent(bucket)
    if bucket == 'movies':
        return 'movies'
    if bucket in ('series', 'anime', 'turkish', 'korean'):
        return 'tvshows'
    # Arabic/custom folders may mix movies and shows; Live contains videos.
    return 'videos'


def _hub_icon_for_bucket(bucket):
    if _is_subfolder_bucket(bucket):
        return _hub_icon_for_bucket(_subfolder_parent(bucket))
    if bucket == 'movies':
        return catalog_art('movies', 'movie')
    if bucket == 'series':
        return catalog_art('series', 'series')
    if bucket == 'anime':
        return catalog_art('anime', 'series')
    if bucket == 'arabic':
        return catalog_art('arabic movies series عربي', 'movie')
    if bucket == 'turkish':
        return catalog_art('turkish series drama', 'series')
    if bucket == 'korean':
        return catalog_art('korean drama kdrama', 'series')
    if bucket == 'live':
        return catalog_art('live tv channels', 'tv')
    return root_art('catalogs')


def _home_folders_path():
    return os.path.join(_profile_path(), 'hub_home_folders.json')


def _slugify_home_bucket(name):
    text = _hub_words(name or '')
    text = re.sub(r'[^a-z0-9\u0600-\u06FF]+', '-', text, flags=re.I).strip('-').lower()
    if not text:
        text = 'folder-%d' % int(time.time())
    return 'custom:%s' % text[:48]


def _load_custom_home_folders():
    try:
        path = _home_folders_path()
        if not xbmcvfs.exists(path):
            return []
        with open(path, 'r', encoding='utf-8') as fh:
            data = json.load(fh) or []
        rows = []
        for row in data if isinstance(data, list) else []:
            if not isinstance(row, dict):
                continue
            bucket = str(row.get('bucket') or '').strip()
            title = str(row.get('title') or '').strip()
            if bucket and title:
                rows.append({'bucket': bucket, 'title': title, 'created': int(row.get('created') or 0)})
        return rows
    except Exception:
        return []


def _save_custom_home_folders(rows):
    try:
        profile = _profile_path()
        if not xbmcvfs.exists(profile):
            xbmcvfs.mkdirs(profile)
        with open(_home_folders_path(), 'w', encoding='utf-8') as fh:
            json.dump(rows or [], fh, ensure_ascii=False, indent=2)
    except Exception:
        pass


def _home_subfolders_path():
    return os.path.join(_profile_path(), 'hub_home_subfolders.json')


def _load_home_subfolders():
    try:
        path = _home_subfolders_path()
        if not xbmcvfs.exists(path):
            return []
        with open(path, 'r', encoding='utf-8') as fh:
            data = json.load(fh) or []
        rows = []
        for row in data if isinstance(data, list) else []:
            if not isinstance(row, dict):
                continue
            parent = str(row.get('parent') or '').strip()
            bucket = str(row.get('bucket') or '').strip()
            title = str(row.get('title') or '').strip()
            if parent and bucket and title:
                rows.append({'parent': parent, 'bucket': bucket, 'title': title, 'created': int(row.get('created') or 0)})
        return rows
    except Exception:
        return []


def _save_home_subfolders(rows):
    try:
        profile = _profile_path()
        if not xbmcvfs.exists(profile):
            xbmcvfs.mkdirs(profile)
        with open(_home_subfolders_path(), 'w', encoding='utf-8') as fh:
            json.dump(rows or [], fh, ensure_ascii=False, indent=2)
    except Exception:
        pass


def _is_subfolder_bucket(bucket):
    return str(bucket or '').startswith('sub:')


def _home_subfolders(parent=''):
    parent = str(parent or '').strip()
    return [r for r in _load_home_subfolders() if (r.get('parent') or '') == parent]


def _subfolder_info(bucket=''):
    bucket = str(bucket or '').strip()
    for row in _load_home_subfolders():
        if row.get('bucket') == bucket:
            return row
    return {}


def _subfolder_parent(bucket=''):
    return (_subfolder_info(bucket) or {}).get('parent') or ''


def _subfolder_title(bucket=''):
    return (_subfolder_info(bucket) or {}).get('title') or ''


def _subfolder_bucket(parent, name):
    parent = str(parent or '').strip() or 'home'
    slug = _slugify_home_bucket(name).replace('custom:', '')
    parent_slug = re.sub(r'[^a-z0-9_-]+', '-', parent, flags=re.I).strip('-') or 'home'
    return 'sub:%s:%s' % (parent_slug[:36], slug[:40])


def _bucket_pin_count(bucket):
    pins = _load_catalog_pins()
    total = len([p for p in pins if (p.get('bucket') or '') == bucket])
    for sub in _home_subfolders(bucket):
        total += len([p for p in pins if (p.get('bucket') or '') == (sub.get('bucket') or '')])
    return total


def _catalog_source_bucket_for(bucket):
    bucket = str(bucket or '').strip()
    if _is_subfolder_bucket(bucket):
        return _subfolder_parent(bucket) or bucket
    return bucket


def _default_home_bucket_defs():
    return [
        {'bucket': 'movies', 'title': 'أفلام'},
        {'bucket': 'series', 'title': 'مسلسلات'},
        {'bucket': 'anime', 'title': 'أنمي'},
        {'bucket': 'arabic', 'title': 'عربي'},
        {'bucket': 'turkish', 'title': 'Turkish'},
        {'bucket': 'korean', 'title': 'Korean'},
        {'bucket': 'live', 'title': 'IPTV'},
    ]


def _home_bucket_defs(include_collection=False):
    rows = list(_default_home_bucket_defs())
    seen = set([r.get('bucket') for r in rows])
    for row in _load_custom_home_folders():
        if row.get('bucket') in seen:
            continue
        rows.append(row)
        seen.add(row.get('bucket'))
    if include_collection:
        rows.append({'bucket': 'collection', 'title': 'Collection'})
    return rows


def _custom_home_bucket_title(bucket):
    bucket = str(bucket or '').strip()
    if not bucket:
        return ''
    for row in _load_custom_home_folders():
        if row.get('bucket') == bucket:
            return row.get('title') or ''
    return ''


def _home_bucket_context(bucket):
    try:
        items = list(_folder_tools_context(bucket) or [])
    except Exception:
        items = []
    items += [
        # v3.9.48: per-folder meta source override. Lets the user pick
        # a meta source (TMDb, Cinemeta, or any installed provider)
        # specifically for this bucket, overriding the global default
        # set under "مصادر الميتاداتا".
        (tr('🖼️ تعديل مصدر الميتاداتا لهذا المجلد'),
         'RunPlugin(%s)' % build_url(action='bucket_meta_pick', bucket=bucket)),
        ('إضافة Sub folder داخل هذا المجلد', 'RunPlugin(%s)' % build_url(action='home_subfolder_add', parent=bucket)),
        ('إدارة Sub folders لهذا المجلد', 'Container.Update(%s)' % build_url(action='home_subfolder_manage', parent=bucket)),
        ('إضافة مجلد جديد في الهوم', 'RunPlugin(%s)' % build_url(action='home_folder_add')),
        ('إدارة مجلدات الهوم', 'Container.Update(%s)' % build_url(action='home_folder_manage')),
        ('عرض مصادر هذا المجلد', 'Container.Update(%s)' % build_url(action='hub_section', bucket=bucket, raw='1')),
    ]
    if str(bucket or '').startswith('custom:'):
        items.insert(1, ('حذف هذا المجلد من الهوم', 'RunPlugin(%s)' % build_url(action='home_folder_remove', bucket=bucket)))
    return items


# v3.9.48: per-bucket meta source overrides.
# Each home bucket (movies, series, anime, ...) can have its own
# meta source configured independently of the global default and
# the per-provider mapping. When rendering a bucket, the code sets
# the active-bucket context, and the meta source resolver consults
# that context first.
def _bucket_meta_map_path():
    return os.path.join(_profile_path(), 'bucket_meta_map.json')


def _load_bucket_meta_map():
    try:
        with xbmcvfs.File(_bucket_meta_map_path(), 'r') as fh:
            data = fh.read()
        return json.loads(data) if data else {}
    except Exception:
        return {}


def _save_bucket_meta_map(mapping):
    try:
        with xbmcvfs.File(_bucket_meta_map_path(), 'w') as fh:
            fh.write(json.dumps(mapping or {}, ensure_ascii=False, indent=2))
    except Exception:
        pass


def get_bucket_meta_source(bucket):
    """Return the meta source override for a bucket, or empty string
    if no override is set (caller should fall back to provider-level
    or global default)."""
    if not bucket:
        return ''
    return (_load_bucket_meta_map() or {}).get(bucket, '')


# Thread-local active-bucket flag the meta source layer reads to
# resolve the current rendering context. Set by hub_section before
# emission, cleared after.
_ACTIVE_BUCKET_TLS = threading.local()


def _set_active_bucket(bucket):
    _ACTIVE_BUCKET_TLS.bucket = bucket or ''


def _get_active_bucket():
    return getattr(_ACTIVE_BUCKET_TLS, 'bucket', '') or ''


def bucket_meta_pick(bucket=''):
    """Open a select dialog to assign a meta source to a bucket."""
    bucket = (bucket or '').strip()
    if not bucket:
        notify(tr('لم يتم تحديد المجلد'))
        return
    # Build the list of source options: auto (use global), TMDb Helper,
    # Cinemeta, and any installed Stremio provider that declares the
    # meta resource. All labels go through tr() so English users see
    # English text.
    options = [
        ('auto', tr('استخدام الإعداد العام (افتراضي)')),
        ('tmdb_helper', tr('TMDb Helper (يتطلب تثبيت الإضافة)')),
        ('cinemeta', tr('Cinemeta (Stremio الرسمي)')),
    ]
    try:
        for p in store.list_providers() or []:
            manifest = p.get('manifest') or {}
            resources = manifest.get('resources') or []
            supports_meta = False
            for r in resources:
                if isinstance(r, str) and r == 'meta':
                    supports_meta = True; break
                if isinstance(r, dict) and r.get('name') == 'meta':
                    supports_meta = True; break
            if supports_meta and p.get('id'):
                options.append((p.get('id'), tr('مصدر: %s') % (p.get('name') or p.get('id'))))
    except Exception:
        pass
    current = get_bucket_meta_source(bucket)
    labels = []
    for sid, name in options:
        marker = '  ✓' if sid == current or (not current and sid == 'auto') else ''
        labels.append(name + marker)
    bucket_title = _hub_bucket_title(bucket) or bucket
    idx = xbmcgui.Dialog().select(tr('مصدر الميتاداتا لمجلد: %s') % bucket_title, labels)
    if idx < 0:
        return
    chosen_id, chosen_name = options[idx]
    mapping = _load_bucket_meta_map()
    if chosen_id == 'auto':
        mapping.pop(bucket, None)
    else:
        mapping[bucket] = chosen_id
    _save_bucket_meta_map(mapping)
    try:
        from .dexhub.client import purge_meta_cache as _purge
        _purge()
    except Exception:
        pass
    notify(tr('تم: %s ← %s') % (bucket_title, chosen_name))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass


def home_folder_add():
    keyboard = xbmc.Keyboard('', tr('اسم مجلد الهوم الجديد'))
    keyboard.doModal()
    if not keyboard.isConfirmed():
        return end_dir(content='files', cache=False)
    title = keyboard.getText().strip()
    if not title:
        return end_dir(content='files', cache=False)
    rows = _load_custom_home_folders()
    bucket = _slugify_home_bucket(title)
    existing = set([r.get('bucket') for r in rows] + [r.get('bucket') for r in _default_home_bucket_defs()])
    base = bucket
    i = 2
    while bucket in existing:
        bucket = '%s-%d' % (base, i)
        i += 1
    rows.append({'bucket': bucket, 'title': title, 'created': int(time.time())})
    _save_custom_home_folders(rows)
    notify(tr('تمت إضافة مجلد الهوم'))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return end_dir(content='files', cache=False)


def home_folder_remove(bucket=''):
    bucket = str(bucket or '').strip()
    if not bucket.startswith('custom:'):
        notify(tr('لا يمكن حذف المجلدات الأساسية'))
        return end_dir(content='files', cache=False)
    rows = [r for r in _load_custom_home_folders() if r.get('bucket') != bucket]
    _save_custom_home_folders(rows)
    sub_buckets = set([r.get('bucket') for r in _home_subfolders(bucket)])
    _save_home_subfolders([r for r in _load_home_subfolders() if (r.get('parent') or '') != bucket])
    pins = [p for p in _load_catalog_pins() if (p.get('bucket') or '') != bucket and (p.get('bucket') or '') not in sub_buckets]
    _save_catalog_pins(pins)
    notify(tr('تم حذف مجلد الهوم'))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return end_dir(content='files', cache=False)


def home_subfolder_add(parent=''):
    parent = str(parent or '').strip()
    if not parent:
        return end_dir(content='files', cache=False)
    keyboard = xbmc.Keyboard('', tr('اسم Sub folder'))
    keyboard.doModal()
    if not keyboard.isConfirmed():
        return end_dir(content='files', cache=False)
    title = keyboard.getText().strip()
    if not title:
        return end_dir(content='files', cache=False)
    rows = _load_home_subfolders()
    bucket = _subfolder_bucket(parent, title)
    existing = set([r.get('bucket') for r in rows] + [r.get('bucket') for r in _home_bucket_defs(include_collection=False)])
    base = bucket
    i = 2
    while bucket in existing:
        bucket = '%s-%d' % (base, i)
        i += 1
    rows.append({'parent': parent, 'bucket': bucket, 'title': title, 'created': int(time.time())})
    _save_home_subfolders(rows)
    notify(tr('تمت إضافة Sub folder'))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return end_dir(content='files', cache=False)


def home_subfolder_remove(bucket=''):
    bucket = str(bucket or '').strip()
    if not _is_subfolder_bucket(bucket):
        return end_dir(content='files', cache=False)
    _save_home_subfolders([r for r in _load_home_subfolders() if (r.get('bucket') or '') != bucket])
    pins = [p for p in _load_catalog_pins() if (p.get('bucket') or '') != bucket]
    _save_catalog_pins(pins)
    notify(tr('تم حذف Sub folder'))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass
    return end_dir(content='files', cache=False)


def home_subfolder_manage(parent=''):
    parent = str(parent or '').strip()
    title = _hub_bucket_title(parent)
    add_item(tr('+ إضافة Sub folder'), build_url(action='home_subfolder_add', parent=parent), art=root_art('add'), info={'title': tr('إضافة Sub folder'), 'plot': tr('أضف مجلدًا فرعيًا داخل %s ثم ثبّت فيه كتالوجات من Sources') % title})
    pins = _load_catalog_pins()
    subs = _home_subfolders(parent)
    if not subs:
        add_item(tr('[COLOR yellow]لا توجد Sub folders بعد[/COLOR]'), build_url(action='home_subfolder_add', parent=parent), art=root_art('add'), info={'title': tr('لا توجد Sub folders'), 'plot': tr('اضغط لإضافة مجلد فرعي داخل %s') % title})
    for row in subs:
        bucket = row.get('bucket') or ''
        stitle = row.get('title') or _hub_bucket_title(bucket)
        pins_count = len([p for p in pins if (p.get('bucket') or '') == bucket])
        ctx = [
            ('حذف Sub folder', 'RunPlugin(%s)' % build_url(action='home_subfolder_remove', bucket=bucket)),
            ('عرض مصادر هذا Sub folder', 'Container.Update(%s)' % build_url(action='hub_section', bucket=bucket, raw='1')),
        ]
        add_item('%s (%d)' % (stitle, pins_count), build_url(action='hub_section', bucket=bucket), art=_hub_icon_for_bucket(bucket), info={'title': stitle, 'plot': tr('Sub folder داخل %s') % title}, context_menu=ctx)
    return end_dir(content='files', cache=False)


def home_folder_manage():
    add_item(tr('+ إضافة مجلد جديد'), build_url(action='home_folder_add'), art=root_art('add'), info={'title': tr('إضافة مجلد جديد'), 'plot': tr('أضف مجلدًا جديدًا في الصفحة الرئيسية ثم ثبّت داخله كتالوجات من Sources')})
    pins = _load_catalog_pins()
    for row in _home_bucket_defs(include_collection=False):
        bucket = row.get('bucket') or ''
        title = row.get('title') or _hub_bucket_title(bucket)
        pins_count = _bucket_pin_count(bucket)
        ctx = _home_bucket_context(bucket)
        add_item('%s (%d)' % (title, pins_count), build_url(action='hub_section', bucket=bucket), art=_hub_icon_for_bucket(bucket), info={'title': title, 'plot': tr('مجلد هوم مخصص — ثبّت داخله كتالوجات من Sources')}, context_menu=ctx)
    return end_dir(content='files', cache=False)


def _hub_catalog_entries(bucket=None, provider_id=None):
    # v3.9.63: defensive wrapping. The service-thread pinned-provider
    # sync calls this with bucket=None to enumerate every catalog
    # across every provider. If even one provider has a malformed
    # manifest (missing 'name', non-string catalog id, etc.), the
    # naive code path raised "list index out of range" deep inside
    # _provider_catalogs or sort_key tuple unpacking, killing the
    # entire enumeration. Each provider is now isolated so one bad
    # row can't kill the whole list.
    rows = []
    try:
        providers = [store.get_provider(provider_id)] if provider_id else store.list_providers()
    except Exception as exc:
        try:
            xbmc.log('[DexHub] _hub_catalog_entries: list_providers failed: %s' % exc, xbmc.LOGWARNING)
        except Exception:
            pass
        return []
    for provider in [p for p in providers if p]:
        try:
            catalogs = _provider_catalogs(provider) or []
        except Exception as exc:
            try:
                xbmc.log('[DexHub] _hub_catalog_entries: provider_catalogs failed for %s: %s' % (
                    (provider or {}).get('name') or '?', exc), xbmc.LOGWARNING)
            except Exception:
                pass
            continue
        for catalog in catalogs:
            if not isinstance(catalog, dict):
                continue
            try:
                b = _hub_catalog_bucket(provider, catalog)
            except Exception:
                b = 'other'
            if bucket and b != bucket:
                continue
            rows.append((provider, catalog, b))

    def _sort_key(entry):
        try:
            provider, catalog, b = entry
            name = '%s %s' % (
                (catalog.get('name') if isinstance(catalog, dict) else None) or
                (catalog.get('id') if isinstance(catalog, dict) else None) or '',
                (provider.get('name') if isinstance(provider, dict) else None) or ''
            )
            order = {'movies': 0, 'series': 1, 'anime': 2, 'arabic': 3, 'turkish': 4,
                     'korean': 5, 'live': 6, 'other': 9}.get(b, 8)
            return (order, name.lower())
        except Exception:
            # Anything weird: push it to the end with the original label.
            return (99, '')

    try:
        return sorted(rows, key=_sort_key)
    except Exception:
        return rows


# Clean hub layer: users see friendly rows like Trending/Popular instead of raw
# Stremio catalogue names. Raw catalogues stay available in Sources.
def _hub_provider_rank(provider):
    blob = _hub_text_blob((provider or {}).get('name'), ((provider or {}).get('manifest') or {}).get('name'), ((provider or {}).get('manifest') or {}).get('id'), (provider or {}).get('manifest_url'))
    rank = 50
    if 'trakt' in blob:
        rank = min(rank, 0)
    if 'tmdb' in blob or 'the movie database' in blob:
        rank = min(rank, 5)
    if 'cinemeta' in blob:
        rank = min(rank, 10)
    if 'dexworld' in blob or 'dex hub' in blob or 'dexhub' in blob:
        rank = min(rank, 15)
    if ('plexio' in blob or 'plex' in blob or 'streambridge' in blob or
            'emby' in blob or 'silo' in blob):
        rank = min(rank, 20)
    return rank


def _hub_words(*values):
    blob = _hub_text_blob(*values)
    # Normalize common separators so simple substring checks catch ids like
    # top_rated, latest-movies, new.episodes, etc.
    return re.sub(r'[\W_]+', ' ', blob, flags=re.U).strip()


