def _search_incomplete_footer(failed, silent, ceiling):
    """Row shown when some sources did not contribute to the results."""
    if not failed and not silent:
        return
    bits = []
    if silent:
        bits.append(tr('%d لم ترد خلال %ds') % (len(silent), int(ceiling)))
    if failed:
        bits.append(tr('%d فشلت') % len(failed))
    names = ', '.join((silent + sorted(failed))[:6])
    add_item(tr('[COLOR grey]⚠ نتائج ناقصة: %s[/COLOR]') % ' • '.join(bits),
             build_url(action='hub_search_menu'), is_folder=False,
             art=root_art('search'),
             info={'title': 'نتائج ناقصة',
                   'plot': tr('هذه المصادر لم تُضِف نتائج لهذا البحث:\n%s\n\n'
                           'ارفع مهلة البحث من الإعدادات إن كانت بطيئة، أو '
                           'تحقق من أنها تدعم البحث أصلاً.') % (names or '-')})


def search_selftest(query=''):
    """Prove, source by source, that every provider actually answers a search.

    v3.9.197 — the honest answer to "does each of my sources really return
    results?". Runs ONE real query against every searchable catalog of every
    provider (servers included, since they are providers now) and reports what
    each one did: how many results, how long it took, or exactly why it
    contributed nothing.
    """
    query = (query or '').strip() or 'matrix'
    providers = [p for p in (store.list_providers() or []) if p] + _server_providers()

    jobs, skipped = [], []
    for provider in providers:
        manifest = provider.get('manifest') or {}
        cat_types = {c.get('type') for c in (manifest.get('catalogs') or [])
                     if isinstance(c, dict) and c.get('type')}
        found = False
        for media_type in sorted(cat_types | set(manifest.get('types') or []) | {'movie', 'series'}):
            for cat in _provider_catalogs(provider, media_type):
                if _catalog_supports_search(cat):
                    jobs.append((provider, cat, media_type))
                    found = True
        if not found:
            skipped.append(provider.get('name') or '?')

    def _probe(job):
        provider, cat, media_type = job
        started = time.time()
        try:
            if provider.get('backend') in SERVER_BACKENDS:
                page = _server_catalog(provider, media_type, extra={'search': query})
            else:
                page = fetch_catalog(provider, media_type, cat.get('id'),
                                     extra={'search': query},
                                     timeout_override=fast_timeout('search'))
            metas = (page or {}).get('metas') or []
            return {'ok': True, 'count': len(metas), 'secs': time.time() - started,
                    'sample': (metas[0].get('name') if metas else ''),
                    'ids': sorted(_meta_identity(metas[0]))[:3] if metas else []}
        except Exception as exc:
            return {'ok': False, 'error': str(exc)[:70], 'secs': time.time() - started}

    per_provider = {}
    if jobs:
        for job, result in iter_parallel(_probe, jobs):
            name = job[0].get('name') or '?'
            row = per_provider.setdefault(name, {'count': 0, 'secs': 0.0, 'errors': [],
                                                 'cats': 0, 'sample': '', 'ids': []})
            row['cats'] += 1
            row['secs'] = max(row['secs'], (result or {}).get('secs') or 0.0)
            if not (result or {}).get('ok'):
                row['errors'].append(result.get('error') or 'error')
            else:
                row['count'] += result.get('count') or 0
                if not row['sample'] and result.get('sample'):
                    row['sample'] = result['sample']
                    row['ids'] = result.get('ids') or []

    healthy = sum(1 for r in per_provider.values() if r['count'] > 0)
    add_item(tr('[B]فحص البحث: "%s"[/B]   [COLOR lightgrey]%d/%d مصدر أجاب بنتائج[/COLOR]')
             % (query, healthy, len(per_provider) or 0),
             build_url(action='search_selftest'), is_folder=False,
             art=root_art('search'),
             info={'title': 'فحص البحث',
                   'plot': 'اضغط لإعادة الفحص. كل مصدر أدناه جُرِّب باستعلام حقيقي.'})

    for name in sorted(per_provider, key=lambda k: (-per_provider[k]['count'], k)):
        row = per_provider[name]
        if row['count'] > 0:
            mark = '[COLOR lime]✔[/COLOR]'
            detail = tr('%d نتيجة • %.1fs') % (row['count'], row['secs'])
        elif row['errors']:
            mark = '[COLOR red]✘[/COLOR]'
            detail = row['errors'][0]
        else:
            mark = '[COLOR yellow]○[/COLOR]'
            detail = tr('أجاب بلا نتائج • %.1fs') % row['secs']
        plot = [tr('المصدر: %s') % name, tr('كتالوجات البحث: %d') % row['cats'], detail]
        if row['sample']:
            plot.append(tr('عيّنة: %s') % row['sample'])
        if row['ids']:
            plot.append(tr('المعرّفات: %s') % ', '.join(row['ids']))
        add_item('%s  %s   [COLOR grey]%s[/COLOR]' % (mark, name, detail),
                 build_url(action='search_selftest'), is_folder=False,
                 art=root_art('search'),
                 info={'title': name, 'plot': '\n'.join(plot)})

    for name in sorted(skipped):
        add_item(tr('[COLOR grey]— %s   (لا يدعم البحث)[/COLOR]') % name,
                 build_url(action='search_selftest'), is_folder=False,
                 art=root_art('search'),
                 info={'title': name,
                       'plot': 'لا يعلن هذا المصدر أي كتالوج قابل للبحث، أو أن '
                               'كتالوجه يشترط خياراً إجبارياً آخر (نوعاً مثلاً) '
                               'فلا يمكن البحث فيه باستعلام مجرد.'})

    xbmc.log('[DexHub] search selftest "%s": %d/%d providers returned results; '
             'no searchable catalog: %s' % (query, healthy, len(per_provider),
                                            ', '.join(skipped) or 'none'), xbmc.LOGINFO)
    return end_dir(content='files', cache=False)


def _hub_search_unified_render(query, providers_list, include_tmdb=False, collect=None):
    """v3.9.46: run a parallel search across every media type each
    provider supports, then render the results grouped by media type.

    Two design decisions worth noting. First, the loading dialog reuses
    the same SourcesLoadingDialog from the source picker so the user
    sees the same cancel and satisfy buttons they already understand.
    Pressing "اكتفي بالموجود" stops the search early and renders
    whatever results have already arrived; pressing "إلغاء" aborts
    cleanly. Second, the result rendering groups items by media type
    with section headers so Movies, Series, Anime, and other types
    appear as distinct labelled blocks in one continuous page rather
    than forcing the user to navigate three separate sub-pages.
    """
    # Build the search job list across every searchable catalog in
    # every media type each provider declares support for.
    # v3.9.225: providers blacklisted while the Plex step was starving the scan
    # were punished for someone else's slowness. Give them a clean slate.
    try:
        from .dexhub.client import provider_health_pause
        provider_health_pause(0)
    except Exception:
        pass

    # Connected servers are appended to the provider list itself: from here on
    # nothing in the search knows or cares that they are not Stremio addons.
    providers_list = list(providers_list or []) + _server_providers(cached=True) + _dexworld_iptv_providers()

    jobs = []
    if include_tmdb:
        jobs.append(({
            'id': '__tmdb_search__', 'name': 'TMDb', 'backend': 'tmdb',
            'manifest': {'types': ['movie', 'series'], 'catalogs': []},
        }, {'id': '__tmdb_search__', 'name': 'TMDb'}, 'mixed'))
    # v5.10.28: the same addon can be registered twice through two transports
    # (the URL Nuvio's account synced and the URL Stremio's account synced).
    # Both answer the same catalogs, so the twin burned a worker slot and
    # returned duplicate rows. Skip a provider whose manifest id AND catalog
    # list exactly match one already scheduled; file order decides which row
    # wins, and differently configured instances of the same addon stay.
    _twin_sigs = set()

    def _is_twin(row):
        m = row.get('manifest') or {}
        mid = str(m.get('id') or '').strip().lower()
        if not mid or row.get('backend'):
            return False
        try:
            sig = (mid, json.dumps(m.get('catalogs') or [], sort_keys=True, ensure_ascii=False))
        except Exception:
            return False
        if sig in _twin_sigs:
            return True
        _twin_sigs.add(sig)
        return False

    for provider in providers_list:
        if _is_twin(provider):
            try:
                xbmc.log('[DexHub] search: skipping duplicate transport of %s'
                         % (provider.get('name') or provider.get('id') or '?'), xbmc.LOGINFO)
            except Exception:
                pass
            continue
        manifest = provider.get('manifest') or {}
        # v3.9.194: derive the types from the catalogs THEMSELVES, not from
        # manifest['types']. Addons routinely ship searchable catalogs whose
        # type is missing from that list (anime, tv, custom types) — every one
        # of them used to be skipped silently, which is the single biggest
        # reason search "never returns everything".
        cat_types = set()
        for cat in (manifest.get('catalogs') or []):
            if isinstance(cat, dict) and cat.get('type'):
                cat_types.add(cat.get('type'))
        for media_type in sorted(cat_types | set(manifest.get('types') or []) | {'movie', 'series'}):
            for cat in _provider_catalogs(provider, media_type):
                if _catalog_supports_search(cat):
                    jobs.append((provider, cat, media_type))

    jobs = _fair_search_job_order(jobs)
    # A manifest can expose the same searchable catalog through both its
    # ``types`` declaration and catalog list (or repeat the catalog verbatim).
    # Collapse identical requests before they consume a worker/network slot.
    _job_signatures = set()
    _unique_jobs = []
    for _job in jobs:
        _provider, _catalog, _media_type = _job
        _server = (_provider or {}).get('_server') or {}
        _provider_key = (
            (_provider or {}).get('id') or
            (_provider or {}).get('base_url') or
            (_server or {}).get('id') or
            (_server or {}).get('url') or
            (_provider or {}).get('name') or ''
        )
        _signature = (
            str(_provider_key).strip().casefold(),
            str((_catalog or {}).get('id') or '').strip().casefold(),
            str(_media_type or '').strip().casefold(),
        )
        if _signature in _job_signatures:
            continue
        _job_signatures.add(_signature)
        _unique_jobs.append(_job)
    jobs = _unique_jobs

    # Plex servers join the SAME parallel search — one job per server,
    # results interleaved into the type sections below.

    if not jobs:
        if collect is not None:
            collect['status'] = 'no_catalogs'
            return None
        notify(tr('لا توجد كتالوجات تدعم البحث في مصادرك'))
        return end_dir(content='files', cache=False)

    results_by_type = {}
    seen_ids = set()
    kept_count = [0]      # counts RESULTS; seen_ids counts ID identities

    def _job_cache_key(job):
        _p, _c, _mt = job
        _server = (_p or {}).get('_server') or {} if isinstance(_p, dict) else {}
        _pn = (_p if isinstance(_p, str) else
               (_p.get('id') or _p.get('base_url') or
                _server.get('id') or _server.get('url') or
                _p.get('name') or '?'))
        _cn = (_c or {}).get('id') or (_c or {}).get('name') or ''
        return 'job|%s|%s|%s|%s' % (
            query.strip().casefold(), str(_pn).strip().casefold(),
            str(_cn).strip().casefold(), str(_mt).strip().casefold())

    def _run_one(job):
        _ck = _job_cache_key(job)
        _hit = _search_cache_get(_ck)
        if _hit is not None:
            return _hit

        def _keep(value):
            # Never cache a failure: the next attempt must be allowed to retry.
            if not isinstance(value, Exception):
                _search_cache_put(_ck, value)
            return value

        provider, cat, media_type = job
        if provider.get('backend') == 'tmdb':
            try:
                from . import tmdb_direct
                return _keep({'metas': _tmdb_direct.search_metas(query, limit=40)})
            except Exception as exc:
                return exc
        if provider.get('backend') in SERVER_BACKENDS:
            try:
                return _keep(_server_catalog(provider, media_type,
                                             extra={'search': query}))
            except Exception as exc:
                return exc
        if provider.get('backend') == 'dwiptv':
            try:
                found = fetch_catalog(provider, media_type, cat.get('id'), extra={'search': query},
                                      timeout_override=min(fast_timeout('search'), float(_ceiling))) or {}
                metas = [dict(m, _backend='dwiptv') for m in found.get('metas') or [] if isinstance(m, dict)]
                return _keep(dict(found, metas=metas))
            except Exception as exc:
                return exc
        try:
            # v4.7.1: send ONLY the declared `search` extra — Stremio parity.
            # stremio-core never attaches undeclared props to the extra path
            # segment; our extra 'limit' made strict addon routers miss the
            # search handler and fall through to the UNFILTERED catalog —
            # the alphabetical "letter A" results, on the very addons that
            # search fine inside Stremio itself.
            return _keep(fetch_catalog(
                provider, media_type, cat.get('id'),
                extra={'search': query},
                timeout_override=min(fast_timeout('search'), float(_ceiling)),
            ))
        except Exception as exc:
            return exc

    # Hard ceiling protects against any combination of slow providers keeping
    # the dialog open forever. The user can still dismiss earlier with the
    # satisfy/cancel buttons, so a generous default costs nothing: at 20s the
    # slower Arabic catalogs were being cut off before they answered.
    _ceiling = _get_int_setting('search_ceiling_seconds', 6, minimum=3, maximum=60)
    was_cancelled = False
    answered = set()
    failed = {}
    relevant_sources = set()
    _job_order = {id(job): pos for pos, job in enumerate(jobs)}

    # v4.6.0: hand the full ordered provider list to the dashboard so every
    # provider is visible from the first paint (waiting → done + count).
    _loader_names = []
    for _job in jobs:
        try:
            _nm = str((_job[0] or {}).get('name') or '').strip()
        except Exception:
            _nm = ''
        if _nm and _nm not in _loader_names:
            _loader_names.append(_nm)
    def _ui_rows_of(by_type):
        """The result rows of the providers answered so far (v5.10.117: the
        Home's search page shows them while the others still answer)."""
        type_order = ['movie', 'series', 'anime', 'person', 'tv', 'channel']
        type_labels = {
            'movie': 'أفلام',
            'series': 'مسلسلات',
            'anime': 'أنمي',
            'person': 'أشخاص',
            'tv': 'قنوات',
            'channel': 'قنوات',
        }
        _all_types = set(by_type.keys())
        ordered_types = [t for t in type_order if t in _all_types] + \
                        [t for t in _all_types if t not in type_order]
        ui_rows = []

        for type_key in ordered_types:
            # Stable, request-order sections (Nuvio-style): the layout no longer
            # depends on which provider happened to answer first.
            batches = sorted(by_type.get(type_key, []), key=lambda b: b[0])
            batches = [(b[1], b[2]) for b in batches]
            # v4.8.3: count AFTER the relevance filter below, so the header never
            # promises rows the section no longer shows.
            _rows = []
            for _b_idx, (_prov, _metas) in enumerate(batches):
                for _m_idx, _meta in enumerate(_metas):
                    _rows.append((_prov, _meta, _b_idx, _m_idx))
            _scored, _dropped = _search_match.filter_relevant(
                _rows, query, lambda r: r[1], fallback_when_empty=False)
            _kept = [row + (score,) for row, score in _scored]
            type_count = len(_kept)
            if type_count == 0:
                continue
            # v4.7.2: ONE merged, relevance-ranked stream per section — Stremio,
            # Plex and Emby results interleave by match score instead of by
            # which provider happened to answer first (stable on ties).
            # v4.8.4: the relevance filter is search_match.filter_relevant now —
            # one implementation for both search paths instead of the two inline
            # copies that had to be patched separately.
            if _dropped:
                xbmc.log('[DexHub] search: dropped %d irrelevant row(s) of %d in "%s"'
                         % (_dropped, _dropped + len(_kept), type_key), xbmc.LOGINFO)
            _flat = sorted(_kept, key=lambda row: (-row[4], _hub_provider_rank(row[0]), row[2], row[3]))
            for provider, meta, _b_idx, _m_idx, _score in _flat:
                provider_name = provider.get('name') or ''
                if True:
                    meta_id = meta.get('id') or ''
                    title = meta.get('name') or meta.get('title') or meta_id
                    year_raw = meta.get('year') or meta.get('releaseInfo') or ''
                    year_text = ''
                    year_int = None
                    try:
                        year_match = YEAR_RE.search(str(year_raw))
                        if year_match:
                            year_int = int(year_match.group(1))
                            year_text = str(year_int)
                    except Exception:
                        pass
                    display = title if not year_text else '%s  •  %s' % (title, year_text)
                    try:
                        # v3.9.206: this used to pass extract_ids(meta) as the
                        # media_type and a base_url kwarg the function never had, so
                        # it raised TypeError on EVERY row and silently fell back to
                        # the generic search icon — which is why no result, Plex and
                        # Emby included, ever showed its poster.
                        _search_fallback = catalog_art('search', type_key) or {}
                        _poster_fallback = media_path(
                            'default_series_poster.png'
                            if type_key in ('series', 'anime', 'tv', 'show')
                            else 'default_movie_poster.png')
                        _search_fallback = dict(_search_fallback)
                        _search_fallback['poster'] = _poster_fallback
                        _search_fallback['thumb'] = _poster_fallback
                        art = (native_meta_art(
                            meta, media_type=(meta.get('type') or type_key or 'movie'),
                            fallback_art=_search_fallback)
                            or _search_fallback)
                    except Exception:
                        art = catalog_art('search', type_key) or {}
                    try:
                        _meta_mem_put(type_key, meta_id, meta, source_provider_id=provider.get('id') or '')
                    except Exception:
                        pass
                    _ids = extract_ids(meta)
                    # v5.10.302: Like Nuvio: the profile's poster pattern (screen search, like Nuvio)
                    if type_key != 'person' and meta.get('_backend') not in SERVER_BACKENDS:
                        try:
                            from .meta_policy import nuvio_parity as _nv_parity
                            if _nv_parity():
                                from .dexhub import nuvio_poster as _nv_poster
                                _nv_card = _nv_poster.apply(dict(meta, poster=art.get('poster') or ''), 'search',
                                                            media_type=type_key, extra_ids=_ids)
                                if _nv_card.get('_nuvio_custom_poster'):
                                    art = dict(art, poster=_nv_card['poster'], thumb=_nv_card['poster'])
                        except Exception:
                            pass
                    if type_key == 'person':
                        _person_id = str(meta.get('person_id') or meta_id).split(':')[-1]
                        path = build_url(
                            action='people_filmography', person_id=_person_id,
                            name=title)
                        is_folder = True
                    else:
                        path, is_folder = _content_click_path(
                            media_type=type_key, canonical_id=meta_id, title=title,
                            tmdb_id=_ids.get('tmdb_id') or '', imdb_id=_ids.get('imdb_id') or '', tvdb_id=_ids.get('tvdb_id') or '',
                            source_provider_id=provider.get('id') or '', ui_seed=art)
                    info_dict = {
                        'title': title,
                        'plot': meta.get('description') or '',
                        'mediatype': ('movie' if type_key == 'movie' else
                                      ('video' if type_key == 'person' else 'tvshow')),
                    }
                    if year_int:
                        info_dict['year'] = year_int
                    _row_kwargs = {}
                    if meta.get('_backend') in SERVER_BACKENDS:
                        # The only server-specific lines left in the search: the row
                        # plays from the server instead of opening the generic meta
                        # page, and keeps its branded "PLEX • server • 26.0 GB" line.
                        path, is_folder = _server_row_path(meta)
                        _row_kwargs['label2'] = meta.get('_label2') or ''
                        _row_kwargs['properties'] = None if is_folder else {'IsPlayable': 'true'}
                    elif meta.get('_backend') == 'dwiptv':
                        # v5.10.239: from the DexWorld IPTV subscription
                        path, is_folder = _dexworld_vod_path(meta, type_key)
                        _row_kwargs['label2'] = 'DexWorld IPTV'
                    ui_rows.append({
                        'title': title, 'year': year_text, 'media_type': type_key,
                        'plot': info_dict.get('plot') or '',
                        'rating': meta.get('imdbRating') or meta.get('rating') or '',
                        'genre': meta.get('genres') or meta.get('genre') or [],
                        'runtime': meta.get('runtime') or '',
                        'poster': art.get('poster') or art.get('thumb') or '',
                        'fanart': art.get('fanart') or art.get('landscape') or '',
                        'landscape': art.get('landscape') or art.get('fanart') or '',
                        'clearlogo': art.get('clearlogo') or art.get('logo') or '',
                        'path': path, 'is_folder': '1' if is_folder else '',
                        'source_label': (
                            ('TMDb  •  %s' % (meta.get('known_for_department') or tr('أعمال معروفة')))
                            if type_key == 'person' else
                            (_row_kwargs.get('label2') or provider_name)),
                        'is_anime': type_key == 'anime',
                        'is_person': type_key == 'person',
                        # v5.10.102: for the Home's search page
                        'imdb_id': _ids.get('imdb_id') or '',
                        'tmdb_id': _ids.get('tmdb_id') or '',
                        'tvdb_id': _ids.get('tvdb_id') or '',
                        'server': bool(meta.get('_backend') in SERVER_BACKENDS),
                        'iptv': meta.get('_backend') == 'dwiptv',
                        'score': _score,
                    })

        return ui_rows

    _partial = collect.get('partial') if collect is not None else None
    _partial_at = [0.0]
    if collect is not None:
        # v5.10.102: the Home's search page shows the progress itself
        _search_loader = _QuietSearchLoader(len(jobs), collect.get('progress'),
                                            collect.get('should_stop'))
    else:
        _search_loader = SourcesLoadingDialog(
            title=tr('بحث: %s') % query,
            fanart='',
            provider_count=len(jobs),
            provider_names=_loader_names,
        )
    with _search_loader as loader:
        # Search owns a small lane that cannot block source discovery after the
        # user clicks a result. Polling (rather than a fixed sleep) also lets us
        # render as soon as the useful responses settle.
        _search_race = start_parallel_race(
            _run_one, jobs,
            workers=max(2, min(4, parallel_workers(), len(jobs))),
            timeout=float(_ceiling), lane='search',
        )

        for idx, (job, result) in enumerate(
                _iter_search_race(
                    _search_race, lambda: kept_count[0],
                    lambda: bool(relevant_sources),
                    should_stop=loader.is_stopped,
                    on_ready=lambda: loader.mark_sufficient(auto_seconds=0),
                    # v5.10.28: the module defaults (12 rows / 0.3s quiet /
                    # 1.2s fallback) let the first fast addon (Cinemeta)
                    # end the race before the self-hosted Nuvio bridge and
                    # the Arabic catalogs had even started; the footer then
                    # blamed them for "not answering". Settle 1.5s after the
                    # last provider that added rows, bounded by the ceiling.
                    real_goal=max(48, 12 * len(jobs)),
                    quiet_seconds=1.5,
                    fallback_seconds=float(_ceiling),
                ), start=1):
            if loader.is_stopped():
                break
            provider, cat, media_type = job
            loader.update(
                provider_name=provider.get('name') or '',
                index=idx,
                status=tr('البحث في المصادر...'),
                sub_status=('%d %s' % (kept_count[0], tr('نتيجة'))) if kept_count[0] else '',
            )
            _pname = (provider.get('name') if isinstance(provider, dict) else str(provider)) or '?'
            if isinstance(result, Exception):
                failed[_pname] = str(result)[:90]
                continue
            answered.add(_pname)
            if not result:
                continue
            raw_metas = [meta for meta in ((result or {}).get('metas') or [])
                         if isinstance(meta, dict) and meta.get('id')]
            _scored_raw, _dropped_raw = _search_match.filter_relevant(
                raw_metas, query, lambda meta: meta, fallback_when_empty=False)
            relevant_metas = [meta for meta, _score in _scored_raw]
            if _dropped_raw:
                xbmc.log('[DexHub] search: dropped %d irrelevant row(s) of %d from %s'
                         % (_dropped_raw, len(raw_metas), _pname), xbmc.LOGINFO)
            if relevant_metas and provider.get('backend') != 'tmdb':
                relevant_sources.add(_pname)
            metas_by_type = {}
            for meta in relevant_metas:
                if not meta.get('id'):
                    continue          # unroutable: no id to open it with
                actual_type = meta.get('type') or (media_type if media_type != 'mixed' else 'movie')
                # v5.10.28: TMDb movie and TV ids are separate number spaces,
                # so identities are qualified by type; a folded title+year
                # key lets opaque-id rows (Arabic addons) merge with the
                # same title from another provider.
                _norm_type = ('person' if str(actual_type).lower() == 'person'
                              else ('tv' if _is_series_media(actual_type)
                                    else 'movie'))
                identity = set(_meta_identity(meta))
                _t_key = _clean_title_for_key(meta.get('name') or meta.get('title') or '')
                _y_key = _year_for_key(meta)
                if _t_key and _y_key and len(_t_key) >= 3:
                    identity.add('title:%s:%s' % (_t_key, _y_key))
                identity = {'%s|%s' % (_norm_type, k) for k in identity}
                if meta.get('_backend') in SERVER_BACKENDS or meta.get('_backend') == 'dwiptv':
                    # A copy on the user's OWN server is a different class of
                    # result — it always renders, and it never suppresses the
                    # addon rows for the same title (those still carry streams).
                    kept_count[0] += 1
                    metas_by_type.setdefault(actual_type, []).append(meta)
                    continue
                if identity & seen_ids:
                    continue          # same title, different ID namespace
                seen_ids |= identity
                kept_count[0] += 1
                metas_by_type.setdefault(actual_type, []).append(meta)
            if not metas_by_type:
                continue
            batch_rank = _job_order.get(id(job), idx)
            added = 0
            for actual_type, metas_new in metas_by_type.items():
                if provider.get('backend') not in SERVER_BACKENDS and provider.get('backend') not in ('tmdb', 'dwiptv'):
                    try:
                        from . import meta_source as _meta_source
                        metas_new = _meta_source.override_metas_batch(
                            provider, actual_type, metas_new)
                    except Exception:
                        pass
                results_by_type.setdefault(actual_type, []).append(
                    (batch_rank, provider, metas_new))
                added += len(metas_new)
            loader.add_results(added, provider_name=_pname,
                               unique_total=kept_count[0])
            if _partial is not None and added and not loader.is_stopped():
                _p_now = time.monotonic()
                if _p_now - _partial_at[0] >= 0.8:
                    _partial_at[0] = _p_now
                    try:
                        _partial(_ui_rows_of(dict((k, list(v)) for k, v in results_by_type.items())))
                    except Exception:
                        import traceback as _tb
                        xbmc.log('[DexHub] search: early results failed:\n%s' % _tb.format_exc(),
                                 xbmc.LOGWARNING)
        was_cancelled = loader.is_cancelled()
        loader.set_finalizing()

    if was_cancelled:
        if collect is not None:
            collect['status'] = 'cancelled'
            return None
        return end_dir(content='files', cache=False)

    # ── Render the categorised results ─────────────────────────────
    total_count = kept_count[0]

    # Every source that never answered is now visible instead of silently
    # missing — the user can see WHICH source is incomplete, and why.
    _expected = set()
    for _j in jobs:
        if isinstance(_j[0], dict):
            _expected.add(_j[0].get('name') or '?')
    _silent = sorted(_expected - answered - set(failed))
    try:
        xbmc.log('[DexHub] search done: %d results | answered=%d/%d | failed=%s | timed_out=%s'
                 % (total_count, len(answered), len(_expected),
                    ', '.join('%s(%s)' % (k, v) for k, v in failed.items()) or 'none',
                    ', '.join(_silent) or 'none'), xbmc.LOGINFO)
    except Exception:
        pass

    # Cinematic mode owns its ListItems. The old path first built and sent a
    # complete classic Kodi directory, then built the same rows again for the
    # custom window. On large searches that duplicate bridge work dominated
    # the delay *after* providers had already answered.
    # Poster grid is now the single search-results surface. ``search_style``
    # has been hidden for several releases, but old profiles can still carry
    # its legacy list value and unexpectedly bypass the redesigned UI.
    _cinematic_search = total_count > 0 or collect is not None
    if collect is not None and total_count == 0:
        collect['status'] = 'empty'
        collect['rows'] = []
        return None
    if not _cinematic_search:
        header_label = tr('[B][COLOR cyan]🔍 بحث: %s[/COLOR][/B]    [COLOR lightgrey]نتائج: %d[/COLOR]') % (query, total_count)
        add_item(header_label,
                 build_url(action='hub_search_menu'),
                 is_folder=False,
                 info={'title': 'نتائج البحث',
                       'plot': 'ضغطة لإعادة البحث بكلمة أخرى. النتائج مُجمَّعة حسب نوع المحتوى أدناه.'})

    if total_count == 0:
        add_item(tr('[COLOR yellow]لم يتم العثور على نتائج لـ "%s"[/COLOR]') % query,
                 build_url(action='hub_search_menu'), is_folder=False,
                 info={'title': 'لا نتائج', 'plot': 'جرّب صياغة مختلفة أو معرّفاً مثل tt1234567 أو tmdb:123'})
        return end_dir(content='videos', cache=False)

    ui_rows = _ui_rows_of(results_by_type)

    if collect is not None:
        collect['rows'] = ui_rows
        collect['status'] = 'ok' if ui_rows else 'empty'
        collect['incomplete'] = sorted(set(failed) | set(_silent))
        return None
    if not _cinematic_search:
        _search_incomplete_footer(failed, _silent, _ceiling)
    result = end_dir(content='videos', cache=False)
    try:
        # v5.4.1: the fallback here said '1' (classic) while the setting
        # itself defaults to '0' (cinematic), so a profile that had never
        # written the key got the classic list even though the UI showed
        # cinematic selected. One default, in one place.
        if _cinematic_search and ui_rows:
            from . import search_window
            search_window.drop_brand_logos(ui_rows)
            search_window.open_search_results(query, ui_rows)
    except Exception as exc:
        xbmc.log('[DexHub] cinematic search window failed: %s' % exc, xbmc.LOGWARNING)
    return result


def hub_search_bucket(bucket='anime'):
    entries = [(p, c, b) for (p, c, b) in _hub_catalog_entries(bucket=bucket) if _catalog_supports_search(c)]
    if not entries:
        error(tr('لا توجد كتالوجات تدعم البحث في هذا القسم'))
        return hub_section(bucket)
    keyboard = xbmc.Keyboard('', tr('ابحث في %s') % _hub_bucket_title(bucket))
    keyboard.doModal()
    if not keyboard.isConfirmed():
        return end_dir(content='files', cache=False)
    query = keyboard.getText().strip()
    if not query:
        return end_dir(content='files', cache=False)
    try:
        from . import search_history as _sh
        _sh.add(query, media_type=bucket or 'all')
    except Exception:
        pass
    seen = {}
    ordered_rows = []
    limit = str(_listing_page_size())

    # ─── v3.9.27: Index-first search (FTS5) ─────────────────────────
    # In index/hybrid mode, hit the local FTS5 index first. Returns
    # instantly. Then ALSO run the live aggregator to catch items the
    # index doesn't have (just-released titles not yet synced, addons
    # whose catalogs differ from search endpoint). The live results are
    # merged at the END so indexed items render first.
    if _index_mode_active():
        try:
            from . import index_render
            indexed = index_render.search_metas(
                query, media_type=_hub_bucket_media_type(bucket),
                limit=int(limit) * 2,
            )
            fake_provider = entries[0][0] if entries else {}
            for meta in indexed:
                meta_id = meta.get('id') or meta.get('imdb_id')
                if not meta_id or meta_id in seen:
                    continue
                seen[meta_id] = True
                if _search_match.best_match_score(query, meta) <= 0:
                    continue
                ordered_rows.append((
                    fake_provider,
                    meta.get('type') or _hub_bucket_media_type(bucket) or 'series',
                    meta_id, meta,
                ))
            if ordered_rows:
                xbmc.log('[DexHub] index search seeded %d results' % len(ordered_rows),
                         xbmc.LOGINFO)
        except Exception as exc:
            xbmc.log('[DexHub] index search failed: %s' % exc, xbmc.LOGWARNING)

    def _run_search(job):
        provider, cat, _b = job
        return fetch_catalog(provider, cat.get('type') or _hub_bucket_media_type(bucket) or 'series', cat.get('id'), extra={'search': query}, timeout_override=fast_timeout('search'))

    batch_size = max(2, min(parallel_workers(), 4, len(entries)))
    for job, result in iter_parallel(
            _run_search, _fair_search_job_order(entries), workers=batch_size,
            timeout=6.0, lane='search'):
        provider, cat, _b = job
        media_type = cat.get('type') or _hub_bucket_media_type(bucket) or 'series'
        if isinstance(result, Exception):
            continue
        for meta in (result or {}).get('metas') or []:
            meta_id = meta.get('id')
            if (not meta_id
                    or _search_match.best_match_score(query, meta) <= 0):
                continue
            # v5.10.28: tt1160419 from Cinemeta and tmdb:438631 from a bridge
            # are the same film; dedupe on the type-aware folded key too.
            _dk = _meta_dedupe_key(media_type, meta_id, meta)
            if meta_id in seen or _dk in seen:
                continue
            seen[meta_id] = True
            seen[_dk] = True
            ordered_rows.append((provider, media_type, meta_id, meta))
        if len(ordered_rows) >= 160:
            ordered_rows = ordered_rows[:160]
            break
    ordered_rows.sort(
        key=lambda row: -_search_match.best_match_score(query, row[3]))
    if not ordered_rows:
        notify(tr('لا توجد نتائج مطابقة'))
    for provider, media_type, meta_id, meta in ordered_rows:
        item_label = meta.get('name') or meta_id
        try:
            _meta_mem_put(media_type, meta_id, meta, source_provider_id=provider.get('id') or '')
        except Exception:
            pass
        path_action = 'series_meta' if _is_series_media(media_type) else 'play_item'
        fallback = _item_fallback_art(provider, media_type, None, item_label)
        add_item(item_label,
                 build_url(action=path_action, media_type=media_type, canonical_id=meta_id, title=item_label, source_provider_id=provider.get('id') or ''),
                 is_folder=_is_series_media(media_type), info=_meta_info(meta),
                 art=_resolve_meta_art(provider, media_type, meta, fallback_art=fallback), ids=extract_ids(meta),
                 context_menu=_build_source_picker_menu(media_type=media_type, canonical_id=meta_id, title=item_label, source_provider_id=provider.get('id') or ''))
    return end_dir(content=_directory_content_for_type(
        _hub_bucket_media_type(bucket) or 'videos'), cache=False)




def hub_search_folder(bucket='movies'):
    bucket = bucket or 'movies'
    entries = [row for row in _hub_pinned_catalog_entries(bucket) if _catalog_supports_search(row[1])]
    if not entries:
        notify(tr('لا توجد كتالوجات مثبتة تدعم البحث داخل هذا المجلد'))
        return hub_section(bucket)
    keyboard = xbmc.Keyboard('', tr('ابحث داخل %s') % tr(_hub_bucket_title(bucket)))
    keyboard.doModal()
    if not keyboard.isConfirmed():
        return hub_section(bucket)
    query = (keyboard.getText() or '').strip()
    if not query:
        return hub_section(bucket)
    try:
        from . import search_history as _sh
        _sh.add(query, media_type=bucket or 'all')
    except Exception:
        pass
    page_size = _listing_page_size()
    seen = set()
    ordered_rows = []

    def _run_search(job):
        provider, catalog, _b, _pin = job
        extra = dict(_folder_filtered_extra_for_catalog(bucket, (provider or {}).get('id') or '', (catalog or {}).get('id') or '', catalog) or {})
        # v4.7.1: declared extras only (Stremio parity) — the folder
        # filters above are catalog-declared; 'limit' is not.
        extra.update({'search': query})
        return fetch_catalog(provider, catalog.get('type') or _hub_bucket_media_type(bucket) or 'movie', catalog.get('id'), extra=extra, timeout_override=fast_timeout('search'))

    batch_size = max(1, min(parallel_workers(), 4, len(entries)))
    for job, result in iter_parallel(
            _run_search, _fair_search_job_order(entries), workers=batch_size,
            timeout=6.0, lane='search'):
        provider, catalog, _b, _pin = job
        media_type = (catalog or {}).get('type') or _hub_bucket_media_type(bucket) or 'movie'
        if isinstance(result, Exception):
            continue
        for meta in (result or {}).get('metas') or []:
            meta_id = str((meta or {}).get('id') or '')
            if not meta_id or _search_match.best_match_score(query, meta) <= 0:
                continue
            key = _meta_dedupe_key(media_type, meta_id, meta) if _folder_dedupe_enabled(bucket) else '%s:%s:%s' % ((provider or {}).get('id') or '', (catalog or {}).get('id') or '', meta_id)
            if key in seen:
                continue
            seen.add(key)
            ordered_rows.append((provider, catalog, media_type, meta_id, meta))
            if len(ordered_rows) >= page_size * 2:
                break
        if len(ordered_rows) >= page_size * 2:
            break
    if not ordered_rows:
        notify(tr('لا توجد نتائج داخل هذا المجلد'))
        return hub_section(bucket)
    ordered_rows.sort(
        key=lambda row: -_search_match.best_match_score(query, row[4]))
    _hub_render_media_rows(ordered_rows[:page_size * 2], bucket=bucket, page_num=0, has_more=False)
    return end_dir(content=_hub_directory_content(bucket), cache=False)

def hub_collection():
    _set_render_section('collection')
    add_item(tr('المفضلة / Watchlist'), build_url(action='favorites'), art=root_art('favorites'),
             info={'title': 'المفضلة / Watchlist', 'plot': 'قائمة Trakt Watchlist + مفضلة Dex Hub المحلية'})
    # v4.7.9: ready-made sets first — nothing to configure, always current.
    add_item(tr('مجموعات جاهزة'), build_url(action='ready_collections_menu'),
             art=root_art('catalogs'),
             info={'title': tr('مجموعات جاهزة'),
                   'plot': tr('رائج الآن، الأكثر شعبية، الأعلى تقييماً، في السينما وقريباً — مباشرة من TMDb.')})
    add_item(tr('مجموعات Collection'), build_url(action='collection_sets'), art=root_art('catalogs'),
             info={'title': 'مجموعات Collection', 'plot': 'فتح مجموعات الكتالوجات والقوائم اليدوية أو المستوردة'})
    if mdblist.configured():
        add_item('MDBList • %s' % tr('لستاتي'),
                 build_url(action='mdblist_my_lists'), art=root_art('mdblist'),
                 info={'title': 'MDBList',
                       'plot': tr('فتح القوائم الخاصة والعامة المرتبطة بمفتاح حسابك.')})
    add_item(tr('[COLOR grey]كتالوجات Sources لا تضاف هنا[/COLOR]'), build_url(action='providers'), art=root_art('providers'),
             info={'title': 'Collection', 'plot': 'ثبّت كتالوجات Sources داخل مجلدات الهوم أو Sub folders. Collection مخصص للمفضلة والقوائم فقط.'})
    return end_dir(content='files', cache=False)


def ready_collections_menu():
    """v4.7.9: ready-made collection sets.

    Every set is a TMDb-native endpoint (trending / popular / top rated /
    now playing / upcoming), so each row already carries its TMDb id and
    poster — no id conversion and no per-item lookup before the list can
    render. Clicking a title uses the SAME _content_click_path as any
    catalog row, so the user's click-mode setting and the source picker
    behave identically here.
    """
    from . import tmdb_direct as _tmdb
    if not _tmdb._api_key():
        add_item(tr('[COLOR yellow]أضف مفتاح TMDb من الإعدادات لتفعيل المجموعات[/COLOR]'),
                 build_url(action='open_settings'), is_folder=False,
                 art=root_art('tmdb'),
                 info={'title': tr('مجموعات جاهزة'),
                       'plot': tr('المجموعات الجاهزة تُبنى من TMDb مباشرة وتحتاج مفتاح API.')})
        return end_dir(content='files', cache=False)
    for set_id, label, _path, media_type in _tmdb.READY_SETS:
        art = root_art('movies' if media_type == 'movie' else 'series')
        # Cover art comes from the first cached row when the set has been
        # opened before — zero extra requests on this render.
        try:
            cached = _tmdb.ready_set_items(set_id, page=1, limit=1) or []
        except Exception:
            cached = []
        if cached:
            art = dict(art or {})
            if cached[0].get('poster'):
                art['poster'] = art['thumb'] = cached[0]['poster']
            if cached[0].get('backdrop'):
                art['fanart'] = art['landscape'] = cached[0]['backdrop']
        add_item(tr(label), build_url(action='ready_collection', set_id=set_id),
                 art=art,
                 info={'title': tr(label),
                       'plot': tr('مجموعة جاهزة تُحدَّث تلقائياً من TMDb.'),
                       'mediatype': 'movie' if media_type == 'movie' else 'tvshow'})
    return end_dir(content='files', cache=True)


def ready_collection(set_id='', page='1'):
    """Render one ready-made set as a normal media listing."""
    from . import tmdb_direct as _tmdb
    row_def = _tmdb.ready_set_def(set_id)
    if not row_def:
        return ready_collections_menu()
    _sid, label, _path, media_type = row_def
    try:
        page_num = max(1, int(page or 1))
    except Exception:
        page_num = 1
    rows = _tmdb.ready_set_items(set_id, page=page_num, limit=_listing_page_size())
    if not rows:
        add_item(tr('[COLOR yellow]لا توجد عناصر في هذه المجموعة الآن[/COLOR]'),
                 build_url(action='ready_collections_menu'), is_folder=False,
                 art=root_art('catalogs'), info={'title': tr(label)})
        return end_dir(content='files', cache=False)
    for row in rows:
        title = row.get('title') or ''
        year = row.get('year') or ''
        display = title if not year else '%s  •  %s' % (title, year)
        tmdb_id = row.get('tmdb_id') or ''
        art = {'poster': row.get('poster') or '', 'thumb': row.get('poster') or '',
               'fanart': row.get('backdrop') or '', 'landscape': row.get('backdrop') or ''}
        path, is_folder = _content_click_path(
            media_type=media_type, canonical_id='tmdb:%s' % tmdb_id, title=title,
            tmdb_id=tmdb_id, ui_seed=art)
        info = {'title': title, 'plot': row.get('overview') or '',
                'mediatype': 'movie' if media_type == 'movie' else 'tvshow'}
        if year and str(year).isdigit():
            info['year'] = int(year)
        try:
            info['rating'] = float(row.get('rating') or 0.0)
        except Exception:
            pass
        add_item(display, path, is_folder=is_folder, info=info, art=art,
                 ids={'tmdb_id': tmdb_id},
                 context_menu=_build_source_picker_menu(
                     media_type=media_type, canonical_id='tmdb:%s' % tmdb_id, title=title))
    if len(rows) >= _listing_page_size() and not globals().get('_pagination_hidden', lambda: False)():
        add_item(tr('المزيد'), build_url(action='ready_collection', set_id=set_id,
                                          page=str(page_num + 1)),
                 art=root_art('catalogs'), info={'title': tr('المزيد')})
    return end_dir(content=_directory_content_for_type(media_type), cache=True)


def tmdb_titles_view(mode='', tid='', media='movie', name='', page='1'):
    """v5.10.313: a TMDb collection's films in release order, or a studio's
    or a network's titles (most popular first): what the title page's
    Collection card and Studios tiles open in the grid."""
    from . import tmdb_direct as _tmdb
    try:
        page_num = max(1, int(page or 1))
    except Exception:
        page_num = 1
    rows, more, media_type = [], False, 'movie'
    tid = str(tid or '')
    if mode == 'collection' and tid.isdigit():
        from .skinui import title_extras as _tx
        for part in (_tx.collection_parts(tid) or {}).get('parts') or []:
            rows.append({'tmdb_id': part['tmdb'], 'title': part['title'], 'year': part['year'],
                         'overview': part['overview'], 'poster': part['poster'], 'backdrop': part['backdrop'],
                         'rating': part['rating']})
    elif mode in ('company', 'network') and tid.isdigit():
        kind = 'tv' if (mode == 'network' or media == 'series') else 'movie'
        media_type = 'series' if kind == 'tv' else 'movie'
        from .skinui import title_extras as _tx
        language = _tx._lang()
        key = 'dh-studio1:%s:%s:%s:%s:%d' % (mode, tid, kind, language, page_num)
        cached = _tmdb._cache_get(key)
        if cached is None:
            query = {'page': str(page_num), 'sort_by': 'popularity.desc', 'include_adult': 'false',
                     'language': language, ('with_networks' if mode == 'network' else 'with_companies'): tid}
            data = _tmdb._request('/discover/%s' % kind, query, timeout=6, max_attempts=2) or {}
            cached = {'rows': [_tmdb._row_from_tmdb(r, media_type) for r in data.get('results') or []
                               if isinstance(r, dict)],
                      'pages': int(data.get('total_pages') or 1)}
            _tmdb._cache_set(key, cached, 24 * 3600 if cached['rows'] else 600)
        rows = [r for r in cached.get('rows') or [] if r.get('tmdb_id') and r.get('title')]
        more = page_num < min(int(cached.get('pages') or 1), 25)
    for row in rows:
        title = row.get('title') or ''
        year = row.get('year') or ''
        tmdb_id = row.get('tmdb_id') or ''
        art = {'poster': row.get('poster') or '', 'thumb': row.get('poster') or '',
               'fanart': row.get('backdrop') or '', 'landscape': row.get('backdrop') or ''}
        path, is_folder = _content_click_path(
            media_type=media_type, canonical_id='tmdb:%s' % tmdb_id, title=title,
            tmdb_id=tmdb_id, ui_seed=art)
        info = {'title': title, 'plot': row.get('overview') or '',
                'mediatype': 'movie' if media_type == 'movie' else 'tvshow'}
        if year and str(year).isdigit():
            info['year'] = int(year)
        try:
            info['rating'] = float(row.get('rating') or 0.0)
        except Exception:
            pass
        add_item(title if not year else '%s  •  %s' % (title, year), path, is_folder=is_folder, info=info,
                 art=art, ids={'tmdb_id': tmdb_id},
                 context_menu=_build_source_picker_menu(
                     media_type=media_type, canonical_id='tmdb:%s' % tmdb_id, title=title))
    if more:
        add_item(tr('المزيد'), build_url(action='tmdb_titles', mode=mode, id=tid, media=media, name=name,
                                          page=str(page_num + 1)),
                 art=root_art('catalogs'), info={'title': tr('المزيد')})
    return end_dir(content=_directory_content_for_type(media_type), cache=True)


