# ─────────────────────────────────────────────────────────────────────
# v3.9.26: home-folder pre-fetch.
#
# Why this is the single biggest perceived-perf win for DexHub:
# Folder-open cold-start is dominated by N parallel HTTP requests to N
# Stremio catalogs (4s timeout each). For an 80-item Movies folder with
# 4 pinned catalogs, that's typically a 1.5-4s wait. After the first
# open, Kodi's directory cache makes subsequent opens instant — but
# that first open every 5-10 minutes is what makes the addon feel slow
# next to Plex (1 HTTP) or the Stremio native app (aggressive prefetch).
#
# Solution: when the user lands on the Home screen, fire a background
# thread that pre-fetches the first catalog of each top home bucket.
# Their HTTP responses land in our 600s cache. When the user actually
# clicks the bucket, the cache hit is instant.
#
# Constraints:
#   * Never block home() rendering — strictly background daemon thread.
#   * Rate-limit per session: don't re-prefetch on every home re-render.
#     Use a Window property timestamp; cooldown 10 minutes (matches the
#     new catalog TTL so the prefetch matures right when the cache
#     would otherwise go stale).
#   * Cap concurrency: 4 HTTP at a time total, across all prefetched
#     buckets. Don't drown a slow network in dozens of parallel fetches.
#   * Cap depth: only the FIRST catalog of each top-2 most-pinned
#     buckets gets prefetched. We want a warm CACHE, not a complete
#     mirror of every catalog the user has pinned.
#   * Short timeout: 3s. If a catalog doesn't respond in 3s during a
#     speculative prefetch, it wasn't going to be useful anyway.
# ─────────────────────────────────────────────────────────────────────

_HOME_PREFETCH_COOLDOWN = 600.0   # 10 minutes — matches catalog_cache_ttl



# v5.4.16: Home is intentionally fixed; per-row visibility/pinning was removed.


def home():
    # v3.9.53: top-level try/except. If home() fails for any reason —
    # network, file IO, plugin store corruption, missing setting — the
    # full traceback is logged AND a minimal recovery directory is
    # emitted so the user always sees SOMETHING and can navigate to
    # Sources or Settings to recover. Previously a silent home crash
    # would leave the user with an empty or stuck directory.
    try:
        return _home_impl()
    except Exception as _exc:
        try:
            import traceback as _tb
            xbmc.log('[DexHub] home() CRASHED: %s\n%s' % (_exc, _tb.format_exc()),
                     xbmc.LOGERROR)
        except Exception:
            pass
        # Emergency-recovery minimal home so the user is not stuck.
        try:
            add_item('[COLOR red]تعذر فتح الصفحة الرئيسية[/COLOR]',
                     build_url(action='setup_center'),
                     info={'title': 'Recovery',
                           'plot': 'افتح مركز الإعداد والتشخيص، أو راجع kodi.log للتفاصيل.'})
            add_item('[COLOR yellow]Sources[/COLOR]',
                     build_url(action='providers'))
            add_item('[COLOR yellow]الإعداد والتشخيص[/COLOR]',
                     build_url(action='setup_center'))
            end_dir(content='files', cache=False)
        except Exception:
            pass


def _home_feature_art(key, rows=None):
    """Complete root art with a local TMDb Helper hero when available.

    This path is intentionally read-only and offline: at most four recent rows
    are checked in TMDb Helper's SQLite cache.  The root/service icon remains
    the poster while fanart, landscape and clearlogo become content-aware.
    """
    art = dict(root_art(key) or {})
    for row in (rows or [])[:4]:
        if not isinstance(row, dict):
            continue
        identity = dict(row)
        identity.setdefault('id', row.get('canonical_id') or row.get('video_id') or '')
        try:
            extracted = extract_ids(identity) or {}
        except Exception:
            extracted = {}
        media_type = str(row.get('media_type') or row.get('type') or 'movie').lower()
        helper_type = 'tv' if media_type in (
            'series', 'show', 'tv', 'tvshow', 'season', 'episode', 'anime') else 'movie'
        tmdb_id = str(
            row.get('show_tmdb_id') or row.get('tmdb_id') or
            extracted.get('tmdb_id') or '').strip()
        imdb_id = str(row.get('imdb_id') or extracted.get('imdb_id') or '').strip()
        title = row.get('show_title') or row.get('title') or row.get('name') or ''
        year = row.get('year') or ''
        bundle = {}
        if tmdb_id or imdb_id or title:
            try:
                bundle = _tmdb_art_db.get_art_bundle_from_db(
                    tmdb_id=tmdb_id, media_type=helper_type,
                    imdb_id=imdb_id, title=title, year=year) or {}
            except Exception:
                bundle = {}

        fanart = (bundle.get('fanart') or bundle.get('landscape') or
                  row.get('fanart') or row.get('background') or
                  row.get('landscape') or row.get('backdrop') or '')
        landscape = bundle.get('landscape') or row.get('landscape') or fanart
        clearlogo = (bundle.get('clearlogo') or row.get('clearlogo') or
                     row.get('logo') or '')
        if fanart:
            art['fanart'] = fanart
            art['banner'] = row.get('banner') or fanart
        if landscape:
            art['landscape'] = landscape
        if clearlogo:
            art['clearlogo'] = clearlogo
            art['tvshow.clearlogo'] = clearlogo
            art['clearart'] = row.get('clearart') or clearlogo
            art['logo'] = clearlogo
        if fanart or clearlogo:
            break
    return art


def _home_impl():
    # v3.9.44: defensive logging on every home render so future issues
    # like "buttons don't work" can be triaged from kodi.log without
    # ambiguity. Emits one line on entry and one on exit, with the
    # final emitted-items count visible.
    try:
        xbmc.log('[DexHub] home() entered', xbmc.LOGINFO)
    except Exception:
        pass
    win = xbmcgui.Window(WINDOW_ID)
    # Clear stale one-shot handoff/source properties. Keep OSD artwork while video is active.
    _clear_tmdbh_transient()
    _clear_source_transient_props(clear_global=True)
    cw_dirty = False
    try:
        if win.getProperty('dexhub.cw_dirty') == '1':
            cw_dirty = True
            win.clearProperty('dexhub.cw_dirty')
            win.clearProperty('dexhub.cw_dirty_ts')
    except Exception:
        pass

    # v5.4.16: no provider scan / catalog-pin prefetch on Home. The fixed Home
    # contains only navigation anchors, so warming hidden catalog buckets here
    # wastes I/O and makes AF3 entry feel slower. Each destination stays lazy.

    # Mirror POV's progress cache first so the home row behaves like POV and
    # does not require a separate Dex Hub Trakt activation.
    try:
        _import_pov_progress_if_available()
    except Exception:
        pass

    try:
        cw_items = playback_store.list_continue_items(limit=24) or []
    except Exception:
        cw_items = []
    cw_count = len(cw_items)

    # Fanart slideshow from recent progress, without blocking home.
    if cw_items:
        try:
            import random as _rnd
            picked = _rnd.choice(cw_items[:10])
            bg = picked.get('background') or picked.get('poster') or ''
            if bg:
                win.setProperty('fanart', bg)
        except Exception:
            pass

    # v5.4.16: Home is a stable media dashboard even on a fresh install.
    # Settings has one dedicated Home entry; the mandatory bundled Collection means an
    # empty provider list no longer needs a welcome/setup card ahead of media.

    # v5.4.16 fixed Home order requested for AF3. These are navigation anchors,
    # so labels and order do not move when provider counts/settings change.
    add_item('Continue Watching', build_url(action='continue'),
             art=_home_feature_art('continue', cw_items),
             info={'title': 'Continue Watching',
                   'plot': 'استمرار المشاهدة من Trakt / DexHub / POV المحلي عند توفره'})
    add_item('Next Up', build_url(action='nextup'),
             art=_home_feature_art('nextup', cw_items),
             info={'title': 'Next Up',
                   'plot': tr('الحلقة التالية من المسلسلات التي تتابعها عبر Trakt وDex Hub.')})

    try:
        fav_items = favorites_store.list_favorites(limit=4) or []
    except Exception:
        fav_items = []
    add_item('Favorites', build_url(action='favorites'),
             art=_home_feature_art('favorites', fav_items),
             info={'title': 'Favorites',
                   'plot': 'المفضلة المحلية + Watchlist من Trakt.'})

    # Collections are first-class and mandatory. One bundled Nuvio collection
    # ships with the add-on; additional imports automatically join the same
    # Movies/TV virtual views without pinning them in another Home location.
    add_item('Movies', build_url(action='nuvio_home_media', media='movie'),
             art=root_art('movie_collections'),
             info={'title': 'Movies',
                   'plot': 'نفس صفوف وكتالوجات Nuvio Home للأفلام وبنفس الترتيب.'},
             properties={'dexhub.tile_shape': 'landscape', 'dexhub.nuvio_home_media': 'movie'})
    add_item('TV Shows', build_url(action='nuvio_home_media', media='series'),
             art=root_art('tv_collections'),
             info={'title': 'TV Shows',
                   'plot': 'نفس صفوف وكتالوجات Nuvio Home للمسلسلات وبنفس الترتيب.'},
             properties={'dexhub.tile_shape': 'landscape', 'dexhub.nuvio_home_media': 'series'})
    add_item('Collections', build_url(action='collection_sets'),
             art=collection_banner_art('Collections', fanart=addon_fanart()),
             info={'title': 'Collections',
                   'plot': 'كل Collections من Nuvio والمجموعات الخارجية والافتراضية في مكان مستقل.'},
             properties={'dexhub.tile_shape': 'landscape', 'dexhub.collection_set': '1'})

    add_item('Plex', build_url(action='plex_menu'), art=root_art('plex'),
             info={'title': 'Plex', 'plot': 'فتح وربط وإدارة سيرفرات ومكتبات Plex.'})
    add_item('Emby', build_url(action='emby_menu'), art=root_art('emby'),
             info={'title': 'Emby', 'plot': 'فتح وربط وإدارة مكتبات Emby / Jellyfin.'})
    add_item('Jellyfin', build_url(action='jellyfin_menu'), art=root_art('jellyfin'),
             info={'title': 'Jellyfin'})
    add_item('Silo', build_url(action='silo_menu'), art=root_art('silo'),
             info={'title': 'Silo', 'plot': 'ربط Silo وإظهاره كمصدر أصلي سريع.'})
    add_item('Search', build_url(action='hub_search_menu'), art=root_art('search_movie'),
             info={'title': 'Search', 'plot': 'بحث موحّد عبر المصادر والمكتبات.'})
    add_item('Settings', build_url(action='setup_center'), art=root_art('settings'),
             info={'title': 'Settings', 'plot': 'إعداد Dex Hub بشكل مرتب: الواجهة، الكوليكشن، Self‑Hosted، الجودة، الترجمات والأداء.'})
    add_item('Sources', build_url(action='providers'), art=root_art('providers'),
             info={'title': 'Sources', 'plot': 'إدارة إضافات Stremio والمصادر فقط.'})

    end_dir(content='files', cache=not cw_dirty)
    return



