def first_run_wizard():
    """Simple first-run flow: Nuvio, Stremio, or manual setup.

    Keep onboarding focused. Nuvio can populate Collections, sources, progress and library;
    Stremio imports installed add-ons and watch progress; manual setup opens
    the normal Sources page where Plex/Emby and manifest tools are available.
    """
    try:
        choice = _setup_route_mod.choose_setup_path(xbmcgui.Dialog(), tr)
    except Exception:
        choice = None
    if choice is None:
        return home()
    try:
        ADDON.setSetting('wizard_completed', 'true')
    except Exception:
        pass
    if choice == 'nuvio':
        _accounts_route_mod.connect_nuvio(ADDON, tr)
        return setup_center()
    if choice == 'stremio':
        xbmc.executebuiltin('RunPlugin(%s)' % build_url(action='stremio_login'))
        return sync_accounts_menu()
    return providers()

