# v3.9.45: configuration backup and restore. The complete user-curated
# state of DexHub serialised to a single JSON document so it can be
# migrated to a new install or new device without losing setup work.
def _config_snapshot():
    """Build the full configuration snapshot for export."""
    snapshot = {
        'dexhub_export_version': 1,
        'created_unix': int(time.time()),
        'plugin_version': ADDON.getAddonInfo('version'),
        'providers': [],
        'catalog_pins': [],
        'home_buckets': [],
        'bucket_art_map': {},
        'settings': {},
    }
    try:
        snapshot['providers'] = store.list_providers() or []
    except Exception:
        pass
    try:
        snapshot['catalog_pins'] = _load_catalog_pins() or []
    except Exception:
        pass
    try:
        snapshot['home_buckets'] = _home_bucket_defs(include_collection=False) or []
    except Exception:
        pass
    try:
        raw_map = (ADDON.getSetting('bucket_art_map') or '{}').strip()
        snapshot['bucket_art_map'] = json.loads(raw_map) if raw_map else {}
    except Exception:
        snapshot['bucket_art_map'] = {}
    # Capture every user-facing setting value. We enumerate from
    # settings.xml because addon.getSetting('') doesn't return a list.
    try:
        import xml.etree.ElementTree as _ET
        settings_xml_path = os.path.join(ADDON.getAddonInfo('path'), 'resources', 'settings.xml')
        tree = _ET.parse(settings_xml_path)
        for s in tree.findall('.//setting'):
            sid = s.get('id') or ''
            if not sid:
                continue
            try:
                snapshot['settings'][sid] = ADDON.getSetting(sid) or ''
            except Exception:
                pass
    except Exception:
        pass
    return snapshot


def config_export():
    """Write a complete configuration snapshot to a user-chosen file."""
    snapshot = _config_snapshot()
    dest_dir = xbmcgui.Dialog().browse(0, tr('اختر مجلد الحفظ'), 'files', '', False, False, '')
    if not dest_dir:
        return
    timestamp = time.strftime('%Y%m%d-%H%M%S')
    filename = 'dexhub-config-%s.json' % timestamp
    dest_path = os.path.join(dest_dir, filename)
    try:
        body = json.dumps(snapshot, ensure_ascii=False, indent=2)
        with xbmcvfs.File(dest_path, 'w') as fh:
            fh.write(body)
        notify(tr('تم التصدير: %s') % filename)
    except Exception as exc:
        error(tr('فشل التصدير: %s') % exc)


def config_import():
    """Restore configuration from a user-chosen JSON file."""
    src_path = xbmcgui.Dialog().browse(1, tr('اختر ملف JSON الذي صدّرته سابقاً'), 'files', '.json', False, False, '')
    if not src_path or not src_path.lower().endswith('.json'):
        return
    if not xbmcgui.Dialog().yesno(
        'Dex Hub',
        tr('سيستبدل هذا الإجراء التكوين الحالي بمحتوى الملف. هل تريد المتابعة؟'),
    ):
        return
    try:
        with xbmcvfs.File(src_path, 'r') as fh:
            text = fh.read()
        if not text:
            error(tr('الملف فارغ'))
            return
        snapshot = json.loads(text)
    except Exception as exc:
        error(tr('فشل قراءة الملف: %s') % exc)
        return
    if not isinstance(snapshot, dict):
        error(tr('صيغة الملف غير صحيحة'))
        return
    return config_import_data(snapshot)


def config_import_data(snapshot):
    """Restore an old export (dexhub_export_version 1); v5.10.212: also
    reached from the new Backup's restore when it is given such a file."""
    if int(snapshot.get('dexhub_export_version') or 0) < 1:
        error(tr('إصدار الملف غير مدعوم'))
        return
    # Restore providers — we keep the existing addition flow so all
    # manifest validation runs, but we cheat by writing the providers
    # store directly since the snapshot already contains validated
    # manifests at the time of export.
    restored_providers = 0
    try:
        providers_in = snapshot.get('providers') or []
        if providers_in:
            store.write_providers_raw(providers_in)
            restored_providers = len(providers_in)
    except Exception as exc:
        xbmc.log('[DexHub] import providers failed: %s' % exc, xbmc.LOGWARNING)
    restored_pins = 0
    try:
        pins_in = snapshot.get('catalog_pins') or []
        if pins_in:
            _save_catalog_pins(pins_in)
            restored_pins = len(pins_in)
    except Exception as exc:
        xbmc.log('[DexHub] import pins failed: %s' % exc, xbmc.LOGWARNING)
    try:
        bucket_art = snapshot.get('bucket_art_map') or {}
        if bucket_art:
            ADDON.setSetting('bucket_art_map', json.dumps(bucket_art, ensure_ascii=False))
    except Exception:
        pass
    restored_settings = 0
    try:
        for sid, sval in (snapshot.get('settings') or {}).items():
            # Skip the two settings whose state is captured by other
            # fields above to avoid double-write conflicts.
            if sid in ('bucket_art_map', 'catalog_pins_json'):
                continue
            try:
                ADDON.setSetting(sid, str(sval) if sval is not None else '')
                restored_settings += 1
            except Exception:
                pass
    except Exception:
        pass
    try:
        _better_posters.invalidate()
        from . import settings_cache as _settings_cache
        _settings_cache.invalidate()
    except Exception:
        pass
    xbmcgui.Dialog().ok(
        'Dex Hub',
        tr('تم الاستيراد بنجاح:\n• المصادر: %d\n• الكتالوجات المُثبّتة: %d\n• الإعدادات: %d') %
            (restored_providers, restored_pins, restored_settings))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass


def source_health():
    """Show diagnostic metrics for each installed source."""
    rows = store.list_providers() or []
    if not rows:
        notify(tr('لا توجد مصادر مُثبّتة'))
        return end_dir()
    # Read health snapshot from the existing blacklist / telemetry store
    # if present. The telemetry was recorded internally but never shown.
    try:
        from . import source_browser as _sb
        health_data = getattr(_sb, 'health_snapshot', lambda: {})() or {}
    except Exception:
        health_data = {}
    add_item(tr('[COLOR cyan]صحة المصادر — لقطة من آخر سبعة أيام[/COLOR]'),
             build_url(action='source_health'),
             is_folder=False,
             art=root_art('providers'),
             info={'title': 'صحة المصادر',
                   'plot': 'كلما زاد معدّل النجاح وقلّ زمن الاستجابة، كان المصدر أكثر موثوقية. المصادر التي تظهر باللون الرمادي لم تُستخدم في الأسبوع الماضي.'})
    for prov in rows:
        prov_id = prov.get('id') or ''
        name = prov.get('name') or prov_id
        h = health_data.get(prov_id) or {}
        attempts = int(h.get('attempts') or 0)
        successes = int(h.get('successes') or 0)
        streams_produced = int(h.get('streams') or 0)
        avg_ms = int(h.get('avg_ms') or 0)
        last_failure = h.get('last_failure') or ''
        if attempts == 0:
            label = tr('[COLOR grey]%s — لم يُستخدم مؤخراً[/COLOR]') % name
            plot = 'لم يُسجَّل أي طلب لهذا المصدر في آخر سبعة أيام. قد يكون مُعطَّلاً أو غير مُستخدَم في تشكيلتك الحالية.'
        else:
            rate = (successes * 100) // max(1, attempts)
            colour = 'lightgreen' if rate >= 80 else ('yellow' if rate >= 50 else 'red')
            label = tr('[COLOR %s]%s — نجاح %d%% • %d بث • %d مللي ثانية[/COLOR]') % (colour, name, rate, streams_produced, avg_ms)
            plot_lines = [
                tr('إجمالي المحاولات: %d') % attempts,
                tr('الناجحة منها: %d') % successes,
                tr('البثوث المُنتجة: %d') % streams_produced,
                tr('متوسّط زمن الاستجابة: %d مللي ثانية') % avg_ms,
            ]
            if last_failure:
                plot_lines.append(tr('آخر فشل: %s') % last_failure)
            plot = '\n'.join(plot_lines)
        add_item(label,
                 build_url(action='provider_menu', provider_id=prov_id),
                 art=provider_art(name, prov.get('manifest') or {}, base_url=prov.get('base_url') or ''),
                 info={'title': name, 'plot': plot})
    end_dir()


# v3.9.64: Performance Boost preset for slow devices (ARM 32-bit
# CoreELEC, older Fire TV, low-RAM boxes). Flips four settings at
# once so the user doesn't have to know what each one does:
#
#   1. lightweight_mode = true   — skip aggregated hub buckets +
#                                   skip the background index sync
#                                   scheduler. Sources stay fully
#                                   functional via the Sources page.
#   2. catalog_cache_ttl = 1800  — keep catalog responses 30 min
#                                   instead of the default 10 min,
#                                   reducing Stremio addon HTTP calls
#                                   by 3x for repeat browses.
#   3. meta_cache_ttl = 14400    — keep item metadata 4 hours instead
#                                   of the default 1 hour, reducing
#                                   per-item enrichment cost when the
#                                   user revisits the same lists.
#   4. tmdb_helper default       — set Dex Hub as TMDb Helper's
#                                   default player for movies and
#                                   episodes, so the skin's TMDb
#                                   Helper widgets browse via TMDb
#                                   Helper's local SQLite cache and
#                                   only hand off to Dex Hub at Play.
#
# This is the single biggest perceived-perf win for Arctic Fuse and
# any TMDb-Helper-dependent skin on a low-end device, because almost
# all browsing becomes a local cache hit instead of a Stremio HTTP
# round-trip.

PERFORMANCE_PRESET = (
    ('lightweight_mode',   'true'),
    ('catalog_cache_ttl',  '1800'),
    ('meta_cache_ttl',     '14400'),
)


# v3.9.103: one-tap "Recommended" preset. Bundles the quality profile +
# the performance preset into a single action so a first-run user goes
# from "nothing tuned" to "well-tuned" with one click instead of needing
# to find two separate settings buried in different categories.
RECOMMENDED_PRESET = (
    ('quality_profile',    'Balanced (recommended)'),
    ('lightweight_mode',   'true'),
    ('catalog_cache_ttl',  '1800'),
    ('meta_cache_ttl',     '14400'),
    ('bypass_all_filters', 'false'),  # ensure the new bypass is OFF in Recommended
)


def _performance_boost_state():
    """Return a dict with current preset state for the UI status row."""
    state = {'all_active': True, 'missing_count': 0, 'items': []}
    try:
        for key, want in PERFORMANCE_PRESET:
            cur = (ADDON.getSetting(key) or '').strip().lower()
            ok = cur == want.lower()
            state['items'].append((key, cur, want, ok))
            if not ok:
                state['all_active'] = False
                state['missing_count'] += 1
    except Exception:
        state['all_active'] = False
        state['missing_count'] = len(PERFORMANCE_PRESET)
    return state


def apply_performance_preset():
    """Flip all preset toggles after explaining trade-offs to the user."""
    state = _performance_boost_state()
    # Compose the explainer dialog: show exactly what will change so
    # the user understands the trade-offs rather than blindly accepting.
    lines = [
        tr('سيُطبَّق على هذه الإعدادات:'),
        '',
    ]
    label_map = {
        'lightweight_mode':  tr('الوضع الخفيف (يلغي مجلدات التجميع ومزامنة الفهرس)'),
        'catalog_cache_ttl': tr('ذاكرة الكتالوجات: 30 دقيقة (بدل 10)'),
        'meta_cache_ttl':    tr('ذاكرة الميتاداتا: 4 ساعات (بدل 1)'),
    }
    for key, cur, want, ok in state['items']:
        mark = '✓' if ok else '○'
        lines.append('[COLOR %s]%s[/COLOR] %s' % ('green' if ok else 'yellow', mark, label_map.get(key, key)))
    lines.extend([
        '',
        tr('السكين سيصبح أخف وأسرع. القوائم تستخدم الذاكرة المخزّنة بدل الجلب الحيّ، والبوسترات تأتي من ذاكرة Kodi بعد أوّل تحميل. لن تفقد أي مصدر — يبقى كل شيء داخل صفحة Sources.'),
    ])
    if state['all_active']:
        # Already on — offer re-apply only.
        try:
            want = xbmcgui.Dialog().yesno(
                tr('Dex Hub • تحسين الأداء'),
                tr('كلّ تحسينات الخفّة مُفعَّلة بالفعل. هل تريد إعادة تطبيقها للتأكّد؟'),
                yeslabel=tr('أعد التطبيق'),
                nolabel=tr('إغلاق'),
            )
        except Exception:
            want = False
        if not want:
            return integrations_menu()
    else:
        try:
            want = xbmcgui.Dialog().yesno(
                tr('Dex Hub • تحسين الأداء'),
                '\n'.join(lines),
                yeslabel=tr('فعّل الكلّ'),
                nolabel=tr('إلغاء'),
            )
        except Exception:
            want = False
        if not want:
            return integrations_menu()

    applied = []
    failed = []
    for key, value in PERFORMANCE_PRESET:
        try:
            ADDON.setSetting(key, value)
            applied.append(key)
        except Exception as exc:
            xbmc.log('[DexHub] performance preset setSetting(%s, %s) failed: %s' % (key, value, exc), xbmc.LOGWARNING)
            failed.append(key)

    try:
        xbmc.log('[DexHub] performance preset applied: %s, failed: %s' % (
            ', '.join(applied) or 'none', ', '.join(failed) or 'none'), xbmc.LOGINFO)
    except Exception:
        pass

    if failed:
        notify(tr('طُبِّق جزئياً (%d ناجح، %d فشل)') % (len(applied), len(failed)))
    else:
        notify(tr('تم تفعيل تحسين الأداء ✓'))

    # Some toggles (lightweight_mode in particular) only take effect on
    # the next home() render. Suggest a restart of the addon's home so
    # the user sees the effect immediately. Optional — they can also
    # just navigate away and back.
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass

    return integrations_menu()


