    add_item('إعادة الربط عبر QR', build_url(action='silo_qr_login'), is_folder=False,
             art=root_art('settings'), info={'title': 'QR', 'plot': 'ربط حساب Silo آخر.'})
    add_item('[COLOR grey]فصل Silo[/COLOR]', build_url(action='silo_logout'),
             is_folder=False, art=root_art('settings'))
