def _silo_server():
    rows = silo_client.servers()
    if not rows:
        raise Exception('لم يتم ربط Silo بعد')
    return rows[0]


_SILO_SECTION_ART = {}
_SILO_ART_BUDGET = 4.0



def _silo_resolve_section_art(server, sections, fetcher, scope):
    """Assign stable navigation art without fetching child media.

    Older builds fetched the first movie/episode of every Silo section solely
    to borrow its poster as the section card/background. Besides adding up to
    four seconds of browse latency, this made a section such as "Recommended"
    look like one unrelated movie. Navigation art is now local and stable;
    real Silo artwork is used only once the user opens the section and sees
    actual media items.
    """
    for section in sections or []:
        title = str(section.get('title') or section.get('name') or 'Section')
        key = '%s|%s' % (scope, str(section.get('id') or title))
        art = _SILO_SECTION_ART.get(key)
        if art is None:
            art = collection_banner_art(title, fanart=addon_fanart())
            _SILO_SECTION_ART[key] = art
        section['_art'] = art
    return sections

def _silo_section_art(section):
    title = str((section or {}).get('title') or (section or {}).get('name') or 'Section')
    return (section or {}).get('_art') or collection_banner_art(title, fanart=addon_fanart())


def _silo_art(item):
    poster = str(item.get('thumb') or '')
    fanart = str(item.get('art') or poster)
    logo = str(item.get('logo') or '')
    art = {'poster': poster, 'thumb': poster, 'icon': poster,
           'fanart': fanart, 'landscape': fanart}
    if logo:
        art['clearlogo'] = logo
        art['logo'] = logo
    return art


def _silo_render_one(item, server):
    item_id = str(item.get('rating_key') or '')
    if not item_id:
        return False
    kind = item.get('media_type') or 'movie'
    if kind == 'show':
        path = build_url(action='silo_series', series_id=item_id,
                         title=item.get('title') or 'Series')
        is_folder = True
    elif kind == 'season':
        # A season card must open its episodes directly. Sending its own
        # content_id back to the series route creates the repeated nested
        # folder the user reported and may never reach a playable episode.
        path = build_url(action='silo_episodes',
                         series_id=item.get('series_id') or item_id,
                         season=str(item.get('season') or 0),
                         title=item.get('show_title') or item.get('title') or 'Series')
        is_folder = True
    else:
        path = build_url(action='silo_play',
                         item_id=item.get('play_content_id') or item_id)
        is_folder = False
    label = item.get('title') or 'Silo'
    if kind == 'episode':
        label = '%s  [COLOR grey](S%02dE%02d)[/COLOR]' % (
            label, int(item.get('season') or 0), int(item.get('index') or 0))
    add_item(label, path, is_folder=is_folder, info=_plex_item_info(item),
             art=_silo_art(item), ids=_plex_item_ids(item),
             context_menu=[(tr('قوائم وكوليكشنات Silo'),
                            'RunPlugin(%s)' % build_url(action='silo_tools', item_id=item_id))],
             label2=('Silo • %s' % (item.get('info_line') or '')).rstrip(' •'))
    return True


def _silo_render_items(items, empty='لا توجد عناصر في Silo'):
    try:
        server = _silo_server()
    except Exception as exc:
        _silo_error(exc)
        return 0
    count = sum(1 for item in (items or []) if _silo_render_one(item, server))
    if not count:
        add_item('[COLOR grey]%s[/COLOR]' % empty, build_url(action='silo_menu'),
                 art=root_art('silo'))
    return count


def _silo_content(items=None, media_type=''):
    """Give Kodi/AF3 the real media class so it selects poster layouts."""
    explicit = _directory_content_for_type(media_type) if media_type else ''
    if explicit and explicit != 'videos':
        return explicit
    kinds = {str((row or {}).get('media_type') or '').lower()
             for row in (items or [])}
    if kinds and kinds <= {'show', 'series', 'tvshow'}:
        return 'tvshows'
    if kinds and kinds <= {'episode'}:
        return 'episodes'
    if kinds and kinds <= {'season'}:
        return 'seasons'
    if 'movie' in kinds or not kinds:
        return 'movies'
    return 'videos'


def silo_home():
    """Silo's Home exactly as the site renders it: same sections, same order.

    v5.10.16: sections whose teaser arrived without inline items used to fall
    back to the generic Silo poster, so Home looked like one placeholder
    repeated. Art is now resolved per section under a shared budget.
    """
    try:
        server = _silo_server()
        sections = silo_client.home_sections(server)
        _silo_resolve_section_art(server, sections,
                                  silo_client.home_section_items, 'home')
        for section in sections:
            if not section.get('id'):
                continue
            count = int(section.get('total_count') or len(section.get('items') or []))
            add_item(section.get('title') or 'Section',
                     build_url(action='silo_section', section_id=section.get('id'),
                               title=section.get('title') or '',
                               section_type=section.get('section_type') or ''),
                     art=_silo_section_art(section),
                     info={'title': section.get('title') or 'Section',
                           'plot': '%d عنصر • Silo Home' % count})
        if not sections:
            add_item('[COLOR grey]لا توجد أقسام في Silo Home[/COLOR]',
                     build_url(action='silo_menu'), art=root_art('silo'))
    except Exception as exc:
        _silo_error(exc)
    return end_dir(content='videos', cache=False)


def silo_section(section_id, title='', offset='0', section_type=''):
    # View-all in Silo Web/App uses the paginated section catalog rather than
    # the small inline Home teaser. This keeps the exact recipe/order while
    # allowing the complete section to be browsed.
    return _silo_page('silo_section', offset, title=title,
                      source='section', section_id=section_id, scope='home', section_type=section_type)


def silo_library(library_id, title='', media_type=''):
    """Three doors, matching Silo's own library layout: All, Recommended, Collections.

    v5.10.16: the library used to dump "كل المحتوى" plus every recommendation
    row plus "الكوليكشنات" into one flat screen, which buried the sections the
    site groups under Recommended. Each door now carries real artwork taken
    from its own first item rather than the shared Silo placeholder.
    """
    try:
        server = _silo_server()
        sections = silo_client.library_sections(server, library_id)

        def _section_items(_srv, sid):
            return silo_client.library_section_items(_srv, library_id, sid)

        _silo_resolve_section_art(server, sections, _section_items,
                                  'lib:%s' % library_id)
        collections = []
        try:
            collections = silo_client.library_collections(server, library_id)
        except Exception:
            collections = []

        # Navigation cards never borrow a random movie poster. This also
        # removes one catalog round-trip from every library open.
        all_art = collection_banner_art('Library', fanart=addon_fanart())
        add_item('All', build_url(action='silo_catalog', library_id=library_id,
                                  media_type=media_type, title=title),
                 art=all_art,
                 info={'title': 'All', 'plot': '%s • كل المحتوى' % (title or 'المكتبة')})

        if sections:
            add_item('Recommended',
                     build_url(action='silo_recommended', library_id=library_id,
                               title=title, media_type=media_type),
                     art=_silo_section_art(sections[0]),
                     info={'title': 'Recommended',
                           'plot': '%d قسم • %s' % (
                               len(sections),
                               '، '.join([s.get('title') or '' for s in sections[:4]]))})

        if collections:
            col_art = collection_banner_art('Collections', fanart=addon_fanart())
            add_item('Collection',
                     build_url(action='silo_collections', library_id=library_id,
                               media_type=media_type, title=title),
                     art=col_art,
                     info={'title': 'Collection', 'plot': '%d كوليكشن' % len(collections)})
    except Exception as exc:
        _silo_error(exc)
    return end_dir(content='videos', cache=False)


