def _emby_server():
    servers = emby_client.servers()
    if not servers:
        raise Exception('لم يتم ربط Emby بعد')
    return servers[0]


def _emby_art(item, server):
    thumb = emby_client.artwork_url(server, item.get('thumb') or '')
    fan = emby_client.artwork_url(server, item.get('art') or '', kind='Backdrop')
    fallback = {'poster': thumb, 'thumb': thumb, 'icon': thumb, 'fanart': fan}
    fallback.update(item.get('artwork') or {})
    return _server_tmdb_art(item, fallback, backend=server.get('backend') or 'emby')


def _emby_render_one(item, server):
    kind = item.get('media_type') or 'movie'
    item_id = item.get('rating_key') or ''
    if not item_id:
        return False
    if kind in ('show', 'season'):
        path = build_url(action='emby_children', key=item_id,
                         title=item.get('title') or 'Emby')
        is_folder = True
    else:
        path = build_url(action='emby_play', item_id=item_id)
        is_folder = False
    label = item.get('title') or 'Emby'
    if kind == 'episode':
        label = '%s  [COLOR grey](S%02dE%02d)[/COLOR]' % (
            label, int(item.get('season') or 0), int(item.get('index') or 0))
    facts = item.get('info_line') or ''
    name = item.get('server_name') or 'Emby'
    add_item(label, path, is_folder=is_folder,
             info=_plex_item_info(item), art=_emby_art(item, server),
             ids=_plex_item_ids(item),
             label2=_native_library_facts(item, 'Emby'),
             properties=None)
    return True


def emby_continue():
    """Emby Continue Watching (Resume + Next Up), mirroring plex_continue."""
    rows = []
    try:
        server = _emby_server()
        try:
            resumed, _total = emby_client.resume(server)
            rows.extend(resumed)
        except Exception as exc:
            try:
                xbmc.log('[DexHub] Emby Resume skipped: %s' % exc, xbmc.LOGWARNING)
            except Exception:
                pass
        # Next Up fills in series whose last episode was finished, so the row
        # behaves like Plex's On Deck rather than a bare "partially played" list.
        try:
            seen = {r.get('rating_key') for r in rows}
            for row in emby_client.next_up(server):
                if row.get('rating_key') not in seen:
                    rows.append(row)
        except Exception as exc:
            try:
                xbmc.log('[DexHub] Emby NextUp skipped: %s' % exc, xbmc.LOGWARNING)
            except Exception:
                pass
    except Exception as exc:
        _emby_error(exc)
    _emby_render_items(rows, 'لا توجد عناصر للمتابعة في Emby')
    end_dir(content='videos', cache=False)


def _emby_render_items(items, empty_label='لا توجد عناصر في Emby'):
    try:
        server = _emby_server()
    except Exception as exc:
        _emby_error(exc)
        return 0
    count = 0
    for item in items or []:
        if _emby_render_one(item, server):
            count += 1
    if not count:
        add_item('[COLOR grey]%s[/COLOR]' % empty_label, build_url(action='emby_menu'),
                 art=root_art('emby'))
    return count


def emby_login():
    """Sign in with the Emby username/password (EmbyCon's AuthenticateByName)."""
    url = _private_input(tr('عنوان سيرفر Emby (مثال: http://192.168.1.10:8096)'))
    if not url:
        return
    user = _private_input(tr('اسم المستخدم'))
    if not user:
        return
    password = xbmcgui.Dialog().input(tr('كلمة المرور'), option=xbmcgui.ALPHANUM_HIDE_INPUT)
    try:
        auth = emby_client.sign_in(url, user, password or '')
    except Exception as exc:
        return _emby_error(exc)
    xbmc.log('[DexHub] Emby linked: user=%s server=%s' % (auth.get('username'), auth.get('server_name')), xbmc.LOGINFO)
    _servers_changed('emby')
    notify(tr('تم ربط Emby • %s') % (auth.get('server_name') or ''))
    xbmc.executebuiltin('Container.Refresh')


def emby_logout():
    emby_client.sign_out()
    _servers_changed('emby')
    notify('تم فصل Emby')
    xbmc.executebuiltin('Container.Refresh')


def emby_menu():
    _set_render_section('emby')
    if not emby_client.is_signed_in():
        add_item('ربط Emby', build_url(action='emby_login'), is_folder=False,
                 art=root_art('settings'), info={'title': 'ربط Emby'})
        return end_dir(content='files', cache=False)
    try:
        server = _emby_server()
        add_item(tr('بحث Emby'), build_url(action='emby_search'), art=root_art('search_movie'))
        # v3.9.232: Emby had NO continue-watching row at all while Plex has had
        # one all along. Emby's /Users/{id}/Items/Resume is the exact equivalent
        # of Plex's On Deck.
        add_item('متابعة المشاهدة • Emby',
                 build_url(action='emby_continue'), art=root_art('continue'),
                 info={'title': 'متابعة المشاهدة',
                       'plot': 'أكمل ما بدأته على Emby.'})
        for library in emby_client.libraries(server):
            _lkey = library.get('key') or ''
            _ltitle = library.get('title') or 'Library'
            _ltype = library.get('type') or ''
            _sorts = [('آخر إضافة', 'DateCreated:desc'),
                      ('آخر إصدار', 'PremiereDate:desc'),
                      ('التقييم', 'CommunityRating:desc'),
                      ('الاسم', 'SortName'),
                      ('السنة', 'ProductionYear:desc')]
            # The sort is SAVED now (emby_sort persists it), so the tile itself
            # reopens in the chosen order instead of snapping back to SortName.
            _saved = sort_prefs.get_sort('emby', 'emby', _lkey, '')
            _ctx = [(tr('فرز: %s%s') % (('● ' if _key == _saved else ''), _label),
                     'RunPlugin(%s)' % build_url(
                         action='emby_sort', key=_lkey, title=_ltitle,
                         library_type=_ltype, current=_saved))
                    for _label, _key in _sorts]
            _saved_label = next((l for l, k in _sorts if k == _saved), '')
            add_item('%s • %s' % (_ltitle, server.get('name') or 'Emby'),
                     build_url(action='emby_library', key=_lkey, title=_ltitle,
                               library_type=_ltype, sort=_saved),
                     art=library.get('artwork') or root_art('emby'), context_menu=_ctx,
                     info={'title': _ltitle,
                           'plot': (tr('الفرز: %s') % _saved_label) if _saved_label else ''})
    except Exception as exc:
        _emby_error(exc)
    add_item('[COLOR grey]فصل Emby[/COLOR]', build_url(action='emby_logout'),
             is_folder=False, art=root_art('settings'))
    end_dir(content='files', cache=False)


_EMBY_SORTS = [
    ('SortName', 'الاسم'),
    ('DateCreated:desc', 'الأحدث إضافة'),
    ('PremiereDate:desc', 'الأحدث إصدارًا'),
    ('ProductionYear:desc', 'السنة'),
    ('CommunityRating:desc', 'التقييم'),
]



def emby_sort(key, title='', library_type='', current=''):
    """Pick a sort for an Emby library AND remember it.

    v3.9.232: the choice used to live only in the Container.Update URL, so it
    was forgotten as soon as the user left the library.  It is now stored per
    library, and the active entry is marked in the dialog.
    """
    # The store is authoritative: `current` is baked into the context-menu URL
    # when the PARENT list is rendered, so it goes stale as soon as the sort
    # changes without leaving that list.
    saved = sort_prefs.get_sort('emby', 'emby', key, '') or current or sort_prefs.newest_first('emby', library_type)
    labels = [(('[COLOR limegreen]● %s[/COLOR]' % label) if _key == saved else label)
              for _key, label in _EMBY_SORTS]
    choice = xbmcgui.Dialog().select(tr('فرز Emby'), labels)
    if choice < 0:
        return
    chosen = _EMBY_SORTS[choice][0]
    sort_prefs.set_sort('emby', 'emby', key, chosen)
    url = build_url(action='emby_library', key=key, title=title,
                    library_type=library_type, sort=chosen, start='0')
    xbmc.executebuiltin('Container.Update(%s,replace)' % url)


def emby_library_filters(genre='', unwatched='', decade='', rating=''):
    """Emby's and Jellyfin's own item filters for a library page (v5.10.106,
    the Home's Filter and Genre): a genre id, unwatched only, a decade, a
    lowest community rating."""
    filters = {}
    if str(genre or '').strip():
        filters['GenreIds'] = str(genre).strip()
    if str(unwatched or '') in ('1', 'true'):
        filters['IsPlayed'] = 'false'
    decade = str(decade or '').strip()
    if decade.isdigit() and len(decade) == 4:
        first = int(decade) - int(decade) % 10
        filters['Years'] = ','.join(str(first + i) for i in range(10))
    try:
        if rating and float(rating) > 0:
            filters['MinCommunityRating'] = str(float(rating))
    except Exception:
        pass
    return filters


def emby_library(key, title='', library_type='', start='0', sort='', genre='', unwatched='',
                 decade='', rating=''):
    # Explicit ?sort= wins; otherwise reopen with the remembered choice instead
    # of silently snapping back to SortName.
    if not sort:
        sort = sort_prefs.get_sort('emby', 'emby', key, '')
    # v5.10.198: by default, what was added last (shows: the newest episode)
    sort = sort or sort_prefs.newest_first('emby', library_type)
    try:
        server = _emby_server()
        # Top-level libraries are flattened recursively. Movie libraries return
        # only Movie rows; TV libraries return only Series rows. This removes
        # the filesystem/collection folders that Emby exposes as children.
        include_types = 'Series' if library_type == 'show' else 'Movie'
        rows, total = emby_client.children(
            server, key, start=int(start or 0), sort=sort,
            include_types=include_types, recursive=True,
            filters=emby_library_filters(genre, unwatched, decade, rating))
        for row in rows:
            row['library_name'] = row.get('library_name') or title
        # v3.9.225: the sort control no longer eats the first slot of every
        # library. It lives where Plex's already does — long-press the library.
        _emby_render_items(rows)
        nxt = int(start or 0) + len(rows)
        if rows and total > nxt:
            more = dict(action='emby_library', key=key, title=title,
                        library_type=library_type, sort=sort, start=str(nxt))
            for name, value in (('genre', genre), ('unwatched', unwatched),
                                ('decade', decade), ('rating', rating)):
                if value:
                    more[name] = value
            add_item('المزيد', build_url(**more),
                     art=root_art('emby'), info={'title': 'المزيد'})
    except Exception as exc:
        _emby_error(exc)
    end_dir(content='tvshows' if library_type == 'show' else 'movies', cache=False)


def emby_children(key, title='', start='0'):
    from .server_art import listing_content
    content = 'episodes'
    try:
        server = _emby_server()
        rows, total = emby_client.children(server, key, start=int(start or 0))
        content = listing_content(rows, content)
        _emby_render_items(rows)
        nxt = int(start or 0) + len(rows)
        if rows and total > nxt:
            add_item('المزيد', build_url(action='emby_children', key=key, title=title,
                                          start=str(nxt)),
                     art=root_art('emby'), info={'title': 'المزيد'})
    except Exception as exc:
        _emby_error(exc)
    end_dir(content=content, cache=False)


def emby_play(item_id, server=None, backend='emby', force_native=False, ui_seed_key='', preferred_version='', resume_seconds=None):
    try:
        server = server or _emby_server()
        item = emby_client.metadata(server, item_id)
    except Exception as exc:
        return _emby_error(exc)
    from .library_mode import library_direct as _library_direct
    if not force_native and not _library_direct(ADDON):
        return _library_dexhub_play(item, backend, server, ui_seed_key=ui_seed_key)
    versions = list(item.get('versions') or [])
    source_id = ''
    selected_version = {}
    from .playback_choices import saved_version
    selected_version = saved_version(versions, preferred_version, ('media_source_id',))
    if selected_version:
        source_id = selected_version.get('media_source_id') or ''
    elif len(versions) > 1:
        poster = emby_client.artwork_url(server, item.get('thumb') or '')
        try:
            rows = []
            for i, version in enumerate(versions):
                li = xbmcgui.ListItem(item.get('raw_title') or item.get('title') or 'Emby')
                try:
                    li.setLabel2(version.get('version_label') or 'Version %d' % (i + 1))
                    if poster:
                        li.setArt({'icon': poster, 'thumb': poster, 'poster': poster})
                except Exception:
                    pass
                rows.append(li)
            choice = xbmcgui.Dialog().select(tr('اختر النسخة'), rows, useDetails=True)
        except Exception:
            choice = xbmcgui.Dialog().select(
                tr('اختر النسخة'), [v.get('version_label') or '?' for v in versions])
        if choice < 0:
            return
        selected_version = versions[choice]
        source_id = selected_version.get('media_source_id') or ''
    elif versions:
        selected_version = versions[0]
        source_id = selected_version.get('media_source_id') or ''
    try:
        resolved = emby_client.resolve_playback(server, item_id, source_id)
        stream_url = resolved.get('url') or ''
        selected_version = resolved.get('version') or selected_version
        source_id = resolved.get('media_source_id') or source_id
    except Exception as exc:
        return _emby_error(exc)
    _ids = item.get('ids') or {}
    _show_ids = {}
    _show_item = None
    if item.get('media_type') == 'episode' and item.get('series_id'):
        try:
            _show_item = emby_client.metadata(server, item.get('series_id'))
            _show_ids = _show_item.get('ids') or {}
        except Exception as exc:
            xbmc.log('[DexHub][TheIntroDB] Emby show identity unavailable: %s' % exc,
                     xbmc.LOGWARNING)
    try:
        _open_poster, _open_fanart, _open_logo = _server_open_art(
            item, backend, server, ui_seed_key=ui_seed_key,
            show_ids=_show_ids if item.get('media_type') == 'episode' else None, show_item=_show_item,
            network=False)
    except Exception:
        _open_poster, _open_fanart, _open_logo = '', '', ''
    ctx = {
        'media_type': 'series' if item.get('media_type') == 'episode' else 'movie',
        'canonical_id': _ids.get('imdb_id') or ('tmdb:%s' % _ids.get('tmdb_id') if _ids.get('tmdb_id') else '%s:%s' % (backend, item_id)),
        'video_id': str(item_id),
        'title': item.get('raw_title') or item.get('title') or 'Emby',
        'show_title': item.get('show_title') or '',
        'stream_url': stream_url,
        'provider_id': '%s_native' % backend,
        'server_id': str(server.get('id') or ''),
        'provider_name': '%s • %s' % (backend.title(), server.get('name') or 'Server'),
        'server_type': backend,
        'server_url': server.get('url') or '',
        'token': server.get('token') or '',
        'item_id': str(item_id),
        'device_id': emby_client._device_id(backend),
        'session_id': resolved.get('play_session_id') or '',
        'play_session_id': resolved.get('play_session_id') or '',
        'media_source_id': source_id,
        'native_playback_resolved': True,
        'poster': _open_poster or (item.get('artwork') or {}).get('poster') or emby_client.artwork_url(server, item.get('thumb') or ''),
        'background': _open_fanart or (item.get('artwork') or {}).get('fanart') or emby_client.artwork_url(server, item.get('art') or item.get('thumb') or '', kind='Backdrop'),
        'clearlogo': _open_logo,
        'duration_ms': item.get('duration_ms') or 0,
        'duration': int((item.get('duration_ms') or 0) / 1000),
        'season': item.get('season') or None,
        'episode': item.get('index') or None,
        'imdb_id': _normalize_imdb_id(_ids.get('imdb_id')) or '',
        'tmdb_id': _ids.get('tmdb_id') or '',
        'tvdb_id': _ids.get('tvdb_id') or '',
        'show_imdb_id': _normalize_imdb_id(_show_ids.get('imdb_id')) or '',
        'show_tmdb_id': _show_ids.get('tmdb_id') or '',
        'show_tvdb_id': _show_ids.get('tvdb_id') or '',
        'subtitles': list(selected_version.get('subtitles') or []),
    }
    if resume_seconds is not None:
        ctx['resume_seconds'] = float(resume_seconds)
    elif backend == 'jellyfin' or force_native:
        ctx['resume_seconds'] = float(item.get('view_offset_ms') or 0) / 1000
    ctx['stream_key'] = cache_store.put('stream', {
        'stream_url': stream_url,
        'name': item.get('title') or 'Emby',
        'provider_name_raw': '%s • %s' % (backend.title(), server.get('name') or ''),
        'size_label': item.get('size_label') or '',
        'subtitles': list(selected_version.get('subtitles') or []),
    })
    return _play_with_context(ctx, stream_key=ctx['stream_key'], use_resolved_url=False)



