def poster_pick_global():
    from . import meta_source as _ms
    sources = [{'id': 'same', 'name': tr('نفس مصدر الميتاداتا')},
               {'id': 'betterposters', 'name': 'Better Posters'}]
    sources += [s for s in _ms.list_available_meta_sources() if s['id'] not in ('auto', 'native')]
    current = ADDON.getSetting('global_poster_source_id') or 'same'
    choice = xbmcgui.Dialog().select(tr('مصدر البوستر للكل'), [tr(s['name']) for s in sources],
        preselect=next((i for i, s in enumerate(sources) if s['id'] == current), 0))
    if choice < 0:
        return
    ADDON.setSetting('global_poster_source_id', sources[choice]['id'])
    if sources[choice]['id'] == 'betterposters':
        ADDON.setSetting('betterposters_enabled', 'true')
        _better_posters.invalidate()
    # v5.10.288: listings replayed to Kodi's widgets carry the old posters
    # (the skin's rows get the poster pass from the service: skinui.worker)
    try:
        from . import widget_cache as _widget_cache
        _widget_cache.clear()
    except Exception:
        pass
    _refresh_metadata_selection()
    notify('%s: %s' % (tr('مصدر البوستر للكل'), tr(sources[choice]['name'])))


def _meta_pick_target(target_key='', title=''):
    try:
        from . import meta_source as _meta_source
    except Exception as exc:
        error('meta_source missing: %s' % exc)
        return
    if not target_key:
        return
    sources = _meta_source.list_available_meta_sources()
    provider = store.get_provider(target_key)
    if provider:
        sources = [s for s in sources if s.get('id') != target_key]
        title = title or (provider.get('name') or target_key)
    if target_key in ('plex_server', 'emby_server'):
        # A Stremio addon cannot supply artwork for a Plex/Emby library row, so
        # only the real choices are offered. 'native' = keep the SERVER's own
        # posters, which is what you want when they carry overlays/badges.
        _server_name = 'Plex' if target_key == 'plex_server' else 'Emby'
        sources = [s for s in sources
                   if s.get('id') in ('auto', 'tmdb_helper', 'native')]
        for s in sources:
            if s.get('id') == 'native':
                s['name'] = tr('بوسترات %s نفسها (تُبقي الأوفرلايات)') % _server_name
    is_nuvio_collection_target = str(target_key).startswith('virtual.collection.nuvio:')
    if is_nuvio_collection_target:
        # For a Nuvio collection, Auto means exactly what Nuvio is configured
        # to use (native addon artwork + synced TMDb/profile preferences). Do
        # not display Dex Hub's global metadata default as if it were active.
        for src in sources:
            if src.get('id') == 'auto':
                src['name'] = tr('Nuvio — حسب إعدادات الحساب والمصدر')
                break
        current = _meta_source.get_explicit_meta_source_for(target_key) or 'auto'
    else:
        current = _meta_source.get_meta_source_for(target_key)
    labels = [s.get('name') or s.get('id') or 'Source' for s in sources]
    preselect = 0
    for idx, src in enumerate(sources):
        if src.get('id') == current:
            preselect = idx
            break
    choice = xbmcgui.Dialog().select(tr(title or tr('اختر مصدر الميتاداتا')), [tr(x) for x in labels], preselect=preselect)
    if choice < 0:
        return
    picked = sources[choice]
    _meta_source.set_meta_source_for(target_key, picked.get('id') or 'auto')
    # Drop the in-memory meta cache layer so the next catalog/detail render
    # actually re-applies the override path. The HTTP cache is purged by
    # set_meta_source_for; _META_MEM still holds POST-override metas keyed by
    # the previous discriminator — it's already unreachable, but clearing
    # frees the memory immediately and prevents accidental re-use under any
    # future code path that might key by something other than the full map.
    _meta_mem_clear()
    notify('%s → %s' % (title or target_key, picked.get('name') or picked.get('id') or ''))
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass


def meta_sources_dialog():
    _close_native_settings_dialog()
    try:
        from . import meta_source as _meta_source
    except Exception as exc:
        error('meta_source missing: %s' % exc)
        return
    # v3.9.30: top-level picker — by provider (legacy) or by folder (new).
    mode = xbmcgui.Dialog().select(tr('إدارة مصادر الميتاداتا'), [
        tr('لكل الإضافة — تخصيص كامل للصور'),
        tr('حسب الإضافة (مصدر الميتاداتا)'),
        tr('حسب المجلد (استثناءات مخصصة)'),
    ])
    if mode < 0:
        return
    if mode == 0:
        return global_art_sources_dialog()
    if mode == 2:
        return _meta_sources_by_bucket_dialog()
    # Per-provider metadata flow
    rows = []
    for prov in store.list_providers() or []:
        pid = prov.get('id') or ''
        if not pid:
            continue
        current = _meta_source.source_display_name(_meta_source.get_meta_source_for(pid))
        rows.append((pid, '%s → %s' % (prov.get('name') or pid, current), prov.get('name') or pid))
    for key, label in _virtual_meta_targets():
        current = _meta_source.source_display_name(_meta_source.get_meta_source_for(key))
        rows.append((key, '%s → %s' % (label, current), label))
    if not rows:
        error(tr('لا توجد مصادر بعد'))
        return
    choice = xbmcgui.Dialog().select(tr('إدارة مصادر الميتاداتا'), [tr(row[1]) for row in rows])
    if choice < 0:
        return
    target_key, _label, title = rows[choice]
    return _meta_pick_target(target_key, title)


def _art_type_rows():
    return [
        ('poster', tr('البوستر')),
        ('background', tr('الخلفية Fanart')),
        ('landscape', tr('Landscape')),
        ('banner', tr('Banner')),
        ('clearlogo', tr('ClearLogo')),
        ('clearart', tr('ClearArt')),
    ]


def global_art_sources_dialog():
    from . import meta_source as _ms
    while True:
        rows = _art_type_rows()
        labels = []
        for kind, label in rows:
            current = _ms.get_global_art_priority(kind)
            summary = ' → '.join(_ms.source_display_name(x) for x in current[:3])
            if len(current) > 3:
                summary += ' +%d' % (len(current) - 3)
            labels.append('%s%s' % (label, ('  [%s]' % summary) if summary else ''))
        labels.extend([tr('مسح كل تخصيص الصور'), tr('رجوع')])
        idx = xbmcgui.Dialog().select(tr('تخصيص الصور لكل الإضافة'), labels)
        if idx < 0 or idx == len(rows) + 1:
            return
        if idx == len(rows):
            if xbmcgui.Dialog().yesno('Dex Hub', tr('سيتم مسح كل مصادر الصور المخصصة. هل تريد المتابعة؟')):
                _ms.clear_global_art()
                _meta_mem_clear()
                xbmc.executebuiltin('Container.Refresh')
            continue
        _art_pick_priority_global(rows[idx][0])


def _all_art_source_candidates():
    from . import meta_source as _ms
    candidates = [('native', tr('الصورة الأصلية من المصدر')),
                  ('tmdb_helper', 'TMDb Helper')]
    seen = {'native', 'tmdb_helper'}
    for provider in store.list_providers() or []:
        pid = provider.get('id') or ''
        if pid and pid not in seen and _ms._provider_supports_meta(provider):
            seen.add(pid)
            candidates.append((pid, provider.get('name') or pid))
    return candidates


def _art_pick_priority_global(art_type):
    from . import meta_source as _ms
    candidates = _all_art_source_candidates()
    current = _ms.get_global_art_priority(art_type)
    current_set = set(current)
    ordered = []
    for pid in current:
        match = next((x for x in candidates if x[0] == pid), None)
        if match:
            ordered.append(match)
    for row in sorted(candidates, key=lambda x: x[1].lower()):
        if row[0] not in current_set:
            ordered.append(row)
    labels = []
    for pid, name in ordered:
        labels.append(('[%d]  ' % (current.index(pid) + 1) if pid in current_set else '     ') + name)
    selected = xbmcgui.Dialog().multiselect(
        tr('اختر المصادر بالترتيب — الأولوية من الأعلى للأسفل'),
        labels,
        preselect=[i for i, (pid, _n) in enumerate(ordered) if pid in current_set],
    )
    if selected is None:
        return
    _ms.set_global_art_priority(art_type, [ordered[i][0] for i in selected])
    _meta_mem_clear()
    try:
        xbmc.executebuiltin('Container.Refresh')
    except Exception:
        pass


