def section_art_sources_dialog():
    """Customize artwork for stable Dex Hub sections and user folders."""
    sections = [
        ('continue', tr('متابعة المشاهدة')),
        ('favorites', tr('المفضلة')),
        ('search', tr('البحث')),
        ('collection', 'Collection'),
        ('plex', 'Plex'),
        ('emby', 'Emby / Jellyfin'),
        ('stremio', tr('مصادر Stremio')),
    ]
    dynamic = sorted(set((b or '') for (_p, _c, b) in (_hub_catalog_entries(bucket=None) or []) if b))
    known = set(k for k, _ in sections)
    sections.extend((b, _hub_bucket_title(b)) for b in dynamic if b not in known)
    idx = xbmcgui.Dialog().select(tr('اختر القسم لتخصيص صوره'), [label for _key, label in sections])
    if idx < 0:
        return
    bucket, title = sections[idx]
    while True:
        rows = _art_type_rows()
        labels = []
        from . import meta_source as _ms
        for kind, label in rows:
            cur = _ms.get_bucket_art_priority(bucket, kind)
            summary = ' → '.join(_ms.source_display_name(x) for x in cur[:2])
            labels.append(label + (('  [%s]' % summary) if summary else ''))
        labels.extend([tr('مسح تخصيص هذا القسم'), tr('رجوع')])
        pick = xbmcgui.Dialog().select('%s • %s' % (tr('تخصيص الصور'), title), labels)
        if pick < 0 or pick == len(rows) + 1:
            return
        if pick == len(rows):
            if xbmcgui.Dialog().yesno('Dex Hub', tr('مسح كل تخصيص الصور لهذا القسم؟')):
                _ms.clear_bucket_art_for(bucket)
                _meta_mem_clear()
            continue
        _bucket_art_pick_priority(bucket, rows[pick][0])


def _meta_sources_by_bucket_dialog():
    """Per-bucket art priority picker (v3.9.30).

    Walks the user through:
      1) Pick a bucket (movies/series/anime/etc.)
      2) Pick an art type (poster/background/clearlogo)
      3) Re-rank the provider priority list for that combo
    """
    from . import meta_source as _ms
    # Step 1 — bucket. Build the list from the home folder catalog so
    # only buckets the user actually has show up.
    buckets = sorted(set(
        (b or '') for (_p, _c, b) in (_hub_catalog_entries(bucket=None) or [])
        if b
    ))
    if not buckets:
        error(tr('لا توجد مجلدات بعد'))
        return
    titles = [(b, _hub_bucket_title(b)) for b in buckets]
    bidx = xbmcgui.Dialog().select(
        tr('اختر المجلد'),
        [t for (_b, t) in titles])
    if bidx < 0:
        return
    bucket = titles[bidx][0]

    while True:
        # Step 2 — art type
        art_types = _art_type_rows() + [
            ('__reset', tr('🗑  مسح كل الأولويات لهذا المجلد')),
            ('__back', tr('↩  رجوع')),
        ]
        # Show current priority count next to each art type
        type_labels = []
        for (kind, label) in art_types:
            if kind.startswith('__'):
                type_labels.append(label)
                continue
            n = len(_ms.get_bucket_art_priority(bucket, kind))
            badge = (' (%d)' % n) if n > 0 else ''
            type_labels.append(label + badge)
        tidx = xbmcgui.Dialog().select(
            tr('%s — اختر نوع الـ Art') % _hub_bucket_title(bucket),
            type_labels)
        if tidx < 0:
            return
        kind, _label = art_types[tidx]
        if kind == '__back':
            return
        if kind == '__reset':
            if xbmcgui.Dialog().yesno('Dex Hub',
                tr('سيتم مسح كل أولويات الـ Art لهذا المجلد. هل تريد المتابعة؟')):
                _ms.clear_bucket_art_for(bucket)
                xbmcgui.Dialog().notification('Dex Hub',
                    tr('تم المسح'), xbmcgui.NOTIFICATION_INFO, 2000, sound=False)
            continue

        # Step 3 — pick providers
        _bucket_art_pick_priority(bucket, kind)


def _bucket_art_pick_priority(bucket, art_type):
    """Show the user every meta-capable provider for this bucket and let
    them tick the ones to use, ordered by tick order."""
    from . import meta_source as _ms
    # Collect candidate providers — pinned to this bucket OR globally meta-capable.
    pinned = [p for (p, _c, b) in (_hub_catalog_entries(bucket=bucket) or []) if p]
    seen_pids = {'native', 'tmdb_helper'}
    candidates = [('native', tr('الصورة الأصلية من المصدر')),
                  ('tmdb_helper', 'TMDb Helper')]
    for p in pinned:
        pid = (p or {}).get('id') or ''
        if pid and pid not in seen_pids:
            seen_pids.add(pid)
            candidates.append((pid, p.get('name') or pid))
    # Add any meta-capable provider not already in pinned list
    for p in (store.list_providers() or []):
        pid = (p or {}).get('id') or ''
        if pid and pid not in seen_pids and _ms._provider_supports_meta(p):
            seen_pids.add(pid)
            candidates.append((pid, p.get('name') or pid))
    if not candidates:
        error(tr('لا توجد مصادر مرشّحة'))
        return

    current = _ms.get_bucket_art_priority(bucket, art_type)
    current_set = set(current)

    # Show candidates sorted: currently-chosen first (in priority order),
    # then the rest alphabetically.
    ordered = []
    for pid in current:
        match = next((c for c in candidates if c[0] == pid), None)
        if match:
            ordered.append(match)
    for c in sorted(candidates, key=lambda x: x[1].lower()):
        if c[0] not in current_set:
            ordered.append(c)

    # Build label list — show position number for selected entries.
    labels = []
    for (pid, name) in ordered:
        if pid in current_set:
            pos = current.index(pid) + 1
            labels.append('[%d]  %s' % (pos, name))
        else:
            labels.append('     %s' % name)

    # Multi-select preserves order of selection — that's our priority.
    selected = xbmcgui.Dialog().multiselect(
        tr('اختر مصادر %s بالترتيب') % {
            'poster': tr('البوستر'),
            'background': tr('الخلفية'),
            'landscape': 'Landscape',
            'banner': 'Banner',
            'clearlogo': 'ClearLogo',
            'clearart': 'ClearArt',
        }.get(art_type, art_type),
        labels,
        preselect=[i for i, (pid, _n) in enumerate(ordered) if pid in current_set],
    )
    if selected is None:
        return
    new_priority = [ordered[i][0] for i in selected]
    _ms.set_bucket_art_priority(bucket, art_type, new_priority)
    xbmcgui.Dialog().notification('Dex Hub',
        tr('تم حفظ ترتيب %d مصدر') % len(new_priority),
        xbmcgui.NOTIFICATION_INFO, 2500, sound=False)


def selfhost_settings_menu():
    """One small page for the Kaptain/AIO self-host workflow."""
    from . import selfhost_aio as _selfhost
    state = _selfhost.config_status()
    on = _selfhost.enabled()
    manifest = _selfhost.manifest_url()
    add_item(tr('Self‑Hosted • %s') % (tr('مفعّل') if on else tr('متوقف')),
             build_url(action='selfhost_toggle'), is_folder=False, art=root_art('settings'),
             info={'title': 'Self‑Hosted', 'plot': tr('تحويل كتالوجات aio-metadata إلى TMDb/Trakt محلياً، واستخدام السيرفر المخصص فقط لما لا يمكن تحويله.')})
    add_item(tr('AIO Metadata URL • %s') % (manifest or tr('غير محدد')),
             build_url(action='selfhost_set_manifest'), is_folder=False, art=root_art('providers'),
             info={'title': 'AIO Metadata', 'plot': tr('الصق رابط السيرفر أو manifest.json. يمكن تركه فارغاً إذا كنت تستخدم خريطة الكتالوجات المحلية فقط.')})
    add_item(tr('استيراد AIO Metadata config • %d كتالوج') % int(state.get('catalogs') or 0),
             build_url(action='selfhost_import_aio_config'), is_folder=False, art=root_art('catalogs'),
             info={'title': 'AIO Metadata config', 'plot': tr('استيراد ملف aiometadata_config JSON الذي يصدره إعدادك Self‑Hosted.')})
    add_item(tr('استخدام Collection Self‑Hosted المدمجة'),
             build_url(action='selfhost_use_bundled_collection'), is_folder=False, art=root_art('movie_collections'),
             info={'title': 'Self‑Hosted Collection', 'plot': tr('استيراد نسخة Nuvio/Kaptain Self‑Hosted المدمجة كـ Collection مستقلة. يمكنك استبدالها بأي ملف JSON من Kaptain.')})
    add_item(tr('اختبار Self‑Hosted'), build_url(action='selfhost_test'), is_folder=False,
             art=root_art('settings'), info={'title': tr('اختبار الاتصال'), 'plot': tr('يفحص خريطة الكتالوجات والرابط إن كان موجوداً.')})
    return end_dir(content='files', cache=False)
def selfhost_toggle():
    from . import selfhost_aio as _selfhost
    value = not _selfhost.enabled()
    ADDON.setSetting('selfhost_enabled', 'true' if value else 'false')
    notify(tr('Self‑Hosted مفعّل') if value else tr('Self‑Hosted متوقف'))
    return selfhost_settings_menu()
def selfhost_set_manifest():
    from . import selfhost_aio as _selfhost
    current = _selfhost.manifest_url()
    try:
        raw = _private_input(tr('رابط AIO Metadata Self‑Hosted'), defaultt=current or '', type=xbmcgui.INPUT_ALPHANUM)
    except Exception:
        raw = ''
    raw = str(raw or '').strip()
    if raw.endswith('/manifest.json'):
        raw = raw[:-len('/manifest.json')]
    ADDON.setSetting('selfhost_aio_manifest_url', raw.rstrip('/'))
    notify(tr('تم حفظ رابط Self‑Hosted') if raw else tr('تم مسح رابط Self‑Hosted'))
    return selfhost_settings_menu()
def selfhost_import_aio_config():
    from . import selfhost_aio as _selfhost
    try:
        path = xbmcgui.Dialog().browse(1, tr('اختر ملف AIO Metadata config'), 'files', '.json')
    except Exception:
        path = ''
    path = str(path or '').strip()
    if not path:
        return selfhost_settings_menu()
    try:
        local_path = xbmcvfs.translatePath(path)
        _target, count = _selfhost.save_imported_config(local_path)
        notify(tr('تم استيراد %d كتالوج') % int(count))
    except Exception as exc:
        error(tr('فشل استيراد AIO Metadata: %s') % exc)
    return selfhost_settings_menu()
def selfhost_use_bundled_collection():
    from . import selfhost_aio as _selfhost
    try:
        from . import bundled_data as _bundled_data
        path = _selfhost.bundled_collection_path()
        raw = _bundled_data.read_text(path)
        if not raw:
            raise IOError('bundled collection not readable: %s' % path)
        row = _collections_mod.add_set_from_text(raw, source_label='Self Hosted Collection', manifest_resolver=_make_addon_manifest_resolver(''))
        notify(tr('تم استيراد Collection Self‑Hosted'))
        try:
            xbmc.executebuiltin('Container.Refresh')
        except Exception:
            pass
        return collection_set_browse(row.get('id') or '')
    except Exception as exc:
        error(tr('تعذّر استيراد Collection Self‑Hosted: %s') % exc)
        return selfhost_settings_menu()
def selfhost_test():
    from . import selfhost_aio as _selfhost
    state = _selfhost.config_status()
    lines = [tr('Catalog map: %d') % int(state.get('catalogs') or 0),
             tr('Config: مخصص') if state.get('custom') else tr('Config: المدمج')]
    manifest = _selfhost.manifest_url()
    if manifest:
        try:
            result = validate_manifest(manifest)
            ok = bool(result)
            lines.append(tr('Manifest: متصل') if ok else tr('Manifest: لم يستجب'))
        except Exception:
            lines.append(tr('Manifest: لم يستجب'))
    else:
        lines.append(tr('Manifest: غير مطلوب للكتالوجات القابلة للتحويل'))
    xbmcgui.Dialog().ok('Dex Hub • Self‑Hosted', '\n'.join(lines))
    return selfhost_settings_menu()


