def _close_native_settings_dialog():
    """Prevent Kodi's stale settings tree from overwriting dialog changes."""
    # v5.10.145: wait until the dialog has really closed (and saved its own
    # copy); a fixed 180 ms let that copy undo our write on a slow box.
    try:
        if xbmc.getCondVisibility('Window.IsVisible(addonsettings)'):
            xbmc.executebuiltin('Dialog.Close(addonsettings)')
            for _ in range(60):
                xbmc.sleep(50)
                if not xbmc.getCondVisibility('Window.IsVisible(addonsettings)'):
                    break
            xbmc.sleep(150)
    except Exception:
        pass


