def theme_select_action():
    """v4.6.0: one-tap theme picker.

    The theme_preset setting existed since 4.4.0 but was buried mid-way
    through the Accounts & API keys category, so nobody could find it. This
    action gives it a front door: a select dialog with a live colour swatch
    per preset, applied instantly (publish_theme repaints every open DexHub
    window on its next frame) — no settings spelunking, no restart.
    """
    from . import skin_theme
    current = ''
    try:
        current = (ADDON.getSetting('theme_preset') or '0').strip()
    except Exception:
        current = '0'
    dexhub_skin = xbmc.getSkinDir() == skin_theme.DEXHUB_SKIN
    if dexhub_skin:
        # v5.10.131: on skin.dexhub the theme is the skin's colour theme
        current = skin_theme.preset_for_colour(skin_theme.skin_colour_theme()) or current
    options = [('0', tr('تلقائي (حسب السكين)'), '')]
    for key in sorted(skin_theme.THEME_PRESETS.keys(), key=int):
        preset = skin_theme.THEME_PRESETS[key]
        options.append((key, preset.get('name') or key, preset.get('accent') or ''))
    labels = []
    preselect = 0
    for idx, (key, name, accent) in enumerate(options):
        # v4.6.1: the NAME itself was the colour swatch (U+2B24 / U+2713 render
        # as tofu boxes in some skin fonts). v5.10.132: a dot (U+25CF, in
        # every font the skins ship) carries the colour and the name keeps the
        # list's own colour: a light theme's name vanished on a light focus.
        shown = ('[COLOR %s]●[/COLOR]  [B]%s[/B]' % (accent, name)) if accent else name
        if key == current:
            shown = '%s  %s' % (shown, tr('(الحالي)'))
            preselect = idx
        labels.append(shown)
    try:
        choice = xbmcgui.Dialog().select(tr('اختيار الثيم'), labels, preselect=preselect)
    except TypeError:
        # Kodi builds without the preselect kwarg
        choice = xbmcgui.Dialog().select(tr('اختيار الثيم'), labels)
    if choice < 0:
        return
    key, name, _accent = options[choice]
    try:
        ADDON.setSetting('theme_preset', key)
    except Exception as exc:
        xbmc.log('[DexHub] theme_select: setSetting failed: %s' % exc, xbmc.LOGWARNING)
    # v4.6.4: settings_cache serves a per-invocation snapshot — without an
    # invalidate, publish_theme() re-reads the OLD preset in this same
    # invocation and republishes the previous palette.
    try:
        from . import settings_cache as _sc
        _sc.invalidate()
    except Exception:
        pass
    later = False
    if dexhub_skin and key != '0':
        # v5.10.131: skin.dexhub takes the theme as its colour theme (Kodi's
        # Interface > Skin > Colours): the skin and Dex Hub stay one theme
        try:
            from . import theme_sync
            later = not theme_sync.picked(key)
        except Exception as exc:
            xbmc.log('[DexHub] theme_select: skin colours not set: %s' % exc, xbmc.LOGWARNING)
    try:
        skin_theme.publish_theme(log=lambda m: xbmc.log('[DexHub] %s' % m, xbmc.LOGINFO))
    except Exception as exc:
        xbmc.log('[DexHub] theme_select: publish failed: %s' % exc, xbmc.LOGWARNING)
    message = tr('تم تطبيق الثيم: %s') % name
    if later:
        message = tr('يُطبَّق الثيم %s على السكين بعد إغلاق صفحات Dex Hub') % name
    xbmcgui.Dialog().notification('Dex Hub', message, xbmcgui.NOTIFICATION_INFO, 2500, sound=False)


def _upgrade_or_warn_http_url(manifest_url, silent=False):
    """v3.9.17: HTTPS hardening for manifest URLs.

    Stremio manifests are loaded into Kodi every catalog open and stream
    pick — exposing them over plaintext HTTP lets any actor on the network
    swap the response and seed the user with malicious URLs. We do two
    things, in order:

    1) **Silent upgrade** — if the user pasted ``http://``, try the same
       URL with ``https://`` first. If that responds and parses as a valid
       manifest, switch. Most public Stremio addons run on TLS by default,
       so this fixes the common case (user copied an old http link from a
       forum) with zero friction.

    2) **Loud warning** — if HTTPS isn't reachable, surface a Yes/No dialog
       explaining the risk and let the user decide. Local self-hosted
       servers and LAN deployments are legitimate use cases for HTTP, so
       blocking outright would break them.

    Returns the (possibly upgraded) manifest URL, or ``None`` if the user
    declined to proceed with plaintext HTTP.
    """
    if not manifest_url or not manifest_url.lower().startswith('http://'):
        return manifest_url

    https_candidate = 'https://' + manifest_url[len('http://'):]
    try:
        # Cheap probe with explicit short timeout — we're only confirming
        # the manifest reachably parses; full validation runs again later
        # in the normal flow.
        validate_manifest(https_candidate)
        xbmc.log('[DexHub] HTTPS upgrade succeeded for %s -> %s' %
                 (manifest_url, https_candidate), xbmc.LOGINFO)
        notify(tr('تم ترقية الرابط إلى HTTPS تلقائياً'))
        return https_candidate
    except Exception as exc:
        xbmc.log('[DexHub] HTTPS upgrade not possible for %s: %s' %
                 (manifest_url, exc), xbmc.LOGINFO)

    # HTTPS not reachable — explicit consent required for plaintext.
    #
    # v3.9.236: a headless caller (phone / JSON-RPC) has nobody at the TV to
    # answer this dialog. Do NOT silently accept plaintext on their behalf —
    # that would be consenting to a downgrade the user never saw. Refuse, and
    # say why. The user can still add an http-only source from the TV, where
    # the warning is actually shown and answered.
    if silent:
        xbmc.log('[DexHub] refusing http-only manifest for a headless caller: %s'
                 % manifest_url, xbmc.LOGWARNING)
        error(tr('هذا المصدر يستخدم HTTP غير مشفّر. أضِفه من التلفاز للموافقة على التحذير.'))
        return None

    proceed = xbmcgui.Dialog().yesno(
        'Dex Hub',
        tr('هذا المصدر يستخدم HTTP غير المشفّر. أي شخص على نفس الشبكة يستطيع اعتراض البيانات أو تبديلها. هل تريد المتابعة على مسؤوليتك؟'),
        nolabel=tr('إلغاء'),
        yeslabel=tr('متابعة على HTTP'),
        defaultbutton=xbmcgui.DLG_YESNO_NO_BTN,
    )
    return manifest_url if proceed else None


def add_provider(manifest_url=''):
    """Add a source. `manifest_url` may be supplied by the CALLER.

    v3.9.236: this used to unconditionally open xbmc.Keyboard, which meant the
    only way to add a source was to type a manifest URL with a TV remote — the
    single most painful thing in the addon. Passing the URL as a parameter makes
    the action headless, so it can be driven from a phone over Kodi's own
    JSON-RPC:

        Addons.ExecuteAddon
          addonid = plugin.video.dexhub
          params  = ["action=add_provider",
                     "manifest_url=https://…/manifest.json"]

    The keyboard remains the fallback when no URL is given, so the on-TV flow is
    unchanged. Everything below this point was already headless-safe.
    """
    manifest_url = (manifest_url or '').strip()
    _headless = bool(manifest_url)
    if not manifest_url:
        keyboard = xbmc.Keyboard('', tr('ألصق رابط manifest.json أو collections.json'))
        _private_modal(keyboard)
        if not keyboard.isConfirmed():
            return end_dir()
        manifest_url = keyboard.getText().strip()
        if not manifest_url:
            return end_dir()
    # v5.10.143 (GitHub issue #1): an install button's stremio:// link or a
    # Stremio Web link stands for the https manifest behind it.
    from .dexhub.links import manifest_link
    manifest_url = manifest_link(manifest_url)
    try:
        promoted = _collections_mod.manifest_url_from_collections_url(manifest_url)
    except Exception:
        promoted = ''
    converted = bool(promoted and promoted != manifest_url)
    if promoted:
        manifest_url = promoted
    # v3.9.17: HTTPS hardening — attempt silent upgrade, fall back to a
    # consent dialog if only HTTP is reachable, abort if user declines.
    # A headless caller cannot answer a consent dialog on the TV, so an
    # http-only URL is refused outright rather than hanging on a modal.
    manifest_url = _upgrade_or_warn_http_url(manifest_url, silent=_headless)
    if not manifest_url:
        notify(tr('تم إلغاء إضافة المصدر'))
        return end_dir()
    try:
        manifest = validate_manifest(manifest_url)
        name = manifest.get('name') or manifest.get('id') or 'Provider'
        store.add_provider(name=name, manifest_url=manifest_url, manifest=manifest)
        if converted:
            notify(tr('تمت إضافة المصدر من رابط الكوليكشن: %s') % name)
        else:
            notify(tr('تمت إضافة المصدر: %s') % name)
    except Exception as exc:
        error(tr('فشل إضافة المصدر: %s') % exc)
    if _headless:
        # Nothing is rendering a directory for a JSON-RPC caller.
        try:
            xbmc.executebuiltin('Container.Refresh')
        except Exception:
            pass
        return
    return providers()

def providers():
    _set_render_section('stremio')
    rows = store.list_providers()
    # v5.4.30: Sources is sources only. All configuration lives under the
    # single Settings icon on Home.
    add_item(tr('إضافة مصدر Stremio'),
             build_url(action='add_provider'), art=root_art('add'),
             info={'title': 'إضافة رابط Manifest', 'plot': 'أضف manifest.json لأي إضافة Stremio.'})
    if not rows:
        add_item(tr('[COLOR grey]لا توجد إضافات Stremio مثبتة[/COLOR]'),
                 build_url(action='first_run_wizard'), is_folder=False,
                 art=root_art('providers'),
                 info={'title': 'المصادر', 'plot': 'استخدم Stremio sync أو أضف رابط manifest يدويًا.'})
        return end_dir(content='files', cache=False)

    # Identify providers whose stored manifest has no usable logo.
    # Refresh their manifests in the background so the NEXT open
    # shows the correct icon (CDN Plex servers often serve the logo URL
    # from a different base than the manifest URL, and the first save may
    # have caught a 503 / empty response).
    def _bg_refresh_missing_logos(stale_rows):
        for row in stale_rows:
            try:
                murl = row.get('manifest_url') or ''
                if not murl:
                    continue
                fresh = validate_manifest(murl)
                if not fresh:
                    continue
                logo = (fresh.get('logo') or fresh.get('icon') or '').strip()
                if logo:
                    store.refresh_provider_manifest(row.get('id'), fresh)
            except Exception as exc:
                xbmc.log('[DexHub] manifest logo refresh failed for %s: %s' % (
                    row.get('name', ''), exc), xbmc.LOGDEBUG)

    stale = [r for r in rows
             if not (r.get('manifest') or {}).get('logo')
             and not (r.get('manifest') or {}).get('icon')]
    # Missing artwork must never cause a network sweep every time Sources is
    # opened. At most one silent refresh per hour per Kodi session.
    _logo_refresh_due = False
    if stale:
        try:
            _w = xbmcgui.Window(WINDOW_ID)
            _last = float(_w.getProperty('dexhub.provider_logo_refresh_ts') or 0)
            _now = time.time()
            if (_now - _last) >= 3600:
                _logo_refresh_due = True
                _w.setProperty('dexhub.provider_logo_refresh_ts', str(int(_now)))
        except Exception:
            _logo_refresh_due = True
    if stale and _logo_refresh_due:
        _submit_optional(_bg_refresh_missing_logos, args=(stale,),
                         key='provider-logo-refresh')

    total = len(rows)
    for idx, row in enumerate(rows):
        label = row.get('name') or row.get('id')
        meta = row.get('manifest') or {}
        plot = meta.get('description') or row.get('manifest_url') or ''
        provider_id = row.get('id')
        # v3.9.34: position badge so the user sees the priority order at a glance.
        # Keep the visible list clean. Position remains available in the
        # secondary label and context menu instead of prefixing every name.
        position_badge = '%d/%d' % (idx + 1, total)
        display_label = label
        # v3.9.39: replaced inline move rows with one position action.
        # The user picks one item from the context menu, types the
        # target position (1 to N), and the source is placed exactly
        # there. This is dramatically faster than repeated nudging and
        # keeps the Sources page uncluttered.
        ctx_menu = []
        if total >= 2:
            ctx_menu.append(('تغيير ترتيب المصدر',
                'RunPlugin(%s)' % build_url(action='provider_set_position', provider_id=provider_id)))
        ctx_menu.extend([
            (tr('تغيير مصدر الميتاداتا'), 'RunPlugin(%s)' % build_url(action='meta_pick_for_provider', provider_id=provider_id)),
            ('تحديث المصدر', 'RunPlugin(%s)' % build_url(action='refresh_provider', provider_id=provider_id)),
            ('إزالة المصدر', 'RunPlugin(%s)' % build_url(action='remove_provider', provider_id=provider_id)),
        ])
        add_item(display_label, build_url(action='provider_menu', provider_id=provider_id),
                 label2=position_badge,
                 info={'title': display_label, 'plot': plot},
                 art=provider_art(label, row.get('manifest') or {}, base_url=row.get('base_url') or ''),
                 context_menu=ctx_menu)
    end_dir()


def provider_menu(provider_id):
    provider = store.get_provider(provider_id)
    if not provider:
        return end_dir()
    pname = provider.get('name') or 'Provider'
    summary = _provider_summary(provider)

    for catalog in _provider_catalogs(provider):
        cname = catalog.get('name') or catalog.get('id') or 'Catalog'
        media_type = catalog.get('type')
        plot = catalog.get('description') or (tr('تصفح قسم %s') % cname)
        extras = [x.get('name') for x in (catalog.get('extra') or []) if isinstance(x, dict) and x.get('name') not in ('skip',)]
        if extras:
            plot += '\nExtras: ' + ', '.join(extras)
        # Open the listing directly; source/folder/filter tools stay in the context menu.
        all_url = build_url(action='catalog_all', provider_id=provider_id, media_type=media_type, catalog_id=catalog.get('id'), label=cname)
        bucket = _hub_catalog_bucket(provider, catalog)
        ctx_menu = _hub_catalog_context(provider, catalog, bucket) + _catalog_filter_context(
            provider_id=provider_id, media_type=media_type, catalog_id=catalog.get('id') or '', catalog_def=catalog
        )
        add_item(
            cname,
            all_url,
            info={'title': cname, 'plot': plot},
            art=catalog_art(cname, media_type, provider.get('manifest') or {}, catalog),
            context_menu=ctx_menu,
        )

    for media_type in _available_types(provider):
        if _provider_supports_search(provider, media_type):
            s_label = tr('بحث %s') % _group_title(media_type)
            add_item(s_label, build_url(action='search', media_type=media_type, provider_id=provider_id), info={'title': s_label, 'plot': tr('بحث داخل %s') % pname}, art=root_art('search_movie' if media_type == 'movie' else 'search_series'))

    # Management stays on the provider row context menu. Duplicating Refresh
    # and Delete as normal catalogue rows made this page look like Settings.
    end_dir()


def remove_provider(provider_id):
    provider = store.get_provider(provider_id)
    if provider and xbmcgui.Dialog().yesno('Dex Hub', tr('حذف المصدر: %s ؟') % provider.get('name')):
        store.remove_provider(provider_id)
        # v3.9.45: also purge the index data attributed to this provider
        # so its items disappear from Hybrid renders immediately rather
        # than persisting until the next nightly prune sweep.
        try:
            from . import index_render
            index_render.get_db().purge_provider(provider_id)
        except Exception as _exc:
            xbmc.log('[DexHub] purge_provider failed: %s' % _exc, xbmc.LOGWARNING)
        notify(tr('تم حذف المصدر'))
    return providers()


def _meta_info(meta):
    year = None
    release = meta.get('releaseInfo') or meta.get('year') or ''
    premiered = ''
    if release:
        release_str = str(release)
        m = YEAR_RE.search(release_str)
        if m:
            try:
                year = int(m.group(1))
            except Exception:
                year = None
        m2 = re.search(r'(\d{4}-\d{2}-\d{2})', release_str)
        if m2:
            premiered = m2.group(1)
    title = meta.get('name') or 'Unknown'
    info = {
        'title': title,
        'sorttitle': title,
        'plot': meta.get('description') or meta.get('overview') or '',
        'year': year or 0,
        'genre': ' / '.join(meta.get('genres') or []),
        'rating': _meta_rating_value(meta),
        'premiered': premiered,
        'date': premiered,
        'mediatype': 'tvshow' if meta.get('type') == 'series' else 'movie',
    }
    # Promote richer fields when the meta source provides them. These are what
    # makes Kodi 20+ skins render full info panels (the "TMDb Helper look").
    if meta.get('runtime'):
        # Cinemeta returns "120 min" string sometimes, so be tolerant.
        try:
            rt = str(meta.get('runtime') or '').strip()
            mins = int(re.match(r'\s*(\d+)', rt).group(1)) if re.match(r'\s*(\d+)', rt) else 0
            if mins:
                info['duration'] = mins * 60
        except Exception:
            pass
    if meta.get('director'):
        info['director'] = meta.get('director') if isinstance(meta.get('director'), list) else [str(meta.get('director'))]
    if meta.get('writer'):
        info['writer'] = meta.get('writer') if isinstance(meta.get('writer'), list) else [str(meta.get('writer'))]
    if meta.get('country'):
        info['country'] = meta.get('country') if isinstance(meta.get('country'), list) else [str(meta.get('country'))]
    if meta.get('tagline'):
        info['tagline'] = str(meta.get('tagline'))
    if meta.get('trailer') or meta.get('trailers'):
        # Cinemeta puts trailers as YouTube IDs in 'trailers' (list)
        trailer = meta.get('trailer') or ''
        if not trailer and isinstance(meta.get('trailers'), list) and meta.get('trailers'):
            t = meta['trailers'][0]
            if isinstance(t, dict) and t.get('source'):
                trailer = 'plugin://plugin.video.youtube/play/?video_id=%s' % t['source']
            elif isinstance(t, str):
                trailer = 'plugin://plugin.video.youtube/play/?video_id=%s' % t
        if trailer:
            info['trailer'] = trailer
    if meta.get('certification'):
        info['mpaa'] = str(meta.get('certification'))
    if meta.get('imdbRating') and meta.get('imdb_votes'):
        try:
            info['votes'] = int(meta.get('imdb_votes'))
        except Exception:
            pass
    # Cast — the single biggest visual upgrade. Cinemeta returns it as a list
    # of strings (just names) OR as a list of dicts (with profile photos).
    cast_raw = meta.get('cast') or meta.get('credits_cast') or []
    if cast_raw:
        cast_list = []
        for entry in cast_raw[:25]:
            if isinstance(entry, dict):
                cast_list.append({
                    'name': str(entry.get('name') or '').strip(),
                    'role': str(entry.get('character') or entry.get('role') or '').strip(),
                    'thumbnail': str(entry.get('photo') or entry.get('thumbnail') or entry.get('profile_path') or '').strip(),
                })
            elif isinstance(entry, str) and entry.strip():
                cast_list.append({'name': entry.strip(), 'role': '', 'thumbnail': ''})
        if cast_list:
            info['cast'] = cast_list
    # v3.9.54: studio / production company extraction. The user noted that
    # other Kodi addons (Composite for Plex, TMDb Helper) show this field
    # in catalog listings while DexHub omitted it. Stremio metas use
    # several field names depending on the addon: 'studios' (Cinemeta),
    # 'production_companies' (TMDb-shaped), 'network' (TV shows), or just
    # 'studio'. We collect all of them and emit a clean string list to
    # match what Kodi skins expect.
    studio_sources = []
    for key in ('studios', 'production_companies', 'productionCompanies',
                'studio', 'network', 'networks'):
        raw = meta.get(key)
        if not raw:
            continue
        if isinstance(raw, list):
            for entry in raw:
                if isinstance(entry, dict) and entry.get('name'):
                    studio_sources.append(str(entry['name']).strip())
                elif isinstance(entry, str) and entry.strip():
                    studio_sources.append(entry.strip())
        elif isinstance(raw, str) and raw.strip():
            studio_sources.append(raw.strip())
    if studio_sources:
        # Deduplicate while preserving order.
        seen = set()
        deduped = []
        for s in studio_sources:
            key = s.lower()
            if key not in seen:
                seen.add(key)
                deduped.append(s)
        info['studio'] = deduped if len(deduped) > 1 else deduped[0]
    ids = extract_ids(meta)
    if ids.get('imdb_id'):
        info['imdbnumber'] = ids['imdb_id']
    return info


def _studio_resource_icon(value):
    """Return an installed Arctic/Kodi studio texture, never a guessed path."""
    try:
        from . import studio_art
        return studio_art.resolve(value)
    except Exception:
        return ''


def _as_clean_list(value):
    if value in (None, ''):
        return []
    if isinstance(value, (list, tuple)):
        out = []
        for item in value:
            if isinstance(item, dict):
                name = str(item.get('name') or item.get('title') or '').strip()
                if name:
                    out.append(name)
            else:
                text = str(item or '').strip()
                if text:
                    # Split only common comma-separated metadata strings.
                    out.extend([x.strip() for x in re.split(r'[,/]', text) if x.strip()] if ',' in text or '/' in text else [text])
    else:
        text = str(value or '').strip()
        out = [x.strip() for x in re.split(r'[,/]', text) if x.strip()] if text else []
    seen = set()
    deduped = []
    for x in out:
        key = x.lower()
        if key and key not in seen:
            seen.add(key)
            deduped.append(x)
    return deduped


def _stream_meta_info_payload(best_meta, media_type='', title='', show_title='', season=None, episode=None):
    """Return JSON-safe rich metadata for playback/ListItem InfoTag.

    DexHub source rows are cached before playback, so the player handoff can
    lose the rich fields that skins expect unless we persist them here. This is
    intentionally shaped like Kodi/TMDb Helper metadata: InfoTag fields, cast,
    unique ids, and common media properties all travel with the selected stream.
    """
    meta = best_meta or {}
    try:
        info = dict(_meta_info(meta) or {})
    except Exception:
        info = {}
    is_ep = season not in (None, '', 0, '0') or episode not in (None, '', 0, '0')
    if title:
        info['title'] = title
    if is_ep:
        info['mediatype'] = 'episode'
        try:
            info['season'] = int(season or 0)
        except Exception:
            info['season'] = 0
        try:
            info['episode'] = int(episode or 0)
        except Exception:
            info['episode'] = 0
        if show_title or meta.get('name') or meta.get('title'):
            info['tvshowtitle'] = show_title or meta.get('name') or meta.get('title') or ''
    else:
        mt = str(media_type or meta.get('type') or '').lower()
        if mt in ('series', 'show', 'tv', 'anime', 'tvshow'):
            info['mediatype'] = 'tvshow'
        else:
            info['mediatype'] = 'movie'
    # Normalize list-like fields because Kodi skins read them consistently from
    # the VideoInfoTag when they are true lists.
    for key in ('studio', 'country', 'director', 'writer', 'genre'):
        if key in info and info.get(key) not in (None, ''):
            vals = _as_clean_list(info.get(key))
            if vals:
                info[key] = vals
    if not info.get('studio'):
        studios = []
        for key in ('studios', 'production_companies', 'productionCompanies', 'network', 'networks', 'studio'):
            studios.extend(_as_clean_list(meta.get(key)))
        if studios:
            info['studio'] = studios
    if not info.get('genre'):
        genres = _as_clean_list(meta.get('genres') or meta.get('genre'))
        if genres:
            info['genre'] = genres
    # Runtime can be minutes, seconds, or a string like '120 min'. Store seconds.
    if not info.get('duration'):
        # v5.10.286: 'runtime' is minutes, 'duration' seconds (9000 s was read as
        # 9000 minutes: a 2h 30m film showed 150h 0m)
        try:
            from .durations import to_seconds
            secs = to_seconds(meta.get('runtime') or '', meta.get('duration') or '')
            if secs:
                info['duration'] = secs
        except Exception:
            pass
    return {k: v for k, v in info.items() if v not in (None, '', [], {})}


def _tmdb_type_from_ctx(ctx):
    ctx = ctx or {}
    if ctx.get('season') not in (None, '', 0, '0') or ctx.get('episode') not in (None, '', 0, '0'):
        return 'tv'
    mt = str(ctx.get('media_type') or '').strip().lower()
    if mt in ('series', 'show', 'tv', 'anime', 'tvshow'):
        return 'tv'
    return 'movie'


def _playback_art_from_ctx(ctx):
    from .playback_context import playback_art_from_ctx
    return playback_art_from_ctx(sys.modules[__name__], ctx=ctx)



def _lookup_local_clearlogo_for_playback(ctx):
    from .playback_context import lookup_local_clearlogo_for_playback
    return lookup_local_clearlogo_for_playback(sys.modules[__name__], ctx=ctx)


def _ensure_playback_art_context(ctx):
    from .playback_context import ensure_playback_art_context
    return ensure_playback_art_context(sys.modules[__name__], ctx=ctx)

def _safe_int_value(value, default=0):
    try:
        return int(float(str(value).strip()))
    except Exception:
        try:
            m = YEAR_RE.search(str(value or ''))
            return int(m.group(1)) if m else default
        except Exception:
            return default


def _playback_info_from_ctx(ctx):
    ctx = ctx or {}
    info = dict(ctx.get('kodi_info') or {})
    is_ep = bool(ctx.get('season') not in (None, '', 0, '0') or ctx.get('episode') not in (None, '', 0, '0'))
    if ctx.get('title'):
        info['title'] = ctx.get('title')
    info['year'] = _safe_int_value(ctx.get('year') or info.get('year') or 0, 0)
    info['mediatype'] = 'episode' if is_ep else ('tvshow' if _tmdb_type_from_ctx(ctx) == 'tv' else 'movie')
    if is_ep:
        info['season'] = _safe_int_value(ctx.get('season') or info.get('season') or 0, 0)
        info['episode'] = _safe_int_value(ctx.get('episode') or info.get('episode') or 0, 0)
        info['tvshowtitle'] = ctx.get('show_title') or info.get('tvshowtitle') or ctx.get('title') or ''
    if ctx.get('plot') and not info.get('plot'):
        info['plot'] = ctx.get('plot')
    if ctx.get('genre') and not info.get('genre'):
        info['genre'] = ctx.get('genre')
    if ctx.get('rating') not in (None, '') and not info.get('rating'):
        try:
            info['rating'] = float(ctx.get('rating'))
        except Exception:
            pass
    if ctx.get('studio') and not info.get('studio'):
        info['studio'] = ctx.get('studio')
    if ctx.get('duration_ms') and not info.get('duration'):
        try:
            info['duration'] = int(float(ctx.get('duration_ms')) / 1000.0)
        except Exception:
            pass
    if ctx.get('imdb_id'):
        info['imdbnumber'] = ctx.get('imdb_id')
    for key in ('studio', 'country', 'director', 'writer', 'genre'):
        if key in info and info.get(key) not in (None, ''):
            vals = _as_clean_list(info.get(key))
            if vals:
                info[key] = vals
    return {k: v for k, v in info.items() if v not in (None, '', [], {})}


def _playback_skin_properties(ctx, art, info):
    ctx = ctx or {}
    art = art or {}
    info = info or {}
    props = {}
    tmdb_type = _tmdb_type_from_ctx(ctx)

    # Kodi 22 safe mode: publish the IDs a4k/skins need, but avoid fake
    # VideoPlayer.* infolabel properties and tvshow.* art aliases on the
    # playback ListItem. Kodi itself will create real VideoPlayer labels after
    # start from the InfoTag/UniqueIDs.
    if _safe_playback_handoff_enabled():
        for k, v in (
            ('tmdb_type', tmdb_type),
            ('tmdb_id', ctx.get('tmdb_id') or ''),
            ('imdb_id', ctx.get('imdb_id') or ''),
            ('tvdb_id', ctx.get('tvdb_id') or ''),
            ('imdb', ctx.get('imdb_id') or ''),
            ('imdbnumber', ctx.get('imdb_id') or ''),
            ('IMDBNumber', ctx.get('imdb_id') or ''),
            ('season', ctx.get('season') if ctx.get('season') not in (None, '') else ''),
            ('episode', ctx.get('episode') if ctx.get('episode') not in (None, '') else ''),
            ('title', info.get('title') or ctx.get('title') or ''),
            ('tvshowtitle', info.get('tvshowtitle') or ctx.get('show_title') or ''),
            ('year', info.get('year') or ctx.get('year') or ''),
            ('studio', ' / '.join(info.get('studio') if isinstance(info.get('studio'), (list, tuple)) else _as_clean_list(info.get('studio')))),
            ('genre', ' / '.join(info.get('genre') if isinstance(info.get('genre'), (list, tuple)) else _as_clean_list(info.get('genre')))),
            ('rating', info.get('rating') or ctx.get('rating') or ''),
            ('plot', info.get('plot') or ctx.get('plot') or ''),
        ):
            if v not in (None, ''):
                props[k] = str(v)
        for k in ('poster', 'thumb', 'icon', 'thumbnail', 'fanart', 'fanart_image', 'landscape', 'clearlogo', 'logo', 'clearart', 'banner'):
            v = art.get(k)
            if v:
                props[k] = str(v)
        return props

    for k, v in (
        ('tmdb_type', tmdb_type),
        ('tmdb_id', ctx.get('tmdb_id') or ''),
        ('imdb_id', ctx.get('imdb_id') or ''),
        ('tvdb_id', ctx.get('tvdb_id') or ''),
        ('imdb', ctx.get('imdb_id') or ''),
        ('imdbnumber', ctx.get('imdb_id') or ''),
        ('IMDBNumber', ctx.get('imdb_id') or ''),
        ('VideoPlayer.IMDBNumber', ctx.get('imdb_id') or ''),
        ('VideoPlayer.UniqueID(imdb)', ctx.get('imdb_id') or ''),
        ('VideoPlayer.UniqueID(tmdb)', ctx.get('tmdb_id') or ''),
        ('VideoPlayer.UniqueID(tvdb)', ctx.get('tvdb_id') or ''),
        ('season', ctx.get('season') if ctx.get('season') not in (None, '') else ''),
        ('episode', ctx.get('episode') if ctx.get('episode') not in (None, '') else ''),
        ('title', info.get('title') or ctx.get('title') or ''),
        ('tvshowtitle', info.get('tvshowtitle') or ctx.get('show_title') or ''),
        ('year', info.get('year') or ctx.get('year') or ''),
        ('genre', ' / '.join(info.get('genre') if isinstance(info.get('genre'), (list, tuple)) else _as_clean_list(info.get('genre')))),
        ('studio', ' / '.join(info.get('studio') if isinstance(info.get('studio'), (list, tuple)) else _as_clean_list(info.get('studio')))),
        ('rating', info.get('rating') or ctx.get('rating') or ''),
        ('plot', info.get('plot') or ctx.get('plot') or ''),
        ('premiered', info.get('premiered') or ''),
        ('duration', info.get('duration') or ''),
    ):
        if v not in (None, ''):
            props[k] = str(v)
    for k, v in art.items():
        if v:
            props[k] = str(v)
    return props

def _enrich_listing_meta(provider, media_type, meta):
    if _provider_prefers_native_art(provider):
        return meta
    if ADDON.getSettingBool('deep_meta_enrich'):
        try:
            full = fetch_meta(provider, media_type, meta.get('id'), timeout_override=fast_timeout('meta'))
            deep = full.get('meta') or {}
            if deep:
                merged = dict(meta)
                merged.update({k: v for k, v in deep.items() if v not in (None, '', [], {})})
                return merged
        except Exception:
            pass
    return meta


def _nuvio_metadata_preferences():
    try:
        from .dexhub import nuvio_profile_prefs as _npp
        return _npp.normalized_tmdb() or {}
    except Exception:
        return {}


def _nuvio_merge_tmdb_meta(base, tmdb_meta, prefs):
    """Apply the same *Home preview* merge policy as Nuvio TV.

    Catalog ``poster`` and the native add-on title are deliberately not generic
    TMDb replacement fields. Nuvio Home uses TMDb artwork for backdrop/logo;
    the localized title is used only by Modern Home when its separate toggle
    is enabled. Rich credits/production fields belong to the details view and
    must not silently restyle a catalog row.
    """
    from .dexhub import nuvio_profile_prefs as _npp
    return _npp.merge_home_preview(base, tmdb_meta, prefs)


def _nuvio_filter_unreleased(metas, treat_missing=False):
    rows = list(metas or [])
    try:
        from .dexhub import nuvio_home_mirror as _nhm
        from .dexhub import nuvio_profile_prefs as _npp
        if not (_nhm.load() or {}).get('hide_unreleased_content'):
            return rows
        return [row for row in rows
                if not _npp.is_unreleased(
                    row, treat_missing_as_unreleased=treat_missing)]
    except Exception:
        return rows


def _apply_nuvio_metadata_preferences(media_type, metas, screen='home'):
    """Render a Nuvio catalog using Nuvio's synced TMDb preferences.

    If TMDb enrichment is disabled, native addon metadata/art is kept exactly.
    If enabled, only metadata already present in the local TMDb cache may fill
    fields Nuvio says to use. Directory/widget rendering never performs a
    detail request. Dex Hub's own global artwork priorities are bypassed.
    """
    prefs = _nuvio_metadata_preferences()
    rows = [dict(m or {}) for m in (metas or [])]
    if not rows:
        return rows

    def _native_only(values):
        out = []
        for meta in values:
            value = _nuvio_merge_tmdb_meta(meta, {}, prefs)
            value['_dexhub_art_strict'] = '1'
            out.append(value)
        return _nuvio_custom_posters(_nuvio_filter_unreleased(out), screen, media_type)

    # Even before the first profile-settings sync, Nuvio Home should not be
    # silently restyled by Dex-specific metadata sources. Native is safest.
    if not prefs.get('synced') or not prefs.get('home_enabled'):
        return _native_only(rows)

    try:
        from . import tmdb_direct as _td
    except Exception:
        return _native_only(rows)

    language = prefs.get('language') or 'en'
    requests = []
    for meta in rows:
        ids = extract_ids(meta) or {}
        requests.append({
            'tmdb_id': ids.get('tmdb_id') or '',
            'imdb_id': ids.get('imdb_id') or '',
            'media_type': media_type,
            'title': meta.get('name') or meta.get('title') or '',
            'year': meta.get('year') or meta.get('releaseInfo') or '',
            'language_override': language,
            'nuvio_exact': True,
        })

    try:
        cached_rows = _td.metas_for_cached_only(requests)
    except Exception:
        cached_rows = [{} for _meta in rows]
    try:
        xbmc.log(
            '[DexHub] Nuvio directory metadata cache-only rows=%d hits=%d network=0' % (
                len(rows), sum(1 for value in cached_rows if value)),
            xbmc.LOGDEBUG)
    except Exception:
        pass

    merged = []
    for idx, meta in enumerate(rows):
        tmdb_meta = cached_rows[idx] if idx < len(cached_rows) else {}
        value = _nuvio_merge_tmdb_meta(meta, tmdb_meta, prefs)
        # Nuvio catalog artwork, including BTTR/decorated posters, is the
        # authority for this row. Never run Dex's poster substitution pass.
        value['_dexhub_art_strict'] = '1'
        merged.append(value)
    # v5.10.302: what the local cache lacks is fetched in the background (two
    # at a time, in the profile's language), so the next look at the row has
    # Nuvio's TMDb art; the page itself never waits for it
    try:
        from . import meta_source as _ms_warm
        for idx, request in enumerate(requests):
            if not (cached_rows[idx] if idx < len(cached_rows) else {}):
                if request.get('tmdb_id') or str(request.get('imdb_id') or '').startswith('tt'):
                    _ms_warm._tmdb_warm(request)
    except Exception:
        pass
    return _nuvio_custom_posters(_nuvio_filter_unreleased(merged), screen, media_type)


def _nuvio_custom_posters(rows, screen, media_type=''):
    """v5.10.302: the Nuvio profile's own poster pattern (RPDB, top-posters
    and the like) on the screens the profile turned it on for."""
    try:
        from .dexhub import nuvio_poster as _np
        return _np.apply_all(rows, screen, media_type)
    except Exception:
        return rows


def _listing_art_goes_remote(provider, meta):
    """Would _resolve_meta_art look this title's art up (TMDb Helper's
    database, TMDb)? Mirrors _resolve_meta_art_inner's choice."""
    meta = meta or {}
    meta_source_id = _meta_source_id_from_meta(meta)
    if _meta_art_is_strict(meta) or (meta_source_id and meta_source_id not in ('auto', 'native')):
        return False
    if _provider_meta_source_id(provider) not in ('', 'auto'):
        return False
    if _provider_is_rating_proxy(provider):
        return True
    if _provider_is_plexio(provider):
        return False
    if _provider_prefers_native_art(provider):
        return not posters_prefer_local()
    if posters_prefer_local():
        return not (meta.get('background') or meta.get('fanart')) or not (meta.get('clearlogo') or meta.get('logo'))
    return True


def _warm_listing_art(provider, media_type, metas, limit=12):
    """The art lookups of a listing's first titles, all at once (v5.10.117).

    The render asks for each title's art one after the other: with a TMDb
    key that was up to three TMDb requests per title, a dozen titles in a
    row, seconds before a catalog showed. Read here in parallel, the render
    finds every answer in the cache.
    """
    try:
        from . import tmdb_direct as _td
        if not _td._api_key():
            return
        from .art import _remote_art_bundles
    except Exception:
        return
    todo = []
    for meta in (metas or [])[:limit]:
        if not isinstance(meta, dict):
            continue
        try:
            meta = _normalize_meta_art_urls(provider, meta)
            if _listing_art_goes_remote(provider, meta):
                todo.append(meta)
        except Exception:
            continue
    if len(todo) < 2:
        return
    try:
        run_parallel(lambda m: _remote_art_bundles(m, media_type), todo, workers=6, timeout=8, lane='art')
    except Exception as exc:
        xbmc.log('[DexHub] listing art warm-up failed: %s' % exc, xbmc.LOGDEBUG)


def _enrich_listing_metas_batch(provider, media_type, metas, nuvio_mode=False, meta_target=''):
    """Parallel version of _enrich_listing_meta for a whole catalog page.

    Skips items that already have a poster + a plot/description in the
    listing payload — those don't need a /meta/ fetch round-trip.

    For Plex/Emby/Plexio providers, transparently swap metadata for a
    reliable source (Cinemeta/TMDB meta addons or TMDb Helper) based on
    the `meta_source_mode` setting — fixes broken posters and incomplete
    plots.

    v3.9.0: After enrichment, every item passes through:
      * SQLite meta_cache.put → so the next render is sub-5ms
      * fanart.tv merge → adds clearart/banner/discart/clearlogo so modern
        skins render the rich "TMDb Helper" view
    """
    if nuvio_mode:
        metas = [_normalize_meta_art_urls(provider, m) for m in (metas or [])]
        # Nuvio is the default artwork/metadata authority.  Only an EXPLICIT
        # long-press choice is allowed to replace it; Dex Hub's global default
        # must not silently restyle Nuvio Home/Collections.
        try:
            from . import meta_source as _meta_source
            target_choice = _meta_source.nuvio_override_for(meta_target) if meta_target else ''
            if target_choice:
                return _meta_source.override_virtual_metas_batch(
                    meta_target, media_type, metas, warm=True)
            provider_choice = _meta_source.nuvio_override_for((provider or {}).get('id') or '')
            if provider_choice:
                return _meta_source.override_metas_batch(provider, media_type, metas, warm=True)
        except Exception as exc:
            xbmc.log('[DexHub] Nuvio explicit metadata override failed: %s' % exc, xbmc.LOGWARNING)
        return _apply_nuvio_metadata_preferences(
            media_type, metas,
            screen='collections' if str(meta_target or '').startswith('virtual.collection') else 'home')

    # Meta source override: Plex/Emby providers get their metadata
    # upgraded before the normal enrich path runs.
    meta_source_id = 'auto'
    try:
        from . import meta_source as _meta_source
        meta_source_id = _meta_source.get_meta_source_for((provider or {}).get('id') or '') or 'auto'
        # v5.10.67: warm=True fills this page's misses from the selected
        # source in one bounded pass (directory opens only, never widgets).
        metas = _meta_source.override_metas_batch(provider, media_type, metas, warm=True)
    except Exception as exc:
        xbmc.log('[DexHub] meta override failed: %s' % exc, xbmc.LOGWARNING)

    metas = [_normalize_meta_art_urls(provider, m) for m in (metas or [])]

    # Try meta_cache fast path BEFORE going to network. For each item that
    # has a stable canonical id, replace its meta with the cached payload
    # if one exists. Items without an id (or with a cache miss) fall
    # through to the existing enrichment path.
    try:
        from . import meta_cache as _mc
        normalized_mt = 'series' if media_type in ('series', 'show', 'tv', 'tvshow', 'anime') else 'movie'
        cache_misses = []
        cached_replacements = {}
        # v3.9.17: batch SQLite read. Was N connection-open + PRAGMA + SELECT
        # cycles per folder (e.g. 80 SQLite roundtrips for an 80-item catalog).
        # Now: one connection, one SELECT … WHERE canonical_id IN (…), one
        # bulk memory-cache populate. Saves ~80-200ms on cold renders.
        meta_ids = []
        meta_id_at = {}
        for idx, m in enumerate(metas or []):
            cid = str((m or {}).get('id') or '').strip()
            if not cid:
                cache_misses.append(idx)
                continue
            meta_ids.append(cid)
            meta_id_at.setdefault(cid, []).append(idx)
        bulk_hits = _mc.get_many(normalized_mt, meta_ids,
                                  source_id=meta_source_id or 'auto') if meta_ids else {}
        for cid, indices in meta_id_at.items():
            cached = bulk_hits.get(cid)
            for idx in indices:
                if cached:
                    m = (metas or [])[idx] or {}
                    if meta_source_id in ('', 'auto'):
                        from .auto_metadata import merge_missing
                        merged = merge_missing(m, cached, media_type)
                    else:
                        merged = dict(cached)
                    # Keep live id/type fields from the addon — it may emit
                    # richer routing metadata than the cached payload.
                    for k in ('id', 'type'):
                        if m.get(k):
                            merged[k] = m[k]
                    cached_replacements[idx] = merged
                else:
                    cache_misses.append(idx)
    except Exception:
        cache_misses = list(range(len(metas or [])))
        cached_replacements = {}

    # Explicit source must remain explicit. Do not fetch/merge the original
    # provider's /meta after the user picked TMDb Helper/Trakt/Cinemeta/etc.
    skip_deep_fetch = (meta_source_id not in ('', 'auto', 'native')) \
                      or _provider_prefers_native_art(provider) \
                      or not ADDON.getSettingBool('deep_meta_enrich') \
                      or not metas

    if skip_deep_fetch:
        # Apply cached replacements + fanart.tv merge, then return.
        out = []
        for idx, meta in enumerate(metas):
            base = cached_replacements.get(idx) or meta
            out.append(_attach_fanarttv(base, media_type))
        return out

    def _fetch_one(meta):
        try:
            full = fetch_meta(
                provider, media_type, meta.get('id'),
                timeout_override=min(4.0, float(fast_timeout('meta'))),
                retry=False, rate_wait=0.5)
            return full.get('meta') or {}
        except Exception:
            return {}

    # Only fetch for true cache misses (saves N network calls on warm pages)
    fetch_targets = [metas[i] for i in cache_misses]
    fetch_results = run_parallel(
        _fetch_one, fetch_targets, timeout=4.5,
        lane='browse') if fetch_targets else []
    fetch_by_idx = {}
    for offset, idx in enumerate(cache_misses):
        try:
            _, deep = fetch_results[offset]
            fetch_by_idx[idx] = deep if not isinstance(deep, Exception) else {}
        except Exception:
            fetch_by_idx[idx] = {}

    enriched = []
    try:
        from . import meta_cache as _mc
        normalized_mt = 'series' if media_type in ('series', 'show', 'tv', 'tvshow', 'anime') else 'movie'
    except Exception:
        _mc = None
        normalized_mt = 'movie'

    for idx, meta in enumerate(metas):
        if idx in cached_replacements:
            base = cached_replacements[idx]
        else:
            deep = fetch_by_idx.get(idx) or {}
            if deep:
                merged = dict(meta)
                merged.update({k: v for k, v in deep.items() if v not in (None, '', [], {})})
                base = _normalize_meta_art_urls(provider, merged)
                # Persist to disk cache for next render
                if _mc is not None:
                    cid = str((base or {}).get('id') or meta.get('id') or '').strip()
                    if cid:
                        try:
                            _mc.put(normalized_mt, cid, base, source_id=meta_source_id or 'auto')
                        except Exception:
                            pass
            else:
                base = meta
        enriched.append(_attach_fanarttv(base, media_type))
    return enriched


def _attach_fanarttv(meta, media_type):
    """Merge fanart.tv artwork into a single meta dict.

    Honors user setting `fanarttv_enrich`; defaults ON. Skips silently when
    no usable id is present, when the user disabled it, or when fanart.tv
    has no entries (negative cache covers that case).
    """
    try:
        from . import fanarttv as _ft
    except Exception:
        return meta
    if not isinstance(meta, dict):
        return meta
    try:
        ids = extract_ids(meta) or {}
        return _ft.merge_into_meta(
            meta, media_type,
            tmdb_id=ids.get('tmdb_id') or '',
            tvdb_id=ids.get('tvdb_id') or '',
            imdb_id=ids.get('imdb_id') or '',
        )
    except Exception:
        return meta


def _filter_state(provider_id, catalog_id):
    return dict(store.get_catalog_state(provider_id, catalog_id) or {})


def _available_filter_extras(catalog_def):
    extras = []
    for extra in catalog_def.get('extra') or []:
        if not isinstance(extra, dict):
            continue
        name = extra.get('name')
        if name in ('skip',):
            continue
        extras.append(extra)
    return extras


# Extras that are ordering/sorting/paging — never make sense as folders,
# always show as filters.
_SORT_LIKE_EXTRAS = {'sort', 'sortby', 'orderby', 'order', 'limit', 'search', 'skip'}

# Extras that are natural categories — default to folder view.
_CATEGORY_LIKE_EXTRAS = {'genre', 'year', 'category', 'language', 'country',
                         'network', 'studio', 'contentrating', 'collection', 'type'}


def _extra_mode(name, catalog_def=None):
    """Return 'folder' or 'filter' for a given extra name.

    Rules, in order:
      1. Never-a-folder names (sort/order/limit/...) → filter.
      2. User override via settings (comma lists).
      3. Default classification by name heuristic.
      4. Fallback: filter.
    """
    key = (name or '').strip().lower().replace('_', '').replace('-', '')
    if key in _SORT_LIKE_EXTRAS:
        return 'filter'
    # User overrides
    try:
        force_folder = set(
            s.strip().lower().replace('_', '').replace('-', '')
            for s in ((ADDON.getSetting('extras_as_folder') or '').split(','))
            if s.strip()
        )
        force_filter = set(
            s.strip().lower().replace('_', '').replace('-', '')
            for s in ((ADDON.getSetting('extras_as_filter') or '').split(','))
            if s.strip()
        )
    except Exception:
        force_folder, force_filter = set(), set()
    if key in force_filter:
        return 'filter'
    if key in force_folder:
        return 'folder'
    if key in _CATEGORY_LIKE_EXTRAS:
        return 'folder'
    return 'filter'


def _folder_extras_with_options(catalog_def):
    """Return [(extra_name, [options])] for extras classified as 'folder'
    that actually have an explicit options list in the manifest."""
    out = []
    for extra in (catalog_def.get('extra') or []):
        if not isinstance(extra, dict):
            continue
        name = extra.get('name') or ''
        if _extra_mode(name, catalog_def) != 'folder':
            continue
        opts = [str(o) for o in (extra.get('options') or []) if o not in (None, '')]
        if opts:
            out.append((name, opts))
    return out


def _catalog_declares_extra(catalog_def, wanted):
    """Accept all Stremio manifest spellings for one catalog extra."""
    wanted = str(wanted or '').strip().lower()
    for field in ('extra', 'extraSupported', 'extraRequired'):
        for entry in (catalog_def or {}).get(field) or []:
            name = entry.get('name') if isinstance(entry, dict) else entry
            if str(name or '').strip().lower() == wanted:
                return True
    return False


def _preset_extras(text, catalog_def=None):
    """{extra: value} from a catalog URL's ``extras`` (JSON; v5.10.106).

    The Home's catalog page passes the genre and the other filters chosen
    there with each request. Only extras the catalog declares are sent (when
    it declares any); paging and search are the route's own.
    """
    if not text:
        return {}
    try:
        data = json.loads(text)
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    declared = any((catalog_def or {}).get(field)
                   for field in ('extra', 'extraSupported', 'extraRequired'))
    out = {}
    for name, value in data.items():
        name = str(name or '').strip()
        value = '' if value is None else str(value)
        if not name or not value.strip() or name.lower() in ('skip', 'search', 'limit'):
            continue
        # a genre is sent as the genre folders always sent it, even to a
        # catalog that lists none (its page was opened from such a folder)
        if declared and name.lower() not in ('genre', 'sort') and not _catalog_declares_extra(catalog_def, name):
            continue
        if declared and name.lower() == 'sort' and not _catalog_declares_extra(catalog_def, name):
            # Known DexWorld Kodi manifests omit sort; its native handler
            # accepts it. The request builder validates this exception.
            out[name] = value
            continue
        out[name] = value
    return out


def _filter_label(name):
    return FILTER_NAMES.get(name, name)


def _catalog_toolbar(provider, provider_id, media_type, catalog_id, catalog_def, state, force_remote=False):
    # Clean UI: catalog filters are exposed from the Kodi context menu
    # (long-press / options) on catalog rows and on items inside the catalog.
    # Do not add visible filter rows at the top of the listing.
    return None


def _apply_catalog_request(provider, media_type, catalog_id, state,
                           include_limit=True):
    from .homeui import stremio_catalogs as SC
    catalog_def = _catalog_definition(provider, catalog_id, media_type) or {}
    if SC.dexworld_sortable(provider, catalog_def):
        catalog_def = dict(catalog_def, extraSupported=list(catalog_def.get('extraSupported') or []) + ['sort'])
    state = state or {}
    extra = SC.request_extras(catalog_def, {'extras': json.dumps(state)})
    for name in ('skip', 'search'):
        if SC.supports(catalog_def, name) and state.get(name) not in (None, '', '0', 0):
            extra[name] = state[name]
    if include_limit and SC.supports(catalog_def, 'limit') and 'limit' not in extra:
        extra['limit'] = str(_listing_page_size())
    return fetch_catalog(
        provider, media_type, catalog_id, extra=extra,
        timeout_override=fast_timeout('catalog'), retry=False,
        rate_wait=0.5)



def _is_dns_resolution_error(exc):
    """True for urllib/socket name-resolution failures (macOS Errno 8 etc.)."""
    text = str(exc or '').lower()
    markers = (
        'nodename nor servname', 'name or service not known',
        'temporary failure in name resolution', 'getaddrinfo failed',
        'errno 8', 'failed to resolve', 'name resolution',
    )
    return any(m in text for m in markers)


def _is_transport_failure(exc):
    """A catalog request that failed because of this transport, not the catalog.

    v5.10.97: another installed copy of the same add-on (a second manifest URL
    for one manifest id) is also tried when this copy answers with something
    that is not JSON (an HTML error page), an HTTP error or a refused
    connection, not only when its host cannot be resolved. Nuvio Home rows
    resolve by manifest id, so a dead duplicate used to blank rows such as
    Cinemeta's Popular/Featured/New while the working copy sat unused.
    """
    if _is_dns_resolution_error(exc):
        return True
    text = str(exc or '').lower()
    if re.search(r'\b(?:http|upstream|status)(?: error)? [45]\d\d\b', text):
        return True
    markers = (
        'expecting value', 'jsondecodeerror', 'invalid json', 'unexpected character',
        'http error 4', 'http error 5', 'status 4', 'status 5', 'ssl',
        'connection refused', 'max retries exceeded', 'connection reset',
        'remote end closed', 'bad gateway', 'service unavailable', 'not found',
    )
    return any(m in text for m in markers)


def _retry_nuvio_catalog_with_alternate_provider(
        provider, media_type, catalog_id, request_state, include_limit=True):
    """Try another installed transport exposing the same manifest.id once."""
    try:
        manifest = (provider or {}).get('manifest') or {}
        addon_id = str(manifest.get('id') or '').strip()
        if not addon_id:
            return None, None
        alt = _collections_mod.find_nuvio_provider_by_addon_id(
            addon_id, exclude_provider_id=(provider or {}).get('id') or '')
        if not alt:
            return None, None
        data = _apply_catalog_request(
            alt, media_type, catalog_id, request_state,
            include_limit=include_limit)
        xbmc.log('[DexHub] Nuvio catalog failover %s -> %s for %s' % (
            (provider or {}).get('manifest_url') or (provider or {}).get('id'),
            alt.get('manifest_url') or alt.get('id'), catalog_id), xbmc.LOGINFO)
        return alt, data
    except Exception as exc:
        xbmc.log('[DexHub] Nuvio catalog alternate transport failed: %s' % exc, xbmc.LOGWARNING)
        return None, None


def catalog(provider_id, media_type, catalog_id, label='', page='0', genre='',
            year='', force_remote='', nuvio='', meta_target='', cursor='',
            _skip_gate=False, _extra_name='', _extra_value='', extras=''):
    provider = store.get_provider(provider_id)
    if not provider:
        return end_dir()
    force_remote = _force_remote_posters_enabled(force_remote)
    nuvio_mode = str(nuvio or '').strip().lower() in ('1', 'true', 'yes', 'on')
    if nuvio_mode:
        _set_render_section('nuvio_%s' % (
            'series' if _is_series_media(media_type) else 'movie'))
    nuvio_query = {'nuvio': '1'} if nuvio_mode else {}
    if meta_target:
        nuvio_query['meta_target'] = str(meta_target)
    catalog_def = _catalog_definition(provider, catalog_id, media_type)
    try:
        xbmcplugin.setPluginCategory(
            HANDLE, str(label or catalog_def.get('name') or catalog_id or ''))
    except Exception:
        pass
    state = _filter_state(provider_id, catalog_id)
    _catalog_add_toolbar(provider, provider_id, media_type, catalog_id, catalog_def, label=label)

    # Preset filters from URL (used by "filter folders" below) — non-persistent.
    preset_filters = {}
    if genre:
        preset_filters['genre'] = genre
    if year:
        preset_filters['year'] = year
    # Keep per-request presets as Python arguments. Window properties are
    # global, so simultaneous AF3 widgets used to clear each other's state.
    _xn = str(_extra_name or '')
    _xv = str(_extra_value or '')
    skip_gate_requested = bool(_skip_gate)
    if _xn and _xv:
        preset_filters[_xn] = _xv
    # v5.10.106: the filters chosen on the Home's catalog page (Sort, Filter
    # and Genre), all of them in one ``extras`` parameter; never saved here.
    # That page decides alone: the classic saved filters stay out of it.
    if extras:
        state = {}
        preset_filters.update(_preset_extras(extras, catalog_def))

    # Detect filter-as-folder opportunities.
    try:
        show_genre_folders = (ADDON.getSetting('catalog_genre_folders') or 'false').lower() != 'false'
    except Exception:
        show_genre_folders = True
    has_preset = bool(preset_filters)
    # Issue #5: DexWorld Pro internal sub-catalogs should ALWAYS open as
    # folders. Flip the gate on regardless of the global setting and
    # regardless of whether the user already opened the catalog before.
    # Nuvio Home is already a catalog navigator. Re-introducing DexWorld's
    # internal folder gate beneath it creates the exact repeated-folder stack
    # the dedicated Movies/TV page is meant to remove. Dex's normal provider
    # browser keeps the mandatory folder behavior unchanged.
    force_folders = _force_folders_for_provider(provider) and not nuvio_mode
    if force_folders:
        show_genre_folders = True

    bypass_folder_gate = bool(nuvio_mode or skip_gate_requested)
    if show_genre_folders and not has_preset             and not any(state.get(k) for k in (state or {}))             and not bypass_folder_gate:
        folder_extras = _folder_extras_with_options(catalog_def)
        cat_fb = _item_fallback_art(provider, media_type, catalog_def, catalog_def.get('name') or catalog_id)
        any_folders = False
        for extra_name, opts in folder_extras:
            if extra_name.lower() == 'year' and len(opts) > 40:
                continue
            for opt in opts:
                label_text = opt if extra_name.lower() == 'genre' else '%s: %s' % (_filter_label(extra_name), opt)
                if extra_name.lower() == 'genre':
                    link = build_url(action='catalog', provider_id=provider_id, media_type=media_type,
                                     catalog_id=catalog_id, label=label, genre=opt, **dict(_force_remote_query(force_remote), **nuvio_query))
                elif extra_name.lower() == 'year':
                    link = build_url(action='catalog', provider_id=provider_id, media_type=media_type,
                                     catalog_id=catalog_id, label=label, year=opt, **dict(_force_remote_query(force_remote), **nuvio_query))
                else:
                    link = build_url(action='catalog_extra', provider_id=provider_id, media_type=media_type,
                                     catalog_id=catalog_id, label=label, extra_name=extra_name, extra_value=opt,
                                     **dict(_force_remote_query(force_remote), **nuvio_query))
                folder_art = section_art(label_text, media_type=media_type,
                                         fanart=cat_fb.get('fanart') or addon_fanart())
                add_item(label_text, link, info={'title': label_text}, art=folder_art,
                         properties={'dexhub.tile_shape': 'square', 'dexhub.section_icon': '1'})
                any_folders = True
        if any_folders:
            _catalog_toolbar(provider, provider_id, media_type, catalog_id, catalog_def, state, force_remote=force_remote)
            # Hide the "show everything unfiltered" escape hatch when folders
            # are mandatory (DexWorld Pro). The user explicitly wants the
            # internal sub-catalogs to always be the entry point.
            if not force_folders:
                add_item(
                    '[COLOR yellow]◉ عرض كل العناصر بدون تصفية[/COLOR]',
                    build_url(action='catalog_all', provider_id=provider_id, media_type=media_type, catalog_id=catalog_id, label=label, **dict(_force_remote_query(force_remote), **nuvio_query)),
                    art=root_art('catalogs'),
                    info={'title': 'كل العناصر', 'plot': 'تجاوز المجلدات وعرض القائمة الكاملة'},
                )
            end_dir(content='files')
            return

    _catalog_toolbar(provider, provider_id, media_type, catalog_id, catalog_def, state, force_remote=force_remote)
    skip_supported = _catalog_declares_extra(catalog_def, 'skip')
    try:
        page_num = max(0, int(page or 0))
    except Exception:
        page_num = 0
    page_size = _listing_page_size()
    metas = []
    seen_ids = set()
    has_more = False
    next_cursor = ''

    request_state = dict(state or {})
    request_state.update(preset_filters)

    if skip_supported:
        try:
            request_skip = (max(0, int(cursor)) if str(cursor or '').strip()
                            else page_num * page_size)
        except Exception:
            request_skip = page_num * page_size
        # Nuvio's initial URL has no synthetic skip=0 segment. Strict catalog
        # modifiers can treat that segment as a separate unsupported route.
        if request_skip > 0:
            request_state['skip'] = str(request_skip)
        else:
            request_state.pop('skip', None)
        try:
            data = _apply_catalog_request(
                provider, media_type, catalog_id, request_state,
                include_limit=not nuvio_mode)
            batch = data.get('metas') or []
        except Exception as exc:
            alt_data = None
            if nuvio_mode and _is_transport_failure(exc):
                alt_provider, alt_data = _retry_nuvio_catalog_with_alternate_provider(
                    provider, media_type, catalog_id, request_state,
                    include_limit=not nuvio_mode)
                if alt_provider and isinstance(alt_data, dict):
                    provider = alt_provider
                    batch = alt_data.get('metas') or []
            if alt_data is None:
                xbmc.log('[DexHub] catalog load failed %s/%s: %s' % (provider_id, catalog_id, exc), xbmc.LOGWARNING)
                if nuvio_mode and _is_dns_resolution_error(exc):
                    notify(tr('مصدر Nuvio غير متصل الآن — تم تجاوز الخطأ'))
                else:
                    error(tr('فشل تحميل الكتالوج: %s') % exc)
                return end_dir()
        displayed_raw = 0
        for raw_position, meta in enumerate(batch, 1):
            if not isinstance(meta, dict) or not meta.get('id'):
                continue
            mid = str((meta or {}).get('id') or '')
            if mid and mid in seen_ids:
                continue
            if mid:
                seen_ids.add(mid)
            metas.append(meta)
            if len(metas) <= page_size:
                displayed_raw = raw_position
        # Client-side cap: many Stremio addons ignore our `limit` param and
        # return fixed-size pages (100 items). Trim to page_size so the
        # user sees the expected 30 — with a "المزيد" button for the rest.
        had_overflow = len(metas) > page_size
        if had_overflow:
            metas = metas[:page_size]
        # The native fallback renders only ``metas`` from this response, so
        # advance by the number actually shown. The immersive page retains the
        # full raw batch in memory and can advance by raw_count without loss.
        next_cursor = str(request_skip + (displayed_raw if had_overflow else len(batch))) if batch else ''
        has_more = bool(batch)  # Declared skip support, independent of provider page size.
    else:
        try:
            data = _apply_catalog_request(
                provider, media_type, catalog_id, request_state,
                include_limit=not nuvio_mode)
            batch = data.get('metas') or []
        except Exception as exc:
            alt_data = None
            if nuvio_mode and _is_transport_failure(exc):
                alt_provider, alt_data = _retry_nuvio_catalog_with_alternate_provider(
                    provider, media_type, catalog_id, request_state,
                    include_limit=not nuvio_mode)
                if alt_provider and isinstance(alt_data, dict):
                    provider = alt_provider
                    batch = alt_data.get('metas') or []
            if alt_data is None:
                xbmc.log('[DexHub] catalog load failed %s/%s: %s' % (provider_id, catalog_id, exc), xbmc.LOGWARNING)
                if nuvio_mode and _is_dns_resolution_error(exc):
                    notify(tr('مصدر Nuvio غير متصل الآن — تم تجاوز الخطأ'))
                else:
                    error(tr('فشل تحميل الكتالوج: %s') % exc)
                return end_dir()
        all_metas = []
        for meta in batch:
            if not isinstance(meta, dict) or not meta.get('id'):
                continue
            mid = str((meta or {}).get('id') or '')
            if mid and mid in seen_ids:
                continue
            if mid:
                seen_ids.add(mid)
            all_metas.append(meta)
        page_num, _ps, metas, has_more = _page_slice(all_metas, page_num)

    win = xbmcgui.Window(WINDOW_ID)
    first_fanart = ''
    _provider_identity_art = provider_art(
        provider.get('name') or (provider.get('manifest') or {}).get('name') or '',
        provider.get('manifest') or {},
        provider.get('base_url') or provider.get('manifest_url') or '')
    _provider_icon = (_provider_identity_art.get('icon') or
                      _provider_identity_art.get('thumb') or '')
    _provider_name = str(
        provider.get('name') or (provider.get('manifest') or {}).get('name') or '').strip()
    metas = _enrich_listing_metas_batch(provider, media_type, metas, nuvio_mode=nuvio_mode, meta_target=meta_target)
    # v5.10.117: titles the catalog sent without a poster take one from the
    # account's metadata add-ons, TMDb Helper or TMDb (poster_doctor)
    _poster_report = None
    try:
        from . import poster_doctor as _poster_doctor
        from .meta_policy import nuvio_parity as _nv_parity
        # v5.10.302: Like Nuvio keeps a Nuvio row's poster as Nuvio has it
        # (no other add-on's, TMDb Helper's or TMDb's in its place)
        if not (nuvio_mode and _nv_parity()):
            metas, _poster_report = _poster_doctor.rescue(sys.modules[__name__], provider, media_type, metas)
    except Exception as exc:
        xbmc.log('[DexHub] posters: rescue failed: %s' % exc, xbmc.LOGWARNING)
    if not nuvio_mode:
        _warm_listing_art(provider, media_type, metas, limit=len(metas) if force_remote else 12)
    try:
        favorite_keys = favorites_store.favorite_keys()
    except Exception:
        favorite_keys = set()
    for idx, meta in enumerate(metas):
        meta = _normalize_meta_art_urls(provider, meta)
        meta_id = meta.get('id')
        item_label = meta.get('name') or meta_id or 'Unknown'
        fallback = _item_fallback_art(provider, media_type, catalog_def, meta.get('name') or meta_id or '')
        # Nuvio rows are always local/cache-only while Kodi builds AF3 widgets.
        # Other providers retain full art for visible rows and lazy art below.
        if nuvio_mode:
            art = _resolve_meta_art_fast(
                provider, media_type, meta, fallback_art=fallback)
        else:
            art = _resolve_meta_art(
                provider, media_type, meta, fallback_art=fallback,
                force_remote=force_remote,
                lazy=(idx >= 12 and not force_remote))
        if not first_fanart and art.get('fanart'):
            first_fanart = art.get('fanart')
        try:
            _meta_mem_put(media_type, meta_id, meta, source_provider_id=provider.get('id') or '')
        except Exception:
            pass
        info = _meta_info(meta)
        ids = extract_ids(meta)
        path, path_is_folder = _content_click_path(media_type=media_type, canonical_id=meta_id, title=item_label, tmdb_id=ids.get('tmdb_id') or '', imdb_id=ids.get('imdb_id') or '', tvdb_id=ids.get('tvdb_id') or '', source_provider_id=provider.get('id') or '', ui_seed=art)
        ctx_menu = _catalog_filter_context(
            provider_id=provider.get('id') or '', media_type=media_type, catalog_id=catalog_id,
            catalog_def=catalog_def, force_remote='1' if force_remote else ''
        ) + _build_source_picker_menu(media_type=media_type, canonical_id=meta_id, title=item_label, source_provider_id=provider.get('id') or '') + _build_player_chooser_menu(
            media_type=media_type,
            canonical_id=meta_id,
            title=item_label,
            tmdb_id=ids.get('tmdb_id') or '',
            imdb_id=ids.get('imdb_id') or '',
            tvdb_id=ids.get('tvdb_id') or '',
            source_provider_id=provider.get('id') or '',
        )
        # NOTE: TMDb Helper is already accessible via "اختيار المشغّل…" above.
        # Adding a separate "فتح في TMDb Helper" entry here caused it to appear
        # twice (once in the chooser dialog, once as a direct item). Removed.
        already_fav = (str(media_type or ''), str(meta_id or '')) in favorite_keys
        if already_fav:
            ctx_menu.append(('إزالة من المفضلة', 'RunPlugin(%s)' % build_url(
                action='fav_remove', media_type=media_type, canonical_id=meta_id,
            )))
        else:
            ctx_menu.append(('إضافة إلى المفضلة', 'RunPlugin(%s)' % build_url(
                action='fav_add', media_type=media_type, canonical_id=meta_id,
                title=item_label, poster=art.get('poster') or '',
                background=art.get('fanart') or '', clearlogo=art.get('clearlogo') or '',
                year=str(info.get('year') or 0),
            )))
        _studio = info.get('studio') or ''
        _studio_text = ', '.join(_studio) if isinstance(_studio, (list, tuple)) else str(_studio or '')
        _studio_icon = _studio_resource_icon(_studio)
        _props = {
            'dexhub.tile_shape': 'poster',
            'dexhub.work_item': '1',
            'dexhub.clearlogo_as_title': '1',
            'dexhub.studio': _studio_text,
            'studio_icon': _studio_icon,
            'dexhub.studio_icon': _studio_icon,
            'provider_icon': _provider_icon,
            'dexhub.provider_icon': _provider_icon,
            'dexhub.provider_name': _provider_name,
        }
        add_item(item_label, path, is_folder=path_is_folder, info=info, art=art, ids=ids, properties=_props, context_menu=ctx_menu, is_favorite=already_fav)
    if first_fanart:
        win.setProperty('fanart', first_fanart)
    if has_more and metas:
        if _xn and _xv:
            more_action = 'catalog_extra'
        elif bypass_folder_gate:
            more_action = 'catalog_all'
        else:
            more_action = 'catalog'
        more_args = dict(action=more_action, provider_id=provider_id, media_type=media_type, catalog_id=catalog_id, label=label, page=str(page_num + 1))
        if _xn and _xv:
            more_args['extra_name'] = _xn
            more_args['extra_value'] = _xv
        if genre:
            more_args['genre'] = genre
        if year:
            more_args['year'] = year
        if extras:
            more_args['extras'] = extras
        if force_remote:
            more_args['force_remote'] = '1'
        if nuvio_mode:
            more_args['nuvio'] = '1'
        if meta_target:
            more_args['meta_target'] = str(meta_target)
        if skip_supported and next_cursor:
            more_args['cursor'] = next_cursor
        more_url = build_url(**more_args)
        if not globals().get('_pagination_hidden', lambda: False)():
            add_item(tr('المزيد'), more_url, info={'title': tr('المزيد'), 'plot': tr('تحميل المزيد من نتائج هذا الكتالوج')}, art=root_art('catalogs'))
        if skip_supported and not nuvio_mode:
            try:
                import threading as _thr
                def _prefetch():
                    try:
                        next_state = dict(state or {})
                        next_state.update(preset_filters)
                        next_state['skip'] = (next_cursor or
                                              str((page_num + 1) * page_size))
                        _apply_catalog_request(
                            provider, media_type, catalog_id, next_state,
                            include_limit=not nuvio_mode)
                    except Exception:
                        pass
                _thr.Thread(target=_prefetch, daemon=True).start()
            except Exception:
                pass
    end_dir(content=_directory_content_for_type(media_type))
    if page_num == 0 and _poster_report is not None:
        # what stayed without a poster is said once, with its cause and fix
        try:
            _issue = _poster_doctor.record(
                provider, media_type, catalog_id,
                (catalog_def or {}).get('name') or label or catalog_id, _poster_report)
            if _issue:
                _poster_doctor.maybe_alert(_issue)
        except Exception as exc:
            xbmc.log('[DexHub] posters: report failed: %s' % exc, xbmc.LOGWARNING)

def catalog_all(provider_id, media_type, catalog_id, label='', page='0', genre='', year='', force_remote='', nuvio='', meta_target='', cursor='', extras=''):
    """Bypass genre/year folder gate — show the full unfiltered catalog listing."""
    return catalog(
        provider_id, media_type, catalog_id, label=label, page=page,
        genre=genre, year=year, force_remote=force_remote, nuvio=nuvio,
        meta_target=meta_target, cursor=cursor, _skip_gate=True, extras=extras)


def catalog_extra(provider_id, media_type, catalog_id, label='', page='0', extra_name='', extra_value='', force_remote='', nuvio='', meta_target='', cursor='', extras=''):
    """Open a catalog with one arbitrary preset extra (used for folder-mode extras
    that aren't specially named genre/year)."""
    return catalog(
        provider_id, media_type, catalog_id, label=label, page=page,
        force_remote=force_remote, nuvio=nuvio, meta_target=meta_target,
        cursor=cursor, _skip_gate=True, _extra_name=extra_name,
        _extra_value=extra_value, extras=extras)


def _return_after_filters(provider_id, media_type, catalog_id, force_remote='', return_action='', return_bucket=''):
    if return_action == 'hub_section' and return_bucket:
        return hub_section(return_bucket)
    return catalog(provider_id, media_type, catalog_id, force_remote=force_remote)


def filters_menu(provider_id, media_type, catalog_id, force_remote='', return_action='', return_bucket=''):
    provider = store.get_provider(provider_id)
    if not provider:
        return end_dir()
    catalog_def = _catalog_definition(provider, catalog_id, media_type)
    extras = [e for e in _available_filter_extras(catalog_def)
              if _extra_mode((e.get('name') or ''), catalog_def) == 'filter']
    if not extras:
        return _return_after_filters(provider_id, media_type, catalog_id, force_remote=force_remote, return_action=return_action, return_bucket=return_bucket)
    state = _filter_state(provider_id, catalog_id)
    labels = []
    actions = []
    for extra in extras:
        name = extra.get('name')
        if not name:
            continue
        current = state.get(name)
        labels.append('%s%s' % (_filter_label(name), ('  •  %s' % current) if current not in (None, '') else ''))
        actions.append(('set', name))
    if state:
        labels.append('مسح كل الفلاتر')
        actions.append(('clear', ''))
    idx = xbmcgui.Dialog().select(tr('الفرز والتصفية'), [tr(x) for x in labels])
    if idx < 0:
        return _return_after_filters(provider_id, media_type, catalog_id, force_remote=force_remote, return_action=return_action, return_bucket=return_bucket)
    action, value = actions[idx]
    if action == 'clear':
        store.clear_catalog_filters(provider_id, catalog_id)
        return _return_after_filters(provider_id, media_type, catalog_id, force_remote=force_remote, return_action=return_action, return_bucket=return_bucket)
    return select_filter(provider_id, media_type, catalog_id, value, force_remote=force_remote, return_action=return_action, return_bucket=return_bucket)


def select_filter(provider_id, media_type, catalog_id, filter_name, force_remote='', return_action='', return_bucket=''):
    provider = store.get_provider(provider_id)
    if not provider:
        return end_dir()
    catalog_def = _catalog_definition(provider, catalog_id, media_type)
    extra_def = None
    for extra in catalog_def.get('extra') or []:
        if isinstance(extra, dict) and extra.get('name') == filter_name:
            extra_def = extra
            break
    if not extra_def:
        return _return_after_filters(provider_id, media_type, catalog_id, force_remote=force_remote, return_action=return_action, return_bucket=return_bucket)

    options = list(extra_def.get('options') or [])
    title = _filter_label(filter_name)
    if options:
        labels = ['إلغاء الفلتر'] + [str(x) for x in options]
        idx = xbmcgui.Dialog().select(tr('اختر %s') % tr(title), [tr(x) for x in labels])
        if idx < 0:
            return _return_after_filters(provider_id, media_type, catalog_id, force_remote=force_remote, return_action=return_action, return_bucket=return_bucket)
        if idx == 0:
            store.set_catalog_filter(provider_id, catalog_id, filter_name, '__clear__')
        else:
            store.set_catalog_filter(provider_id, catalog_id, filter_name, labels[idx])
    else:
        default = _filter_state(provider_id, catalog_id).get(filter_name, '')
        kb = xbmc.Keyboard(default, tr('اكتب %s') % tr(title))
        kb.doModal()
        if not kb.isConfirmed():
            return _return_after_filters(provider_id, media_type, catalog_id, force_remote=force_remote, return_action=return_action, return_bucket=return_bucket)
        value = kb.getText().strip()
        store.set_catalog_filter(provider_id, catalog_id, filter_name, value or '__clear__')
    return _return_after_filters(provider_id, media_type, catalog_id, force_remote=force_remote, return_action=return_action, return_bucket=return_bucket)


def clear_filters(provider_id, media_type, catalog_id, force_remote='', return_action='', return_bucket=''):
    store.clear_catalog_filters(provider_id, catalog_id)
    return _return_after_filters(provider_id, media_type, catalog_id, force_remote=force_remote, return_action=return_action, return_bucket=return_bucket)


def _query_is_id(query):
    q = (query or '').strip().lower()
    # v5.10.28: "tt" alone or "ttyl" used to short-circuit into a bogus
    # single-id row instead of a search.
    return bool(re.match(r'^(tt\d{5,12}|(tmdb|imdb|tvdb):[a-z0-9]+)$', q))



def _search_identity_keys(meta):
    """Every identity a search meta is known by, across ID namespaces.

    v3.9.237: search dedup used the RAW meta id only. Different providers name
    the SAME title in different namespaces — Cinemeta says tt1160419, a TMDb
    catalog says tmdb:438631, Plexio says plex://… — none of which collide, so
    one movie could render two or three times in the results list.

    A meta usually carries its sibling ids (moviedb_id / imdb_id fields), and
    when it does not, a normalised title+year is a safe last-resort identity
    for search display purposes (NOT for playback identity).
    """
    keys = set()
    mid = str(meta.get('id') or '').strip().lower()
    if mid:
        keys.add(mid)
    imdb = str(meta.get('imdb_id') or meta.get('imdbId') or '').strip().lower()
    if imdb.startswith('tt'):
        keys.add(imdb)
    tmdb = str(meta.get('moviedb_id') or meta.get('tmdb_id') or
               meta.get('tmdbId') or '').strip().lower()
    if tmdb and tmdb not in ('0', 'none'):
        keys.add('tmdb:%s' % tmdb)
    # Last resort: normalised title + year. Only when it is trustworthy
    # (title long enough and a real year), to avoid merging distinct films.
    title = str(meta.get('name') or meta.get('title') or '').strip().lower()
    year = str(meta.get('year') or meta.get('releaseInfo') or '')[:4]
    if len(title) >= 3 and year.isdigit():
        keys.add('ty:%s|%s' % (''.join(ch for ch in title if ch.isalnum()), year))
    return keys


def search(media_type, provider_id=None, query=''):
    """Search. `query` may be supplied by the CALLER.

    v3.9.236: like add_provider, this always opened xbmc.Keyboard — so searching
    meant pecking out a title with a TV remote. Accepting the query as a
    parameter makes it drivable from a phone via Kodi's JSON-RPC:

        Addons.ExecuteAddon
          addonid = plugin.video.dexhub
          params  = ["action=search", "media_type=movie", "query=dune"]

    The keyboard stays as the fallback, so the on-TV flow is unchanged.
    """
    rows = [store.get_provider(provider_id)] if provider_id else store.list_providers()
    rows = [x for x in rows if x]
    if not rows:
        return providers()
    win = xbmcgui.Window(WINDOW_ID)
    last_key = 'dexhub.last_search.%s' % (media_type or 'any')
    query = (query or '').strip()
    if not query:
        # Seed keyboard with the last query so users can refine without retyping.
        last_query = win.getProperty(last_key) or ''
        keyboard = xbmc.Keyboard(last_query, tr('ابحث أو اكتب tmdb:123 / tt1234567'))
        keyboard.doModal()
        if not keyboard.isConfirmed():
            return end_dir()
        query = keyboard.getText().strip()
        if not query:
            return end_dir()
    win.setProperty(last_key, query)
    # Persist to the search-history DB so the user can pick it from the
    # history menu next time without retyping. Best-effort.
    try:
        from . import search_history as _sh
        _sh.add(query, media_type=media_type or 'all')
    except Exception:
        pass
    seen = {}
    # v3.9.40: clear leftover source-art window properties from a
    # previous item before rendering search results. Without this, when
    # the user has been viewing item A and then opens search for item B,
    # the skin's $INFO bindings continue reading A's poster/clearlogo
    # from the home window — visible in some skins as the OLD item's
    # artwork on top of the NEW search result. _clear_source_transient_props
    # already exists and is used elsewhere; we now also call it here.
    _clear_source_transient_props(clear_global=True)
    if _query_is_id(query):
        item_label = query
        if media_type == 'series':
            path, path_is_folder = _content_click_path(media_type=media_type, canonical_id=query, title=item_label)
            add_item(item_label, path, is_folder=path_is_folder, info={'title': item_label}, art=catalog_art('search', media_type))
        else:
            path, path_is_folder = _content_click_path(media_type=media_type, canonical_id=query, title=item_label)
            add_item(item_label, path, is_folder=path_is_folder, info={'title': item_label}, art=catalog_art('search', media_type), context_menu=_build_source_picker_menu(media_type=media_type, canonical_id=query, title=item_label))
        return end_dir(content=_directory_content_for_type(media_type), cache=False)

    search_jobs = []
    for provider in rows:
        for cat in _provider_catalogs(provider, media_type):
            searchable = _catalog_supports_search(cat)
            if searchable:
                search_jobs.append((provider, cat))

    if not search_jobs:
        return end_dir(content=_directory_content_for_type(media_type), cache=False)

    cache_key = ('v500', str(media_type or ''), str(provider_id or ''),
                 query.casefold(), _meta_cache_discriminator(provider_id or ''))
    cached_rows = _search_cache_get(cache_key)
    if cached_rows:
        # v3.9.36: cached rows go through the same render path as fresh
        # results below — header + dedupe + provider count — so the user
        # experience is identical regardless of cache state. We pre-fill
        # the meta memory then jump to the shared rendering block.
        for provider, meta_id, meta in cached_rows:
            try:
                _meta_mem_put(media_type, meta_id, meta, source_provider_id=provider.get('id') or '')
            except Exception:
                pass
        ordered_rows = list(cached_rows)
    else:
        ordered_rows = None   # filled below by the live search loop

    def _run_search(job):
        provider, cat = job
        return fetch_catalog(provider, media_type, cat.get('id'), extra={'search': query}, timeout_override=fast_timeout('search'))

    if ordered_rows is None:
        # Issue: previously we early-stopped at ~30 results, which in practice
        # meant only the FIRST provider returned anything. Users with multiple
        # sources (Cinemeta + Plexio + Plex + custom catalogs) only saw results
        # from one. Now we query EVERY searchable catalog in parallel batches
        # and merge the results. We still cap the total to avoid runaway lists,
        # but the cap is generous (8x page size, max 240) so realistic searches
        # always reach the cap from at least 2-3 sources.
        ordered_rows = []
        enough = max(60, _listing_page_size() * 8)
        enough = min(enough, 240)
        batch_size = max(2, min(parallel_workers(), 4, len(search_jobs)))
        _race = start_parallel_race(
            _run_search, _fair_search_job_order(search_jobs),
            workers=batch_size, timeout=6.0, lane='search')

        for job, result in _iter_search_race(
                _race, lambda: len(ordered_rows), lambda: True,
                real_goal=enough, quiet_seconds=0.30,
                fallback_seconds=4.0):
            provider, _cat = job
            if isinstance(result, Exception):
                continue
            metas = []
            for meta in (result or {}).get('metas') or []:
                meta_id = meta.get('id')
                if (not meta_id
                        or _search_match.best_match_score(query, meta) <= 0):
                    continue
                # Dedup across ID namespaces: the same film arrives as
                # tt…, tmdb:…, and plex://… from different providers.
                _idents = _search_identity_keys(meta)
                if _idents & set(seen):
                    continue
                for _k in _idents:
                    seen[_k] = True
                metas.append(meta)
            if not metas:
                continue
            # Search should feel instant — avoid expensive deep enrich here.
            try:
                from . import meta_source as _meta_source
                metas = _meta_source.override_metas_batch(provider, media_type, metas)
            except Exception:
                pass
            for meta in metas:
                ordered_rows.append((provider, meta.get('id'), meta))
        if len(ordered_rows) >= enough:
            ordered_rows = ordered_rows[:enough]

        if ordered_rows:
            _search_cache_put(cache_key, ordered_rows)

    # Cached rows and freshly enriched rows share one strict relevance floor.
    # This also invalidates old A-Z noise still resident in a reused VM.
    ordered_rows = [row for row in (ordered_rows or [])
                    if _search_match.best_match_score(query, row[2]) > 0]
    ordered_rows.sort(
        key=lambda row: -_search_match.best_match_score(query, row[2]))

    # v3.9.36: improved search results presentation.
    #
    # Strategy:
    # 1. Show a header row at the top with the query, total result count,
    #    active source count, and any blocked-source notice. Gives the
    #    user immediate context — "I searched X across Y sources, Z were
    #    blocked, found N results."
    # 2. Merge duplicates by canonical id across providers. If the same
    #    movie comes from Cinemata + Plexio + Custom, show ONE row with
    #    a "(in 3 sources)" badge instead of three separate rows. The
    #    first provider's metadata wins (Cinemata is usually richest).
    # 3. Each result keeps its primary provider as the source-of-truth
    #    for stream resolution, but also stores the full provider list
    #    in info.plot so the user can see coverage.

    # ─── Header row ───
    active_sources = len({p.get('id') for p, _, _ in ordered_rows} | {p.get('id') for p, _ in search_jobs})
    header_label = tr('🔍 بحث: %s') % query
    header_parts = [tr('نتائج: %d') % len(ordered_rows)]
    header_parts.append(tr('مصادر فعّالة: %d') % active_sources)
    if not ordered_rows:
        header_parts.append('لا توجد نتائج — جرّب صياغة أخرى')
    header_subtitle = ' • '.join(header_parts)
    header_plot = tr('استعلامك: "%s"\n\n%s') % (query, '\n'.join(header_parts))
    # The header is a no-op item (path=current) so clicking it does nothing
    # disruptive. Visually it acts as a section divider.
    add_item('%s — %s' % (header_label, header_subtitle),
             build_url(action='search', media_type=media_type),
             is_folder=True,
             info={'title': header_label, 'plot': header_plot},
             art=catalog_art('search', media_type))

    # ─── Merge duplicates across providers ───
    merged = {}
    order = []
    for provider, meta_id, meta in ordered_rows:
        if meta_id not in merged:
            merged[meta_id] = {
                'primary_provider': provider,
                'meta': meta,
                'provider_names': [provider.get('name') or provider.get('id')],
                'provider_ids': [provider.get('id') or ''],
            }
            order.append(meta_id)
        else:
            entry = merged[meta_id]
            pname = provider.get('name') or provider.get('id')
            if pname not in entry['provider_names']:
                entry['provider_names'].append(pname)
                entry['provider_ids'].append(provider.get('id') or '')

    for _row_idx, meta_id in enumerate(order):
        entry = merged[meta_id]
        provider = entry['primary_provider']
        meta = entry['meta']
        item_label = meta.get('name') or meta_id
        # Append provider-count badge to the label when the same item is
        # available from multiple sources, so the user can see coverage
        # at a glance. Single-source results show no badge to avoid
        # noise.
        n_providers = len(entry['provider_names'])
        if n_providers > 1:
            display_label = '%s  ·  📡 %d' % (item_label, n_providers)
        else:
            display_label = item_label
        try:
            _meta_mem_put(media_type, meta_id, meta, source_provider_id=provider.get('id') or '')
        except Exception:
            pass
        path_action = 'series_meta' if media_type == 'series' else 'play_item'
        fallback = _item_fallback_art(provider, media_type, None, item_label)
        # v5.10.26: search used to run the full sqlite/TMDb art enrichment for
        # every one of up to 240 rows before drawing anything. Only the rows
        # above the fold get it now, exactly like the folder renderer.
        art = _resolve_meta_art(provider, media_type, meta, fallback_art=fallback,
                                lazy=(_row_idx >= 12))
        ids = extract_ids(meta)
        path, path_is_folder = _content_click_path(
            media_type=media_type, canonical_id=meta_id, title=item_label,
            tmdb_id=ids.get('tmdb_id') or '', imdb_id=ids.get('imdb_id') or '', tvdb_id=ids.get('tvdb_id') or '',
            source_provider_id=provider.get('id') or '', ui_seed=art)
        # Enrich plot with the provider-list footer so the user can see
        # exactly which sources have this title without opening it.
        info = _meta_info(meta)
        if n_providers > 1:
            current_plot = info.get('plot') or ''
            info = dict(info)
            info['plot'] = (current_plot
                + ('\n\n' if current_plot else '')
                + tr('متوفر في %d مصادر: %s') % (n_providers, tr('، ').join(entry['provider_names'])))
        add_item(display_label,
                 path,
                 is_folder=path_is_folder,
                 info=info,
                 art=art,
                 ids=ids,
                 context_menu=_build_source_picker_menu(
                     media_type=media_type, canonical_id=meta_id, title=item_label,
                     source_provider_id=provider.get('id') or ''))
    end_dir(content=_directory_content_for_type(media_type), cache=False)


def _provider_order_for_id(media_type, canonical_id):
    rows = []
    for provider in store.list_providers():
        if supports_resource(provider, 'stream', media_type=media_type, item_id=canonical_id) or supports_resource(provider, 'meta', media_type=media_type, item_id=canonical_id):
            rows.append(provider)
    # Bug fix: previously, if the strict idPrefix filter matched 0 providers
    # (e.g. Continue Watching has a `tmdb:` ID but the user's stream addons
    # only declare `tt`), the source list came back empty and Continue
    # Watching items appeared "broken" with no streams. Fall back to ALL
    # stream-capable providers and let each provider decide whether it can
    # actually resolve the ID — this matches Stremio's own behavior.
    if not rows:
        for provider in store.list_providers():
            if supports_resource(provider, 'stream', media_type=media_type) or supports_resource(provider, 'meta', media_type=media_type):
                rows.append(provider)
    return rows


def _normalize_imdb_id(value):
    """Return a full IMDb title id without truncating modern 8+ digit ids."""
    raw = str(value or '').strip()
    if not raw:
        return ''
    m = re.search(r'(?i)\btt(\d{5,12})\b', raw)
    if m:
        return 'tt' + m.group(1)
    if raw.isdigit() and 5 <= len(raw) <= 12:
        return 'tt' + raw
    return ''


def _unique(values):
    seen = set()
    out = []
    for value in values:
        sval = str(value or '').strip()
        if not sval or sval in seen:
            continue
        seen.add(sval)
        out.append(sval)
    return out




# v-hub: resolve an IMDb id from a TMDb id WITHOUT a TMDb API key, so
# Stremio aggregators (which need a `tt` id) get sources even when the user
# never configured a key.
#
# IMPORTANT: this is a BEST-EFFORT fallback. The reliable path is a TMDb API
# key (see _enrich_stream_ids → _tmdb_direct, which uses the account key). This
# keyless resolver only runs when no key resolved an id, and it depends on a
# public community addon being reachable, so every failure degrades to '' and
# the caller simply proceeds without the extra id.
#
# The TMDB Addon (community, keyless) is natively keyed by tmdb: ids and returns
# a meta object carrying the imdb_id. Cinemeta itself is IMDb-only and is NOT
# used here (it can't resolve a tmdb: id).
_CINEMETA_IMDB_CACHE = {}
_STREAM_ID_CACHE = {}
_STREAM_ID_CACHE_ORDER = []
_STREAM_ID_CACHE_LOCK = threading.Lock()
_STREAM_ID_CACHE_MAX = 256
_STREAM_ID_CACHE_TTL = 1800.0

# Public keyless TMDB metadata addon base(s). elfhosted is already used
# elsewhere in this addon for aiostreams/aiometadata, so it's a known-good host.
_TMDB_ADDON_BASES = (
    'https://tmdb.elfhosted.com',
)

def _http_json(url, timeout=3):
    import json as _json
    from urllib.request import Request as _Req, urlopen as _open
    req = _Req(url, headers={'Accept': 'application/json',
                             'User-Agent': 'Mozilla/5.0 (compatible; DexHub)'})
    with _open(req, timeout=timeout) as resp:
        return _json.loads(resp.read().decode('utf-8', 'replace') or '{}')

def _cinemeta_imdb_for_tmdb(tmdb_id, media_type):
    tmdb_id = str(tmdb_id or '').strip()
    if not tmdb_id.isdigit():
        return ''
    mt = 'series' if media_type in ('series', 'tv', 'show', 'anime') else 'movie'
    ck = '%s:%s' % (mt, tmdb_id)
    if ck in _CINEMETA_IMDB_CACHE:
        return _CINEMETA_IMDB_CACHE[ck]

    imdb = ''
    for base in _TMDB_ADDON_BASES:
        try:
            data = _http_json('%s/meta/%s/tmdb:%s.json' % (base, mt, tmdb_id))
            meta = data.get('meta') or {}
            cand = str(meta.get('imdb_id') or '').strip()
            # Some deployments return the imdb id as the meta id when it's a tt.
            if not cand.startswith('tt'):
                mid = str(meta.get('id') or '').strip()
                cand = mid if mid.startswith('tt') else ''
            if cand.startswith('tt'):
                imdb = cand
                break
        except Exception:
            continue

    try:
        xbmc.log('[DexHub] tmdb->imdb (keyless) tmdb:%s -> %s' % (tmdb_id, imdb or 'MISS'),
                 xbmc.LOGINFO)
    except Exception:
        pass
    _CINEMETA_IMDB_CACHE[ck] = imdb
    return imdb


def _enrich_stream_ids(ids, media_type, meta=None, canonical_id='', title='', network=True):
    """Fill IMDb/TMDb/TVDb ids before asking Stremio stream addons.

    Stremio apps normally call stream addons with catalogue ids such as `tt...`.
    When Dex Hub starts from TMDb Helper or TMDb-based catalogues we may only
    have `tmdb:123`; Stremio aggregators then miss Debrid results.  Resolve
    ids locally first, using TMDb Helper's DB (no API) and then TMDb Direct if
    the user has configured an API key.
    """
    out = dict(ids or {})
    meta = meta or {}
    parsed = extract_ids(meta)
    for key in ('tmdb_id', 'imdb_id', 'tvdb_id'):
        if parsed.get(key) and not out.get(key):
            out[key] = parsed.get(key)
    cid = str(canonical_id or meta.get('id') or '').strip()
    if cid.startswith('tmdb:') and not out.get('tmdb_id'):
        tail = cid.split(':')[-1]
        if tail.isdigit():
            out['tmdb_id'] = tail
    elif cid.startswith('tvdb:') and not out.get('tvdb_id'):
        tail = cid.split(':')[-1]
        if tail.isdigit():
            out['tvdb_id'] = tail
    elif re.match(r'^tt\d{5,10}$', cid, re.I) and not out.get('imdb_id'):
        out['imdb_id'] = cid

    # Enrichment only fills these three fields. Complete identity must not pay
    # for another metadata build, database lookup or network request.
    if all(out.get(key) for key in ('tmdb_id', 'imdb_id', 'tvdb_id')):
        return out
    year = (_meta_info(meta).get('year') or meta.get('year') or meta.get('releaseInfo') or '')
    lookup_title = title or meta.get('name') or meta.get('title') or ''
    _cache_key = (
        str(media_type or ''), cid.lower(),
        str(out.get('tmdb_id') or ''), str(out.get('imdb_id') or '').lower(),
        str(out.get('tvdb_id') or ''), str(lookup_title or '').casefold(),
        str(year or '')[:4],
    )
    with _STREAM_ID_CACHE_LOCK:
        _cached = _STREAM_ID_CACHE.get(_cache_key)
        if _cached and _cached[0] > time.monotonic():
            for _key, _value in (_cached[1] or {}).items():
                if _value and not out.get(_key):
                    out[_key] = _value
            return out
    try:
        db_ids = _tmdb_art_db.get_external_ids_from_db(
            tmdb_id=out.get('tmdb_id') or '', imdb_id=out.get('imdb_id') or '', tvdb_id=out.get('tvdb_id') or '',
            media_type=media_type, title=lookup_title, year=year,
        ) or {}
        for key in ('tmdb_id', 'imdb_id', 'tvdb_id'):
            if db_ids.get(key) and not out.get(key):
                out[key] = db_ids.get(key)
    except Exception:
        pass
    if not network:
        # v5.10.27: the pre-play guard only reads local sources. The source
        # scan already ran (and cached) the network race for this item; a
        # miss here must not cost a 3s stall right before Player.play.
        return out
    if not out.get('imdb_id') and (out.get('tmdb_id') or lookup_title):
        # TMDb Direct and the keyless Stremio metadata route are independent.
        # They used to run sequentially (up to two full network timeouts)
        # before source discovery could even begin. Race both under one short
        # identity budget and accept the first valid IMDb answer.
        _identity_jobs = ['tmdb']
        if out.get('tmdb_id'):
            _identity_jobs.append('keyless')

        def _identity_lookup(kind):
            if kind == 'keyless':
                return {'imdb_id': _cinemeta_imdb_for_tmdb(
                    out.get('tmdb_id'), media_type)}
            return _tmdb_direct.art_for(
                tmdb_id=out.get('tmdb_id') or '', imdb_id='',
                media_type=media_type, title=lookup_title, year=year,
            ) or {}

        _id_race = start_parallel_race(
            _identity_lookup, _identity_jobs,
            workers=min(2, len(_identity_jobs)), timeout=3.0, lane='identity')
        try:
            for _kind, _bundle in _id_race.iter_completed(
                    timeout=3.0, poll_interval=0.05):
                if isinstance(_bundle, Exception) or not isinstance(_bundle, dict):
                    continue
                if _bundle.get('imdb_id'):
                    out['imdb_id'] = _bundle.get('imdb_id')
                if _bundle.get('tmdb_id') and not out.get('tmdb_id'):
                    out['tmdb_id'] = str(_bundle.get('tmdb_id'))
                if out.get('imdb_id'):
                    break
        finally:
            _id_race.cancel()
    if out.get('imdb_id'):
        out['imdb_id'] = _normalize_imdb_id(out.get('imdb_id')) or str(out.get('imdb_id')).strip()
    with _STREAM_ID_CACHE_LOCK:
        _STREAM_ID_CACHE[_cache_key] = (
            time.monotonic() + _STREAM_ID_CACHE_TTL, dict(out))
        if _cache_key not in _STREAM_ID_CACHE_ORDER:
            _STREAM_ID_CACHE_ORDER.append(_cache_key)
        while len(_STREAM_ID_CACHE_ORDER) > _STREAM_ID_CACHE_MAX:
            _old = _STREAM_ID_CACHE_ORDER.pop(0)
            _STREAM_ID_CACHE.pop(_old, None)
    return out

def _candidate_ids_from_meta(canonical_id, meta=None, season=None, episode=None, include_episode_variants=False):
    meta = meta or {}
    ids = extract_ids(meta)
    candidates = [canonical_id]
    if ids.get('imdb_id'):
        imdb = ids['imdb_id']
        candidates.extend([imdb, 'imdb:%s' % imdb])
    if ids.get('tmdb_id'):
        candidates.append('tmdb:%s' % ids['tmdb_id'])
    if ids.get('tvdb_id'):
        candidates.append('tvdb:%s' % ids['tvdb_id'])
    for key in ('kitsu_id', 'anilist_id', 'anidb_id', 'mal_id'):
        val = meta.get(key)
        if val:
            prefix = key.replace('_id', '')
            candidates.append('%s:%s' % (prefix, val))
    external = meta.get('externalIds') or {}
    if isinstance(external, dict):
        for key, value in external.items():
            if not value:
                continue
            skey = str(key).lower()
            sval = str(value)
            if skey.startswith('imdb'):
                candidates.extend([sval if sval.startswith('tt') else 'tt%s' % sval, 'imdb:%s' % (sval if sval.startswith('tt') else 'tt%s' % sval)])
            elif skey.startswith('tmdb'):
                candidates.append('tmdb:%s' % sval)
            elif skey.startswith('tvdb'):
                candidates.append('tvdb:%s' % sval)
            elif skey.startswith('anidb'):
                candidates.append('anidb:%s' % sval)
            elif skey.startswith('kitsu'):
                candidates.append('kitsu:%s' % sval)
            elif skey.startswith('anilist'):
                candidates.append('anilist:%s' % sval)
    if include_episode_variants and season and episode:
        episode_ids = []
        for cid in list(candidates):
            lower = cid.lower()
            if ':' in cid and not lower.startswith('tt'):
                episode_ids.append('%s:%s:%s' % (cid, int(season), int(episode)))
            elif lower.startswith('tt'):
                episode_ids.append('%s:%s:%s' % (cid, int(season), int(episode)))
        candidates = episode_ids + candidates
    return _unique(candidates)


def _stream_resource_id_prefixes(provider, media_type=None):
    """Return idPrefixes advertised by a provider's stream resource.

    Some Stremio aggregators such as Stremio aggregators advertise only `tt`
    but can still resolve episode ids like `tt123:1:2`. Dex Hub must not hide
    those providers just because the current catalog id is tmdb/tvdb.
    """
    manifest = (provider or {}).get('manifest') or {}
    for resource in manifest.get('resources', []) or []:
        if resource == 'stream':
            return []
        if isinstance(resource, dict) and resource.get('name') == 'stream':
            types = resource.get('types') or []
            if media_type and types and media_type not in types:
                continue
            return [str(x).lower() for x in (resource.get('idPrefixes') or []) if str(x or '').strip()]
    return []


def _candidate_ids_matching_prefixes(candidate_ids, prefixes):
    prefixes = [str(p or '').lower() for p in (prefixes or []) if str(p or '').strip()]
    if not prefixes:
        return list(candidate_ids or [])
    out = []
    for cid in candidate_ids or []:
        lower = str(cid or '').lower()
        if any(lower.startswith(prefix) for prefix in prefixes):
            out.append(cid)
    return out


def _ordered_stream_candidate_ids(provider_ids, season=None, episode=None):
    """Prefer the id shapes stream aggregators resolve best.

    Stremio aggregators-like addons usually resolve IMDb tt ids first. For
    episodes, the canonical Stremio form is tt1234567:season:episode. Keep
    tmdb/tvdb as fallback candidates, but do not let them run before tt ids.
    """
    ep_suffix = ''
    if season and episode:
        try:
            ep_suffix = ':%s:%s' % (int(season), int(episode))
        except Exception:
            ep_suffix = ''

    def _rank(value):
        lower = str(value or '').lower()
        is_ep = bool(ep_suffix and lower.endswith(ep_suffix))
        if is_ep and lower.startswith('tt'):
            return (0, lower)
        if lower.startswith('tt'):
            return (1, lower)
        if is_ep and lower.startswith('imdb:tt'):
            return (2, lower)
        if lower.startswith('imdb:tt'):
            return (3, lower)
        if is_ep and lower.startswith('tmdb:'):
            return (4, lower)
        if lower.startswith('tmdb:'):
            return (5, lower)
        if is_ep and lower.startswith('tvdb:'):
            return (6, lower)
        if lower.startswith('tvdb:'):
            return (7, lower)
        return (8, lower)

    return sorted(list(provider_ids or []), key=_rank)

def _anime_prefix_providers():
    """Installed addons whose stream resource only accepts anime ids."""
    out = []
    for provider in store.list_providers():
        for prefix in _stream_resource_id_prefixes(provider):
            if str(prefix).split(':')[0] in ('kitsu', 'mal', 'anilist', 'anidb'):
                out.append(provider)
                break
    return out


def _apply_anime_id_policy(ids, media_type):
    """v3.9.200 — the missing half of the stream-request ID policy.

    A stream addon only answers the id SHAPE it declares. Dex Hub translated
    imdb <-> tmdb <-> tvdb, but never produced kitsu/mal/anilist/anidb ids, so
    every anime addon was queried with `tt...` and returned NOTHING — which is
    exactly why anime sources looked empty. The mapping (AIOStreams merges six
    such databases; we use Fribb's, which merges the same systems) is consulted
    ONLY when an anime-prefixed addon is actually installed and the id we need
    is actually missing. Zero cost for everyone else.
    """
    ids = dict(ids or {})
    try:
        if not anime_ids.enabled():
            return ids
        if all(ids.get(k) for k in ('kitsu_id', 'mal_id', 'anilist_id', 'anidb_id')):
            return ids
        if not _anime_prefix_providers():
            return ids
        extra = anime_ids.lookup(ids)
        for key, value in (extra or {}).items():
            if value and not ids.get(key):
                ids[key] = value
        if extra:
            xbmc.log('[DexHub] anime id policy: added %s' % ', '.join(sorted(extra)),
                     xbmc.LOGINFO)
    except Exception:
        pass
    return ids


def _stream_provider_targets(media_type, canonical_id, meta=None, season=None, episode=None):
    from .source_targets import build_targets
    return build_targets(sys.modules[__name__], media_type=media_type, canonical_id=canonical_id, meta=meta, season=season, episode=episode)


def _directory_content_for_type(media_type):
    """Advertise the real media class so skins such as AF3 choose rich views."""
    value = str(media_type or '').strip().lower()
    if value in ('series', 'show', 'shows', 'tv', 'tvshow', 'anime'):
        return 'tvshows'
    if value in ('episode', 'episodes'):
        return 'episodes'
    if value in ('season', 'seasons'):
        return 'seasons'
    if value in ('video', 'videos', 'channel', 'channels', 'live', 'all', 'mixed'):
        return 'videos'
    return 'movies'


def _home_owns_click():
    """v5.10.105: the Dex Hub Home decides where its titles open.

    Its rows are captured from these routes, and every route it opens carries
    dh_home=1. Neither follows the classic "open in TMDb Helper" click mode:
    that sent some series (and Next Up episodes) to TMDb Helper on their own,
    through a Container.Update that Back could not return from.
    """
    try:
        from . import capture
        if capture.active():
            return True
    except Exception:
        pass
    try:
        return 'dh_home=1' in (sys.argv[2] if len(sys.argv) > 2 else '')
    except Exception:
        return False


def _default_click_mode():
    if _home_owns_click():
        return 'dexhub'
    raw = str(ADDON.getSetting('catalog_click_mode') or 'Dex Hub').strip().lower()
    compact = raw.replace(' ', '').replace('_', '').replace('-', '')
    if compact in ('tmdbhelper', 'helper', '1') or 'tmdb' in compact:
        return 'tmdbhelper'
    if raw in ('اسأل كل مرة', 'السؤال كل مرة', 'ask') or compact in ('ask', 'askeverytime', '2'):
        return 'ask'
    return 'dexhub'


def _default_playback_mode():
    raw = (ADDON.getSetting('playback_open_mode') or 'Choose from sources').strip().lower()
    if raw in ('1', 'best quality automatically', 'auto', 'autoplay') or ('best' in raw) or ('أفضل' in raw):
        return 'autoplay'
    return 'sources'


def _prefer_source_picker():
    return _default_playback_mode() != 'autoplay'


# v3.9.40: source resolution strategy. Distinct from catalog_click_mode
# (which decides whether DexHub or TMDb Helper handles the click) and
# from playback_open_mode (which decides picker vs autoplay inside
# DexHub). This setting decides, when DexHub IS handling the playback,
# which source actually resolves the stream:
#   - 'same'  : the originating provider (preferred_provider_name).
#               Falls back to the picker only if that provider has no
#               stream for the item.
#   - 'tmdbh' : hand the playback off to TMDb Helper's player chooser.
#   - 'picker': always show the DexHub source picker (legacy default).
def _source_resolution_mode():
    raw = (ADDON.getSetting('source_resolution_mode') or 'DexHub picker').strip().lower()
    if 'نفس' in raw or 'same' in raw:
        return 'same'
    if 'tmdb' in raw or 'helper' in raw:
        return 'tmdbh'
    return 'picker'


def _resolve_routing_ids(media_type='movie', canonical_id='', title='', tmdb_id='', imdb_id='', tvdb_id='', season='', episode='', local_only=False):
    probe_type = 'series' if _is_series_media(media_type) or (season not in (None, '', '0', 0) and episode not in (None, '', '0', 0)) else 'movie'
    ids = {
        'tmdb_id': str(tmdb_id or '').strip(),
        'imdb_id': str(imdb_id or '').strip(),
        'tvdb_id': str(tvdb_id or '').strip(),
    }
    ids = _merge_seed_ids(ids, _get_tmdbh_seed_ids(canonical_id or ''))
    ids = _merge_seed_ids(ids, extract_ids({'id': canonical_id or ''}))
    if ids.get('tmdb_id') or ids.get('imdb_id') or ids.get('tvdb_id'):
        return ids
    try:
        cached = _meta_mem_get(probe_type, canonical_id)
    except Exception:
        cached = None
    if cached:
        ids = _merge_seed_ids(ids, extract_ids(cached))
        if ids.get('tmdb_id') or ids.get('imdb_id') or ids.get('tvdb_id'):
            return ids
    if local_only:
        return ids
    providers = _provider_order_for_id(probe_type, canonical_id)
    if providers:
        try:
            meta = _best_meta_for_item(probe_type, canonical_id, providers)
            ids = _merge_seed_ids(ids, extract_ids(meta))
        except Exception as exc:
            xbmc.log('[DexHub] routing id probe failed for %s: %s' % (canonical_id, exc), xbmc.LOGWARNING)
    return ids


def _maybe_redirect_default_player(media_type='movie', canonical_id='', title='', season='', episode='', tmdb_id='', imdb_id='', tvdb_id=''):
    mode = _default_click_mode()
    # When TMDb Helper already handed the item off to Dex Hub, do NOT bounce
    # back into TMDb Helper again from inside Dex Hub. That re-entry opens the
    # TMDb Helper page a second time and often ends with failed playback.
    if _tmdbh_invocation_active():
        return False
    if mode != 'tmdbhelper' or not _has_tmdbhelper():
        return False
    probe_type = 'series' if _is_series_media(media_type) or (season not in (None, '', '0', 0) and episode not in (None, '', '0', 0)) else 'movie'
    meta = {'id': canonical_id, 'type': probe_type, 'name': title or canonical_id}
    ids = _resolve_routing_ids(
        media_type=probe_type,
        canonical_id=canonical_id,
        title=title or canonical_id,
        tmdb_id=tmdb_id,
        imdb_id=imdb_id,
        tvdb_id=tvdb_id,
        season=season,
        episode=episode,
    )
    if not (ids.get('tmdb_id') or ids.get('imdb_id') or ids.get('tvdb_id')):
        providers = _provider_order_for_id(probe_type, canonical_id)
        try:
            meta = _best_meta_for_item(probe_type, canonical_id, providers)
        except Exception as exc:
            xbmc.log('[DexHub] default-player meta probe failed for %s: %s' % (canonical_id, exc), xbmc.LOGWARNING)
            meta = {'id': canonical_id, 'type': probe_type, 'name': title or canonical_id}
        ids = _merge_seed_ids(ids, extract_ids(meta))
    url = _tmdbh_url_from_ids(
        media_type='series' if probe_type == 'series' else 'movie',
        tmdb_id=ids.get('tmdb_id') or '',
        imdb_id=ids.get('imdb_id') or '',
        tvdb_id=ids.get('tvdb_id') or '',
        title=(meta.get('name') or meta.get('title') or title or canonical_id),
        season=season or '',
        episode=episode or '',
    )
    if not url:
        return False
    return _launch_tmdbhelper_url(url)


def _quick_same_source_enabled(source_provider_id='', preferred_provider_name=''):
    sid = str(source_provider_id or '').strip()
    return (ADDON.getSetting('quick_same_source_play') == 'true'
            and bool((sid and not sid.startswith('virtual.')) or preferred_provider_name))


def _quick_same_source_targets(targets, source_provider_id='', preferred_provider_name='', server_id=''):
    sid = str(source_provider_id or '').strip()
    if sid.startswith('virtual.'):
        sid = ''  # Continue-watching metadata target is not a stream provider.
    name = str(preferred_provider_name or '').strip().casefold()
    selected = [(p, rid) for p, rid in targets
                if (str(p.get('id') or '') == sid if sid else
                    bool(name) and str(p.get('name') or '').strip().casefold() == name)]
    if server_id:
        selected = _binge_source.filter_targets(selected, server_id=server_id)
    return selected


def _dispatch_dexhub_play(media_type='', canonical_id='', title='', video_id='', season='', episode='', resume_seconds='0', resume_percent='', preferred_provider_name='', tmdb_id='', imdb_id='', tvdb_id='', source_provider_id='', source_mode='', ui_seed=None):
    media_type = str(media_type or 'movie').strip().lower()
    try:
        resume = float(resume_seconds or 0.0)
    except Exception:
        resume = 0.0

    # v3.9.40: consult source_resolution_mode before the picker-vs-autoplay
    # branch. The user wants explicit control over WHICH source resolves
    # the stream, separate from whether the picker is shown.
    resolution_mode = _source_resolution_mode()
    # v3.9.74: carry explicit IDs from catalogue/TMDb Helper click all the
    # way into the stream context. a4kSubtitles relies on a real IMDb id
    # being present during playback; losing these params here made the player
    # start with only title/TMDb data even though the list item had IMDb.
    seed_ids = _seed_ids_from_values(tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id, canonical_id=canonical_id)

    from . import playback_choices, continue_playback
    if ADDON.getSetting('remember_last_source') == 'true' and source_mode != 'picker':
        limited = source_mode in ('only', 'quick_same') or resolution_mode == 'same'
        wanted = source_provider_id if limited else ''
        wanted_server = str((ui_seed or {}).get('native_server_id') or '') if limited else ''
        wanted_name = preferred_provider_name if limited and not (wanted and not wanted.startswith('virtual.')) else ''
        played, result = playback_choices.try_saved(sys.modules[__name__], media_type,
            canonical_id, video_id, season, episode, resume_seconds=resume,
            resume_percent=resume_percent or '', provider_id=wanted, provider_name=wanted_name,
            server_id=wanted_server)
        if played:
            return result
        record = playback_choices.saved(sys.modules[__name__], media_type, canonical_id, video_id, season, episode)
        previous = record.get('ctx') or _last_source_choice(media_type, canonical_id, video_id)
        if previous and continue_playback.known(previous):
            affinity = _binge_source.affinity_from_context(previous)
            remembered_id = affinity.get('provider_id') or ''
            provider_matches = not wanted or wanted.startswith('virtual.') or remembered_id == wanted
            server_matches = not wanted_server or str(affinity.get('server_id') or '') == wanted_server
            name_matches = not wanted_name or str(affinity.get('provider_name') or '').casefold() == str(wanted_name).casefold()
            if provider_matches and server_matches and name_matches:
                source_provider_id = remembered_id or source_provider_id
                preferred_provider_name = affinity.get('provider_name') or preferred_provider_name
                ui_seed = dict(ui_seed or {})
                if affinity.get('server_id'):
                    ui_seed['native_server_id'] = affinity['server_id']
                source_mode = 'quick_same'

    same_requested = (source_mode == 'quick_same' or
                      _quick_same_source_enabled(source_provider_id, preferred_provider_name) or
                      resolution_mode == 'same')
    known_source = continue_playback.known({'source_provider_id':source_provider_id,
                                           'provider_name':preferred_provider_name})
    if same_requested and known_source:
        played, result = playback_choices.try_saved(sys.modules[__name__], media_type, canonical_id,
            video_id, season, episode, resume_seconds=resume, resume_percent=resume_percent or '',
            provider_id=source_provider_id, server_id=(ui_seed or {}).get('native_server_id') or '')
        if played:
            return result
        played, result = playback_choices.native_origin(sys.modules[__name__], source_provider_id, ui_seed, resume)
        if played:
            return result
        common = dict(title=title or canonical_id, seed_ids=seed_ids,
                      preferred_provider_name=preferred_provider_name,
                      source_provider_id=source_provider_id, source_mode='quick_same',
                      source_server_id=(ui_seed or {}).get('native_server_id') or '',
                      resume_seconds=resume, resume_percent=resume_percent or '', ui_seed=ui_seed)
        if season not in (None, '', '0', 0) and episode not in (None, '', '0', 0):
            return _auto_play_first_episode(canonical_id, video_id or canonical_id,
                                            int(season), int(episode), **common)
        if not _is_series_media(media_type):
            return _auto_play_first_movie(canonical_id, **common)

    # Mode "tmdbh": hand off the playback entirely to TMDb Helper's
    # player chooser. Resume position is preserved on TMDb Helper side
    # via its own progress tracking when the user has linked Trakt; for
    # DexHub-tracked rows the position is best-effort only.
    if resolution_mode == 'tmdbh':
        try:
            if tmdbh_player.has_tmdbhelper():
                ids = _resolve_routing_ids(media_type=media_type,
                                            canonical_id=canonical_id,
                                            title=title or canonical_id,
                                            tmdb_id=seed_ids.get('tmdb_id') or '',
                                            imdb_id=seed_ids.get('imdb_id') or '',
                                            tvdb_id=seed_ids.get('tvdb_id') or '',
                                            season=season, episode=episode)
                tmdbh_url = _tmdbh_url_from_ids(
                    media_type='movie' if not (season and episode) else 'tv',
                    tmdb_id=ids.get('tmdb_id', ''),
                    imdb_id=ids.get('imdb_id', ''),
                    tvdb_id=ids.get('tvdb_id', ''),
                    title=title or canonical_id,
                    season=str(season or ''),
                    episode=str(episode or ''),
                )
                if tmdbh_url:
                    _launch_tmdbhelper_url(tmdbh_url)
                    return
        except Exception as _exc:
            xbmc.log('[DexHub] tmdbh-mode dispatch failed: %s' % _exc, xbmc.LOGWARNING)
        # If TMDb Helper isn't installed or the URL build failed, fall
        # through to the DexHub picker. Safer than silently doing nothing.

    # Mode "picker" (default), or fallback paths from "same"/"tmdbh".
    if season not in (None, '', '0', 0) and episode not in (None, '', '0', 0):
        if _prefer_source_picker():
            return episode_streams(canonical_id, video_id or canonical_id, int(season), int(episode), title=title or canonical_id, media_type='series', resume_seconds=resume, resume_percent=resume_percent or '', preferred_provider_name=preferred_provider_name or '', source_provider_id=source_provider_id or '', source_mode=source_mode or '', seed_ids=seed_ids, ui_seed=ui_seed)
        return _auto_play_first_episode(
            canonical_id,
            video_id or canonical_id,
            int(season),
            int(episode),
            title=title or canonical_id,
            seed_ids=seed_ids,
            preferred_provider_name=preferred_provider_name or '',
            resume_seconds=resume,
            resume_percent=resume_percent or '',
            source_provider_id=source_provider_id or '',
            source_mode=source_mode or '',
        )
    if _is_series_media(media_type):
        return series_meta('series', canonical_id, title=title or canonical_id, source_provider_id=source_provider_id or '')
    if _prefer_source_picker():
        return streams(media_type or 'movie', canonical_id, title=title or canonical_id, resume_seconds=resume, resume_percent=resume_percent or '', preferred_provider_name=preferred_provider_name or '', source_provider_id=source_provider_id or '', source_mode=source_mode or '', seed_ids=seed_ids, ui_seed=ui_seed)
    return _auto_play_first_movie(
        canonical_id,
        title=title or canonical_id,
        seed_ids=seed_ids,
        preferred_provider_name=preferred_provider_name or '',
        resume_seconds=resume,
        resume_percent=resume_percent or '',
        source_provider_id=source_provider_id or '',
        source_mode=source_mode or '',
    )


def _has_tmdbhelper():
    try:
        return xbmc.getCondVisibility('System.HasAddon(plugin.video.themoviedb.helper)')
    except Exception:
        return False


def _tmdbh_invocation_active():
    return _tmdbh_handoff_active()


def _tmdbh_url_from_ids(media_type='movie', tmdb_id='', imdb_id='', tvdb_id='', title='', season='', episode='', force_dialog=False):
    media_type = str(media_type or 'movie').strip().lower()
    params = {}
    if media_type in ('movie',):
        params = {'info': 'play', 'type': 'movie'}
    elif media_type in ('series', 'anime', 'show', 'tv') and season not in (None, '', 0, '0') and episode not in (None, '', 0, '0'):
        params = {
            'info': 'play',
            'type': 'episode',
            'season': str(season),
            'episode': str(episode),
        }
    elif media_type in ('series', 'anime', 'show', 'tv'):
        params = {'info': 'details', 'type': 'tv'}
    else:
        return ''
    # Do not force TMDb Helper to ignore its default player by default. The
    # addon explicitly tells users to set Dex Hub as the default TMDb Helper
    # player to avoid the chooser on every click; the old hard-coded
    # ignore_default=true made that impossible and caused a double chooser
    # flow (Dex Hub -> TMDb Helper) for many users. Keep an opt-in flag so we
    # can still force TMDb Helper's chooser from a dedicated path in future if
    # needed.
    if force_dialog and params.get('info') == 'play':
        params['ignore_default'] = 'true'
    if tmdb_id:
        params['tmdb_id'] = str(tmdb_id)
    elif imdb_id:
        params['imdb_id'] = str(imdb_id)
    elif tvdb_id:
        params['tvdb_id'] = str(tvdb_id)
    elif title:
        params['query'] = title
    else:
        return ''
    return 'plugin://plugin.video.themoviedb.helper/?' + urlencode(params)


def _tmdbhelper_play_url(meta, media_type, title=''):
    ids = extract_ids(meta)
    return _tmdbh_url_from_ids(
        media_type=media_type,
        tmdb_id=ids.get('tmdb_id') or '',
        imdb_id=ids.get('imdb_id') or '',
        tvdb_id=ids.get('tvdb_id') or '',
        title=title or meta.get('name') or meta.get('title') or '',
    )


# v3.9.32: dedup state for TMDb Helper launches. The handoff flag
# (_tmdbh_invocation_active) prevents most re-entry, but several call
# paths (item_open, _maybe_redirect_default_player, _content_click_path,
# choose_player) can still race when Kodi fires both a folder-style
# Container.Update on the listitem path AND an item-click action handler
# within milliseconds. The result is the TMDb Helper page opening twice
# before playback starts. This URL-level dedup is the final backstop.
_TMDBH_LAUNCH_LAST = {'at': 0.0, 'url': ''}
_TMDBH_LAUNCH_DEDUP_WINDOW = 5.0   # seconds


def _launch_tmdbhelper_url(url):
    url = str(url or '').strip()
    if not url:
        return False
    # v3.9.32: dedup. Suppress a repeat launch of the same URL within
    # the window. Returns True so the caller treats the suppressed call
    # as success (the first launch IS still in progress / showing).
    now = time.time()
    if (_TMDBH_LAUNCH_LAST.get('url') == url
        and (now - float(_TMDBH_LAUNCH_LAST.get('at') or 0)) < _TMDBH_LAUNCH_DEDUP_WINDOW):
        try:
            xbmc.log('[DexHub] _launch_tmdbhelper_url: dedup suppressed repeat launch of %s' % url,
                     xbmc.LOGINFO)
        except Exception:
            pass
        return True
    _TMDBH_LAUNCH_LAST['url'] = url
    _TMDBH_LAUNCH_LAST['at'] = now
    try:
        # Match the known-good context-menu path used elsewhere in the addon.
        xbmc.executebuiltin('Container.Update(%s)' % url)
        return True
    except Exception as exc:
        xbmc.log('[DexHub] tmdbhelper container update failed: %s' % exc, xbmc.LOGWARNING)
    try:
        xbmc.executebuiltin('ActivateWindow(Videos,%s,return)' % url)
        return True
    except Exception as exc:
        xbmc.log('[DexHub] tmdbhelper activate window failed: %s' % exc, xbmc.LOGWARNING)
    return False


def _default_click_uses_tmdbhelper():
    return (not _tmdbh_invocation_active()) and _default_click_mode() == 'tmdbhelper' and _has_tmdbhelper()


def _ui_seed_query_from_art(art=None, meta=None):
    """Small artwork seed carried from listing -> sources/playback.

    The full meta is still stored in the in-memory cache, but Kodi does not
    pass ListItem art back into a plugin URL when the user clicks an item.
    Carrying just poster/fanart/clearlogo in the URL makes the source picker
    show the same artwork the user saw in search/results, without borrowing
    stale global window art from the previous playback.
    """
    art = art or {}
    meta = meta or {}
    source_art = _source_ui_art(art)
    def _first(*values):
        for value in values:
            value = str(value or '').strip()
            if value:
                return value
        return ''
    def _source_poster(value):
        return '' if _better_posters.is_managed_url(value) else value
    out = {
        'ui_poster': _first(source_art.get('poster'), source_art.get('thumb'),
                            _source_poster(meta.get('poster')),
                            _source_poster(meta.get('thumb'))),
        'ui_fanart': _first(art.get('fanart'), art.get('background'), art.get('landscape'), meta.get('fanart'), meta.get('background'), meta.get('landscape')),
        'ui_clearlogo': _first(art.get('clearlogo'), art.get('logo'), meta.get('clearlogo'), meta.get('logo')),
    }
    studio = art.get('studio') or art.get('ui_studio') or meta.get('studio') or meta.get('studios') or ''
    if isinstance(studio, (list, tuple)):
        studio = ' / '.join(str(x).strip() for x in studio if str(x).strip())
    studio = str(studio or '').strip()
    if studio:
        out['studio'] = studio
    out = {k: v for k, v in out.items() if v}
    if not out:
        return {}
    # Rating-overlay/proxy poster URLs can be very long. For those, store the
    # tiny seed in DexHub's cache and carry only the cache key in the plugin URL
    # so Kodi does not truncate the path before playback.
    try:
        if out.get('studio') or sum(len(str(v)) for v in out.values()) > 1100:
            return {'ui_seed_key': cache_store.put('ui_seed', out, ttl_hours=6)}
    except Exception:
        pass
    return out


def _ui_seed_from_route(ui_poster='', ui_fanart='', ui_clearlogo='', ui_seed_key=''):
    seed = {}
    if ui_seed_key:
        try:
            cached = cache_store.get('ui_seed', ui_seed_key) or {}
            if isinstance(cached, dict):
                seed.update(cached)
        except Exception:
            pass
    if ui_poster:
        seed['ui_poster'] = ui_poster
    if ui_fanart:
        seed['ui_fanart'] = ui_fanart
    if ui_clearlogo:
        seed['ui_clearlogo'] = ui_clearlogo
    return seed


def _merge_ui_seed_into_meta(meta, ui_seed=None):
    merged = dict(meta or {})
    ui_seed = ui_seed or {}
    poster = ui_seed.get('ui_poster') or ui_seed.get('poster') or ''
    fanart = ui_seed.get('ui_fanart') or ui_seed.get('background') or ui_seed.get('fanart') or ''
    logo = ui_seed.get('ui_clearlogo') or ui_seed.get('clearlogo') or ui_seed.get('logo') or ''
    if poster:
        merged['poster'] = poster
        merged.setdefault('thumb', poster)
    if fanart:
        merged['fanart'] = fanart
        merged['background'] = fanart
    elif poster and not (merged.get('fanart') or merged.get('background')):
        merged['fanart'] = poster
        merged['background'] = poster
    if logo:
        merged['clearlogo'] = logo
        merged['logo'] = logo
    studio = ui_seed.get('studio') or ui_seed.get('ui_studio') or ''
    if studio and not merged.get('studio'):
        merged['studio'] = studio
    for key in ('native_server_id', 'native_item_id'):
        if ui_seed.get(key):
            merged[key] = str(ui_seed.get(key))
    return merged


def _merge_ui_seed_into_art(art, ui_seed=None):
    merged = dict(art or {})
    ui_seed = ui_seed or {}
    poster = ui_seed.get('ui_poster') or ui_seed.get('poster') or ''
    fanart = ui_seed.get('ui_fanart') or ui_seed.get('background') or ui_seed.get('fanart') or ''
    logo = ui_seed.get('ui_clearlogo') or ui_seed.get('clearlogo') or ui_seed.get('logo') or ''
    if poster:
        merged['poster'] = poster
        merged['thumb'] = poster
        merged['icon'] = poster
    if fanart:
        merged['fanart'] = fanart
        merged['background'] = fanart
        merged.setdefault('landscape', fanart)
    if logo:
        merged['clearlogo'] = logo
        merged['logo'] = logo
        merged['tvshow.clearlogo'] = logo
    return merged


def _content_click_path(media_type='movie', canonical_id='', title='', tmdb_id='', imdb_id='', tvdb_id='', season='', episode='', video_id='', source_provider_id='', source_mode='', force_dexhub=False, ui_seed=None):
    media_type = str(media_type or 'movie').strip().lower()
    _seed_source = dict(ui_seed or {})
    if not (_seed_source.get('studio') or _seed_source.get('ui_studio')):
        try:
            _mem_meta = _meta_mem_get(media_type, canonical_id, source_provider_id=source_provider_id) or {}
            _mem_studio = _mem_meta.get('studio') or _mem_meta.get('studios') or ''
            if _mem_studio:
                _seed_source['studio'] = _mem_studio
        except Exception:
            pass
    _ui_seed = _ui_seed_query_from_art(_seed_source, {}) if _seed_source else {}
    if (not force_dexhub) and (not source_mode) and not _quick_same_source_enabled(source_provider_id) and _default_click_uses_tmdbhelper():
        route_ids = _resolve_routing_ids(
            media_type=media_type,
            canonical_id=canonical_id,
            title=title or canonical_id,
            tmdb_id=tmdb_id,
            imdb_id=imdb_id,
            tvdb_id=tvdb_id,
            season=season,
            episode=episode,
            local_only=True,
        )
        helper_url = _tmdbh_url_from_ids(
            media_type=media_type,
            tmdb_id=route_ids.get('tmdb_id') or '',
            imdb_id=route_ids.get('imdb_id') or '',
            tvdb_id=route_ids.get('tvdb_id') or '',
            title=title or canonical_id,
            season=season or '',
            episode=episode or '',
        )
        if helper_url and any(route_ids.get(key) for key in ('tmdb_id', 'imdb_id', 'tvdb_id')):
            # Use the exact TMDb Helper URL directly so pressing the item follows
            # the same successful path as the context-menu entry "فتح في TMDb Helper".
            # Mark it as a folder-style navigation target; Kodi then issues a
            # normal plugin container update instead of treating it as a Dex Hub
            # playable item first.
            return helper_url, True
    if media_type in ('series', 'anime', 'show', 'tv') and season not in (None, '', 0, '0') and episode not in (None, '', 0, '0'):
        return build_url(action='play_item', media_type='series', canonical_id=canonical_id, video_id=video_id or canonical_id, season=season, episode=episode, title=title or canonical_id, tmdb_id=tmdb_id or '', imdb_id=imdb_id or '', tvdb_id=tvdb_id or '', source_provider_id=source_provider_id or '', source_mode=source_mode or '', **_ui_seed), False
    if _is_series_media(media_type):
        return build_url(action='item_open', media_type=media_type, canonical_id=canonical_id, title=title or canonical_id, tmdb_id=tmdb_id or '', imdb_id=imdb_id or '', tvdb_id=tvdb_id or '', source_provider_id=source_provider_id or '', **_ui_seed), True
    return build_url(action='play_item', media_type=media_type or 'movie', canonical_id=canonical_id, title=title or canonical_id, tmdb_id=tmdb_id or '', imdb_id=imdb_id or '', tvdb_id=tvdb_id or '', source_provider_id=source_provider_id or '', source_mode=source_mode or '', **_ui_seed), False



def _is_addon_self_art(path):
    """v3.9.108: True when the given art URL/path points to DexHub's own
    packaged fanart / icon / media bundle, not actual content artwork.

    Various upstream call sites (Continue Watching rows, Trakt list seeds,
    plugin-rooted directories) leave a stub `art` dict whose default values
    are the addon's own resources/icon.png or fanart.jpg. When the real
    content has no fanart we used to fall back through that stub and end up
    rendering the addon's own brand image as the full-screen backdrop on
    the loading + results screens. This helper lets every fallback layer
    say 'no thanks, that's our own art' and stay empty instead, which the
    XML now treats as a clean dark backdrop."""
    if not path:
        return False
    try:
        s = str(path).lower()
    except Exception:
        return False
    if 'plugin.video.dexhub' not in s:
        return False
    # Any addon-internal asset path is rejected as content art.
    if '/resources/media/' in s or '/resources/icon' in s or 'fanart.jpg' in s or 'icon.png' in s:
        return True
    return False


def _loading_art_fast(media_type, meta=None, art=None, bg='', ids=None, title=''):
    """Return artwork for the pre-results source-search screen.

    Keep this path local-only and fast: consult TMDb Helper's SQLite cache first,
    then use art already passed from the listing as fallback.  This gives the
    loading sheet the same poster/clearlogo as the final results page without
    waiting on a network call before streams are fetched.

    v3.9.108: any art slot that resolves to DexHub's own bundled fanart/icon
    is rejected — that's brand art, not content art, and it must never leak
    onto the backdrop.
    """
    meta = dict(meta or {})
    art = dict(art or {})
    ids = ids or {}

    def _clean(v):
        return '' if (_is_addon_self_art(v) or
                      _better_posters.is_managed_url(v)) else (v or '')

    carried_poster = (_clean(art.get('poster')) or _clean(art.get('thumb'))
                       or _clean(meta.get('poster')) or _clean(meta.get('thumb')) or '')
    carried_fanart = (_clean(bg) or _clean(art.get('fanart')) or _clean(art.get('background'))
                      or _clean(meta.get('fanart')) or _clean(meta.get('background')) or '')
    carried_clearlogo = (_clean(art.get('clearlogo')) or _clean(art.get('logo'))
                         or _clean(meta.get('clearlogo')) or _clean(meta.get('logo')) or '')

    bundle = {}
    try:
        tmdb_id = str(ids.get('tmdb_id') or meta.get('tmdb_id') or '').strip()
        imdb_id = str(ids.get('imdb_id') or meta.get('imdb_id') or '').strip()
        year = str(meta.get('year') or meta.get('releaseInfo') or '').strip()
        mt = 'tv' if str(media_type or meta.get('type') or '').strip().lower() in ('series','show','tv','tvshow','anime','episode') else 'movie'
        lookup_title = title or meta.get('title') or meta.get('name') or ''
        if tmdb_id or imdb_id or lookup_title:
            from .tmdbhelper import get_art_bundle_from_db
            bundle = get_art_bundle_from_db(
                tmdb_id=tmdb_id, imdb_id=imdb_id, media_type=mt,
                title=lookup_title, year=year) or {}
    except Exception:
        bundle = {}

    poster = _clean(bundle.get('poster')) or carried_poster
    fanart = (_clean(bundle.get('fanart')) or _clean(bundle.get('landscape'))
              or carried_fanart)
    clearlogo = _clean(bundle.get('clearlogo')) or carried_clearlogo

    # v3.9.108: deliberately do NOT promote poster → fanart any more. A
    # squished poster stretched to 1920×1080 was the most obvious "wrong
    # backdrop" — better to show a clean dark backdrop than a distorted
    # poster blown up to fullscreen.
    return {'poster': poster or '', 'fanart': fanart or '',
            'background': fanart or '', 'clearlogo': clearlogo or '',
            'logo': clearlogo or ''}


def _source_ui_art(art, fallback_art=None):
    """Restore native/cached poster art for provider search screens only."""
    out = dict(art or {})
    fallback = dict(fallback_art or {})
    original = str(out.get('dexhub.betterposters.original') or '').strip()
    if _better_posters.is_managed_url(original):
        original = ''
    if not original and _better_posters.is_managed_url(out.get('poster')):
        for key in ('thumb', 'icon'):
            candidate = str(out.get(key) or '').strip()
            if candidate and not _better_posters.is_managed_url(candidate):
                original = candidate
                break
        if not original:
            candidate = str(fallback.get('poster') or fallback.get('thumb') or '').strip()
            if candidate and not _better_posters.is_managed_url(candidate):
                original = candidate
    if original:
        out['poster'] = original
        out['tvshow.poster'] = original
        out['season.poster'] = original
    elif _better_posters.is_managed_url(out.get('poster')):
        # Do not start an uncached image request alongside the first provider
        # requests. A blank poster is preferable to delaying real results.
        out['poster'] = ''
        out['tvshow.poster'] = ''
        out['season.poster'] = ''
    return out

def _source_window_meta_fallback(meta):
    """Final source-window art cleanup without borrowing stale global art.

    Older builds filled missing poster/logo from Window(10000) / ListItem.*.
    Those labels can still point to the last played item, so when the current
    item lacks artwork the sources page showed the previous poster/clearlogo.
    Prefer no logo/default poster over wrong stale artwork.
    """
    meta = dict(meta or {})

    def _first(*values):
        for value in values:
            if value not in (None, ''):
                return value
        return ''

    poster = _first(meta.get('poster'), meta.get('thumb'))
    fanart = _first(meta.get('fanart'), meta.get('background'), poster)
    clearlogo = _first(meta.get('clearlogo'), meta.get('logo'))
    title = _first(meta.get('title'), meta.get('name'))
    plot = _first(meta.get('plot'), meta.get('description'))
    genre = _first(meta.get('genre'))
    year = _first(meta.get('year'))
    rating = _first(meta.get('rating'))

    if poster:
        meta['poster'] = poster
    if fanart:
        meta['fanart'] = fanart
        meta['background'] = fanart
    meta['clearlogo'] = clearlogo or ''
    meta['logo'] = clearlogo or ''
    if title:
        meta['title'] = title
    if plot:
        meta['plot'] = plot
    if genre:
        meta['genre'] = genre
    if year:
        meta['year'] = year
    if rating:
        meta['rating'] = rating
    return meta

def _prioritize_provider_targets(targets, preferred_provider_name=''):
    preferred = str(preferred_provider_name or '').strip().lower()
    if not preferred or not targets:
        return list(targets or [])
    head = []
    tail = []
    for provider, request_id in list(targets or []):
        pid = str((provider or {}).get('id') or '').strip().lower()
        pname = str((provider or {}).get('name') or '').strip().lower()
        if preferred in (pid, pname):
            head.append((provider, request_id))
        else:
            tail.append((provider, request_id))
    return head + tail



def _source_mode_only_enabled(source_mode=''):
    mode = str(source_mode or '').strip().lower()
    return mode in ('only', 'same', 'same_source', 'same-source', 'source_only', 'source-only', 'نفس', 'نفس السورس')


def _split_targets_by_source_mode(targets, source_provider_id='', source_mode=''):
    targets = list(targets or [])
    if not targets or not _source_mode_only_enabled(source_mode) or not source_provider_id:
        return targets, []
    sid = str(source_provider_id or '').strip()
    primary = [(p, rid) for (p, rid) in targets if str((p or {}).get('id') or '').strip() == sid]
    fallback = [(p, rid) for (p, rid) in targets if str((p or {}).get('id') or '').strip() != sid]
    # Same-source means SAME source only. Do not auto-fallback to other
    # providers here; users explicitly asked DexHub not to switch sources
    # behind their back. The caller can still choose DexHub picker manually.
    return primary, []



def _dex_player_url(media_type='movie', canonical_id='', title='', season='', episode='', video_id='', source_provider_id='', source_mode=''):
    media_type = str(media_type or 'movie').strip().lower()
    if media_type in ('series', 'anime', 'show', 'tv') and season not in (None, '', 0, '0') and episode not in (None, '', 0, '0'):
        return build_url(
            action='episode_streams',
            canonical_id=canonical_id,
            video_id=video_id or canonical_id,
            season=str(season),
            episode=str(episode),
            title=title or canonical_id,
            media_type='series',
            source_provider_id=source_provider_id or '',
            source_mode=source_mode or '',
        )
    return build_url(
        action='series_meta' if media_type in ('series', 'anime', 'show', 'tv') else 'streams',
        media_type='series' if media_type in ('series', 'anime', 'show', 'tv') else 'movie',
        canonical_id=canonical_id,
        title=title or canonical_id,
        source_provider_id=source_provider_id or '',
        source_mode=source_mode or '',
    )


def _build_player_chooser_menu(media_type='movie', canonical_id='', title='', tmdb_id='', imdb_id='', tvdb_id='', season='', episode='', video_id='', source_provider_id=''):
    chooser_url = build_url(
        action='choose_player',
        media_type=media_type,
        canonical_id=canonical_id,
        title=title or canonical_id,
        tmdb_id=tmdb_id or '',
        imdb_id=imdb_id or '',
        tvdb_id=tvdb_id or '',
        season='' if season is None else season,
        episode='' if episode is None else episode,
        video_id=video_id or '',
        source_provider_id=source_provider_id or '',
    )
    return [('التشغيل باستخدام…', 'RunPlugin(%s)' % chooser_url)]


def choose_player(media_type='movie', canonical_id='', title='', tmdb_id='', imdb_id='', tvdb_id='', season='', episode='', video_id='', source_provider_id=''):
    from .play_with import run
    return run(dict(media_type=media_type, canonical_id=canonical_id, title=title,
                    tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id,
                    season=season, episode=episode, video_id=video_id,
                    source_provider_id=source_provider_id))


def _maybe_redirect_player(meta, media_type, title=''):
    if _tmdbh_invocation_active():
        return False
    mode = _default_click_mode()
    if mode == 'dexhub':
        return False
    if mode == 'ask':
        options = ['Dex Hub']
        if _has_tmdbhelper():
            options.append('TMDb Helper')
        choice = xbmcgui.Dialog().select(tr('اختر المشغل'), [tr(x) for x in options])
        if choice < 0:
            return True  # Cancel consumes the request; never start playback.
        if choice == 0:
            return False
        mode = 'tmdbhelper'
    if mode == 'tmdbhelper' and _has_tmdbhelper():
        url = _tmdbhelper_play_url(meta, media_type, title=title)
        if url:
            return _launch_tmdbhelper_url(url)
    return False


def item_open(media_type, canonical_id, title='', tmdb_id='', imdb_id='', tvdb_id='', source_provider_id=''):
    media_type = (media_type or 'movie').strip().lower()
    # Preserve identity supplied by catalog routes (notably Nuvio).  Previous
    # builds accepted these IDs in item_open then dropped them before source
    # discovery, so Plex/Emby/Silo saw an opaque Nuvio catalog id while TMDb
    # entries worked. Seed the resident meta cache once so movie + series +
    # episode paths all inherit one canonical identity contract.
    _route_seed = {'id': canonical_id, 'type': media_type,
                   'name': title or canonical_id, 'title': title or canonical_id}
    _route_seed = _meta_with_seed_ids(_route_seed, {
        'tmdb_id': tmdb_id, 'imdb_id': imdb_id, 'tvdb_id': tvdb_id,
    })
    try:
        if tmdb_id or imdb_id or tvdb_id:
            _meta_mem_put(media_type, canonical_id, _route_seed,
                          source_provider_id=source_provider_id)
    except Exception:
        pass
    if _tmdbh_invocation_active() and not _is_series_media(media_type):
        return play_item(media_type=media_type, canonical_id=canonical_id, title=title or canonical_id, tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id, source_provider_id=source_provider_id or '')
    # Direct playback for movie-like rows. Respect TMDb Helper click-mode if
    # the user explicitly chose it, otherwise go straight to playback.
    if not _is_series_media(media_type):
        mode = _default_click_mode()
        if mode != 'dexhub':
            route_ids = _resolve_routing_ids(media_type=media_type, canonical_id=canonical_id, title=title or canonical_id, tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id)
            if mode == 'tmdbhelper' and _has_tmdbhelper() and (route_ids.get('tmdb_id') or route_ids.get('imdb_id') or route_ids.get('tvdb_id')):
                helper_url = _tmdbh_url_from_ids(media_type=media_type, tmdb_id=route_ids.get('tmdb_id') or '', imdb_id=route_ids.get('imdb_id') or '', tvdb_id=route_ids.get('tvdb_id') or '', title=title or canonical_id)
                if helper_url and _launch_tmdbhelper_url(helper_url):
                    return
            providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
            try:
                meta = _best_meta_for_item(media_type, canonical_id, providers, source_provider_id=source_provider_id)
            except Exception as exc:
                xbmc.log('[DexHub] item_open movie meta probe failed for %s: %s' % (canonical_id, exc), xbmc.LOGWARNING)
                meta = {'id': canonical_id, 'type': media_type, 'name': title or canonical_id}
            try:
                if _maybe_redirect_player(meta, media_type, title=title):
                    return
            except Exception as exc:
                xbmc.log('[DexHub] movie player redirect failed for %s: %s' % (canonical_id, exc), xbmc.LOGWARNING)
        _monitor_playback('item-open-movie', media_type=media_type, canonical_id=canonical_id, title=title or canonical_id)
        return play_item(media_type=media_type, canonical_id=canonical_id,
                         title=title or canonical_id, tmdb_id=tmdb_id,
                         imdb_id=imdb_id, tvdb_id=tvdb_id,
                         source_provider_id=source_provider_id or '')

    # Series rows still open the seasons screen unless the user explicitly
    # redirects them to TMDb Helper via the click-mode setting.
    if _default_click_mode() == 'dexhub':
        resolved_title = title or canonical_id
        return series_meta(media_type, canonical_id, title=resolved_title, source_provider_id=source_provider_id or '')

    if _default_click_mode() == 'tmdbhelper' and _has_tmdbhelper():
        route_ids = _resolve_routing_ids(media_type=media_type, canonical_id=canonical_id, title=title or canonical_id, tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id)
        if route_ids.get('tmdb_id') or route_ids.get('imdb_id') or route_ids.get('tvdb_id'):
            helper_url = _tmdbh_url_from_ids(media_type=media_type, tmdb_id=route_ids.get('tmdb_id') or '', imdb_id=route_ids.get('imdb_id') or '', tvdb_id=route_ids.get('tvdb_id') or '', title=title or canonical_id)
            if helper_url and _launch_tmdbhelper_url(helper_url):
                return
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    try:
        meta = _best_meta_for_item(media_type, canonical_id, providers, source_provider_id=source_provider_id)
    except Exception as exc:
        xbmc.log('[DexHub] item_open meta probe failed for %s: %s' % (canonical_id, exc), xbmc.LOGWARNING)
        meta = {'id': canonical_id, 'type': media_type, 'name': title or canonical_id}
    try:
        if _maybe_redirect_player(meta, media_type, title=title):
            return
    except Exception as exc:
        xbmc.log('[DexHub] player redirect failed for %s: %s' % (canonical_id, exc), xbmc.LOGWARNING)
    resolved_title = title or (meta or {}).get('name') or canonical_id
    try:
        return series_meta(media_type, canonical_id, title=resolved_title, source_provider_id=source_provider_id or '')
    except Exception as exc:
        xbmc.log('[DexHub] series_meta failed for %s: %s' % (canonical_id, exc), xbmc.LOGWARNING)
        return series_meta('series', canonical_id, title=resolved_title)



def _best_meta_for_item(media_type, canonical_id, providers, source_provider_id=''):
    cached = _meta_mem_get(media_type, canonical_id, source_provider_id=source_provider_id)
    if cached:
        return cached
    providers = _meta_provider_first(providers, source_provider_id=source_provider_id)
    if not providers:
        fallback = {'id': canonical_id, 'type': media_type, 'name': canonical_id}
        _meta_mem_put(media_type, canonical_id, fallback, source_provider_id=source_provider_id)
        return fallback

    def _apply_provider_source(provider, meta):
        try:
            if _is_virtual_meta_target(source_provider_id):
                return _meta_source.override_virtual_meta(source_provider_id, media_type, meta) or meta
            return _meta_source.override_meta(provider, media_type, meta) or meta
        except Exception as exc:
            xbmc.log('[DexHub] meta source override failed for %s: %s' % ((provider or {}).get('name') or (provider or {}).get('id') or source_provider_id or '', exc), xbmc.LOGDEBUG)
            return meta

    def _probe(provider):
        data = fetch_meta(provider, media_type, canonical_id, timeout_override=fast_timeout('meta'))
        meta = data.get('meta') or data.get('metas')
        if isinstance(meta, list):
            meta = meta[0] if meta else None
        if not meta:
            return None
        return _apply_provider_source(provider, meta)

    def _score(meta):
        """Rough richness score — prefers metas with poster/fanart/description/year."""
        if not isinstance(meta, dict):
            return -1
        score = 0
        for key in ('poster', 'background', 'fanart', 'logo', 'clearlogo'):
            if meta.get(key):
                score += 2
        for key in ('description', 'overview', 'plot'):
            val = meta.get(key)
            if val and len(str(val)) > 60:
                score += 2
        if meta.get('releaseInfo') or meta.get('year'):
            score += 1
        if meta.get('videos'):
            score += 3  # series with episode list is most useful
        if meta.get('genres'):
            score += 1
        if meta.get('imdbRating') or meta.get('rating'):
            score += 1
        if _meta_art_is_strict(meta):
            score += 50  # explicit picker must win over any other provider
        return score

    # If the item came from a specific catalog/provider, that provider's
    # configured metadata source is authoritative. Do not let a richer unrelated
    # provider win the score race and undo the user's selected source.
    if source_provider_id and not _is_virtual_meta_target(source_provider_id):
        first = providers[0] if providers else None
        if first and str(first.get('id') or '') == str(source_provider_id):
            try:
                meta = _probe(first)
                if meta:
                    _meta_mem_put(media_type, canonical_id, meta, source_provider_id=source_provider_id)
                    return meta
                if _provider_uses_explicit_meta_art(first):
                    seed = {'id': canonical_id, 'type': media_type, 'name': canonical_id, 'title': canonical_id}
                    meta = _meta_source.override_meta(first, media_type, seed) or seed
                    _meta_mem_put(media_type, canonical_id, meta, source_provider_id=source_provider_id)
                    return meta
            except Exception as exc:
                xbmc.log('[DexHub] source-context meta probe failed for %s: %s' % (canonical_id, exc), xbmc.LOGDEBUG)

    best = None
    best_score = -1
    for _prov, result in run_parallel(_probe, list(providers)):
        if isinstance(result, Exception) or not result:
            continue
        sc = _score(result)
        if sc > best_score:
            best = result
            best_score = sc
    if best is not None:
        _meta_mem_put(media_type, canonical_id, best, source_provider_id=source_provider_id)
        return best
    fallback = {'id': canonical_id, 'type': media_type, 'name': canonical_id}
    _meta_mem_put(media_type, canonical_id, fallback, source_provider_id=source_provider_id)
    return fallback

def _fast_meta_for_sources(media_type, canonical_id, providers, title='', source_provider_id='', seed_ids=None):
    cached = _meta_mem_get(media_type, canonical_id, source_provider_id=source_provider_id)
    # A listing already knows the selected identity. Do not synchronously
    # fetch its metadata again just to start the same source search.
    if not cached and seed_ids and any(seed_ids.get(k) for k in ('imdb_id', 'tmdb_id', 'tvdb_id')) and title and not _cw_looks_like_code(title):
        return _meta_with_seed_ids({'id': canonical_id, 'type': media_type,
                                   'name': title, 'title': title}, seed_ids), False
    # Cache-first: consult existing Helper/TMDb data before scheduling provider meta.
    # Exact server identities keep their own metadata path and scoped cache.
    if not cached and not source_provider_id:
        try:
            ids = _merge_seed_ids(extract_ids({'id': canonical_id}), _get_tmdbh_seed_ids(canonical_id))
            kwargs = dict(tmdb_id=ids.get('tmdb_id') or '',
                          imdb_id=ids.get('imdb_id') or '', media_type=media_type)
            if kwargs['tmdb_id'] or kwargs['imdb_id']:
                local = dict(_tmdb_art_db.get_meta_bundle_from_db(**kwargs) or {})
                for key, value in (_tmdb_direct.meta_for_cached_only(**kwargs) or {}).items():
                    if value and not local.get(key):
                        local[key] = value
                if local.get('name') or local.get('title'):
                    local.update({'id': canonical_id, 'type': media_type})
                    cached = _meta_with_seed_ids(local, ids)
                    _meta_mem_put(media_type, canonical_id, cached)
        except Exception:
            pass  # Cache unavailability must not block normal source discovery.
    if str(source_provider_id or '').startswith('virtual.continue'):
        recovered = dict(cached or {})
        ids = extract_ids(dict(recovered, id=canonical_id))
        kwargs = dict(tmdb_id=ids.get('tmdb_id') or '',
                      imdb_id=ids.get('imdb_id') or '', media_type=media_type)
        try:
            bundle = _tmdb_art_db.get_meta_bundle_from_db(**kwargs) or {}
            for key, value in bundle.items():
                if value and (not recovered.get(key) or key in ('name', 'title')):
                    recovered[key] = value
            direct = _tmdb_direct.meta_for_cached_only(**kwargs) or {}
            for key, value in direct.items():
                if value and not recovered.get(key):
                    recovered[key] = value
            name = recovered.get('name') or recovered.get('title') or ''
            # v5.10.79: only look up what can be looked up. A Plex/Emby row
            # whose canonical id is plex:<server>:<key> yields no tmdb/imdb id,
            # and this lookup passes no title either, so TMDb had nothing to
            # resolve and the race simply waited out its 3s timeout. kodi.log
            # (5.10.77, Continue Watching -> Plex movie) measured it at 2.6s of
            # a 4.2s source preparation. The real imdb id is found moments
            # later from the Plex guids by the native target step, so skipping
            # here loses nothing; the fallback meta still carries the title.
            if (not name or _cw_looks_like_code(name)) and (kwargs['tmdb_id'] or kwargs['imdb_id']):
                # One bounded lookup on selection, never on focus. A late
                # response still warms TMDb's cache for the next opening.
                race = start_parallel_race(lambda _: _tmdb_direct.meta_for(**kwargs),
                                           [None], workers=1, timeout=3.0, lane='identity')
                try:
                    for _, result in race.iter_completed():
                        if isinstance(result, dict):
                            recovered.update({k: v for k, v in result.items() if v})
                finally:
                    race.cancel()
            recovered['id'] = canonical_id
            recovered['type'] = media_type
            if recovered.get('name') or recovered.get('title'):
                _meta_mem_put(media_type, canonical_id, recovered, source_provider_id=source_provider_id)
                cached = recovered
        except Exception as exc:
            xbmc.log('[DexHub] continue metadata recovery: %s' % type(exc).__name__, xbmc.LOGDEBUG)
    if cached:
        return cached, True
    if _source_context_requires_exact_meta(source_provider_id):
        # v5.10.80: ask the metadata source with an id it can resolve. A
        # plex:/silo:/emby: id is unknown to every Stremio or TMDb source, so
        # it is translated first, and skipped when no external id is known.
        from .native_ids import external_canonical as _external_canonical
        _lookup_id = _external_canonical(canonical_id, seed_ids)
        try:
            exact = (_best_meta_for_item(media_type, _lookup_id, providers, source_provider_id=source_provider_id)
                     if _lookup_id else None)
            if exact:
                if _lookup_id != canonical_id:
                    # Native routing downstream is keyed by the server id.
                    exact = dict(exact)
                    exact['id'] = canonical_id
                return exact, True
        except Exception as exc:
            xbmc.log('[DexHub] exact meta fetch failed for %s/%s: %s' % (media_type, canonical_id, exc), xbmc.LOGDEBUG)
    label = title or canonical_id
    fallback = {
        'id': canonical_id,
        'type': 'series' if media_type in ('series', 'anime', 'show', 'tv') else 'movie',
        'name': label,
        'title': label,
    }
    return fallback, False


def _prime_best_meta_async(media_type, canonical_id, providers, source_provider_id=''):
    if _meta_mem_get(media_type, canonical_id, source_provider_id=source_provider_id) or not providers:
        return

    def _worker():
        try:
            _best_meta_for_item(media_type, canonical_id, providers, source_provider_id=source_provider_id)
        except Exception:
            pass

    _submit_optional(
        _worker,
        key='meta:%s:%s:%s' % (media_type, canonical_id, source_provider_id),
    )









def _format_size_value(value):
    try:
        if isinstance(value, (int, float)):
            size = float(value)
            if size <= 0:
                return ''
            if size >= 1024 ** 3:
                return '%.2f GB' % (size / float(1024 ** 3))
            if size >= 1024 ** 2:
                return '%.2f MB' % (size / float(1024 ** 2))
            return '%.0f B' % size
    except Exception:
        pass
    return ''


def _extract_size(*values):
    for value in values:
        if isinstance(value, (int, float)):
            formatted = _format_size_value(value)
            if formatted:
                return formatted
        # Parse the raw value before generic filename cleanup: BRACKET_RE turns
        # punctuation (including the decimal dot) into spaces, so "42.5 GB"
        # previously became the incorrect "5 GB".
        raw = html.unescape(str(value or '')).replace(',', '.')
        m = SIZE_RE.search(raw) or SIZE_RE.search(_clean_stream_text(value))
        if m:
            return m.group(1).upper().replace('GIB', 'GB').replace('MIB', 'MB')
    return ''












_GENERIC_SOURCE_NAMES = {
    'direct', 'direct play', 'transcode', 'external', 'torrent', 'stream',
    'usenet', 'nzb', 'nntp', 'newznab', 'http', 'https', 'web', 'download',
    'cached', 'uncached', 'cached torrent', 'uncached torrent', 'unknown',
}
_DEBRID_IDENTITY_NAMES = {
    'rd', 'rd+', 'realdebrid', 'ad', 'ad+', 'alldebrid', 'pm', 'premiumize',
    'tb', 'tb+', 'torbox', 'ed', 'ed+', 'easydebrid',
}
_ADDON_MARKER_RE = re.compile(
    r'(?im)\b(?:source|addon)\s*[:=\-]?\s*'
    r'([a-z0-9][a-z0-9 ._+\-]{1,40}?)(?=\s*(?:[|\u2022\u00b7\n]|$))'
)
_ADDON_PREFIX_RE = re.compile(
    r'(?im)^\s*\[[^\]\n]{1,16}\]\s*'
    r'([a-z0-9][a-z0-9 ._+\-]{1,40}?)(?=\s*(?:[|\u2022\u00b7\n]|$))'
)


def _extract_addon_name(row, provider_name, texts=None):
    hints = row.get('behaviorHints') or {}
    # Structured identity is both more accurate and cheaper than parsing the
    # rendered formatter text. Only run the two marker regexes when the addon
    # did not provide a real identity field.
    structured = [
        row.get('addon'), row.get('addonName'), row.get('sourceAddon'), row.get('source_addon'),
        hints.get('addon') if isinstance(hints, dict) else '', hints.get('addonName') if isinstance(hints, dict) else '',
    ]

    def _usable(value):
        text = _normalize_ascii(value)
        if not text:
            return ''
        lowered = text.lower()
        if lowered in _GENERIC_SOURCE_NAMES or lowered in _DEBRID_IDENTITY_NAMES:
            return ''
        text = MULTI_WS_RE.sub(' ', text.replace('|', ' ').replace('/', ' ')).strip(' -_.')
        return text.upper() if text else ''

    for value in structured:
        clean = _usable(value)
        if clean:
            return clean

    formatted_candidates = []
    for raw in (row.get('description'), row.get('name')):
        text = str(raw or '')[:1536]
        if text:
            formatted_candidates.extend(_ADDON_MARKER_RE.findall(text))
            formatted_candidates.extend(_ADDON_PREFIX_RE.findall(text))
    for value in formatted_candidates:
        clean = _usable(value)
        if clean:
            return clean

    for value in (
            provider_name, row.get('provider'),
            hints.get('provider') if isinstance(hints, dict) else '',
            row.get('source'), hints.get('source') if isinstance(hints, dict) else ''):
        clean = _usable(value)
        if clean:
            return clean
    return (provider_name or 'ADDON').upper()


_INDEXER_PATTERNS = (
    (r'\bnzb\s*geek\b', 'NZBGEEK'),
    (r'\bdrunken\s*slug\b', 'DRUNKENSLUG'),
    (r'\bnzb\s*finder\b', 'NZBFINDER'),
    (r'\balt\s*hub\b', 'ALTHUB'),
    (r'\bdog\s*nzb\b', 'DOGNZB'),
    (r'\bomgwtf(?:nzbs?)?\b', 'OMGWTFNZBS'),
    (r'\bab\s*nzb\b', 'ABNZB'),
    (r'\btabula\s*rasa\b', 'TABULA RASA'),
    (r'\bnzb\s*\.\s*su\b', 'NZB.SU'),
    (r'\bnzbforyou\b', 'NZBFORYOU'),
    (r'\bnewznab\b', 'NEWZNAB'),
)


def _identity_candidates(row, *keys):
    hints = row.get('behaviorHints') or {}
    for key in keys:
        for value in _iter_stream_values(row.get(key)):
            yield value
        if isinstance(hints, dict):
            for value in _iter_stream_values(hints.get(key)):
                yield value


def _extract_indexer_name(row, provider_name='', texts=None, addon_name=''):
    addon_name = addon_name or _extract_addon_name(row, provider_name, texts=texts)
    candidates = list(_identity_candidates(
        row, 'indexer', 'indexerName', 'sourceIndexer', 'tracker',
        'sourceSite', 'site', 'host'))
    candidates.extend(texts if texts is not None else _collect_stream_texts(row))
    blob = ' '.join(_normalize_ascii(v) for v in candidates if v)
    for pattern, label in _INDEXER_PATTERNS:
        if re.search(pattern, blob, re.I):
            return label
    # Structured indexer fields may contain a custom Newznab name/domain.
    for value in _identity_candidates(row, 'indexer', 'indexerName', 'sourceIndexer'):
        text = MULTI_WS_RE.sub(' ', _normalize_ascii(value).replace('|', ' ')).strip(' -_.')
        lowered = text.lower()
        if text and lowered not in ('usenet', 'nzb', 'nntp', 'newznab', 'unknown'):
            if text.upper() not in (addon_name, str(provider_name or '').upper()):
                return text.upper()
    return ''


_SERVICE_PATTERNS = (
    (r'\breal[ -]?debrid\b|\brd\+?\b', 'REAL-DEBRID'),
    (r'\ball[ -]?debrid\b|\bad\+?\b', 'ALLDEBRID'),
    (r'\bpremiumize\b|\bpm\+?\b', 'PREMIUMIZE'),
    (r'\btorbox\b|\btb\+?\b', 'TORBOX'),
    (r'\beasy[ -]?debrid\b|\bed\+?\b', 'EASYDEBRID'),
    (r'\beasynews\b', 'EASYNEWS'),
)
_SERVICE_BADGES = {
    'RD': 'RD+', 'REAL-DEBRID': 'RD+', 'REALDEBRID': 'RD+',
    'AD': 'AD+', 'ALLDEBRID': 'AD+', 'ALL-DEBRID': 'AD+',
    'PM': 'PM', 'PREMIUMIZE': 'PM',
    'TB': 'TB', 'TORBOX': 'TB',
    'ED': 'ED+', 'EASYDEBRID': 'ED+', 'EASY-DEBRID': 'ED+',
}


def _extract_service_name(row, texts=None):
    values = list(_identity_candidates(row, 'service', 'serviceName', 'debridService'))
    for value in values:
        text = _normalize_ascii(value)
        for pattern, label in _SERVICE_PATTERNS:
            if re.search(pattern, text, re.I):
                return label
        cleaned = MULTI_WS_RE.sub(' ', text.replace('|', ' ')).strip(' -_.')
        if cleaned and cleaned.lower() not in ('usenet', 'nzb', 'nntp', 'none', 'unknown'):
            return cleaned.upper()
    # AIOStreams formatter output often contains "SERVICE TorBox" only in
    # name/description. Reuse the already-collected text instead of rescanning.
    blob = ' '.join(texts if texts is not None else _collect_stream_texts(row))[:8192]
    for pattern, label in _SERVICE_PATTERNS:
        if re.search(pattern, blob, re.I):
            return label
    return ''


def _source_origin_line(row, provider_name, addon_name='', indexer_name='',
                        service_name='', provider_domain='', addon_domain=''):
    provider_label = MULTI_WS_RE.sub(' ', str(provider_name or 'Provider')).strip()
    addon_name = addon_name or _extract_addon_name(row, provider_name)
    indexer_name = indexer_name or _extract_indexer_name(
        row, provider_name, addon_name=addon_name)
    service_name = service_name or _extract_service_name(row)
    parts = []
    seen = set()
    for value in (provider_label, provider_domain, addon_name, addon_domain,
                  service_name, indexer_name):
        # v4.3.0: split composite candidates ('Emby • Emby') into tokens and
        # collapse repeated words inside each token ('EMBY EMBY' → 'EMBY') —
        # native servers named after their own product used to triple up.
        for token in re.split(r'[•·|]', str(value or '')):
            words, prev = [], ''
            for word in token.split():
                if word.lower() != prev:
                    words.append(word)
                prev = word.lower()
            token = ' '.join(words).strip()
            key = token.lower()
            if token and key not in seen:
                seen.add(key)
                parts.append(token)
    return '  •  '.join(parts)


def _source_identity_line(source_type, provider_name, addon_name='',
                          indexer_name='', service_name=''):
    """Short, scan-friendly identity with the useful facts first.

    The old origin line started with provider/domain details, pushing the
    indexer beyond the visible part of the row. Keep routing data untouched,
    but present transport -> indexer -> service -> addon so USENET and DEBRID
    are immediately distinguishable on a TV screen.
    """
    try:
        type_label = str((source_type or ('', '', ''))[1] or '').strip()
    except Exception:
        type_label = ''
    parts, seen = [], set()
    for value in (type_label, indexer_name, service_name, addon_name,
                  provider_name):
        value = MULTI_WS_RE.sub(' ', str(value or '')).strip(' •|')
        key = value.casefold()
        if value and key not in seen:
            seen.add(key)
            parts.append(value)
    return '  •  '.join(parts)


def _site_from_url(row):
    for key in ('url', 'externalUrl'):
        value = row.get(key)
        if not value:
            continue
        try:
            host = urlparse(str(value)).netloc.lower()
        except Exception:
            host = ''
        if host:
            host = host.split('@')[-1]
            if host.startswith('www.'):
                host = host[4:]
            return host.upper()
    return ''


def _extract_site(row, provider_name, addon_name=''):
    addon_name = addon_name or _extract_addon_name(row, provider_name)
    url_site = _site_from_url(row)
    candidates = [
        row.get('site'), row.get('host'), row.get('tracker'), row.get('sourceSite'),
        (row.get('behaviorHints') or {}).get('site') if isinstance(row.get('behaviorHints'), dict) else '',
    ]
    for value in candidates:
        text = _normalize_ascii(value)
        if not text:
            continue
        lowered = text.lower()
        if 'direct play' in lowered or 'transcode' in lowered:
            continue
        text = text.replace('|', ' ').replace('/', ' ')
        text = MULTI_WS_RE.sub(' ', text).strip(' -_.')
        if text and text.upper() != addon_name:
            return text.upper()
    if url_site and url_site.upper() != addon_name:
        return url_site.upper()
    return addon_name






def _stream_display_name(row):
    candidates = [
        row.get('folderName'), row.get('filename'), row.get('fileName'),
        (row.get('behaviorHints') or {}).get('filename') if isinstance(row.get('behaviorHints'), dict) else '',
        row.get('releaseTitle'), row.get('release'), row.get('title'), row.get('name'), row.get('description')
    ]
    for value in candidates:
        if value:
            text = _filename_basename(value)
            if text:
                return text.upper()
    return 'STREAM'


# Language hints we look for inside sub filenames / release names. Order
# matters — more specific tokens first so 'arabic' beats 'ara' beats 'ar'.
_FILENAME_LANG_HINTS = [
    ('arabic',     'ar'), ('عربي',     'ar'), ('عربية',    'ar'), ('ara',  'ar'), ('.ar.', 'ar'), ('-ar-', 'ar'), ('_ar_', 'ar'),
    ('english',    'en'), ('eng',      'en'), ('.en.', 'en'), ('-en-', 'en'), ('_en_', 'en'),
    ('french',     'fr'), ('français', 'fr'), ('francais', 'fr'), ('fre',  'fr'), ('fra',  'fr'), ('.fr.', 'fr'),
    ('spanish',    'es'), ('español',  'es'), ('espanol',  'es'), ('spa',  'es'), ('.es.', 'es'),
    ('german',     'de'), ('deutsch',  'de'), ('ger',  'de'), ('deu',  'de'), ('.de.', 'de'),
    ('italian',    'it'), ('italiano', 'it'), ('ita',  'it'), ('.it.', 'it'),
    ('portuguese', 'pt'), ('portugues','pt'), ('por',  'pt'), ('.pt.', 'pt'),
    ('brazilian',  'pt-br'), ('portuguese-br','pt-br'), ('pob','pt-br'), ('pt-br','pt-br'), ('.pb.', 'pt-br'),
    ('turkish',    'tr'), ('turkce',   'tr'), ('türkçe',   'tr'), ('tur',  'tr'), ('.tr.', 'tr'),
    ('russian',    'ru'), ('russky',   'ru'), ('rus',  'ru'), ('.ru.', 'ru'),
    ('japanese',   'ja'), ('jpn',  'ja'), ('.ja.', 'ja'), ('.jp.', 'ja'),
    ('korean',     'ko'), ('kor',  'ko'), ('.ko.', 'ko'), ('.kr.', 'ko'),
    ('chinese',    'zh'), ('chi',  'zh'), ('zho',  'zh'), ('.zh.', 'zh'), ('.cn.', 'zh'),
    ('hindi',      'hi'), ('hin',  'hi'), ('.hi.', 'hi'),
    ('persian',    'fa'), ('farsi','fa'), ('fas',  'fa'), ('per',  'fa'), ('.fa.', 'fa'),
]


def _stream_badges(video_bits, audio_bits, subtitles):
    wanted = ['2160P', '1080P', '720P', 'DV', 'HDR10+', 'HDR10', 'HDR', 'HEVC', 'AV1', 'ATMOS', 'TRUEHD', 'DTS-HD', 'DTS-X', 'DD+', 'DD', '5.1', '7.1', 'MULTI', 'DUBBED', 'SUBS']
    available = [str(x).upper() for x in (video_bits or []) + (audio_bits or [])]
    tags = []
    for key in wanted:
        if key in available and key not in tags:
            tags.append(key)
    if subtitles and 'SUBS' not in tags:
        tags.append('SUBS')
    return ' • '.join(tags[:8])








def _tags_from_fact_lists(video_bits, audio_bits, row=None):
    """Build the UI tag contract from already parsed values; no regex pass."""
    video = [str(x or '').upper() for x in (video_bits or [])]
    audio = [str(x or '').upper() for x in (audio_bits or [])]
    tags = {}
    source = []
    for marker in ('REMUX', 'BLURAY', 'WEB-DL', 'WEBDL', 'WEBRIP', 'HDTV', 'DVD', 'CAM'):
        if any(marker in value for value in video):
            source.append(marker)
    encode = [x for x in video if x in ('HEVC', 'H264', 'H.264', 'AVC', 'AV1', 'XVID')]
    visual = [x for x in video if x in ('DV', 'HDR10+', 'HDR10', 'HDR', 'HLG', 'IMAX', '10BIT', '3D')]
    audio_codec = [x for x in audio if x in ('ATMOS', 'TRUEHD', 'DTS-X', 'DTS-HD MA', 'DTS-HD', 'DTS', 'DD+', 'DD', 'AC3', 'FLAC', 'AAC', 'OPUS')]
    channels = [x for x in audio if x in ('7.1', '5.1', '2.0', '8CH')]
    if source:
        tags['source'] = source[:1]
    if encode:
        tags['encode'] = encode[:1]
    if visual:
        tags['visual'] = visual[:3]
    if audio_codec:
        tags['audio'] = audio_codec[:2]
    if channels:
        tags['channels'] = channels[:1]

    langs = []
    for value in _iter_stream_values((row or {}).get('languages')):
        clean = MULTI_WS_RE.sub(' ', str(value or '')).strip()
        if clean and clean not in langs:
            langs.append(clean)
    for token, label in (('ARABIC', 'عربي'), ('ENGLISH', 'EN'),
                         ('RUSSIAN', 'RU'), ('MULTI', 'Multi')):
        if token in audio and label not in langs:
            langs.append(label)
    if langs:
        tags['languages'] = langs[:4]
    return tags


def _source_type_from_formatter(value):
    raw = str(value or '').strip().lower()
    if 'usenet' in raw or raw in ('nzb', 'nntp'):
        key = 'usenet'
    elif 'debrid' in raw:
        key = 'debrid'
    elif raw in ('p2p', 'torrent') or 'torrent' in raw:
        key = 'torrent'
    elif raw:
        key = 'direct'
    else:
        return None
    return (key,) + _SOURCE_TYPE_STYLES[key]



def _stream_facts(row, provider_name, provider_origin=''):
    row = row or {}
    hints = row.get('behaviorHints') or {}
    formatted = _parse_formatter_fields(row)
    provider_domain = ''
    safe_provider_origin = ''
    safe_provider_origin = _safe_http_origin(provider_origin)
    try:
        provider_domain = urlparse(safe_provider_origin).netloc
    except Exception:
        provider_domain = ''
    if provider_domain.startswith('www.'):
        provider_domain = provider_domain[4:]
    addon_url = ''
    addon_domain = ''

    if formatted:
        # Fast AIOStreams path: use its parsed formatter values directly.
        display_name = (formatted.get('file') or
                        ((hints.get('filename') if isinstance(hints, dict) else '') or '') or
                        formatted.get('title') or _stream_display_name(row))
        video_bits = _formatter_fact_list(formatted.get('video'))
        audio_bits = _formatter_fact_list(formatted.get('audio'))
        size = (_extract_size(formatted.get('size')) or str(formatted.get('size') or '').strip()
                # v5.10.297: a formatter without a size field still sends the bytes
                or _extract_size(hints.get('videoSize') if isinstance(hints, dict) else None,
                                 row.get('size'), row.get('videoSize')))
        addon_name = _normalize_ascii(formatted.get('source') or formatted.get('addon') or '')
        addon_name = addon_name.upper() if addon_name else _extract_addon_name(row, provider_name, texts=[])
        indexer_name = _normalize_ascii(formatted.get('indexer') or '').upper()
        service_name = _normalize_ascii(formatted.get('service') or '').upper()
        addon_url = _safe_http_origin(formatted.get('url'))
        try:
            addon_domain = urlparse(addon_url).netloc
        except Exception:
            addon_domain = ''
        if addon_domain.startswith('www.'):
            addon_domain = addon_domain[4:]
        site = _extract_site(row, provider_name, addon_name=addon_name)
        # v4.6.9: the raw regex scan is BACK as a fallback on the AIO path.
        # "No raw scan on the AIO path" assumed the formatter always supplies
        # video/audio facts — but when the user's AIOStreams formatter preset
        # omits or renames those labelled fields, the bits came back empty,
        # and since the badge builder only emits a tag when it appears in
        # video_bits/audio_bits, the WHOLE badge row vanished (empty in every
        # device screenshot since 4.5.x). Formatter values stay authoritative
        # whenever present; the name/raw regex pass only fills the gap.
        raw_blob = ''
        if not (video_bits or audio_bits):
            _fallback_blob = ' | '.join(_collect_stream_texts(row))[:8192]
            if not video_bits:
                video_bits = _extract_video_bits(_fallback_blob, display_name)
            if not audio_bits:
                audio_bits = _extract_audio_bits(_fallback_blob, display_name)
        source_type = _source_type_from_formatter(formatted.get('type'))
    else:
        # Lightweight compatibility fallback for ordinary Stremio addons.
        values = _collect_stream_texts(row)
        raw_blob = ' | '.join(values)[:8192]
        display_name = _stream_display_name(row)
        addon_name = _extract_addon_name(row, provider_name, texts=values)
        indexer_name = _extract_indexer_name(
            row, provider_name, texts=values, addon_name=addon_name)
        service_name = _extract_service_name(row, texts=values)
        for candidate in _identity_candidates(
                row, 'manifestUrl', 'manifest_url', 'addonUrl', 'addon_url'):
            addon_url = _safe_http_origin(candidate)
            if addon_url:
                break
        try:
            addon_domain = urlparse(addon_url).netloc
        except Exception:
            addon_domain = ''
        if addon_domain.startswith('www.'):
            addon_domain = addon_domain[4:]
        site = _extract_site(row, provider_name, addon_name=addon_name)
        size = _extract_size(
            row.get('size'), row.get('videoSize'),
            hints.get('videoSize') if isinstance(hints, dict) else None,
            hints.get('size') if isinstance(hints, dict) else None,
        ) or _extract_size(raw_blob)
        # One video and one audio pass over one bounded string. v4.2.1 ran
        # these extractors per field and then invoked a second parser again.
        video_bits = _extract_video_bits(raw_blob, display_name)
        audio_bits = _extract_audio_bits(raw_blob, display_name)
        source_type = None

    # v5.10.204: AIOStreams' own data (streamData, sent to its clients)
    # names the type, the debrid service and the indexer exactly
    _sd = row.get('streamData') if isinstance(row.get('streamData'), dict) else {}
    if _sd:
        _sd_service = _sd.get('service') if isinstance(_sd.get('service'), dict) else {}
        if _sd_service.get('id') and not service_name:
            service_name = _normalize_ascii(str(_sd_service['id'])).upper()
        if _sd.get('indexer') and not indexer_name:
            indexer_name = _normalize_ascii(str(_sd['indexer'])).upper()
        _sd_type = _source_type_from_formatter(_sd.get('type'))
        if _sd_type:
            source_type = _sd_type
    subtitles = row.get('subtitles') or []
    badges = _stream_badges(video_bits, audio_bits, subtitles)
    if formatted or (_sd and service_name):
        provider_badge = _SERVICE_BADGES.get(service_name.upper())
        if not provider_badge:
            provider_badge = (service_name[:12] if service_name else
                              _provider_badge(row, provider_name, text_blob=' '))
    else:
        provider_badge = _provider_badge(
            row, provider_name, text_blob=raw_blob)
    if source_type is None:
        source_type = _stream_source_type(
            row, provider_name, text_blob=raw_blob,
            provider_badge=provider_badge)
    # AIOStreams may expose the delivery service as ``TYPE debrid`` even when
    # the underlying result is an NZB/Usenet row.  The indexer is the stronger
    # transport signal: EASYNEWS, ALTHUB, NZBGEEK, etc. must remain USENET in
    # the chip, count and type filter.  Keep the debrid/cache service visible
    # separately in ``service_name`` instead of letting it overwrite origin.
    source_type = _source_type_with_identity(
        source_type, indexer_name, service_name, addon_name, site)
    source_identity_line = _source_identity_line(
        source_type, provider_name, addon_name=addon_name,
        indexer_name=indexer_name, service_name=service_name)
    tags = _tags_from_fact_lists(video_bits, audio_bits, row=row)
    if formatted.get('lang'):
        formatter_langs = [
            part.strip() for part in
            re.split(r'\s*(?:/|\||\u2022|\u00b7)\s*', formatted.get('lang'))
            if part.strip()
        ]
        if formatter_langs:
            tags['languages'] = formatter_langs[:6]
    origin_line = _source_origin_line(
        row, provider_name, addon_name=addon_name,
        indexer_name=indexer_name, service_name=service_name,
        provider_domain=provider_domain, addon_domain=addon_domain)
    codec = next((x for x in video_bits if x in ('HEVC', 'H264', 'AV1')), '')
    audio = next((x for x in audio_bits if x in (
        'ATMOS', 'TRUEHD', 'DTS-X', 'DTS-HD', 'DTS', 'DD+', 'DD', 'AC3',
        'FLAC', 'AAC', 'OPUS')), '')
    hdr = next((x for x in video_bits if x in ('DV', 'HDR10+', 'HDR10', 'HDR')), '')
    return {
        'display_name': display_name,
        'site': site,
        'addon': addon_name,
        'indexer': indexer_name,
        'service': service_name,
        'origin_line': origin_line,
        'provider_domain': provider_domain,
        'provider_url': safe_provider_origin,
        'addon_domain': addon_domain,
        'addon_url': addon_url,
        'provider_badge': provider_badge,
        'size': size,
        'video_bits': video_bits,
        'audio_bits': audio_bits,
        'subtitles': subtitles,
        'badges': badges,
        'tags': tags,
        'source_type': source_type,
        'source_identity_line': source_identity_line,
        'codec': codec,
        'audio': audio,
        'hdr': hdr,
        '_raw_blob': raw_blob,
        '_formatter': formatted,
    }


def _stream_label(row, provider_name, index=None, facts=None):
    facts = facts or _stream_facts(row, provider_name)
    display_name = facts['display_name']
    site = facts['site']
    size = facts['size']
    video_bits = facts['video_bits']
    audio_bits = facts['audio_bits']
    subtitles = facts['subtitles']
    subs = _subtitles_summary(subtitles)
    badges = facts['badges']
    formatted = facts.get('_formatter') or {}
    description = ('' if formatted else
                   _normalize_ascii(row.get('description') or ''))
    title = _normalize_ascii(
        formatted.get('title') or row.get('title') or '')

    prefix = ('%02d. ' % int(index)) if index else ''
    label = '[B]%s%s[/B]' % (prefix, display_name)

    line2 = []
    if size:
        line2.append('SIZE: %s' % size)
    line2.append('VIDEO: %s' % (' | '.join(video_bits[:6]) if video_bits else '--'))
    line2.append('AUDIO: %s' % (' | '.join(audio_bits[:6]) if audio_bits else '--'))
    if site:
        line2.append('SITE: %s' % site)
    if badges:
        line2.append('TAGS: %s' % badges)
    label2 = '    '.join(line2)

    plot_lines = []
    if title and title.upper() != display_name:
        plot_lines.append(title)
    if description and description.upper() not in [x.upper() for x in plot_lines]:
        plot_lines.append(description)
    if subs:
        plot_lines.append('Subtitles: %s' % subs)
    plot = '\n'.join(plot_lines) or display_name
    return label, label2, plot


def _quality_badge(video_bits):
    bits = [str(x).upper() for x in (video_bits or [])]
    if '2160P' in bits or '4K' in bits:
        return '4K', 'FF0891B2'
    if '1080P' in bits:
        return '1080P', 'FF2563EB'
    if '720P' in bits:
        return '720P', 'FF059669'
    if '480P' in bits:
        return '480P', 'FFD97706'
    return '--', 'FF475569'


PLEX_COLOR = 'FFE5A00D'   # Plex brand gold
EMBY_COLOR = 'FF52B54B'   # Emby brand green


# ─────────────────────────────────────────────────────────────────────────────
# v3.9.198 — SOURCE DEDUPLICATION, after AIOStreams (streams/deduplicator.ts)
#
# Aggregating a dozen addons means the SAME physical file arrives a dozen
# times, each addon labelling it slightly differently. AIOStreams solves this
# with three independent keys and a union-find: two streams sharing ANY key
# are the same file, and the grouping is transitive (A~B by filename, B~C by
# infoHash => A, B and C are one file).
#
#   1. filename  — extension stripped, every non-alphanumeric character
#                  removed, lowercased. "Dune.2021.2160p.WEB-DL.mkv" and
#                  "Dune 2021 2160p WEB DL.MKV" become the same key.
#   2. infoHash  — the torrent hash (+ file index), when present.
#   3. smart     — a fingerprint of size + resolution + codec + audio + HDR,
#                  with the size GEOMETRICALLY rounded (±10% buckets) so two
#                  addons reporting 26.0 GB and 25.7 GB still collapse.
#
# The survivor of each group is the copy the user actually wants: their own
# server first (instant, no debrid), then the provider order they configured.
# ─────────────────────────────────────────────────────────────────────────────
_DEDUP_EXT_RE = re.compile(
    r'\.(mkv|mp4|avi|mov|wmv|flv|webm|m4v|mpg|mpeg|3gp|m2ts|ts|vob|ogv|divx|xvid|rmvb|asf|mka)$',
    re.I)
_DEDUP_NONALNUM_RE = re.compile(r'[^0-9a-z\u0600-\u06ff+]', re.I)


def _dedup_geometric_bucket(value, round_pct=10):
    """Bucket a number so near-identical sizes share a key (AIOStreams)."""
    try:
        value = float(value or 0)
    except (TypeError, ValueError):
        return ''
    if value <= 0:
        return ''
    step = math.log(1.0 + round_pct / 100.0)
    index = round(math.log(value) / step)
    return str(int(round(math.exp(index * step))))


def _dedup_keys(entry):
    """The set of identity keys this source row is known by."""
    keys = set()

    name = str(entry.get('filename') or entry.get('name') or '').strip()
    if name:
        base = _DEDUP_EXT_RE.sub('', name)
        base = _DEDUP_NONALNUM_RE.sub('', base).lower()
        if len(base) >= 8:      # too short to be a trustworthy identity
            keys.add('f:%s' % base)

    info_hash = str(entry.get('info_hash') or '').strip().lower()
    if len(info_hash) >= 32:
        keys.add('h:%s|%s' % (info_hash, entry.get('file_idx') or 0))

    # The size fingerprint is a FALLBACK ONLY. AIOStreams defaults to
    # ['filename', 'infoHash'] and treats smart-detect as opt-in, for good
    # reason: two DIFFERENT films that happen to share a size and a resolution
    # would otherwise be merged into one. It is used here only when the row
    # carries no filename and no hash — i.e. when there is nothing else to
    # identify it by.
    size_bucket = _dedup_geometric_bucket(entry.get('size_bytes')) if not keys else ''
    if size_bucket:
        keys.add('s:%s|%s|%s|%s|%s' % (
            size_bucket,
            str(entry.get('quality') or '').lower(),
            str(entry.get('video_codec') or '').lower(),
            str(entry.get('audio') or '').lower(),
            str(entry.get('hdr') or '').lower(),
        ))
    return keys


def _dedup_rank(entry, priority):
    """Lower sorts first: the copy the user should keep."""
    provider = str(entry.get('provider_name_raw') or entry.get('addon') or '')
    native = 0 if provider.startswith(('Plex \u2022 ', 'Emby \u2022 ', 'Silo \u2022 ')) else 1
    try:
        order = priority.index(provider.lower())
    except ValueError:
        order = len(priority)
    try:
        size = -int(entry.get('size_bytes') or 0)      # bigger file wins a tie
    except (TypeError, ValueError):
        size = 0
    return (native, order, size)


def dedupe_stream_entries(entries, mode='single', priority=None):
    """Collapse duplicate source rows. Returns (kept, removed_count)."""
    entries = list(entries or [])
    if mode == 'off' or len(entries) < 2:
        return entries, 0
    priority = [str(p).lower() for p in (priority or [])]

    parent = list(range(len(entries)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            parent[rb] = ra

    seen = {}
    for index, entry in enumerate(entries):
        for key in _dedup_keys(entry):
            if key in seen:
                union(seen[key], index)      # transitive, like AIOStreams' DSU
            else:
                seen[key] = index

    groups = {}
    for index in range(len(entries)):
        groups.setdefault(find(index), []).append(index)

    kept_indexes = set()
    for members in groups.values():
        if len(members) == 1:
            kept_indexes.add(members[0])
            continue
        if mode == 'per_addon':
            by_addon = {}
            for index in members:
                addon = str(entries[index].get('provider_name_raw') or '?')
                current = by_addon.get(addon)
                if current is None or _dedup_rank(entries[index], priority) < _dedup_rank(entries[current], priority):
                    by_addon[addon] = index
            kept_indexes.update(by_addon.values())
        else:
            kept_indexes.add(min(members, key=lambda i: _dedup_rank(entries[i], priority)))

    kept = [entry for index, entry in enumerate(entries) if index in kept_indexes]
    removed = len(entries) - len(kept)
    if removed:
        try:
            xbmc.log('[DexHub] source dedup: %d -> %d (%d duplicates removed, mode=%s)'
                     % (len(entries), len(kept), removed, mode), xbmc.LOGINFO)
        except Exception:
            pass
    return kept, removed


def _dedup_mode():
    """Cross-addon dedupe mode, from settings.

    The source window is an inventory, not a shortlist: two identical
    filenames from DIFFERENT addons can still be different servers, paths,
    encodes, subtitle sets or access routes, so the default stays 'off'.
    Repeated rows from the SAME provider are handled separately and
    unconditionally by _collapse_repeated_provider_rows.
    """
    # --- dexhub-406-patch --- honour the setting instead of ignoring it
    try:
        raw = str(ADDON.getSetting('source_dedup_mode') or '').strip().lower()
    except Exception:
        return 'off'
    if raw.startswith('single'):
        return 'single'
    if raw.startswith('one per'):
        return 'per_addon'
    return 'off'


# ─────────────────────────────────────────────────────────────────────────────
# v3.9.199 — STREAM TAG PARSER, after AIOStreams (parser/regex.ts)
#
# AIOStreams' strength in search is that it UNDERSTANDS what each addon
# returned: it pulls seven structured facts out of the raw stream title, so
# every result can be judged, ranked and filtered at a glance. Dex Hub was only
# reading size and site, which is why a long source list looked like noise.
#
# Nothing is merged or removed here — every source the addons return is still
# shown. They are simply *legible* now.
# ─────────────────────────────────────────────────────────────────────────────
_SEP = r'[ .\-_\[\]()]'

_TAG_PATTERNS = {
    'visual': [
        ('DV', r'do?(lby)?%s?vi?(sion)?|(?<![a-z])dv(?![a-z])' % _SEP),
        ('HDR10+', r'hdr%s?10%s?(\+|p(lus)?)' % (_SEP, _SEP)),
        ('HDR', r'(?<![a-z])hdr(?![a-z+])'),
        ('HLG', r'(?<![a-z])hlg(?![a-z])'),
        ('IMAX', r'(?<![a-z])imax(?![a-z])'),
        ('10bit', r'10%s?bit|hi10p?' % _SEP),
        ('3D', r'(?<![a-z0-9])3%s?d(?![a-z])' % _SEP),
    ],
    'audio': [
        ('Atmos', r'(?<![a-z])atmos(?![a-z])|ddpa\d?'),
        ('DTS-X', r'dts%s?x(?![a-z])' % _SEP),
        ('DTS-HD MA', r'dts%s?hd%s?ma' % (_SEP, _SEP)),
        ('DTS-HD', r'dts%s?hd(?!%s?ma)' % (_SEP, _SEP)),
        ('TrueHD', r'true%s?hd' % _SEP),
        ('DTS', r'(?<![a-z])dts(?![a-z:%s-])' % _SEP),
        ('DD+', r'(?<![a-z])(dd%s?(\+|p)|e%s?ac%s?3)(?![a-z])' % (_SEP, _SEP, _SEP)),
        ('DD', r'(?<![a-z+])(dd|ac%s?3)(?![a-z+])' % _SEP),
        ('FLAC', r'(?<![a-z])flac(?![a-z])'),
        ('AAC', r'(?<![a-z])aac(?![a-z])'),
    ],
    'channels': [
        # The lookbehind matters: without it "720p" yielded a phantom "2.0"
        # channel layout (the "20" inside 720).
        ('7.1', r'(?<![0-9])7%s?1(ch)?(?![0-9])' % _SEP),
        ('5.1', r'(?<![0-9])5%s?1(ch)?(?![0-9])' % _SEP),
        ('2.0', r'(?<![0-9])2%s?0(ch)?(?![0-9])' % _SEP),
    ],
    'encode': [
        ('HEVC', r'hevc|[xh]%s?265' % _SEP),
        ('AV1', r'(?<![a-z])av1(?![a-z])'),
        ('H.264', r'(?<![a-z])avc(?![a-z])|[xh]%s?264' % _SEP),
        ('XviD', r'(?<![a-z])xvid(?![a-z])'),
    ],
    'source': [
        ('REMUX', r'(?<![a-z])remux(?![a-z])'),
        ('BluRay', r'blu%s?ray|(?<![a-z])b[dr]%s?rip(?![a-z])' % (_SEP, _SEP)),
        ('WEB-DL', r'web%s?dl' % _SEP),
        ('WEBRip', r'web%s?rip' % _SEP),
        ('WEB', r'(?<![a-z])web(?![a-z-])'),
        ('HDTV', r'(?<![a-z])hd%s?tv(?![a-z])' % _SEP),
        ('DVDRip', r'dvd%s?rip' % _SEP),
        ('CAM', r'(?<![a-z])(cam|ts|telesync|hdcam)(?![a-z])'),
    ],
}

# Arabic first — it is what this addon's audience actually filters on.
_LANG_PATTERNS = [
    ('\u0639\u0631\u0628\u064a', r'(?<![a-z])(arabic|arab|ara|\u0639\u0631\u0628\u064a|\u0645\u062f\u0628\u0644\u062c|\u0645\u062a\u0631\u062c\u0645)(?![a-z])'),
    ('Multi', r'(?<![a-z])multi(?![a-z])|dual%s?audio' % _SEP),
    ('EN', r'(?<![a-z])(english|eng)(?![a-z])'),
    ('FR', r'(?<![a-z])(french|fre|vff|vfq)(?![a-z])'),
    ('ES', r'(?<![a-z])(spanish|spa|esp|castellano|latino)(?![a-z])'),
    ('DE', r'(?<![a-z])(german|ger|deu)(?![a-z])'),
    ('IT', r'(?<![a-z])(italian|ita)(?![a-z])'),
    ('RU', r'(?<![a-z])(russian|rus)(?![a-z])'),
    ('TR', r'(?<![a-z])(turkish|tur)(?![a-z])'),
    ('HI', r'(?<![a-z])(hindi|hin)(?![a-z])'),
    ('JP', r'(?<![a-z])(japanese|jap|jpn)(?![a-z])'),
    ('KR', r'(?<![a-z])(korean|kor)(?![a-z])'),
]

_TAG_RES = []           # v5.10.188: compiled at their first use (44 patterns at every import)


def _tag_res():
    """(the tag patterns by kind, the language patterns), compiled once."""
    if not _TAG_RES:
        _TAG_RES.append((
            {kind: [(label, re.compile(pattern, re.I | re.U)) for label, pattern in patterns]
             for kind, patterns in _TAG_PATTERNS.items()},
            [(label, re.compile(pattern, re.I | re.U)) for label, pattern in _LANG_PATTERNS]))
    return _TAG_RES[0]


_GROUP_RE = re.compile(r'(?:^|[-\[])\s*([A-Za-z0-9]{2,20})\s*$')



def stream_tag_line(tags, size_label='', provider=''):
    """The badges a user actually reads, in the order they care about."""
    bits = []
    if provider:
        bits.append(provider)
    for key in ('source', 'encode'):
        if tags.get(key):
            bits.append(tags[key][0])
    for label in (tags.get('visual') or [])[:2]:
        bits.append(label)
    if tags.get('audio'):
        audio = tags['audio'][0]
        if tags.get('channels'):
            audio += ' ' + tags['channels'][0]
        bits.append(audio)
    elif tags.get('channels'):
        bits.append(tags['channels'][0])
    for label in (tags.get('languages') or [])[:3]:
        bits.append(label)
    if size_label and size_label != '--':
        bits.append(size_label)
    return ' \u00b7 '.join(bits)


def _provider_badge(row, provider_name, text_blob=''):
    # v3.9.185: the built-in media servers get their own clean badge. Without
    # this they fell through to the generic branch and rendered as the mangled
    # 'PLEX HOM' / 'EMBY • H' (name truncated at 8 chars).
    # v3.9.198: match the NATIVE server providers only. The old
    # startswith('Plex') also caught the PlexBridge / Plexio *Stremio addons*,
    # which are something else entirely, and mislabelled them as native Plex.
    _name = str(provider_name or '')
    if _name.startswith('Plex \u2022 '):
        return 'PLEX'
    if _name.startswith('Emby \u2022 '):
        return 'EMBY'
    if text_blob:
        text = _normalize_ascii(text_blob).lower()
    else:
        values = _collect_stream_texts(row)
        values.append(provider_name)
        text = ' '.join(_normalize_ascii(v).lower() for v in values if v)[:8192]
    if 'realdebrid' in text or 'rd+' in text or re.search(r'\brd\+?\b', text):
        return 'RD+'
    if 'alldebrid' in text or re.search(r'\bad\+?\b', text):
        return 'AD+'
    if 'premiumize' in text or re.search(r'\bpm\+?\b', text):
        return 'PM'
    if 'torbox' in text or re.search(r'\btb\+?\b', text):
        return 'TB'
    if 'easydebrid' in text or 'ed+' in text:
        return 'ED+'
    cleaned = _normalize_ascii(provider_name or '')
    return (cleaned.upper()[:12] if cleaned else 'SRC')


# ─────────────────────────────────────────────────────────────────────────────
# v4.1.0 — stream source-type classification (usenet / debrid / torrent /
# direct / native server). Feeds the coloured TYPE chip in the sources window
# and the T: filter group, so users can tell at a glance where a file comes
# from and narrow the list to just their debrid or usenet rows.
# Priority order matters: TorBox usenet rows mention both "TB" and "Usenet",
# so usenet is tested BEFORE the debrid-service badges.
# ─────────────────────────────────────────────────────────────────────────────
_SOURCE_TYPE_STYLES = {
    'usenet':  ('USENET',  'FFD97706'),
    'debrid':  ('DEBRID',  'FF059669'),
    'torrent': ('TORRENT', 'FFDC2626'),
    'direct':  ('DIRECT',  'FF2563EB'),
    # v4.6.0: Plex and Emby no longer share one anonymous purple — they use
    # their brand colours (matching PLEX_COLOR / EMBY_COLOR above and the
    # static chip variants in sources_results.xml).
    'plex':    ('PLEX',    'FFE5A00D'),
    'emby':    ('EMBY',    'FF52B54B'),
    'silo':    ('SILO',    'FF7C3AED'),
}
_USENET_RE = re.compile(r'usenet|nzb|sabnzbd|newznab|easynews|eweka|newshosting|tweaknews|drunkenslug|althub|dognzb|omgwtf|binsearch|newsdemon|giganews|supernews|astraweb|usenetserver|newsgroup', re.I)
_TORRENT_HINT_RE = re.compile(r'\btorrent\w*\b|\bmagnet\b|\bseeders?\b|\bpeers?\b|\bp2p\b', re.I)
_DEBRID_BADGES = ('RD+', 'AD+', 'PM', 'TB', 'ED+')


def _source_type_with_identity(source_type, *identity_values):
    """Let a concrete Usenet identity override a generic delivery label."""
    try:
        current_key = str((source_type or ('',))[0] or '').lower()
    except Exception:
        current_key = ''
    # Never reinterpret native-library transports from their display text.
    if current_key in ('plex', 'emby', 'silo'):
        return source_type
    identity_blob = ' '.join(
        _normalize_ascii(value).lower() for value in identity_values if value)
    if identity_blob and _USENET_RE.search(identity_blob):
        return ('usenet',) + _SOURCE_TYPE_STYLES['usenet']
    return source_type


def _stream_source_type(row, provider_name, text_blob='', provider_badge=''):
    """Classify one raw stream row → (key, chip label, chip ARGB colour)."""
    hints = row.get('behaviorHints') or {}
    if isinstance(hints, dict) and hints.get('nativeProvider'):
        native = str(hints.get('nativeProvider') or '').lower()
        key = ('plex' if 'plex' in native else
               ('silo' if 'silo' in native else
                ('emby' if ('emby' in native or 'jellyfin' in native) else 'direct')))
        return (key,) + _SOURCE_TYPE_STYLES[key]
    _pname = str(provider_name or '')
    if _pname.startswith('Plex \u2022 '):
        return ('plex',) + _SOURCE_TYPE_STYLES['plex']
    if _pname.startswith('Emby \u2022 '):
        return ('emby',) + _SOURCE_TYPE_STYLES['emby']
    if _pname.startswith('Silo \u2022 '):
        return ('silo',) + _SOURCE_TYPE_STYLES['silo']
    # Structural marker first: several aggregators (AIOStreams included)
    # expose the transport as a literal field rather than words in the name.
    for _tf in (row.get('type'), row.get('sourceType'), row.get('transport'),
                (hints.get('type') if isinstance(hints, dict) else None),
                (hints.get('sourceType') if isinstance(hints, dict) else None)):
        if 'usenet' in str(_tf or '').lower():
            return ('usenet',) + _SOURCE_TYPE_STYLES['usenet']
    raw_text = str(text_blob or '')[:8192]
    if not raw_text:
        raw_text = ' '.join(_collect_stream_texts(row))[:8192]
    text_l = _normalize_ascii(raw_text).lower()
    if _USENET_RE.search(text_l):
        return ('usenet',) + _SOURCE_TYPE_STYLES['usenet']
    badge = provider_badge or _provider_badge(
        row, provider_name, text_blob=raw_text)
    if badge in _DEBRID_BADGES or 'debrid' in text_l or 'offcloud' in text_l or 'premiumize' in text_l or '\u26a1' in raw_text:
        return ('debrid',) + _SOURCE_TYPE_STYLES['debrid']
    info_hash = str(row.get('infoHash') or row.get('infohash') or (hints.get('infoHash') if isinstance(hints, dict) else '') or '')
    url = str(row.get('url') or row.get('externalUrl') or '')
    if info_hash or url.lower().startswith('magnet:') or _TORRENT_HINT_RE.search(text_l):
        return ('torrent',) + _SOURCE_TYPE_STYLES['torrent']
    return ('direct',) + _SOURCE_TYPE_STYLES['direct']


def _source_info_text(row, provider_name, facts=None, provider_origin=''):
    parts = []
    facts = facts or _stream_facts(
        row, provider_name, provider_origin=provider_origin)
    addon_name = facts.get('addon') or ''
    site_name = facts.get('site') or ''
    indexer_name = facts.get('indexer') or ''
    service_name = facts.get('service') or ''
    parts.append('provider: %s' % (provider_name or 'Provider'))
    safe_provider_url = facts.get('provider_url') or _safe_http_origin(provider_origin)
    if safe_provider_url:
        parts.append('provider URL: %s' % safe_provider_url)
    if addon_name:
        parts.append('addon: %s' % addon_name)
    if facts.get('addon_url'):
        parts.append('addon URL: %s' % facts.get('addon_url'))
    if service_name:
        parts.append('service: %s' % service_name)
    if indexer_name:
        parts.append('indexer: %s' % indexer_name)
    if site_name and site_name != addon_name:
        parts.append('site: %s' % site_name)
    detail_keys = ('name', 'title', 'filename')
    for key in detail_keys:
        val = row.get(key)
        if val:
            parts.append('%s: %s' % (key, _clean_stream_text(val)))
    formatted = facts.get('_formatter') or {}
    if formatted:
        for key in ('file', 'title', 'video', 'audio', 'size', 'lang', 'subs'):
            val = formatted.get(key)
            if val:
                parts.append('%s: %s' % (key, _clean_stream_text(val)))
    elif row.get('description'):
        parts.append('description: %s' % _clean_stream_text(row.get('description')))
    if row.get('subtitles'):
        parts.append('subtitles: %s' % _subtitles_summary(row.get('subtitles') or []))
    hints = row.get('behaviorHints') or {}
    if isinstance(hints, dict) and hints:
        # Keep the useful technical fields but never copy a tokenised manifest,
        # request headers or a huge opaque JSON blob into every ListItem.
        compact_hints = {}
        for key in ('filename', 'videoSize', 'bingeGroup', 'sourceType',
                    'quality', 'resolution', 'codec', 'audioChannels',
                    'nativeProvider', 'serverType'):
            value = hints.get(key)
            if value not in (None, '', [], {}):
                compact_hints[key] = value
        try:
            if compact_hints:
                parts.append('behaviorHints: %s' % json.dumps(
                    compact_hints, ensure_ascii=False, separators=(',', ':')))
        except Exception:
            pass
    return '\n'.join(parts)




# ─────────────────────────────────────────────────────────────────────────────
# v3.9.231 — subtitles, the DPlex way
#
# Two things DPlex gets right and Dex Hub did not:
#
#   1. BITMAP subtitles (PGS / VobSub / DVD) CANNOT be loaded with
#      setSubtitles(). They are images, not text; Kodi needs them transcoded by
#      the server. Handing one to the player produces no subtitle and no error
#      — a silent failure the user can only describe as "the subtitle doesn't
#      work". They are filtered out before they ever reach the player.
#
#   2. Text subtitles are DOWNLOADED to a temp file first. A remote URL means
#      the player fetches it itself, mid-handoff, with no retry — if the server
#      is slow the subtitle simply never appears.
#
# And for a STREMIO source the addon's OWN subtitles come first, because the
# addon is what is serving the file: it knows which subtitle belongs to it.
# ─────────────────────────────────────────────────────────────────────────────
_SUBS_TMP_DIRNAME = 'dexhub_subs'


def _companion_context_from_playback(ctx):
    hints = ctx.get('behaviorHints') or {}
    if not isinstance(hints, dict):
        hints = {}
    comp = {}
    for src, dst in (
        ('bootstrapUrl', 'bootstrapUrl'),
        ('companionUrl', 'companionUrl'),
        ('companionScrobbleUrl', 'companionScrobbleUrl'),
        ('companionUnscrobbleUrl', 'companionUnscrobbleUrl'),
        ('sessionIdentifier', 'sessionIdentifier'),
        ('playbackSessionId', 'playbackSessionId'),
        ('clientIdentifier', 'clientIdentifier'),
        ('plexDuration', 'duration_ms'),
        ('serverType', 'server_type'),
        ('serverUrl', 'server_url'),
        ('token', 'token'),
        ('itemId', 'item_id'),
        ('deviceId', 'device_id'),
        ('sessionId', 'session_id'),
        ('durationMs', 'duration_ms'),
    ):
        val = hints.get(src)
        if val not in (None, ''):
            comp[dst] = val
    if comp.get('duration_ms'):
        try:
            comp['duration_ms'] = int(float(comp['duration_ms']))
        except Exception:
            comp['duration_ms'] = int(ctx.get('duration_ms') or 0)
    elif ctx.get('duration_ms'):
        comp['duration_ms'] = int(ctx.get('duration_ms') or 0)
    if not comp.get('clientIdentifier'):
        comp['clientIdentifier'] = hints.get('clientIdentifier') or 'DexHub-Kodi'
    if comp.get('server_type') and isinstance(comp.get('server_type'), str):
        comp['server_type'] = comp['server_type'].lower()
    comp['deviceName'] = 'Kodi'
    comp['product'] = 'Dex Hub'
    if any(comp.get(k) for k in ('companionUrl', 'companionScrobbleUrl', 'companionUnscrobbleUrl')):
        return comp
    if all(ctx.get(k) for k in ('server_type', 'server_url', 'token')):
        direct = {
            'server_type': ctx.get('server_type'),
            'server_url': ctx.get('server_url'),
            'token': ctx.get('token'),
            'duration_ms': int(ctx.get('duration_ms') or 0),
        }
        for key in ('rating_key', 'client_id', 'device_name', 'product', 'product_version', 'item_id', 'device_id', 'session_id'):
            if ctx.get(key):
                direct[key] = ctx.get(key)
        return direct
    return {}

_SESSION_CTX_COPY_KEYS = (
    # The service ownership gate requires this identity on every handoff.
    # Losing it makes our own stream look foreign and disables resume/progress.
    'playback_uid', 'playback_created_at',
    'source_switch_pending', 'source_switch_captured_at', 'source_switch_reuse_subtitle',
    'media_type', 'canonical_id', 'video_id', 'title', 'show_title', 'year',
    'season', 'episode', 'imdb_id', 'tmdb_id', 'tvdb_id', 'provider_id',
    'source_provider_id', 'server_id', 'source_addon', 'source_indexer',
    'source_service', 'source_type', 'binge_group', 'behaviorHints',
    'show_imdb_id', 'show_tmdb_id', 'show_tvdb_id', 'external_ids',
    'introdb_post_start',
    'provider_name', 'provider_base_url', 'subtitles', 'stream_url', 'poster',
    'background', 'clearlogo', 'genre', 'rating', 'studio', 'premiered',
    'duration', 'duration_ms', 'kodi_info', 'cast', 'resume_seconds', 'resume_percent',
    'switch_subtitle_path', 'switch_subtitle_enabled', 'switch_subtitle_name',
    # --- direct-server reporting keys (v3.9.232) --------------------------
    # companion.get_reporter() builds its EmbyReporter/PlexReporter from the
    # SAVED SESSION, and needs (server_type, server_url, token) plus item_id
    # for Emby / rating_key for Plex.  None of them were copied here, so
    # get_reporter() returned None on the native-server path: no progress was
    # ever POSTed to /Sessions/Playing, Emby never marked anything as
    # in-progress, /Users/{id}/Items/Resume stayed empty, and Emby's Continue
    # Watching row was permanently blank.  (Plex only looked fine because the
    # Plex apps write their own progress.)
    'server_type', 'server_url', 'token', 'item_id', 'rating_key',
    'media_source_id', 'part_key', 'play_session_id', 'device_id', 'session_id', 'silo_session',
)



def _augment_session_ctx(target, ctx, fallback_keys, include_stream_url=True):
    """Copy live playback fields from ``ctx`` onto a session dict ``target``.

    Shared by both the companion-sync and the minimal (no-companion) branches
    of ``_play_with_context`` — previously duplicated verbatim.  Behaviour is
    identical to the original inline blocks:

      * only non-empty ctx values overwrite target keys,
      * ``include_stream_url=False`` skips the stream_url key so the caller's
        pre-seeded ``{'stream_url': ...}`` precedence is preserved,
      * source picker URL and next-episode hint are attached when available
        (picker-url failures are swallowed exactly as before),
      * automatic stream fallback is explicitly removed.  A failed source must
        never switch to a different source without the user's choice.
    """
    for key in _SESSION_CTX_COPY_KEYS:
        if key == 'stream_url' and not include_stream_url:
            continue
        if ctx.get(key) not in (None, ''):
            target[key] = ctx.get(key)
    target.pop('fallback_stream_keys', None)
    try:
        _picker_url = _source_picker_url_from_ctx(ctx)
        if _picker_url:
            target['source_picker_url'] = _picker_url
    except Exception:
        pass
    next_hint = ctx.get('next_episode') or _compute_next_episode_hint(ctx)
    if next_hint:
        target['next_episode'] = next_hint
    return target


def _publish_playback_art_properties(ctx):
    """Publish playback artwork/skin properties for the current item.

    Extracted verbatim from _play_with_context (v3.9.145). Writes the
    dexhub.* window properties, mirrors artwork onto the always-alive
    home window (Window 10000), and publishes Arctic Fuse / Arctic
    Zephyr skin properties. Property write ORDER is preserved exactly;
    several skins and the Kodi 22 safe-handoff path depend on it.
    Self-contained: reads only ctx, leaks no locals back to the caller.
    """
    # Always write clearlogo — even when empty — so stale art from the
    # previous item doesn't bleed through to the current one.
    _logo = ctx.get('clearlogo') or ''
    xbmcgui.Window(WINDOW_ID).setProperty('dexhub.clearlogo', _logo)
    xbmcgui.Window(WINDOW_ID).setProperty('clearlogo', _logo)
    xbmcgui.Window(WINDOW_ID).setProperty('tvshow.clearlogo', _logo)
    # v3.9.85: scrub the poster URL before propagating. Some Stremio
    # addons (notably the smaller anime/streaming providers) return
    # their own logo in the meta record's poster field when they have
    # no real poster for an item. Without this cleanup, that addon
    # logo would appear in Dex Hub's source-loading dialog, the source
    # picker hero, and the player overlay — looking broken because the
    # SAME logo appears for every item from that addon. See
    # _is_suspect_logo_poster for the detection heuristic.
    _clean_p = _clean_poster(ctx.get('poster') or '',
                              fallback=ctx.get('background') or '',
                              imdb_id=ctx.get('imdb_id') or '')
    _clean_fanart = ctx.get('background') or _clean_p or neutral_fanart()
    if _clean_p:
        xbmcgui.Window(WINDOW_ID).setProperty('dexhub.poster', _clean_p)
    xbmcgui.Window(WINDOW_ID).setProperty('dexhub.fanart', _clean_fanart)
    # Mirror the active playback artwork onto the always-alive home window as
    # well. Several skins/player overlays read artwork from Window(10000) or
    # global properties during fullscreen playback, not from our transient
    # custom source window. Without this mirror the clearlogo can be visible in
    # Dex Hub's source picker yet disappear once the actual player takes over.
    try:
        home = xbmcgui.Window(10000)
        logo_value = ctx.get('clearlogo') or ''
        poster_value = _clean_p   # v3.9.85: same scrubbed value used above
        fanart_value = _clean_fanart
        title_value = ctx.get('title') or ''
        plot_value = ctx.get('plot') or ''
        year_value = str(ctx.get('year') or '')
        genre_value = str(ctx.get('genre') or '')
        studio_value = str(ctx.get('studio') or '')
        rating_value = str(ctx.get('rating') or '')
        home.setProperty('dexhub.source.clearlogo', logo_value)
        home.setProperty('dexhub.source.poster', poster_value)
        home.setProperty('dexhub.source.thumb', poster_value)
        home.setProperty('dexhub.source.fanart', fanart_value)
        home.setProperty('dexhub.source.title', title_value)
        home.setProperty('dexhub.source.plot', plot_value)
        home.setProperty('dexhub.source.year', year_value)
        home.setProperty('dexhub.source.genre', genre_value)
        home.setProperty('dexhub.source.studio', studio_value)
        home.setProperty('dexhub.source.rating', rating_value)
        home.setProperty('dexhub.source.key', _source_art_identity_key(ctx))
        if _safe_playback_handoff_enabled():
            # Kodi 22 safe path: publish ONLY the lightweight logo properties
            # used by Arctic Fuse/skin player overlays.  Do not publish the full
            # poster/fanart/tvshow alias set here; that was the risky part on
            # CoreELEC Piers alpha.
            home.setProperty('clearlogo', logo_value)
            home.setProperty('logo', logo_value)
            home.setProperty('tvshow.clearlogo', logo_value)
            home.setProperty('ArcticFuse.NowPlaying.Logo', logo_value)
            home.setProperty('ArcticFuse.Player.Logo', logo_value)
            home.setProperty('ArcticFuse.CurrentlyPlaying', 'true' if logo_value else '')
        else:
            # Publish common global artwork keys too; many fullscreen skins read
            # these instead of the addon's namespaced properties during playback.
            home.setProperty('clearlogo', logo_value)
            home.setProperty('logo', logo_value)
            home.setProperty('tvshow.clearlogo', logo_value)
            home.setProperty('poster', poster_value)
            home.setProperty('thumb', poster_value)
            home.setProperty('fanart', fanart_value)
            home.setProperty('fanart_image', fanart_value)
            home.setProperty('landscape', fanart_value)
            home.setProperty('tvshow.poster', poster_value)
            home.setProperty('tvshow.fanart', fanart_value)
            home.setProperty('tvshow.landscape', fanart_value)
            home.setProperty('studio', studio_value)
            home.setProperty('genre', genre_value)
            home.setProperty('rating', rating_value)
            home.setProperty('tmdb_type', _tmdb_type_from_ctx(ctx))
            if ctx.get('tmdb_id'):
                home.setProperty('tmdb_id', str(ctx.get('tmdb_id')))
            if ctx.get('imdb_id'):
                home.setProperty('imdb_id', str(ctx.get('imdb_id')))
                home.setProperty('IMDBNumber', str(ctx.get('imdb_id')))
            if ctx.get('tvdb_id'):
                home.setProperty('tvdb_id', str(ctx.get('tvdb_id')))

            # ── Arctic Fuse 3 / Arctic Zephyr 2 skin properties ─────────────
            home.setProperty('ArcticFuse.NowPlaying.Logo',    logo_value)
            home.setProperty('ArcticFuse.NowPlaying.Thumb',   poster_value)
            home.setProperty('ArcticFuse.NowPlaying.Fanart',  fanart_value)
            home.setProperty('ArcticFuse.NowPlaying.Title',   title_value)
            home.setProperty('ArcticFuse.NowPlaying.Plot',    plot_value)
            home.setProperty('ArcticFuse.NowPlaying.Year',    year_value)
            home.setProperty('ArcticFuse.NowPlaying.Studio',  studio_value)
            home.setProperty('ArcticFuse.NowPlaying.Genre',   genre_value)
            home.setProperty('ArcticFuse.NowPlaying.Rating',  rating_value)
            home.setProperty('ArcticFuse.CurrentlyPlaying',   'true')
            home.setProperty('ArcticFuse.Player.Logo',        logo_value)
            home.setProperty('ArcticFuse.Player.Thumb',       poster_value)
            home.setProperty('ArcticFuse.Player.Fanart',      fanart_value)
            home.setProperty('ArcticFuse.Player.Studio',      studio_value)
            home.setProperty('ArcticFuse.Player.Genre',       genre_value)
            home.setProperty('ArcticFuse.Player.Rating',      rating_value)
            if ctx.get('season') and ctx.get('episode'):
                _ep_label = 'S%02dE%02d' % (int(ctx.get('season') or 0), int(ctx.get('episode') or 0))
                home.setProperty('ArcticFuse.NowPlaying.Episode', _ep_label)
                home.setProperty('ArcticFuse.Player.Episode',     _ep_label)
                _show = ctx.get('show_title') or title_value
                home.setProperty('ArcticFuse.NowPlaying.ShowTitle', _show)
                home.setProperty('ArcticFuse.Player.ShowTitle',     _show)
            else:
                home.clearProperty('ArcticFuse.NowPlaying.Episode')
                home.clearProperty('ArcticFuse.Player.Episode')
                home.clearProperty('ArcticFuse.NowPlaying.ShowTitle')
                home.clearProperty('ArcticFuse.Player.ShowTitle')
    except Exception:
        pass
    # 5.10.302: the Home's now-playing logo (kept until playback stops)
    try:
        from . import nowplaying as _np
        _np.publish(ctx, lookup=False)
    except Exception:
        pass


def _refresh_native_playback_context(ctx):
    """Refresh server-owned playback URLs immediately before handoff.

    Source results can stay open for minutes and Emby PlaybackInfo is session
    scoped. Refreshing here prevents stale MediaSource/PlaySession data from
    crashing direct play after the user spends time in the source picker.
    """
    ctx = dict(ctx or {})
    backend = str(ctx.get('server_type') or '').lower()
    if backend not in ('emby', 'silo', 'jellyfin'):
        return ctx
    if ctx.get('native_playback_resolved'):
        return ctx
    # `video_id` is the CANONICAL id (e.g. tt43595399 on the source-picker
    # path), NOT an Emby ItemId. Feeding an IMDb id to Emby's API makes every
    # PlaybackInfo/progress call fail. Only fall back to video_id when it does
    # not look like an external (imdb/tmdb/tvdb/anime) id.
    item_id = str(ctx.get('item_id') or '')
    if not item_id:
        _candidate = str(ctx.get('video_id') or '')
        if _candidate and not _candidate.lower().startswith(
                ('tt', 'tmdb:', 'tvdb:', 'kitsu:', 'mal:', 'anilist:')):
            item_id = _candidate

    server_url = str(ctx.get('server_url') or '')
    token = str(ctx.get('token') or '')
    if not (item_id and server_url and token):
        return ctx
    try:
        client = _server_client(backend)
        auth = client.account() or {}
        server = {
            'id': auth.get('user_id') or backend,
            'name': auth.get('server_name') or ('Silo' if backend == 'silo' else 'Emby'),
            'url': server_url,
            'token': token,
            'user_id': auth.get('user_id') or '',
            'backend': backend,
        }
        # v5.10.27: bound the refresh. It runs synchronously right before
        # Player.play, and the direct URL below is already a valid fallback.
        with emby_client.bounded_timeout(6):
            args = (server, item_id, str(ctx.get('media_source_id') or ''))
            resolved = (client.resolve_playback(*args, start_position=ctx.get('resume_seconds'))
                        if backend == 'silo' else client.resolve_playback(*args))
        if resolved.get('url'):
            ctx['stream_url'] = resolved.get('url')
        if resolved.get('media_source_id'):
            ctx['media_source_id'] = resolved.get('media_source_id')
        if resolved.get('play_session_id'):
            ctx['session_id'] = resolved.get('play_session_id')
        if resolved.get('silo_session'):
            ctx['silo_session'] = resolved['silo_session']
        version = resolved.get('version') or {}
        if version.get('subtitles'):
            ctx['subtitles'] = list(version.get('subtitles') or [])
        ctx['native_playback_resolved'] = True
    except Exception as exc:
        if backend == 'silo':
            raise
        # Keep the already-built direct URL as a compatibility fallback.
        try:
            xbmc.log('[DexHub] %s PlaybackInfo refresh failed; using direct fallback: %s' % (
                         backend.capitalize(), exc),
                     xbmc.LOGWARNING)
        except Exception:
            pass
    return ctx


def _play_with_context(ctx, stream_key='', fallback_keys=None, entries_meta=None, use_resolved_url=None):
    from .playback_engine import play_with_context
    return play_with_context(sys.modules[__name__], ctx=ctx, stream_key=stream_key, fallback_keys=fallback_keys, entries_meta=entries_meta, use_resolved_url=use_resolved_url)

    # v5.4.11: the plugin-side post-start subtitle worker is gone — the job
    # published above is executed by the service companion instead, so this
    # invocation exits with zero surviving threads and the invoker is
    # immediately reusable.

def _compute_next_episode_hint(ctx):
    """Return next-episode playback URL info if current playback is an episode
    and a next episode exists."""
    try:
        season = int(ctx.get('season') or 0)
        episode = int(ctx.get('episode') or 0)
    except Exception:
        return None
    canonical = ctx.get('canonical_id') or ''
    media_type = (ctx.get('media_type') or '').lower()
    if not canonical or season <= 0 or episode <= 0 or media_type not in ('series', 'anime', 'show', 'tv'):
        return None
    # Look up the show's video list from the window prop set by series_meta().
    try:
        raw = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical) or ''
        videos = json.loads(raw) if raw else []
    except Exception:
        videos = []
    if not videos:
        return None
    # Find next episode — same season & ep+1, else season+1 & ep1.
    candidates = [
        (season, episode + 1),
        (season + 1, 1),
    ]
    affinity = _binge_source.affinity_from_context(ctx)
    for s, e in candidates:
        for v in videos:
            try:
                if int(v.get('season') or 0) == s and int(v.get('episode') or 0) == e:
                    hint = {
                        'canonical_id': canonical,
                        'video_id': v.get('id') or canonical,
                        'season': s,
                        'episode': e,
                        'title': ctx.get('show_title') or ctx.get('title') or canonical,
                    }
                    for key, value in affinity.items():
                        if value:
                            # Route code historically consumes
                            # source_provider_id, while affinity helpers use
                            # provider_id. Keep one canonical key in the hint.
                            hint['source_provider_id' if key == 'provider_id' else key] = value
                    return hint
            except Exception:
                continue
    return None


def _source_window_meta_from_entries(entries, meta=None):
    merged = dict(meta or {})
    try:
        home = xbmcgui.Window(10000)
    except Exception:
        home = None
    for entry in list(entries or []):
        try:
            ctx = cache_store.get('stream', entry.get('stream_key') or '') or {}
        except Exception:
            ctx = {}
        if not isinstance(ctx, dict) or not ctx:
            continue
        if not merged.get('poster'):
            merged['poster'] = ctx.get('poster') or ''
        if not merged.get('fanart'):
            merged['fanart'] = ctx.get('background') or ctx.get('poster') or ''
        if not merged.get('clearlogo'):
            merged['clearlogo'] = ctx.get('clearlogo') or ''
        if not merged.get('title'):
            merged['title'] = ctx.get('show_title') or ctx.get('originaltitle') or ctx.get('title') or ''
        if not merged.get('originaltitle'):
            merged['originaltitle'] = ctx.get('originaltitle') or ctx.get('show_title') or ''
        if not merged.get('plot'):
            merged['plot'] = ctx.get('plot') or ctx.get('stream_description') or ''
        if not merged.get('tmdb_id'):
            merged['tmdb_id'] = ctx.get('tmdb_id') or ''
        if not merged.get('imdb_id'):
            merged['imdb_id'] = ctx.get('imdb_id') or ''
        if not merged.get('tvdb_id'):
            merged['tvdb_id'] = ctx.get('tvdb_id') or ''
        if not merged.get('media_type'):
            merged['media_type'] = ctx.get('media_type') or ''
        if not merged.get('year'):
            merged['year'] = ctx.get('year') or ''
        if not merged.get('genre'):
            merged['genre'] = ctx.get('genre') or ''
        if not merged.get('rating'):
            merged['rating'] = ctx.get('rating') or ''
        if not merged.get('studio'):
            merged['studio'] = ctx.get('studio') or ((ctx.get('kodi_info') or {}).get('studio') if isinstance(ctx.get('kodi_info'), dict) else '') or ''
        if merged.get('poster') and merged.get('fanart') and merged.get('title'):
            break
    try:
        if home and _home_source_props_match(merged, home):
            if not merged.get('poster'):
                merged['poster'] = home.getProperty('dexhub.source.poster') or ''
            if not merged.get('fanart'):
                merged['fanart'] = home.getProperty('dexhub.source.fanart') or ''
            if not merged.get('clearlogo'):
                merged['clearlogo'] = home.getProperty('dexhub.source.clearlogo') or ''
            if not merged.get('title'):
                merged['title'] = home.getProperty('dexhub.source.title') or ''
            if not merged.get('plot'):
                merged['plot'] = home.getProperty('dexhub.source.plot') or ''
            if not merged.get('year'):
                merged['year'] = home.getProperty('dexhub.source.year') or ''
            if not merged.get('studio'):
                merged['studio'] = home.getProperty('dexhub.source.studio') or ''
    except Exception:
        pass
    if not merged.get('poster'):
        merged['poster'] = merged.get('fanart') or ''
    return merged


def _current_source_ui_meta(meta=None):
    """Artwork currently shown in the source window, without stale bleed.

    For playback handoff we should preserve the artwork selected for this
    source window, but not pull poster/logo from previous playback globals.
    """
    merged = dict(meta or {})
    try:
        home = xbmcgui.Window(10000)
    except Exception:
        home = None

    def _first(*values):
        for value in values:
            if value not in (None, ''):
                return value
        return ''

    poster = _first(merged.get('poster'), merged.get('thumb'))
    fanart = _first(merged.get('background'), merged.get('fanart'), poster)
    clearlogo = _first(merged.get('clearlogo'), merged.get('logo'))
    title = _first(merged.get('title'), merged.get('name'))
    plot = _first(merged.get('plot'), merged.get('description'))
    year = _first(merged.get('year'))
    genre = _first(merged.get('genre'))
    rating = _first(merged.get('rating'))
    studio = _first(merged.get('studio'))

    try:
        if home and _home_source_props_match(merged, home):
            poster = _first(poster, home.getProperty('dexhub.source.poster'), home.getProperty('dexhub.source.thumb'))
            fanart = _first(fanart, home.getProperty('dexhub.source.fanart'), poster)
            clearlogo = _first(clearlogo, home.getProperty('dexhub.source.clearlogo'))
            title = _first(title, home.getProperty('dexhub.source.title'))
            plot = _first(plot, home.getProperty('dexhub.source.plot'))
            year = _first(year, home.getProperty('dexhub.source.year'))
            genre = _first(genre, home.getProperty('dexhub.source.genre'))
            rating = _first(rating, home.getProperty('dexhub.source.rating'))
            studio = _first(studio, home.getProperty('dexhub.source.studio'))
    except Exception:
        pass

    if poster:
        merged['poster'] = poster
    if fanart:
        merged['fanart'] = fanart
        merged['background'] = fanart
    elif poster:
        merged['fanart'] = poster
        merged['background'] = poster
    merged['clearlogo'] = clearlogo or ''
    merged['logo'] = clearlogo or ''
    if title and not merged.get('title'):
        merged['title'] = title
    if plot and not merged.get('plot'):
        merged['plot'] = plot
    if year and not merged.get('year'):
        merged['year'] = year
    if genre and not merged.get('genre'):
        merged['genre'] = genre
    if rating and not merged.get('rating'):
        merged['rating'] = rating
    if studio and not merged.get('studio'):
        merged['studio'] = studio
    return merged

def _show_stream_window(entries, meta, session_key=''):
    meta = _source_window_meta_from_entries(entries, meta)
    meta = _source_window_meta_fallback(meta)
    chosen_key = None
    play_with_subtitles = False
    play_mode = _subtitle_pick_mode_setting()
    try:
        for _dlg in ('busydialog', 'busydialognocancel'):
            try:
                xbmc.executebuiltin('Dialog.Close(%s,true)' % _dlg)
            except Exception:
                pass
        def retry_source(state, source_meta):
            from .source_retry import fetch
            return fetch(state, source_meta, api=sys.modules[__name__])
        result = open_sources_window(entries, meta, play_mode=play_mode, session_key=session_key,
                                     retry_source=retry_source)
        if isinstance(result, dict):
            chosen_key = result.get('stream_key')
            play_with_subtitles = bool(result.get('play_with_subtitles'))
        else:
            chosen_key = result
    except Exception as exc:
        xbmc.log('[DexHub] source window failed, using dialog fallback: %s' % exc, xbmc.LOGWARNING)
        labels = [e.get('name') or e.get('label2') or e.get('stream_key') or 'Stream' for e in entries]
        idx = xbmcgui.Dialog().select(tr(meta.get('title') or tr('اختر المصدر')), [tr(x) for x in labels])
        if idx >= 0 and idx < len(entries):
            chosen_key = entries[idx].get('stream_key')
            if play_mode == 'ask':
                play_choice = xbmcgui.Dialog().select(tr('اختر طريقة التشغيل'), [tr('تشغيل'), tr('تشغيل مع ترجمة')])
                if play_choice < 0:
                    chosen_key = None
                else:
                    play_with_subtitles = (play_choice == 1)
            else:
                play_with_subtitles = (play_mode == 'play_with_subtitles')
    if chosen_key:
        ctx = cache_store.get('stream', chosen_key)
        if ctx:
            ctx = dict(ctx or {})
            # Preserve exactly the artwork currently shown in the source UI and
            # forward it to the wait window + player overlay. This prevents TMDb
            # fallback art from replacing the correct XML/source artwork.
            meta = _current_source_ui_meta(meta)
            for _art_key in ('clearlogo', 'poster', 'background'):
                _meta_val = meta.get(_art_key) or meta.get('fanart' if _art_key == 'background' else _art_key)
                if _meta_val:
                    ctx[_art_key] = _meta_val
            # Propagate plot/year/title/media_type so the wait window can
            # render the full right panel without a TMDb DB round-trip.
            for _txt_key in ('plot', 'title', 'year', 'media_type', 'genre', 'rating', 'studio', 'premiered', 'duration'):
                _txt_val = meta.get(_txt_key)
                if _txt_val and not ctx.get(_txt_key):
                    ctx[_txt_key] = _txt_val
            ctx['play_with_subtitles'] = bool(play_with_subtitles)
            # The selected source is authoritative. A failed handoff returns
            # control to the user instead of trying a different URL.
            # Pre-emptively close any spinner so it doesn't sit on top of the
            # video player after playback starts. Symptom this fixes:
            # "loading spinner stays even when the movie plays".
            for _dlg in ('busydialog', 'busydialognocancel'):
                try:
                    xbmc.executebuiltin('Dialog.Close(%s,true)' % _dlg)
                except Exception:
                    pass
            _remember_source_choice(ctx)
            try:
                current_action = dict(parse_qsl(sys.argv[2].lstrip('?'))).get('action', '')
            except Exception:
                current_action = ''
            # dialog:false in dexhub.json → no open HANDLE for tmdb_player.
            use_resolved = (HANDLE >= 0 and current_action in (
                'play_item', 'cw_resume', 'cw_play_from_start', 'play',
                # TMDb Helper invokes its player URL through ResolvePath on
                # current Kodi builds even when the player JSON advertises
                # is_resolvable=false. Resolving the selected stream here
                # prevents the parent TMDb Helper route from ending with
                # "is not playable" after the source picker closes.
                'tmdb_player',
            ))
            try:
                _needs_resume_seek = float(ctx.get('resume_seconds') or 0.0) > 1.0 or (1.0 < float(ctx.get('resume_percent') or 0.0) < 95.0)
            except Exception:
                _needs_resume_seek = False
            if _needs_resume_seek and current_action != 'tmdb_player':
                # Normal internal routes keep the known-good Player.play seek
                # path. TMDb Helper must remain resolved through its open
                # handle, otherwise its parent ResolvePath reports the item as
                # unplayable after Dex Hub already opened the source picker.
                use_resolved = False
            # v3.9.80: DPlex-style fast handoff. Keep setResolvedUrl for
            # normal raw media when Kodi gave us a plugin handle; reserve
            # Player.play for resume/plugin/magnet paths.  This usually starts
            # the native player faster and closer to DPlex/TMDb Helper.
            # v3.9.71: full diagnostic wrap around the play handoff. If
            # anything inside _play_with_context raises, the user gets a
            # textviewer dialog with the full traceback instead of a
            # silent crash before playback. Same pattern that exposed
            # the v3.9.62 "ADDON not defined" bug in collection import.
            # v4.7.8: reverted the 4.7.5 resolve-abort here for the same
            # reason as the play-dispatch site — declaring the item unplayable
            # made Kodi's Playlist Player skip it.
            try:
                # Fast DPlex-style handoff: do not add an artificial delay
                # between closing the source picker and resolving the item.
                _play_with_context(ctx, chosen_key, fallback_keys=[], use_resolved_url=use_resolved)
            except Exception as _play_exc:
                import traceback as _tb
                _trace = _tb.format_exc()
                try:
                    xbmc.log('[DexHub] _play_with_context CRASHED before playback:\n%s' % _trace, xbmc.LOGERROR)
                except Exception:
                    pass
                try:
                    xbmcgui.Dialog().textviewer(
                        tr('Dex Hub — تعذّر بدء التشغيل'),
                        ('Crashed before playback could start.\n\n'
                         'Stream key: %s\nProvider: %s\nMedia: %s\n\n'
                         'Error:\n%s\n\n%s') % (
                            chosen_key or '?',
                            ctx.get('provider_name') or ctx.get('provider_id') or '?',
                            ctx.get('media_type') or '?',
                            str(_play_exc),
                            _trace,
                        ),
                    )
                except Exception:
                    pass
                # Still clear handoff flags so we don't bounce through TMDb Helper.
                _clear_tmdbh_transient()
                return
            # v3.9.32: skip endOfDirectory after ANY successful playback
            # start, not just the setResolvedUrl path. When invoked via
            # TMDb Helper handoff, calling endOfDirectory triggers Kodi
            # to re-render the directory we came from (TMDb Helper's
            # player route) — manifesting as a second TMDb Helper page
            # appearing the moment playback starts. Even when not from
            # TMDb Helper, after Player.play() has been called the
            # HANDLE no longer needs an endOfDirectory — Kodi's playback
            # flow doesn't depend on it. Previously only `use_resolved`
            # path returned early; now both paths do.
            # Clear the handoff flag pre-emptively so any later container
            # refresh from playback start doesn't bounce us back through
            # TMDb Helper either.
            _clear_tmdbh_transient()
            return
    else:
        _clear_tmdbh_transient()
        # TMDb Helper invokes this route through ResolvePath. Closing the
        # source picker without choosing a stream must complete that resolver
        # explicitly; otherwise Kodi waits for the Python invoker and reports
        # the parent TMDb Helper item as "is not playable".
        if HANDLE >= 0:
            try:
                xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
            except Exception:
                pass
    try:
        xbmcplugin.endOfDirectory(HANDLE, succeeded=True, updateListing=False, cacheToDisc=False)
    except Exception:
        pass



def _min_quality_required_rank():
    # v3.9.90: respect the active Quality Profile. When the user has
    # picked a preset (not Custom), the preset's min_quality wins over
    # the standalone min_quality setting.
    from .search.ranking import get_effective_min_quality, _min_quality_required_rank as _ranker_min_quality_required_rank
    raw = get_effective_min_quality(ADDON)
    return _ranker_min_quality_required_rank(raw)



# --- dexhub-406-patch ---
def _collapse_repeated_provider_rows(entries):
    """Drop rows the SAME provider returned more than once.

    A provider is queried with up to four candidate ids (imdb/tmdb/tvdb/
    kitsu). Bridge addons resolve every one of them to the same item and
    answer with the same streams, so each version arrives once per matched
    id. Two identical urls from the same addon are the same file by
    definition — there is no server, encode or access route in which they
    differ.

    Rows from DIFFERENT providers are deliberately left alone: the source
    window is an inventory, and two addons offering the same filename can
    still be genuinely different routes.

    Returns (kept, removed_count).
    """
    entries = list(entries or [])
    if len(entries) < 2:
        return entries, 0
    seen = set()
    kept = []
    removed = 0
    for entry in entries:
        provider = str(entry.get('provider_name_raw') or entry.get('addon') or '')
        url = str(entry.get('stream_url') or '').strip()
        info_hash = str(entry.get('info_hash') or '').strip().lower()
        key = None
        if url:
            key = ('u', provider, url)
        elif len(info_hash) >= 32:
            key = ('h', provider, info_hash, str(entry.get('file_idx') or 0))
        if key is not None and key in seen:
            removed += 1
            continue
        if key is not None:
            seen.add(key)
        kept.append(entry)
    return kept, removed


def _finalize_stream_entries(entries, resort=True, media_type='', canonical_id='', video_id=''):
    # --- dexhub-406-patch --- same provider, same url -> one row
    try:
        entries, _repeat_removed = _collapse_repeated_provider_rows(entries)
        if _repeat_removed:
            xbmc.log('[DexHub] collapsed %d repeated rows from the same provider '
                     '(multi-id scan)' % _repeat_removed, xbmc.LOGINFO)
    except Exception:
        pass
    # v3.9.198: collapse the same physical file arriving from several addons
    # (AIOStreams' union-find over filename / infoHash / size fingerprint).
    try:
        _mode = _dedup_mode()
        if _mode != 'off':
            _order = (ADDON.getSetting('source_priority_order') or '')
            entries, _removed = dedupe_stream_entries(
                entries, mode=_mode,
                priority=[p.strip().lower() for p in _order.split(',') if p.strip()])
    except Exception:
        pass
    preferred_source = _last_source_choice(media_type, canonical_id, video_id)
    from .search.ranking import source_settings
    return _rank_finalize_stream_entries(entries, source_settings(ADDON), preferred_source=preferred_source, resort=resort)



def _kodi_header_string(headers):
    """Return Kodi's URL header suffix from a dict/list of HTTP headers."""
    if not headers:
        return ''
    pairs = []
    try:
        if isinstance(headers, dict):
            iterable = headers.items()
        elif isinstance(headers, (list, tuple)):
            iterable = headers
        else:
            iterable = []
        for key, value in iterable:
            key = str(key or '').strip()
            if not key or value in (None, ''):
                continue
            pairs.append((key, str(value)))
    except Exception:
        pairs = []
    if not pairs:
        return ''
    try:
        return urlencode(pairs)
    except Exception:
        return '&'.join('%s=%s' % (quote_plus(k), quote_plus(v)) for k, v in pairs)


def _stream_row_request_headers(row):
    """Extract request headers from Stremio stream rows.

    Stremio aggregators-style addons can attach headers either at the top
    level (`requestHeaders`) or under `behaviorHints.proxyHeaders.request`.
    Kodi needs those encoded after a `|` suffix on the playable URL.
    """
    if not isinstance(row, dict):
        return {}
    out = {}

    def _merge(value):
        if not value:
            return
        try:
            if isinstance(value, dict):
                iterator = value.items()
            elif isinstance(value, (list, tuple)):
                iterator = value
            else:
                return
            for k, v in iterator:
                k = str(k or '').strip()
                if k and v not in (None, ''):
                    out[k] = str(v)
        except Exception:
            pass

    _merge(row.get('requestHeaders'))
    _merge(row.get('headers'))
    hints = row.get('behaviorHints') or {}
    if isinstance(hints, dict):
        _merge(hints.get('requestHeaders'))
        proxy_headers = hints.get('proxyHeaders') or {}
        if isinstance(proxy_headers, dict):
            _merge(proxy_headers.get('request'))
            # Some implementations put the request headers directly under
            # proxyHeaders instead of nesting them under "request".
            if not any(k in proxy_headers for k in ('request', 'response')):
                _merge(proxy_headers)
    return out


def _apply_kodi_request_headers(url, row):
    url = str(url or '').strip()
    if not url:
        return ''
    # Plugin URLs should receive their own query params, not Kodi pipe headers.
    if url.lower().startswith('plugin://'):
        return url
    headers = _stream_row_request_headers(row)
    suffix = _kodi_header_string(headers)
    if not suffix:
        return url
    if '|' in url:
        base, existing = url.split('|', 1)
        if existing:
            return base + '|' + existing + '&' + suffix
        return base + '|' + suffix
    return url + '|' + suffix


def _torrent_handoff_url(magnet):
    """Return a Kodi plugin handoff URL for a magnet when a torrent player exists."""
    magnet = str(magnet or '').strip()
    if not magnet:
        return ''
    # Elementum is the most common Kodi torrent player and understands the
    # Stremio-style magnet handoff reliably. Quasar uses a compatible route.
    for addon_id, template in (
        ('plugin.video.elementum', 'plugin://plugin.video.elementum/play?uri=%s'),
        ('plugin.video.quasar', 'plugin://plugin.video.quasar/play?uri=%s'),
        # Torrest route support varies by build, but this is harmless when
        # installed and gives users another local torrent player option.
        ('plugin.video.torrest', 'plugin://plugin.video.torrest/play_magnet?magnet=%s'),
    ):
        try:
            # the skin condition first: Addon() on a missing add-on logs an
            # EXCEPTION line in kodi.log
            if not xbmc.getCondVisibility('System.HasAddon(%s)' % addon_id):
                continue
            xbmcaddon.Addon(addon_id)
            return template % quote_plus(magnet)
        except Exception:
            continue
    # Kodi cannot natively resolve magnets, but returning the magnet keeps the
    # source visible and lets any external/magnet handler attempt playback.
    return magnet


def _magnet_from_stream_row(row):
    if not isinstance(row, dict):
        return ''
    raw_url = str(row.get('url') or '').strip()
    if raw_url.lower().startswith('magnet:'):
        return raw_url
    hints = row.get('behaviorHints') or {}
    if not isinstance(hints, dict):
        hints = {}
    info_hash = (
        row.get('infoHash') or row.get('infohash') or row.get('btih') or
        hints.get('infoHash') or hints.get('infohash') or hints.get('btih') or ''
    )
    info_hash = re.sub(r'[^A-Fa-f0-9]', '', str(info_hash or '')).strip()
    if len(info_hash) not in (32, 40):
        return ''
    name = (
        row.get('title') or row.get('name') or row.get('filename') or
        hints.get('filename') or hints.get('title') or hints.get('name') or
        'DexHub torrent'
    )
    trackers = []
    for value in (row.get('sources') or hints.get('sources') or []):
        text = str(value or '').strip()
        if not text:
            continue
        if text.lower().startswith(('tracker:', 'dht:', 'udp://', 'http://', 'https://')):
            text = re.sub(r'^(tracker:|dht:)', '', text, flags=re.I).strip()
            if text.lower().startswith(('udp://', 'http://', 'https://')):
                trackers.append(text)
    magnet = 'magnet:?xt=urn:btih:%s&dn=%s' % (info_hash, quote_plus(str(name or 'DexHub torrent')))
    for tr_url in trackers[:30]:
        magnet += '&tr=%s' % quote_plus(tr_url)
    try:
        file_idx = row.get('fileIdx') if row.get('fileIdx') not in (None, '') else row.get('fileIndex')
        if file_idx in (None, ''):
            file_idx = hints.get('fileIdx') if hints.get('fileIdx') not in (None, '') else hints.get('fileIndex')
        if file_idx not in (None, ''):
            # Stremio/Torrentio fileIdx is 0-based. Elementum accepts `so` as
            # the selected file index in the magnet query.
            magnet += '&so=%s' % quote_plus(str(file_idx))
    except Exception:
        pass
    return magnet


def _stream_play_url_from_row(row):
    """Normalize a Stremio stream row into something Kodi can play.

    Important: do NOT use `externalUrl` as a fallback playable URL. In the
    Stremio stream schema it is usually an external webpage/intent, while
    `url` is the direct playable stream and `infoHash`/`fileIdx` is the torrent
    stream shape. Treating externalUrl as video is why Torrentio/AIOStreams
    rows could appear in Dex Hub but fail at playback.
    """
    if not isinstance(row, dict):
        return ''
    url = str(row.get('url') or '').strip()
    if url.lower().startswith('magnet:'):
        return _torrent_handoff_url(url)
    if url:
        return _apply_kodi_request_headers(url, row)
    magnet = _magnet_from_stream_row(row)
    if magnet:
        return _torrent_handoff_url(magnet)
    # Some Stremio/Nuvio-compatible addons return playable resolver links only
    # in externalUrl. Keep direct media, plugin, and manifest-resolver URLs;
    # reject ordinary webpages/configuration links.
    external = str(row.get('externalUrl') or '').strip()
    low = external.lower()
    if low.startswith(('plugin://', 'magnet:')):
        return _torrent_handoff_url(external) if low.startswith('magnet:') else external
    if low.startswith(('http://', 'https://')):
        path = low.split('?', 1)[0]
        media_exts = ('.m3u8', '.mp4', '.mkv', '.webm', '.ts', '.avi', '.mov', '.mpd')
        resolver_markers = ('/stream/', '/play/', '/resolve/', '/redirect/', 'video=', 'url=')
        blocked = ('/configure', '/settings', '/install', '/manifest.json')
        if not any(x in low for x in blocked) and (path.endswith(media_exts) or any(x in low for x in resolver_markers)):
            return _apply_kodi_request_headers(external, row)
    return ''



_APPEND_LEDGER = {}
_APPEND_LEDGER_LOCK = threading.Lock()


def _prune_append_ledger():
    """Keep the dedupe ledger bounded under reuselanguageinvoker.

    Keyed by id(entries), so a list that has been garbage-collected leaves a
    stale entry behind. The scan holds at most a couple of live lists, so
    trimming to the newest few is both safe and enough.
    """
    with _APPEND_LEDGER_LOCK:
        if len(_APPEND_LEDGER) <= 8:
            return
        for key in list(_APPEND_LEDGER)[:-4]:
            _APPEND_LEDGER.pop(key, None)


def _is_aiostreams_provider(provider):
    """Identify an AIOStreams manifest without depending on its display name."""
    provider = provider or {}
    manifest = provider.get('manifest') or {}
    values = (
        manifest.get('id'), manifest.get('name'), manifest.get('logo'),
        provider.get('name'), provider.get('manifest_url'), provider.get('base_url'),
    )
    blob = ' '.join(str(value or '') for value in values).lower()
    return ('com.aiostreams.' in blob or 'viren070/aiostreams' in blob or
            'aiostreams.' in blob)



def _aio_info_lines(text):
    """v5.10.203: the lines of an AIOStreams description worth a row: not the
    title line (the page already names the title), the file path or a
    message, which a formatter often puts first or last."""
    lines = [line for line in str(text or '').splitlines() if line.strip()]
    keep = [line for line in lines
            if not line.lstrip().startswith(('\U0001f3ac', '\U0001f4c1', '\U0001f4c2', '\u2139'))]
    return keep or lines


def _source_left_out(provider):
    """v5.10.203: an add-on the user left out of the source search."""
    try:
        from .source_addons import skipped, key
        return key(provider) in skipped()
    except Exception:
        return False


def _library_state(row):
    """v5.10.204: the source is already in the user's library."""
    try:
        from .source_details import library_state
        return library_state(row)
    except Exception:
        return False


def _ready_state(row, facts):
    """v5.10.203: cached (True), not cached (False) or unknown (None)."""
    try:
        from .source_details import ready_state
        return ready_state(row, facts)
    except Exception:
        return None


def _upstream_formatter_text(value, max_lines=8, max_chars=1600):
    """Keep AIO's line structure/emojis while bounding Kodi ListItem payloads."""
    lines = []
    for raw in str(value or '').replace('\r', '').split('\n')[:max_lines]:
        line = MULTI_WS_RE.sub(' ', raw).strip()
        if line:
            lines.append(line)
    return '\n'.join(lines)[:max_chars]


def _provider_position(provider):
    """v5.10.292: the add-on's place in the Sources list (Nuvio's order)."""
    try:
        from .dexhub import store as _store_mod
        want = {str((provider or {}).get(k) or '').strip().lower()
                for k in ('id', 'base_url', 'manifest_url', 'transport_url')} - {''}
        for index, row in enumerate(_store_mod.list_providers() or []):
            have = {str((row or {}).get(k) or '').strip().lower()
                    for k in ('id', 'base_url', 'manifest_url', 'transport_url')} - {''}
            if want & have:
                return index
    except Exception:
        pass
    return 9999


def _append_stream_entries_from_data(entries, data, provider, request_id, media_type, canonical_id, best_meta, art, bg, ids, title='', video_id=None, season=None, episode=None, show_title='', resume_seconds=0.0, resume_percent=0.0):
    provider_name = provider.get('name') or 'Provider'
    _provider_is_aiostreams = _is_aiostreams_provider(provider)
    _provider_safe_origin = _provider_origin(provider)
    _provider_identity_art = provider_art(
        provider_name,
        provider.get('manifest') or {},
        provider.get('base_url') or provider.get('manifest_url') or '',
    )
    _provider_icon = (_provider_identity_art.get('icon') or
                      _provider_identity_art.get('thumb') or media_path('provider.png'))
    # Self-hosted/rebranded AIOStreams manifests can omit their logo.  Use a
    # bundled official mark in that case so a custom name such as Dexstreams
    # does not fall back to Dex Hub's anonymous provider glyph.
    if (_provider_is_aiostreams and
            _provider_icon == media_path('provider.png')):
        _provider_icon = media_path('provider_aiostreams.png')
    raw_streams = (data or {}).get('streams') or []
    # Be liberal with non-standard addons that return a single stream object
    # instead of a list. More importantly, never turn a multi-version response
    # into a provider-level singleton.
    if isinstance(raw_streams, dict):
        raw_streams = [raw_streams]
    elif not isinstance(raw_streams, (list, tuple)):
        raw_streams = []
    # v5.10.15: idempotency guard. The 5.10.14 kodi.log shows every provider
    # appended TWICE with an identical request id ("collapsed 1/2/4/6/8
    # repeated rows from the same provider"), because the foreground scan and
    # the live-refresh worker can both process the same completion. Collapsing
    # afterwards still paid the full cost: JSON walk, ranking, artwork, UI.
    # `entries` is the one object both phases share, so the ledger lives on it
    # and a payload can be appended at most once per scan.
    _dedupe_key = '%s|%s|%s' % (
        str(provider.get('id') or provider.get('base_url')
            or provider.get('manifest_url') or provider_name or ''),
        str(request_id or ''), str(len(raw_streams)))
    try:
        _seen = _APPEND_LEDGER.setdefault(id(entries), set())
        if _dedupe_key in _seen:
            xbmc.log('[DexHub] duplicate append suppressed: provider=%s request=%s rows=%d'
                     % (provider_name, request_id, len(raw_streams)), xbmc.LOGINFO)
            return
        _seen.add(_dedupe_key)
        if len(_APPEND_LEDGER) > 8:
            _prune_append_ledger()
    except Exception:
        pass
    try:
        xbmc.log('[DexHub] Stremio raw streams: provider=%s request=%s rows=%d' % (
            provider_name, request_id, len(raw_streams)), xbmc.LOGINFO)
    except Exception:
        pass
    _before_provider_rows = len(entries)
    _dropped_no_url = 0
    _addon_pos = _provider_position(provider)
    # Read the user template once per provider response, never on focus or
    # selection changes. The formatter itself caches the parsed template.
    try:
        _formatter_enabled = str(_setting(
            'enable_source_formatter', 'true')).strip().lower() in (
                '1', 'true', 'yes', 'on')
        _follow_aio_formatter = str(_setting(
            'follow_aiostreams_formatter', 'true')).strip().lower() in (
                '1', 'true', 'yes', 'on')
        _formatter_template = (_setting('source_formatter_template', '') or
                               _source_formatter.DEFAULT_TEMPLATE)
    except Exception:
        _formatter_enabled = False
        _follow_aio_formatter = False
        _formatter_template = ''
    from . import source_diagnostics as _diag
    _batch_kodi_info = None
    _batch_year = None
    for _row_index, row in enumerate(raw_streams):
        _row_started = time.monotonic()
        _diag.trace('row-start', _row_index)
        stream_url = _stream_play_url_from_row(row)
        if not stream_url:
            # v3.9.262: a row with no url/magnet/infoHash is unplayable and is
            # skipped — but count and LOG it, so "addon returned 3, Dex shows 1"
            # can be diagnosed from kodi.log instead of guessed at.
            _dropped_no_url += 1
            # v4.7.5: this fired 486 times in ONE session of the user's log.
            # Per-row detail is a DEBUG concern and the per-provider summary
            # below keeps the diagnostic value at INFO; on ARM boxes the write
            # volume itself costs frame time during a source scan.
            try:
                if _dropped_no_url <= 3:
                    xbmc.log('[DexHub] Stremio row dropped (no playable url): provider=%s name=%r external=%r keys=%s' % (
                        provider_name, (row.get('name') or row.get('title') or '')[:60],
                        bool(row.get('externalUrl')), sorted(list(row.keys()))[:12]), xbmc.LOGINFO)
            except Exception:
                pass
            continue
        facts = _stream_facts(
            row, provider_name, provider_origin=_provider_safe_origin)
        _diag.trace('facts-ready', _row_index, _row_started)
        _aio_name = ''
        _aio_description = ''
        _aio_preview = ''
        if (_formatter_enabled and _follow_aio_formatter and
                _provider_is_aiostreams):
            # AIOStreams has already applied the formatter selected in its
            # configuration page. Consume that output instead of trying to
            # retrieve private user configuration or evaluate it a second
            # time. The next stream request therefore follows every saved AIO
            # formatter change automatically and adds zero network calls.
            _aio_name = _upstream_formatter_text(row.get('name'), max_lines=2,
                                                  max_chars=240)
            _aio_description = _upstream_formatter_text(row.get('description'))
            if _aio_name:
                facts['display_name'] = '  '.join(_aio_name.splitlines())
            if _aio_description:
                _aio_preview = '  •  '.join(
                    _aio_info_lines(_aio_description)[:2])[:420]
        elif _formatter_enabled and _formatter_template:
            try:
                _formatted_identity = _source_formatter.render(
                    _formatter_template, row, facts)
                if _formatted_identity:
                    facts['source_identity_line'] = _formatted_identity
            except Exception:
                # A malformed custom preset must never hide or drop a stream.
                pass
        label, label2, plot = _stream_label(
            row, provider_name, facts=facts)
        _diag.trace('formatter-ready', _row_index, _row_started)
        display_name = facts['display_name']
        size = facts['size']
        video_bits = facts['video_bits']
        audio_bits = facts['audio_bits']
        quality, highlight = _quality_badge(video_bits)
        # Do not collapse exact URLs or matching name/size fingerprints.
        # The user explicitly wants every row from every addon/server.
        if _batch_kodi_info is None:
            _batch_kodi_info = _stream_meta_info_payload(
                best_meta, media_type=media_type,
                title=(title or best_meta.get('name') or canonical_id),
                show_title=(show_title or best_meta.get('name') or canonical_id),
                season=season, episode=episode,
            )
            _batch_year = _meta_info(best_meta).get('year') or 0
        _kodi_info = dict(_batch_kodi_info)
        _studio_prop = _kodi_info.get('studio') or ''
        _genre_prop = _kodi_info.get('genre') or ''
        if isinstance(_studio_prop, (list, tuple)):
            _studio_prop = ' / '.join([str(x) for x in _studio_prop if x])
        if isinstance(_genre_prop, (list, tuple)):
            _genre_prop = ' / '.join([str(x) for x in _genre_prop if x])
        payload = {
            'media_type': media_type,
            'canonical_id': canonical_id,
            'video_id': video_id or request_id,
            'provider_name': provider_name,
            'provider_id': provider.get('id') or '',
            # Stable scan target used by same-source next episode. Native
            # playback rewrites provider_id to plex_native/emby_native below,
            # while this field deliberately keeps __plex__/__emby__.
            'source_provider_id': provider.get('id') or '',
            'source_addon': facts.get('addon') or provider_name,
            'source_indexer': facts.get('indexer') or '',
            'source_service': facts.get('service') or '',
            'source_origin': facts.get('origin_line') or provider_name,
            'provider_origin': _provider_safe_origin,
            'provider_domain': facts.get('provider_domain') or '',
            'addon_url': facts.get('addon_url') or '',
            'addon_domain': facts.get('addon_domain') or '',
            'title': title or best_meta.get('name') or canonical_id,
            'show_title': show_title or best_meta.get('name') or canonical_id,
            'year': _batch_year,
            'stream_url': stream_url,
            'poster': art.get('poster') or '',
            'background': bg,
            'clearlogo': art.get('clearlogo') or '',
            'tmdb_id': ids.get('tmdb_id') or '',
            'imdb_id': ids.get('imdb_id') or '',
            'tvdb_id': ids.get('tvdb_id') or '',
            'external_ids': ids,
            'kodi_info': _kodi_info,
            'plot': _kodi_info.get('plot') or best_meta.get('description') or best_meta.get('overview') or '',
            'genre': _genre_prop,
            'studio': _studio_prop,
            'rating': _kodi_info.get('rating') or best_meta.get('imdbRating') or '',
            'premiered': _kodi_info.get('premiered') or '',
            'duration': _kodi_info.get('duration') or '',
            'cast': _kodi_info.get('cast') or [],
            'subtitles': row.get('subtitles') or [],
            'behaviorHints': row.get('behaviorHints') or {},
            'binge_group': ((row.get('behaviorHints') or {}).get('bingeGroup')
                            if isinstance(row.get('behaviorHints') or {}, dict)
                            else '') or '',
            'source_type': (facts.get('source_type') or ('', '', ''))[0],
            'provider_base_url': provider.get('base_url') or '',
            'duration_ms': int((((row.get('behaviorHints') or {}).get('plexDuration') or (row.get('behaviorHints') or {}).get('durationMs') or 0)) or 0),
            'stream_name': row.get('name') or '',
            'stream_title': row.get('title') or '',
            'stream_description': row.get('description') or '',
            'formatter_tags': [],
            # v4.7.3: RAW stream text (AIOStreams formatter output with its
            # \u265b/emoji markers intact). User badges.json presets are
            # written against THIS text; the cleaned display name strips
            # the markers, so crown-gated rules could never match.
            'badge_blob_raw': ' | '.join(_collect_stream_texts(row))[:4096],
            # AIOStreams already formatted the description. source_info keeps
            # it for the details panel; duplicating it as another list property
            # only makes every row heavier and triggers a second badge scan.
            'formatter_summary': '',
            'video_bits': facts.get('video_bits') or [],
            'audio_bits': facts.get('audio_bits') or [],
            'request_headers': _stream_row_request_headers(row),
            'external_url': row.get('externalUrl') or '',
            'info_hash': (row.get('infoHash') or row.get('infohash') or ((row.get('behaviorHints') or {}) if isinstance(row.get('behaviorHints') or {}, dict) else {}).get('infoHash') or ''),
        }
        # A Stremio episode request is made with the series identity, so keep
        # that identity explicit before any native source row replaces the
        # item's generic ids with episode-level ids.
        if season not in (None, '', 0, '0') and episode not in (None, '', 0, '0'):
            payload['show_imdb_id'] = _normalize_imdb_id(ids.get('imdb_id')) or ''
            payload['show_tmdb_id'] = str(ids.get('tmdb_id') or '')
            payload['show_tvdb_id'] = str(ids.get('tvdb_id') or '')
        # Native Plex/Emby rows carry their direct progress and identity
        # context in behaviorHints. Copy it to the playback session so external
        # subtitle addons receive the full IDs and companion reporting does not
        # fall back to a generic Stremio row.
        _hints = row.get('behaviorHints') or {}
        if isinstance(_hints, dict) and _hints.get('nativeProvider'):
            payload['provider_id'] = '%s_native' % str(_hints.get('nativeProvider'))
            payload['server_type'] = str(_hints.get('serverType') or _hints.get('nativeProvider') or '')
            payload['server_url'] = str(_hints.get('serverUrl') or '')
            payload['server_id'] = str(_hints.get('serverId') or '')
            payload['token'] = str(_hints.get('token') or '')
            payload['rating_key'] = str(_hints.get('ratingKey') or '')
            payload['item_id'] = str(_hints.get('itemId') or '')
            payload['media_source_id'] = str(_hints.get('mediaSourceId') or '')
            payload['part_key'] = str(_hints.get('partKey') or '')
            payload['duration_ms'] = int(_hints.get('durationMs') or payload.get('duration_ms') or 0)
            payload['imdb_id'] = _normalize_imdb_id(_hints.get('imdbId') or payload.get('imdb_id')) or payload.get('imdb_id') or ''
            payload['tmdb_id'] = str(_hints.get('tmdbId') or payload.get('tmdb_id') or '')
            payload['tvdb_id'] = str(_hints.get('tvdbId') or payload.get('tvdb_id') or '')
            payload['show_imdb_id'] = _normalize_imdb_id(
                _hints.get('showImdbId') or payload.get('show_imdb_id')) or payload.get('show_imdb_id') or ''
            payload['show_tmdb_id'] = str(
                _hints.get('showTmdbId') or payload.get('show_tmdb_id') or '')
            payload['show_tvdb_id'] = str(
                _hints.get('showTvdbId') or payload.get('show_tvdb_id') or '')
            payload['external_ids'] = {
                'imdb_id': payload.get('imdb_id') or '',
                'tmdb_id': payload.get('tmdb_id') or '',
                'tvdb_id': payload.get('tvdb_id') or '',
                'show_imdb_id': payload.get('show_imdb_id') or '',
                'show_tmdb_id': payload.get('show_tmdb_id') or '',
                'show_tvdb_id': payload.get('show_tvdb_id') or '',
            }

        if season is not None:
            payload['season'] = int(season)
        if episode is not None:
            payload['episode'] = int(episode)
        try:
            rs = float(resume_seconds or 0.0)
        except Exception:
            rs = 0.0
        if rs > 1.0:
            payload['resume_seconds'] = rs
        try:
            rp = float(resume_percent or 0.0)
        except Exception:
            rp = 0.0
        if rp > 1.0 and rp < 95.0:
            payload['resume_percent'] = rp
        cache_key = cache_store.put('stream', payload)
        _diag.trace('cache-written', _row_index, _row_started)
        _row_tags = facts.get('tags') or {}
        _stype, _stype_label, _stype_color = facts.get('source_type') or (
            ('direct',) + _SOURCE_TYPE_STYLES['direct'])
        _source_details = _source_info_text(
            row, provider_name, facts=facts,
            provider_origin=_provider_safe_origin)
        if _aio_description:
            _source_details = '%s\n\n%s' % (_aio_description, _source_details)
        entries.append({
            'stream_key': cache_key,
            # v5.10.292: where the add-on put it (Like Nuvio order)
            '_addon_pos': _addon_pos,
            '_addon_row': _row_index,
            # --- dexhub-406-patch --- identity for same-provider collapsing
            'stream_url': stream_url,
            # v4.1.0: source-type chip (usenet/debrid/torrent/direct/server)
            'source_type': _stype,
            'source_type_label': _stype_label,
            'source_type_color': _stype_color,
            'name': display_name,
            'label2': label2,
            'count': '00.',
            'quality': quality,
            'highlight': highlight,
            'provider': facts.get('provider_badge') or _provider_badge(
                row, provider_name, text_blob=facts.get('_raw_blob') or ''),
            'provider_name_raw': provider_name,
            'binge_group': ((_hints.get('bingeGroup') if isinstance(_hints, dict)
                             else '') or ''),
            'source_addon': facts.get('addon') or provider_name,
            'source_indexer': facts.get('indexer') or '',
            'source_service': facts.get('service') or '',
            'provider_icon': _provider_icon,
            'addon': facts.get('addon') or provider_name,
            'provider_domain': facts.get('provider_domain') or '',
            'provider_url': _provider_safe_origin,
            'addon_url': facts.get('addon_url') or '',
            'addon_domain': facts.get('addon_domain') or '',
            'source_site': facts['site'],
            'indexer': facts.get('indexer') or '',
            'service_name': facts.get('service') or '',
            'origin_line': facts.get('origin_line') or provider_name,
            'source_identity_line': (facts.get('source_identity_line') or
                                     facts.get('origin_line') or provider_name),
            'upstream_formatter_preview': _aio_preview,
            'upstream_formatter_text': _aio_description,
            # v5.10.297: the add-on's own row text, shown as Nuvio shows it
            'stream_name_raw': str(row.get('name') or '')[:400],
            'stream_desc_raw': str(row.get('description') or row.get('title') or '')[:900],
            'stream_video_size': ((row.get('behaviorHints') or {}).get('videoSize') if isinstance(row.get('behaviorHints'), dict) else '') or '',
            'cached': _ready_state(row, facts),
            'in_library': _library_state(row),
            'size_label': size or '--',
            'extraInfo': ' | '.join(video_bits[:8]) if video_bits else '--',
            'extraInfo2': ' | '.join(audio_bits[:8]) if audio_bits else '--',
            'badges': _stream_badges(video_bits, audio_bits, row.get('subtitles') or []),
            'source_info': _source_details + '\n\n' + plot,
            # v3.9.198: identity fields for the AIOStreams-style deduplicator.
            'filename': str((row.get('behaviorHints') or {}).get('filename') or ''),
            'info_hash': str(row.get('infoHash') or row.get('infohash') or
                             (row.get('behaviorHints') or {}).get('infoHash') or ''),
            'file_idx': (row.get('fileIdx') if row.get('fileIdx') is not None
                         else (row.get('behaviorHints') or {}).get('fileIdx')) or 0,
            'size_bytes': _extract_size(
                (row.get('behaviorHints') or {}).get('videoSize'),
                row.get('size'), row.get('sizebytes')) or 0,
            'video_codec': facts.get('codec') or '',
            'audio': facts.get('audio') or '',
            'hdr': facts.get('hdr') or '',
            # v3.9.199: the AIOStreams-grade fact set, parsed from the raw title.
            'tags': _row_tags,
            'languages': _row_tags.get('languages') or [],
            'tag_line': stream_tag_line(_row_tags,
                                        size_label=facts.get('size') or '',
                                        provider=facts.get('addon') or provider_name),
        })
        _diag.trace('row-ready', _row_index, _row_started)
    # Publish the growing index once per provider, not once per result.
    try:
        _publish_last_streams_index(canonical_id, season, episode, entries, poster=art.get('poster') or '')
    except Exception:
        pass
    try:
        xbmc.log('[DexHub] Stremio appended streams: provider=%s raw=%d kept=%d dropped_no_url=%d' % (
            provider_name, len(raw_streams), len(entries) - _before_provider_rows, _dropped_no_url), xbmc.LOGINFO)
    except Exception:
        pass



def _provider_signature_text(provider):
    manifest = (provider or {}).get('manifest') or {}
    return ' '.join([
        str((provider or {}).get('name') or ''),
        str((provider or {}).get('base_url') or ''),
        str((provider or {}).get('manifest_url') or ''),
        str((provider or {}).get('id') or ''),
        str(manifest.get('name') or ''),
        str(manifest.get('id') or ''),
        str(manifest.get('description') or ''),
    ]).lower()


def _stream_timeout_for_provider(provider):
    """Return a bounded timeout for a normal Stremio addon.

    Every installed manifest follows the same provider path. Aggregators such
    as AIOStreams are no longer called through a private/direct API. Their
    configured manifest URL is queried exactly like any other Stremio addon.
    """
    sig = _provider_signature_text(provider)
    try:
        base = int(float(ADDON.getSetting('timeout') or '20'))
    except Exception:
        base = 20
    if any(token in sig for token in ('torrentio', 'comet', 'mediafusion', 'stremthru', 'aiostream')):
        # v5.10.26: 10-25s let one slow aggregator pin a streams-lane worker
        # for the whole scan. 8-12s still covers Torrentio/Comet cold hits.
        return max(8, min(max(base, 8), 12))
    return fast_timeout('stream')


def _setting_bool(name, default=False):
    try:
        raw = (ADDON.getSetting(name) or ('true' if default else 'false')).strip().lower()
    except Exception:
        raw = 'true' if default else 'false'
    return raw in ('true', '1', 'yes', 'on')


def _server_client(backend):
    if backend == 'jellyfin':
        return jellyfin_client
    if backend == 'plex':
        return plex_client
    if backend == 'silo':
        return silo_client
    return emby_client


def _server_stream_rows(backend, server, ids, media_type, titles,
                        season=None, episode=None, titles_loader=None, year=''):
    """ONE lookup for both servers: ID first, titles only as a fallback.

    v3.9.218 — the unified path the user asked for.

    Emby worked because it was asked by ID (AnyProviderIdEquals). Plex was
    asked by TITLE — and an Arabic title can never match an English library,
    let alone the literal string "الحلقة 16". Both servers now take the same
    route through the same code:

        1. every ID we hold (imdb / tmdb / tvdb) -> find_all_by_ids
        2. only if that finds nothing, the title variants
        3. every hit is verified against the IDs before it is trusted

    Whatever comes back is a normal Dex Hub source row, so the servers ARE
    sources — ranked, badged, switchable and resumable like any other.
    """
    client = _server_client(backend)
    identity = MediaIdentity(media_type=media_type, ids=ids, title=(titles or [''])[0],
                             titles=titles, season=season, episode=episode)
    ids = identity.ids
    series = identity.is_episode
    kind = identity.media_type

    # v3.9.225: the server step gets its OWN budget. It used to run inside the
    # shared source scan with no ceiling of its own, so a slow Plex server
    # starved the Stremio addons until they timed out and were blacklisted.
    # Failure accounting is suspended for the duration: a provider must only
    # ever be penalised for its own failures.
    _budget = _get_int_setting('server_lookup_seconds', 7, minimum=4, maximum=60)
    _deadline = time.time() + float(_budget)
    try:
        from .dexhub.client import provider_health_pause
        provider_health_pause(_budget + 2)
    except Exception:
        pass

    matches, seen = [], set()

    def _take(rows):
        for row in (rows or []):
            key = str(row.get('rating_key') or '')
            if key and key not in seen:
                seen.add(key)
                matches.append(row)

    # v5.10.27: every request inside this step is capped at the step budget,
    # so a single hung request can no longer outlive it.
    _bounded = (plex_client.bounded_timeout if backend == 'plex'
                else emby_client.bounded_timeout)
    _per_request = max(3, min(int(_budget), 6))

    # 1) BY ID — the only lookup that survives a translated library
    try:
        with _bounded(_per_request):
            options = {'year': year} if backend == 'jellyfin' else {}
            _take(client.find_all_by_ids(server, ids, media_type=kind, title='', limit=24, **options))
    except Exception as exc:
        xbmc.log('[DexHub] %s id lookup failed: %s' % (backend, exc), xbmc.LOGWARNING)
        # v5.10.91: a timed-out id lookup is a slow server, not an empty one.
        if isinstance(exc, TimeoutError) or 'timed out' in str(exc).lower():
            try:
                if not server.get('_stop_reason'):
                    server['_stop_reason'] = 'deadline'
            except Exception:
                pass

    # v5.10.91: the stop signal installed by the source scan (cancelled when
    # the user picks a source, or past the server's time limit). Emby,
    # Jellyfin and Silo lookups never polled it, so a show with many copies
    # kept resolving episodes after playback had started.
    _stop_signal = (server or {}).get('_should_stop') if isinstance(server, dict) else None

    def _stopped(where):
        if _stop_signal is None:
            return False
        try:
            if _stop_signal():
                if not server.get('_stop_logged'):
                    server['_stop_logged'] = True
                    xbmc.log('[DexHub] %s lookup stopped at %s: search cancelled or over budget (%s)'
                             % (backend, where, server.get('name') or '?'), xbmc.LOGINFO)
                return True
        except Exception:
            pass
        return False

    # 2) BY TITLE. Jellyfin tries local names first: remote enrichment only
    # follows an actual miss, inside this worker's existing time budget.
    def _title_candidates():
        nonlocal titles
        if backend != 'jellyfin' and titles_loader is not None:
            try:
                titles = titles_loader() or titles
            except Exception:
                pass
        used = set()
        for candidate in (titles or []):
            value = str(candidate or '').strip()
            if backend == 'jellyfin' and re.fullmatch(r'(?:tt\d+(?::\d+){0,2}|(?:imdb|tmdb|tvdb):.*)', value, flags=re.I):
                continue
            if value and value.casefold() not in used:
                used.add(value.casefold())
                yield value
        if backend == 'jellyfin' and not matches and titles_loader is not None and time.time() < _deadline and not _stopped('title-enrichment'):
            try:
                loaded = titles_loader() or []
            except Exception:
                loaded = []
            for candidate in loaded:
                value = str(candidate or '').strip()
                if value and value.casefold() not in used and not re.fullmatch(r'(?:tt\d+(?::\d+){0,2}|(?:imdb|tmdb|tvdb):.*)', value, flags=re.I):
                    used.add(value.casefold())
                    titles = list(titles or []) + [value]
                    yield value

    if not matches and time.time() < _deadline:
        for title in _title_candidates():
            if not str(title or '').strip():
                continue
            if time.time() >= _deadline:
                xbmc.log('[DexHub] %s lookup: budget spent — stopping so the '
                         'Stremio providers keep their time' % backend, xbmc.LOGINFO)
                break
            if _stopped('title-search'):
                break
            try:
                with _bounded(_per_request):
                    options = {'year': year} if backend == 'jellyfin' else {}
                    _take(client.find_all_by_ids(server, ids, media_type=kind,
                                                 title=title, limit=24, **options))
            except Exception:
                continue
            # v3.9.222: do NOT stop at the first title that hits. A library
            # routinely holds the same film twice — once under its Arabic name
            # and once under its English one — and each copy is a real source.

    xbmc.log('[DexHub] %s lookup: server=%s ids=%s titles=%d -> %d item(s)'
             % (backend, server.get('name') or '?',
                ','.join('%s=%s' % (k, v) for k, v in sorted((ids or {}).items()) if v) or 'none',
                len(titles or []), len(matches)), xbmc.LOGINFO)
    if not matches:
        return []

    # 3) walk to the exact episode when needed
    items = []
    for index, match in enumerate(matches):
        if series and _stopped('episode-walk %d/%d' % (index, len(matches))):
            break
        if series:
            try:
                # v5.10.241: bounded like the title searches, so a scan the
                # user ended (a source chosen) stops here quickly
                with _bounded(_per_request):
                    row = client.episode_item(server, match, season, episode)
            except Exception:
                row = None
            if not row:
                continue
            if _stopped('episode-walk %d/%d' % (index, len(matches))):
                break
            # v5.10.91: Emby/Jellyfin return the episode WITH its MediaSources
            # and their MediaStreams (DETAIL_FIELDS), so the second request per
            # copy only re-read the same record. Plex and Silo keep the full
            # fetch: their episode listings omit the stream details.
            if backend in ('emby', 'jellyfin') and row.get('versions'):
                items.append(row)
                continue
            try:
                items.append(client.metadata(server, row.get('rating_key')))
            except Exception:
                items.append(row)
        else:
            items.append(match)
    return items


def _emby_stream_payload(provider, media_type):
    """Emby/Silo versions as normal Dex Hub source rows.

    Every MediaSource becomes a stream carrying its real file size, so ranking,
    badges, the switch-source index and resume all work with no special cases.
    """
    server = provider.get('_server') or {}
    backend = {'__silo__': 'silo', '__jellyfin__': 'jellyfin'}.get((provider or {}).get('id'), 'emby')
    client = _server_client(backend)
    brand = backend.upper()
    colour = 'FF7C3AED' if backend == 'silo' else EMBY_COLOR
    title = provider.get('_title') or ''
    from .search.native_titles import resolve as _native_titles
    titles = list(provider.get('_titles') or [])
    if title and title.casefold() not in [str(x).casefold() for x in titles]:
        titles.insert(0, title)
    if not titles and title:
        titles = [title]
    ids = provider.get('_ids') or {}
    season, episode = provider.get('_season'), provider.get('_episode')
    if not (ids.get('imdb_id') or ids.get('tmdb_id') or title):
        return {}
    series = _is_series_media(media_type) and season and episode
    items = _server_stream_rows(
        backend, server, ids, media_type, titles,
        season=season, episode=episode, year=provider.get('_year') or '',
        titles_loader=lambda: _native_titles(provider, media_type, _tmdb_direct))
    if not items:
        return {}
    server_name = server.get('name') or ('Silo' if backend == 'silo' else 'Emby')
    streams = []
    for item in items:
      for version in (item.get('versions') or []):
        url = client.playback_url(server, item.get('rating_key'),
                                       version.get('media_source_id') or '')
        fname = os.path.basename(version.get('file') or '') or (item.get('raw_title') or title)
        facts = ' '.join(x for x in (version.get('resolution'), version.get('hdr'),
                                     version.get('video_codec'), version.get('audio'),
                                     version.get('size_label')) if x)
        streams.append({
            'name': '[COLOR %s]%s NATIVE[/COLOR]\n%s' % (colour, brand, ' • '.join(x for x in (server_name, item.get('library_name')) if x)),
            'title': '%s\n%s' % (fname, facts),
            'url': url,
            'subtitles': list(version.get('subtitles') or []),
            'behaviorHints': {
                'filename': fname,
                'videoSize': version.get('size_bytes') or 0,
                'nativeProvider': backend,
                'serverType': backend,
                'serverUrl': server.get('url') or '',
                'serverId': str(server.get('id') or ''),
                'token': server.get('token') or '',
                'itemId': str(item.get('rating_key') or ''),
                'mediaSourceId': str(version.get('media_source_id') or ''),
                'imdbId': _normalize_imdb_id((item.get('ids') or {}).get('imdb_id')) or '',
                'tmdbId': str((item.get('ids') or {}).get('tmdb_id') or ''),
                'tvdbId': str((item.get('ids') or {}).get('tvdb_id') or ''),
                'showImdbId': _normalize_imdb_id(ids.get('imdb_id')) or '',
                'showTmdbId': str(ids.get('tmdb_id') or ''),
                'showTvdbId': str(ids.get('tvdb_id') or ''),
                'durationMs': int(item.get('duration_ms') or 0),
            },
        })
    return {'streams': streams}


def _plex_stream_payload(provider, media_type):
    """Built-in Plex source step (DPlex trakttokodi-style, v3.9.172).

    GUID-matches the current item on ONE server and returns every file
    version as a Stremio-shaped stream, so Plex copies flow through the
    normal source pipeline — ranking, badges, size parsing, the switch
    index and companion progress all apply with zero special cases.
    """
    server = provider.get('_server') or {}
    title = provider.get('_title') or ''
    from .search.native_titles import resolve as _native_titles
    titles = list(provider.get('_titles') or [])
    if title and title.casefold() not in [str(x).casefold() for x in titles]:
        titles.insert(0, title)
    if not titles and title:
        titles = [title]
    ids = provider.get('_ids') or {}
    wanted_year = str(provider.get('_year') or '').strip()
    season, episode = provider.get('_season'), provider.get('_episode')
    want_imdb = str(ids.get('imdb_id') or '').lower()
    want_tmdb = str(ids.get('tmdb_id') or '')
    want_tvdb = str(ids.get('tvdb_id') or '')
    if not title and not (want_imdb or want_tmdb or want_tvdb):
        return {}

    def _ids_match(it):
        iid = it.get('ids') or {}
        return ((want_imdb and str(iid.get('imdb_id') or '').lower() == want_imdb) or
                (want_tmdb and str(iid.get('tmdb_id') or '') == want_tmdb) or
                (want_tvdb and str(iid.get('tvdb_id') or '') == want_tvdb))

    # v3.9.218: the SAME lookup Emby uses — ID first, titles only as a
    # fallback. The 90 lines this replaces searched Plex by TITLE, which is
    # why an Arabic query never matched an English library and every server
    # answered 'no match' after 14 seconds.
    target_items = _server_stream_rows(
        'plex', server, ids, media_type, titles,
        season=season, episode=episode,
        titles_loader=lambda: _native_titles(provider, media_type, _tmdb_direct))

    if not target_items:
        xbmc.log('[DexHub] Plex Native no match: server=%s title=%s ids=%s' % (
            server.get('name') or '?', title,
            ','.join('%s=%s' % (key, ids.get(key))
                     for key in ('imdb_id', 'tmdb_id', 'tvdb_id') if ids.get(key)) or 'none'),
            xbmc.LOGWARNING)
        return {}
    server_name = server.get('name') or 'Plex'
    streams = []
    for target_item in target_items:
        try:
            item = plex_client.metadata(server, target_item.get('rating_key'))
        except Exception as exc:
            xbmc.log('[DexHub] Plex Native metadata failed: server=%s key=%s error=%s' % (
                server_name, target_item.get('rating_key') or '?', exc), xbmc.LOGWARNING)
            continue
        for version in (item.get('versions') or []):
            if not version.get('part_key'):
                continue
            try:
                url = plex_client.playback_url(item, part_key=version['part_key'])
            except Exception:
                continue
            fname = os.path.basename(version.get('file') or '') or (item.get('raw_title') or title)
            facts = ' '.join(x for x in (version.get('resolution'), version.get('hdr'),
                                         version.get('video_codec'), version.get('audio'),
                                         version.get('size_label')) if x)
            streams.append({
                'name': '[COLOR %s]PLEX NATIVE[/COLOR]\n%s' % (PLEX_COLOR, ' • '.join(x for x in (server_name, item.get('library_name')) if x)),
                'title': '%s\n%s' % (fname, facts),
                'url': url,
                'subtitles': list(version.get('subtitles') or []),
                'behaviorHints': {
                    'filename': fname,
                    'videoSize': version.get('size_bytes') or 0,
                    'nativeProvider': 'plex',
                    'serverType': 'plex',
                    'serverUrl': item.get('server_url') or server.get('url') or '',
                    'serverId': str(server.get('id') or ''),
                    'token': item.get('token') or server.get('token') or '',
                    'ratingKey': str(item.get('rating_key') or target_item.get('rating_key') or ''),
                    'partKey': str(version.get('part_key') or ''),
                    'imdbId': _normalize_imdb_id((item.get('ids') or {}).get('imdb_id')) or '',
                    'tmdbId': str((item.get('ids') or {}).get('tmdb_id') or ''),
                    'tvdbId': str((item.get('ids') or {}).get('tvdb_id') or ''),
                    'showImdbId': _normalize_imdb_id(ids.get('imdb_id')) or '',
                    'showTmdbId': str(ids.get('tmdb_id') or ''),
                    'showTvdbId': str(ids.get('tvdb_id') or ''),
                    'durationMs': int(item.get('duration_ms') or 0),
                },
            })
    return {'streams': streams}


def _fetch_stream_payload(target, media_type):
    from . import source_diagnostics as diagnostics
    handle = diagnostics.begin(target, media_type)
    result = None
    try:
        result = _fetch_stream_payload_inner(target, media_type)
        return result
    except Exception as exc:
        result = exc
        raise
    finally:
        diagnostics.finish(handle, result)


def _fetch_stream_payload_inner(target, media_type):
    from .search.source_engine import fetch
    return fetch(target, media_type, sys.modules[__name__])


# v5.10.15: the first candidate id is right for essentially every provider, so
# it stays a single request. Only a provider that answers EMPTY pays for the
# alternates, and it pays for them concurrently rather than one after another.
# Capped at three because that is what `_candidate_request_ids[:4]` can leave,
# and these threads only exist while a provider is already known to be missing.
_ALT_ID_MAX_PARALLEL = 3


def _fetch_alternate_ids_parallel(provider, media_type, alt_ids, timeout):
    """Try the remaining candidate ids at once; return the first with rows.

    Returns ``(payload, winning_id, last_exception)``. ``payload`` is None when
    no alternate produced any playable row. Threads are daemons and are joined
    only for the provider timeout, so a hung addon cannot extend the scan.
    """
    alt_ids = list(alt_ids or [])[:_ALT_ID_MAX_PARALLEL]
    if not alt_ids:
        return None, '', None
    results = {}
    lock = threading.Lock()

    def _one(index, rid):
        try:
            payload = _stremio_provider.fetch(
                provider, media_type, rid, timeout_override=timeout)
            rows = ((payload or {}).get('streams') or []) if isinstance(payload, dict) else []
            if isinstance(rows, dict):
                rows = [rows]
            if rows:
                with lock:
                    results[index] = (payload, rid)
        except Exception as exc:
            with lock:
                results.setdefault('exc', exc)

    threads = []
    for index, rid in enumerate(alt_ids):
        try:
            thread = threading.Thread(
                target=_one, args=(index, rid),
                name='DexHubAltId%d' % index, daemon=True)
            thread.start()
            threads.append(thread)
        except RuntimeError:
            # Out of threads: run this one inline rather than skipping the id.
            _one(index, rid)
    deadline = time.monotonic() + max(1.0, float(timeout or 0.0))
    for thread in threads:
        thread.join(max(0.0, deadline - time.monotonic()))
    with lock:
        hits = sorted(k for k in results if isinstance(k, int))
        if hits:
            # Candidate ids arrive pre-ranked, so the earliest index wins.
            payload, rid = results[hits[0]]
            xbmc.log('[DexHub] alternate id resolved: provider=%s id=%s (%d tried in parallel)'
                     % ((provider or {}).get('name') or '?', rid, len(alt_ids)), xbmc.LOGINFO)
            return payload, rid, None
        return None, '', results.get('exc')


def _native_payload_budgeted(provider, media_type, backend, budget_seconds):
    """Run a native Plex/Emby lookup under a wall-clock ceiling.

    Used only for servers the health router has marked cold. The worker is a
    daemon and is never joined past the budget, so a slow title scan cannot
    hold the source scan open; if it finishes late its result is simply
    discarded, exactly like the Plex discovery budget above.
    """
    out = {}

    def _worker():
        try:
            out['payload'] = (_plex_stream_payload(provider, media_type)
                              if backend == 'plex'
                              else _emby_stream_payload(provider, media_type))
        except Exception as exc:
            out['exc'] = exc

    try:
        thread = threading.Thread(
            target=_worker, name='DexHubColdNative', daemon=True)
        thread.start()
    except RuntimeError:
        # Out of threads: run inline rather than losing the server entirely.
        return (_plex_stream_payload(provider, media_type) if backend == 'plex'
                else _emby_stream_payload(provider, media_type))
    thread.join(max(0.5, float(budget_seconds or 0.0)))
    if thread.is_alive():
        xbmc.log('[DexHub] %s cold server exceeded its %.0fs budget — moving on'
                 % (backend, budget_seconds), xbmc.LOGINFO)
        # v5.10.91: tell the caller WHY there is nothing, so a lookup that ran
        # out of time is not recorded as a scan that found nothing. Asking the
        # stop signal once also flags the running worker to stop.
        reason = 'deadline'
        try:
            srv = (provider or {}).get('_server') or {}
            stop = srv.get('_should_stop')
            if stop is not None:
                stop()
            if srv.get('_stop_reason') == 'cancelled':
                reason = 'cancelled'
        except Exception:
            pass
        return {'streams': [], '_source_status': reason}
    if out.get('exc') is not None:
        raise out['exc']
    return out.get('payload') or {'streams': []}


def _source_parallel_workers(target_count=0):
    """Worker budget for stream-source scans.

    v3.9.87: CoreELEC boxes can hit "can't start new thread" when several
    plugin invokers, source refreshes and subtitle workers overlap. Keep source
    discovery parallel, but use a fixed 2-4 worker envelope.  Subtitle lookup
    now runs at the same time, so retaining the old six-stream-worker ceiling
    would recreate the CoreELEC thread spike through a different path.
    """
    try:
        base = int(float(ADDON.getSetting('parallel_workers') or parallel_workers() or 4))
    except Exception:
        try:
            base = int(parallel_workers() or 4)
        except Exception:
            base = 4
    workers = max(2, base)
    if target_count:
        workers = min(workers, max(1, int(target_count)))
    return max(1, min(4, workers))


def _source_quick_open_seconds():
    """How long to keep collecting after the first rows before opening UI.

    It is a short post-first-result grace; late providers continue through the
    live session refresh after the source window opens.
    """
    try:
        raw = float(ADDON.getSetting('streams_quick_open_seconds') or 0.3)
    except Exception:
        raw = 0.3
    # This is a post-first-result grace, not a minimum loading screen. The
    # settings UI allows 0.3s; honour it instead of silently clamping the
    # fast path. Providers keep filling the live source window afterwards.
    return max(0.3, min(raw, 4.0))


def _source_result_goal():
    """Unique-row threshold for the cinematic source-search screen.

    Kodi enum values are stored as zero-based indices.  A goal of ``0`` means
    patient mode: do not early-open; wait for every source (bounded by the
    existing global source timeout).
    """
    try:
        raw = str(ADDON.getSetting('streams_result_goal') or '1').strip()
        idx = int(float(raw))
    except Exception:
        idx = 1
    # The shipped default index used to mean 20 rows. Opening the live picker
    # should not wait for a large aggregator dump: ten distinct rows are
    # already enough to choose, and every pending provider continues filling
    # the same window in the background.
    return {0: 4, 1: 4, 2: 10, 3: 0}.get(idx, 4)


def _source_enough_wait_seconds():
    try:
        raw = float(ADDON.getSetting('streams_enough_wait_seconds') or 5.0)
    except Exception:
        raw = 5.0
    # This is only the foreground wait. The existing race remains alive and
    # slow providers keep publishing into the open source window.
    return max(1.5, min(raw, 4.0))


def _source_progress_unique_count(entries):
    """Return the post-dedup count without ranking or rebuilding UI rows."""
    rows = list(entries or [])
    try:
        rows, _removed = _collapse_repeated_provider_rows(rows)
    except Exception:
        pass
    try:
        mode = _dedup_mode()
        if mode != 'off':
            order = (ADDON.getSetting('source_priority_order') or '')
            rows, _removed = dedupe_stream_entries(
                rows, mode=mode,
                priority=[part.strip().lower() for part in order.split(',') if part.strip()],
            )
    except Exception:
        pass
    return len(rows)


# DPlex bridge removed in v3.9.243. Plex Native is the single Plex provider.

def _collect_stream_entries(targets, media_type, canonical_id, best_meta, art, bg, ids, title='',
                            video_id='', season=None, episode=None, show_title='', resume_seconds=0.0,
                            resume_percent=0.0,
                            stop_after_first=False, show_loader=False,
                            processed_targets=None, scan_state=None):
    entries = []
    if not targets:
        return entries

    loader_title = title or show_title or best_meta.get('name') or canonical_id or tr('المصادر')
    # v4.6.3: warm the MDBList aggregated-ratings cache in the background
    # while the providers are queried anyway. The picker's tmdbh_context
    # overlay only ever READS the warm cache (no network in its hot path) —
    # and since 4.2.2 nothing had ever warmed it, so the Letterboxd /
    # MDBList / MAL chips never rendered. Keyed by tmdb id first, exactly
    # like TMDb Helper's own MDBList lookups.
    try:
        from . import mdblist as _mdb_warm
        _mdb_warm.warm_ratings_async(
            imdb_id=(ids or {}).get('imdb_id') or '',
            media_type=media_type,
            tmdb_id=(ids or {}).get('tmdb_id') or '')
    except Exception as _silent_exc:
        log.silent('MDBLIST_WARM', _silent_exc)
    def _run(loader=None):
        # v3.9.43: hard global wall-clock ceiling. Per-provider timeouts
        # protect against any single provider hanging, but if many slow
        # providers each take the full per-provider timeout (which can
        # be 15 seconds for AIOStreams), the cumulative wait can feel
        # like a hang to the user. The ceiling forces the loop to exit
        # even if iter_parallel still has outstanding work. Twenty-five
        # seconds is generous for any realistic scan; the cancel and
        # "اكتفي بالموجود" buttons remain available throughout.
        import time as _t
        _started_at = _t.time()
        _hard_deadline = _started_at + 25.0
        _result_goal = _source_result_goal() if stop_after_first else 0
        _enough_wait = _source_enough_wait_seconds() if stop_after_first else 25.0
        _quick_grace = _source_quick_open_seconds() if stop_after_first else 0.0
        _parallel_timeout = (
            25.0 if (not stop_after_first or _result_goal == 0)
            else min(25.0, _enough_wait)
        )
        _unique_count = 0
        _source_race = start_parallel_race(
            lambda t: _fetch_stream_payload(t, media_type), targets,
            workers=_source_parallel_workers(len(targets)),
            # One race lives through both the foreground and live-refresh
            # phases, so slow aggregators are never requested twice.
            timeout=25.0, lane='streams',
        )

        for idx, (target, data) in enumerate(_iter_source_race(
                _source_race, lambda: _unique_count, lambda: bool(entries),
                _started_at, _parallel_timeout, stop_after_first,
                _result_goal, _quick_grace,
                should_stop=(loader.is_stopped if loader is not None else None),
                consume_continue=(loader.consume_continue_search if loader is not None else None),
                clear_sufficient=(loader.clear_sufficient if loader is not None else None),
                mark_sufficient=(lambda: loader.mark_sufficient(auto_seconds=0)
                                 if loader is not None else None),
            ), start=1):
            _now = _t.time()
            if _now > _hard_deadline:
                try:
                    xbmc.log('[DexHub] source gathering hit 25s hard ceiling — %d targets processed, %d entries gathered' % (idx, len(entries)), xbmc.LOGINFO)
                except Exception:
                    pass
                break
            provider, request_id = target
            request_id = str((provider or {}).get('_resolved_request_id') or request_id)
            if processed_targets is not None:
                try:
                    processed_targets.append(target)
                except Exception:
                    pass
            if loader is not None:
                # v3.9.32: respect either button. The XML now shows two:
                #   "اكتفي بالموجود" → stop scan, keep partial entries
                #   "إلغاء"            → stop scan AND drop entries (true abort)
                # is_stopped() is true for either; we differentiate after
                # the loop so the caller sees the right result list.
                if loader.is_stopped():
                    break
                loader.update(
                    provider_name=provider.get('name') or (provider.get('manifest') or {}).get('name') or '',
                    index=idx,
                    status=tr('جار البحث عن المصادر...'),
                    sub_status='%d %s' % (len(entries), tr('مصدر')) if entries else '',
                )
            if isinstance(data, Exception) or not data:
                continue
            before = len(entries)
            _append_stream_entries_from_data(
                entries, data, provider, request_id, media_type, canonical_id, best_meta, art, bg, ids,
                title=title, video_id=video_id, season=season, episode=episode, show_title=show_title,
                resume_seconds=resume_seconds, resume_percent=resume_percent,
            )
            if len(entries) > before:
                _unique_count = _source_progress_unique_count(entries)
            if loader is not None:
                loader.add_results(
                    len(entries) - before,
                    provider_name=provider.get('name') or (provider.get('manifest') or {}).get('name') or '',
                    unique_total=_unique_count,
                )
        if scan_state is not None:
            scan_state['race'] = _source_race
            scan_state['pending_targets'] = _source_race.pending_items()
        if (scan_state is None or
                (loader is not None and loader.is_cancelled())):
            _source_race.cancel()
        if loader is not None:
            # v3.9.32: if the user pressed the true Cancel button (not
            # "Use what's found"), wipe the partial entries so the
            # caller treats it as an aborted search rather than showing
            # half-scanned sources the user explicitly didn't want.
            if loader.is_cancelled():
                entries[:] = []
            loader.set_finalizing()

    if show_loader:
        # v5.10.15: hold the subtitle broker back while the loading screen is
        # the user's whole world. Released in the finally below, so a cancel,
        # a zero-result scan or an exception all still free it.
        try:
            from .playback.subtitle_files import hold_for_source_scan as _hold_subs
            _hold_subs()
        except Exception:
            pass
        # v3.9.59/v3.9.60: build the subtitle for the bottom-sheet
        # layout's hero area: "2023 • Drama, Sci-Fi • S2E5".
        try:
            sub_parts = []
            _year = best_meta.get('year') or best_meta.get('releaseInfo') or ''
            if _year:
                sub_parts.append(str(_year))
            _genres = best_meta.get('genres') or best_meta.get('genre') or []
            if isinstance(_genres, list) and _genres:
                sub_parts.append(', '.join(str(g) for g in _genres[:2] if g))
            elif isinstance(_genres, str) and _genres:
                sub_parts.append(_genres)
            if season is not None and episode is not None:
                try:
                    sub_parts.append('S%dE%d' % (int(season), int(episode)))
                except Exception:
                    pass
            loader_subtitle = '  •  '.join(sub_parts)
        except Exception:
            loader_subtitle = ''

        # v3.9.89: pass the raw addon poster + IDs to the dialog and let
        # it route through art.clean_poster (same policy as the results
        # window and the player overlay). MetaHub TMDb wins when IMDb is
        # known; addon URL when it's clearly not a logo; local portrait
        # placeholder otherwise. NEVER fanart/thumb — they are landscape
        # and render as a banner stuck at the top of an empty card.
        _media_type_for_loader = (
            (best_meta or {}).get('media_type')
            or (best_meta or {}).get('type')
            or media_type
            or 'movie'
        )
        # v4.6.0: full ordered provider list for the dashboard cards.
        _loader_names = []
        for _tgt in targets:
            try:
                _prov = _tgt[0] or {}
                _nm = str(_prov.get('name')
                          or (_prov.get('manifest') or {}).get('name') or '').strip()
            except Exception:
                _nm = ''
            if _nm and _nm not in _loader_names:
                _loader_names.append(_nm)
        with SourcesLoadingDialog(
            title=loader_title,
            subtitle=loader_subtitle,
            fanart=bg or (art or {}).get('fanart') or '',
            poster=(art or {}).get('poster') or '',
            clearlogo=(art or {}).get('clearlogo') or (art or {}).get('logo') or '',
            media_type=_media_type_for_loader,
            imdb_id=(ids or {}).get('imdb_id') or '',
            tmdb_id=(ids or {}).get('tmdb_id') or '',
            provider_count=len(targets),
            provider_names=_loader_names,
        ) as loader:
            try:
                _run(loader)
            finally:
                try:
                    from .playback.subtitle_files import release_source_scan as _release_subs
                    _release_subs()
                except Exception:
                    pass
    else:
        _run(None)
    return entries


_STREAM_REFRESH_SEM = threading.BoundedSemaphore(2)

def _start_stream_session_refresh(session_key, initial_entries, remaining_targets, media_type, canonical_id,
                                  best_meta, art, bg, ids, title='', video_id='', season=None,
                                  episode=None, show_title='', resume_seconds=0.0,
                                  resume_percent=0.0, scan_race=None):
    if not session_key or not remaining_targets:
        return

    def _worker():
        _acquired = False
        try:
            # Reused foreground futures already own their bounded stream lane;
            # consuming them needs no second network-refresh slot.
            if scan_race is None:
                try:
                    _acquired = _STREAM_REFRESH_SEM.acquire(timeout=1.5)
                except TypeError:
                    _acquired = _STREAM_REFRESH_SEM.acquire(False)
                if not _acquired:
                    xbmc.log('[DexHub] live source refresh slots busy; continuing in low-concurrency mode', xbmc.LOGINFO)
        except Exception:
            _acquired = False
        entries = list(initial_entries or [])
        version = 1
        last_request_id = str(video_id or '')
        refresh_race = scan_race
        pending_count = len(remaining_targets)
        failed_count = 0

        def _publish_status(done=False):
            nonlocal version
            version += 1
            return source_session.update(session_key, {
                'entries': list(entries), 'done': done, 'version': version,
                'search_pending': pending_count,
                'search_failed': failed_count,
            })

        _publish_status()
        try:
            refresh_workers = (_source_parallel_workers(len(remaining_targets))
                               if _acquired else 1)
            if refresh_race is not None:
                # Reuse the live futures. Never re-submit: the originals are
                # still in flight and a second fetch would double the network,
                # the JSON walk and the UI work for the same rows.
                _continue = getattr(refresh_race, 'continue_in_background', None)
                if _continue is not None:
                    _continue(seconds=25.0)
                _iterator = refresh_race.iter_completed(timeout=25.0)
            else:
                # v5.10.15: no race to inherit (pre-cached entries, or a caller
                # that never ran a foreground scan). Only targets that were
                # genuinely never dispatched may be fetched here.
                xbmc.log('[DexHub] refresh handoff: NO race to reuse — dispatching %d target(s)'
                         % len(remaining_targets), xbmc.LOGINFO)
                refresh_race = start_parallel_race(
                    lambda t: _fetch_stream_payload(t, media_type),
                    remaining_targets, workers=refresh_workers, timeout=25.0,
                    lane='stream_refresh')
                _iterator = refresh_race.iter_completed(timeout=25.0)
            # Back closes the session synchronously. Registering the owned
            # race gives that action a direct cancellation path instead of
            # waiting for the next provider completion to notice the closure.
            source_session.register_cancel(session_key, refresh_race.cancel)
            for target, data in _iterator:
                # v5.10.15: the source window can be closed (or Kodi can move
                # on to another item) while slow providers are still answering.
                # The 5.10.14 log shows exactly that outcome: background work
                # outliving its window, then a stuck invoker on the next click
                # ("waiting on thread" + "Error resolving item") and an
                # "EXCEPTION: Window id does not exist" from a dead window.
                # Check every iteration, not just once before the loop.
                if not source_session.is_active(session_key):
                    xbmc.log('[DexHub] live source refresh stopped: session %s closed'
                             % session_key, xbmc.LOGINFO)
                    if refresh_race is not None:
                        try:
                            refresh_race.cancel()
                        except Exception:
                            pass
                    break
                try:
                    provider, request_id = target
                    request_id = str((provider or {}).get('_resolved_request_id') or request_id)
                except Exception:
                    continue
                last_request_id = str(video_id or request_id or last_request_id or '')
                pending_count = max(0, pending_count - 1)
                if isinstance(data, Exception):
                    failed_count += 1
                if isinstance(data, Exception) or not data:
                    _publish_status()
                    continue
                # Closing can race with a just-completed future. Do not spend
                # CPU parsing/formatting hundreds of rows after the user left.
                if not source_session.is_active(session_key):
                    break
                before = len(entries)
                _append_stream_entries_from_data(
                    entries, data, provider, request_id, media_type, canonical_id, best_meta, art, bg, ids,
                    title=title, video_id=video_id, season=season, episode=episode, show_title=show_title,
                    resume_seconds=resume_seconds, resume_percent=resume_percent,
                )
                if len(entries) == before:
                    _publish_status()
                    continue
                if not source_session.is_active(session_key):
                    break
                fresh = list(entries[before:])
                del entries[before:]
                entries.extend(_finalize_stream_entries(fresh, media_type=media_type, canonical_id=canonical_id, video_id=last_request_id))
                version += 1
                if not source_session.update(session_key, {
                    'entries': _finalize_stream_entries(list(entries), resort=False, media_type=media_type, canonical_id=canonical_id, video_id=last_request_id),
                    'done': False,
                    'version': version,
                    'search_pending': pending_count,
                    'search_failed': failed_count,
                }):
                    break

        finally:
            if refresh_race is not None:
                try:
                    refresh_race.cancel()
                except Exception:
                    pass
            try:
                source_session.update(session_key, {
                    'entries': _finalize_stream_entries(list(entries), resort=False, media_type=media_type, canonical_id=canonical_id, video_id=last_request_id),
                    'done': True,
                    'version': version + 1,
                    'search_pending': pending_count,
                    'search_failed': failed_count,
                })
            except Exception:
                pass
            if _acquired:
                try:
                    _STREAM_REFRESH_SEM.release()
                except Exception:
                    pass

    try:
        threading.Thread(target=_worker, name='DexHubStreamRefresh', daemon=True).start()
    except RuntimeError as exc:
        try:
            xbmc.log('[DexHub] skipped background source refresh: %s' % exc, xbmc.LOGWARNING)
        except Exception:
            pass
        try:
            source_session.update(session_key, {
                'entries': _finalize_stream_entries(list(initial_entries or []), resort=False, media_type=media_type, canonical_id=canonical_id, video_id=str(video_id or '')),
                'done': True,
                'version': 2,
                'search_pending': len(remaining_targets),
                'search_failed': 0,
            })
        except Exception:
            pass


def _full_parallel_source_scan_enabled():
    """Optional patient mode: wait for all providers before opening results."""
    try:
        raw = (ADDON.getSetting('streams_full_parallel_scan') or 'false').strip().lower()
    except Exception:
        return False
    return raw in ('true', '1', 'yes', 'on')


def _is_suspect_logo_poster(url):
    """v3.9.85: detect URLs that look like addon icons/logos rather than
    real movie/TV posters. Several Stremio addons (notably some Arabic
    anime addons and small streaming providers) return their OWN logo
    as the poster when their meta record for an item lacks a real one.
    We never want such logos to show in the loading dialog, the source
    picker, or the player overlay — they look broken and identical for
    every item from that addon. The check is two-tier:

      1. Allow-list known reliable poster CDNs (TMDb, MetaHub, Fanart.tv,
         Amazon Images, Imgur). These never get filtered.
      2. Reject URLs matching common addon-icon patterns: paths ending
         in /icon.png, /logo.png, /addon.png, /favicon.*, or containing
         '/logo' or '/icon' segments.

    Returns True if the URL should be treated as a logo (and therefore
    rejected as a poster). False = the URL is fine to use as a poster.
    """
    if not url or not isinstance(url, str):
        return False
    url_low = url.lower()
    safe_hosts = (
        'image.tmdb.org', 'images.metahub.space', 'media-amazon.com',
        'm.media-amazon.com', 'img.youtube.com', 'i.imgur.com',
        'fanart.tv', 'assets.fanart.tv', 'static.metahub.space',
        'image.com', 'imgcdn', 'imageapi',
    )
    for h in safe_hosts:
        if h in url_low:
            return False
    suspect_endings = (
        '/icon.png', '/icon.jpg', '/icon.jpeg', '/icon.webp',
        '/logo.png', '/logo.jpg', '/logo.jpeg', '/logo.webp',
        '/addon.png', '/addon.jpg',
        '/favicon.png', '/favicon.ico', '/favicon.jpg',
        '/poster.png', '/poster.jpg',
        '/banner.png', '/banner.jpg',
    )
    for ending in suspect_endings:
        if url_low.endswith(ending):
            return True
    # Path-segment match — catches /icon/, /logo/, /branding/ subpaths
    for seg in ('/logo/', '/icon/', '/icons/', '/branding/', '/brand/', '/assets/icon'):
        if seg in url_low:
            return True
    return False


def _clean_poster(url, fallback='', imdb_id=''):
    """v3.9.86: poster sourcing with TMDb-first preference.

    Order of preference:
      1. TMDb/MetaHub clean URL if imdb_id is available — most reliable
         source for movie/TV posters, covers ~all titles with an IMDb
         entry, never returns addon logos. MetaHub is the same CDN
         Stremio's official Cinemeta addon uses, keyed by IMDb ID.
      2. The addon-provided URL if it passes the logo-suspect check —
         catches the case where TMDb has no entry but a niche addon
         (anime fan-database, fan-translated content, etc.) does have
         a real poster.
      3. The supplied fallback (typically the fanart/background image
         so the loading dialog and player overlay still show something
         visual even when both sources fail).

    The previous v3.9.85 behaviour was the addon URL first with logo
    filtering. That worked but exposed users to the addon-logo problem
    whenever the addon URL passed the heuristic by luck (e.g. hosted
    on imgur). The user-reported case was an Arabic anime addon
    returning its orange fox icon for the live-action show "FROM";
    moving TMDb to first place fixes that class of issue at the source
    instead of relying on URL pattern detection.
    """
    # Tier 1: TMDb/MetaHub clean URL
    imdb_id = (imdb_id or '').strip()
    if imdb_id.startswith('tt') and len(imdb_id) >= 4:
        return _METAHUB_POSTER % imdb_id
    # Tier 2: addon-provided URL, if not suspect
    if url and not _is_suspect_logo_poster(url):
        return url
    if url:
        try:
            xbmc.log('[DexHub] rejected suspect addon-logo poster: %s' % url[:120], xbmc.LOGINFO)
        except Exception:
            pass
    # Tier 3: caller-supplied fallback
    return fallback or ''



def _quick_to_results_enabled():
    """Default to fast parallel opening with live background completion.

    Full-scan mode is still available for users who prefer waiting up front.
    """
    if _full_parallel_source_scan_enabled():
        return False
    try:
        raw = (ADDON.getSetting('streams_quick_to_results') or 'true').strip().lower()
    except Exception:
        return True

    return raw in ('true', '1', 'yes', 'on')


def _source_scan_cancelled():
    """True when the user backed out of the source scan on purpose.

    v3.9.227: pressing Back mid-scan produced "playback failed" — wrong and
    alarming. The user did not fail; they left. Only a scan that ran to
    completion and genuinely found nothing deserves an error.
    """
    try:
        if xbmc.Monitor().abortRequested():
            return True
    except Exception:
        pass
    for prop in ('dexhub.sources.cancelled', 'dexhub.sources.stopped'):
        try:
            if (xbmcgui.Window(WINDOW_ID).getProperty(prop) or '') == '1':
                return True
        except Exception:
            continue
    return False


def _server_direct_entry(canonical_id, media_type, season=None, episode=None):
    """Play a server item DIRECTLY when the source scan comes back empty.

    v3.9.207 — the honest fix for content that lives ONLY on the user's server.

    A Turkish series with no IMDb/TMDb entry cannot be matched by any Stremio
    addon, and the id-based lookup inside the native Plex/Emby source step has
    nothing to match on either — so the scan ends with zero sources and the
    item simply refuses to play. But we do not NEED to search: the item came
    from the server, we hold its rating key, and the file is right there.

    So when the canonical id IS a server id (`plex:<server>:<key>` /
    `emby:<key>`), resolve the file straight from that server and hand back one
    ready-to-play entry. Identified content is untouched — this only runs after
    everything else has already returned nothing.
    """
    cid = str(canonical_id or '')
    if not cid.startswith(('plex:', 'emby:')):
        return []
    try:
        backend, rest = cid.split(':', 1)
        if backend == 'plex':
            server_id, rating_key = rest.split(':', 1)
            server = _plex_server(server_id)
            item = plex_client.metadata(server, rating_key)
            versions = [v for v in (item.get('versions') or []) if v.get('part_key')]
            make_url = lambda v: plex_client.playback_url(item, part_key=v['part_key'])
            poster = plex_client.artwork_url(item, item.get('thumb') or '')
            label = 'PLEX NATIVE'
            colour = PLEX_COLOR
            server_name = server.get('name') or 'Plex'
        else:
            rating_key = rest
            server = _emby_server()
            item = emby_client.metadata(server, rating_key)
            versions = [v for v in (item.get('versions') or []) if v.get('media_source_id')]
            make_url = lambda v: emby_client.playback_url(
                server, item.get('rating_key'), v.get('media_source_id') or '')
            poster = emby_client.artwork_url(server, item.get('thumb') or '')
            label = 'EMBY NATIVE'
            colour = EMBY_COLOR
            server_name = server.get('name') or 'Emby'
    except Exception as exc:
        xbmc.log('[DexHub] direct server play unavailable: %s' % exc, xbmc.LOGWARNING)
        return []

    if not versions:
        return []

    entries = []
    for version in versions:
        try:
            url = make_url(version)
        except Exception:
            continue
        name = os.path.basename(version.get('file') or '') or (
            item.get('raw_title') or item.get('title') or 'Direct')
        facts = version.get('info_line') or ''
        payload = {
            'stream_url': url,
            'name': name,
            'title': item.get('title') or '',
            'poster': poster,
            'provider_name': '%s \u2022 %s' % (
                'Plex' if label.startswith('PLEX') else 'Emby', server_name),
            'subtitles': list(version.get('subtitles') or []),
            'size_label': version.get('size_label') or '',
        }
        entries.append({
            'stream_key': cache_store.put('stream', payload),
            'name': '[COLOR %s]%s[/COLOR]  %s' % (colour, label, name),
            'quality': version.get('resolution') or '',
            'provider': 'PLEX' if label.startswith('PLEX') else 'EMBY',
            'provider_name_raw': payload['provider_name'],
            'addon': payload['provider_name'],
            'source_site': server_name,
            'size_label': version.get('size_label') or '',
            'size_bytes': version.get('size_bytes') or 0,
            'filename': name,
            'label2': '%s \u2022 %s' % (facts, payload['provider_name']) if facts
                      else payload['provider_name'],
            'source_info': facts,
            'stream_url': url,
        })
    xbmc.log('[DexHub] direct server play: %d version(s) for %s'
             % (len(entries), cid), xbmc.LOGINFO)
    return entries


# v5.10.311: the title page warms a title's sources in the background (its
# Play button got the focus): the same targets the picker would ask, through
# the same per-provider results cache, written to disk before this process
# ends, so a long press on Play opens a full list at once (as Nuvio does).
_WARM_ONLY = False
_WARM_TTL = 240.0


def _warm_source_targets(targets, media_type):
    from .search import source_engine as _engine
    from .search import results_cache as _results
    targets = list(targets or [])[:12]
    if not targets:
        return 0
    done = []
    lock = threading.Lock()

    def _one(target):
        try:
            payload = _engine.fetch(target, media_type, sys.modules[__name__])
        except Exception:
            return
        try:
            provider, request_id = target
            key = _results.key(provider, media_type, request_id)
            with _results._MEM_LOCK:
                entry = _results._MEM.get(key)
            if entry:
                _results._persist(key, entry)
                with lock:
                    done.append(len(((payload or {}).get('streams') or [])))
        except Exception:
            pass

    threads = []
    for target in targets:
        th = threading.Thread(target=_one, args=(target,), name='DexHubWarm', daemon=True)
        th.start()
        threads.append(th)
    deadline = time.monotonic() + 12.0
    for th in threads:
        th.join(max(0.0, deadline - time.monotonic()))
    xbmc.log('[DexHub] sources warmed: %d of %d providers, %d streams' % (
        len(done), len(targets), sum(done)), xbmc.LOGINFO)
    return len(done)


def streams(media_type, canonical_id, title='', resume_seconds='0', resume_percent='', preferred_provider_name='', source_provider_id='', source_mode='', seed_ids=None, ui_seed=None):
    _prepare_started = time.monotonic()
    from . import source_diagnostics
    source_diagnostics.reset()
    _clear_source_transient_props(clear_global=False)
    _mark_interactive_busy()
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    best_meta, has_cached_meta = _fast_meta_for_sources(media_type, canonical_id, providers, title=title, source_provider_id=source_provider_id, seed_ids=seed_ids)
    xbmc.log('[DexHub timing] stage=source-meta ms=%.1f' % ((time.monotonic() - _prepare_started) * 1000), xbmc.LOGINFO)
    best_meta = _merge_ui_seed_into_meta(best_meta, ui_seed)
    provider_fb = _item_fallback_art(providers[0] if providers else {}, media_type)
    art = _resolve_meta_art(providers[0] if providers else {}, media_type, best_meta, fallback_art=provider_fb,
                            lazy=bool((best_meta or {}).get('poster'))) if has_cached_meta else dict(provider_fb)
    art = _prefer_item_art(art, best_meta, media_type, fallback_art=provider_fb)
    art = _merge_ui_seed_into_art(art, ui_seed)
    art = _source_ui_art(art, provider_fb)
    ids = _merge_seed_ids(_merge_seed_ids(extract_ids(best_meta), seed_ids or {}), _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id, title=title or best_meta.get('name') or best_meta.get('title') or '')
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    # Subtitle discovery is independent from the chosen release. Start it at
    # the same moment as stream discovery so one fixed five-second budget
    # covers both phases. Source/native sidecars are still merged only after
    # the user picks the exact stream.
    try:
        start_subtitle_prefetch(
            media_type, canonical_id, ids=ids,
            title=title or best_meta.get('name') or best_meta.get('title') or canonical_id,
        )
    except Exception as exc:
        xbmc.log('[DexHub] source-scan subtitle prefetch failed: %s' % exc,
                 xbmc.LOGDEBUG)
    _prime_best_meta_async(media_type, canonical_id, providers, source_provider_id=source_provider_id)
    win = xbmcgui.Window(WINDOW_ID)
    logo = art.get('clearlogo') or ''
    win.setProperty('clearlogo', logo)
    win.setProperty('tvshow.clearlogo', logo)
    bg = _content_background(art, provider_fb)
    win.setProperty('fanart', bg)
    win.setProperty('poster', art.get('poster') or '')
    try:
        resume_seconds = float(resume_seconds or 0.0)
    except Exception:
        resume_seconds = 0.0
    try:
        resume_percent_val = float(resume_percent or 0.0)
    except Exception:
        resume_percent_val = 0.0
    targets_all = _prioritize_provider_targets(list(_stream_provider_targets(media_type, canonical_id, meta=stream_meta)), preferred_provider_name=preferred_provider_name)
    if _WARM_ONLY:
        return _warm_source_targets(targets_all, media_type)
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id=source_provider_id, source_mode=source_mode)

    xbmc.log('[DexHub timing] stage=source-prepare-total ms=%.1f' % ((time.monotonic() - _prepare_started) * 1000), xbmc.LOGINFO)

    # v3.9.65: race all candidate providers and open the source picker
    # as soon as the FIRST entry arrives (instead of waiting for every
    # provider). Slow providers continue to fill the live results window
    # through the existing stream_session refresh thread, and the user
    # can click any source the moment it appears.
    _quick = _quick_to_results_enabled()
    loading_art = _loading_art_fast(media_type, best_meta, art, bg, ids, title=title or canonical_id)
    art = _merge_ui_seed_into_art(art, loading_art)
    bg = loading_art.get('fanart') or bg
    processed_targets = []
    scan_state = {}
    entries = _collect_stream_entries(
        targets, media_type, canonical_id, best_meta, art, bg, ids,
        title=title, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
        stop_after_first=_quick, processed_targets=processed_targets,
        scan_state=scan_state,
    )
    _active_race = scan_state.get('race')
    if _active_race is not None:
        remaining_targets = _active_race.pending_items()
    else:
        processed_set = set((id(p), rid) for p, rid in processed_targets)
        remaining_targets = [t for t in targets if (id(t[0]), t[1]) not in processed_set]
    if not entries and fallback_targets:
        processed_targets = []
        try:
            if _active_race is not None:
                _active_race.cancel()
        except Exception:
            pass
        scan_state = {}
        entries = _collect_stream_entries(
            fallback_targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
            stop_after_first=_quick, processed_targets=processed_targets,
            scan_state=scan_state,
        )
        _active_race = scan_state.get('race')
        if _active_race is not None:
            remaining_targets = _active_race.pending_items()
        else:
            processed_set = set((id(p), rid) for p, rid in processed_targets)
            remaining_targets = [t for t in fallback_targets if (id(t[0]), t[1]) not in processed_set]
    if not entries:
        # Nothing matched anywhere — but if this item CAME from the user's own
        # server we do not need a match at all: play the file directly.
        entries = _server_direct_entry(canonical_id, media_type)
    if not entries:
        try:
            if _active_race is not None:
                _active_race.cancel()
        except Exception:
            pass
        _clear_tmdbh_transient()
        _clear_source_transient_props(clear_global=True)
        if _source_scan_cancelled():
            xbmc.log('[DexHub] source scan cancelled by the user — no error', xbmc.LOGINFO)
            if HANDLE >= 0:
                try:
                    xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
                except Exception:
                    pass
            return end_dir(cache=False)
        error(tr('لم يتم العثور على روابط تشغيل'))
        if HANDLE >= 0:
            try:
                xbmcplugin.setResolvedUrl(HANDLE, False, xbmcgui.ListItem())
            except Exception:
                pass
        return end_dir()
    entries = _finalize_stream_entries(entries, media_type=media_type, canonical_id=canonical_id)
    # Pull plot/year/genre/rating from best_meta so the source window can
    # render the redesigned hero panel (Plot textbox, year-genre-rating row).
    _genres = best_meta.get('genres') or []
    if isinstance(_genres, list):
        _genre_str = ' / '.join([str(g) for g in _genres[:3] if g])
    else:
        _genre_str = str(_genres or '')
    _year_val = ''
    _release = best_meta.get('releaseInfo') or best_meta.get('year') or ''
    if _release:
        _ymatch = YEAR_RE.search(str(_release))
        if _ymatch:
            _year_val = _ymatch.group(1)
    _rating = best_meta.get('imdbRating') or ''
    try:
        if _rating:
            _rating = '%.1f' % float(_rating)
    except Exception:
        _rating = str(_rating or '')
    _src_info = _stream_meta_info_payload(best_meta, media_type=media_type, title=title or best_meta.get('name') or canonical_id)
    _src_studio = _src_info.get('studio') or ''
    if isinstance(_src_studio, (list, tuple)):
        _src_studio = ' / '.join([str(x) for x in _src_studio if x])
    meta = {
        'title': title or best_meta.get('name') or canonical_id,
        'poster': art.get('poster') or provider_fb.get('poster') or provider_fb.get('thumb') or '',
        'fanart': _content_background(art, provider_fb),
        'clearlogo': art.get('clearlogo') or '',
        'plot': best_meta.get('description') or best_meta.get('overview') or '',
        'year': _year_val,
        'genre': _genre_str,
        'rating': _rating,
        'studio': _src_studio,
        'imdb_id': ids.get('imdb_id') or '',
        'tmdb_id': ids.get('tmdb_id') or '',
        'tvdb_id': ids.get('tvdb_id') or '',
        'media_type': media_type,
        'canonical_id': canonical_id,
    }
    session_key = ''
    if remaining_targets:
        session_key = source_session.create(entries, done=False, version=1)
        _start_stream_session_refresh(
            session_key, entries, remaining_targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title, resume_seconds=resume_seconds, resume_percent=resume_percent_val,
            scan_race=_active_race,
        )
    return _show_stream_window(entries, meta, session_key=session_key)



def _video_season_num(video):
    """Season number of a Stremio video entry, with season 0 kept as 0.

    v3.9.239: both series_meta() and season() parsed this with a bare
    `or 1` fallback. JSON number 0 is falsy, so SPECIALS
    (season 0) were silently merged into Season 1 — polluting its episode list
    and letting a special "S01E01" collide with the real S01E01, which could
    send stream matching after the wrong video id. A string '0' did NOT trigger
    it (non-empty strings are truthy), so the bug was intermittent by provider.
    Missing/None/garbage still defaults to season 1.
    """
    raw = video.get('season')
    if raw is None or raw == '':
        return 1
    try:
        return int(raw)
    except Exception:
        return 1


def series_meta(media_type, canonical_id, title='', source_provider_id=''):
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    meta = None
    meta_provider = None
    for provider in providers:
        try:
            data = fetch_meta(provider, media_type, canonical_id, timeout_override=fast_timeout('meta'))
            meta = data.get('meta') or data.get('metas')
            if isinstance(meta, list):
                meta = meta[0] if meta else None
            if meta and meta.get('videos'):
                meta_provider = provider
                break
        except Exception:
            continue
    if not meta:
        error(tr('تعذر جلب بيانات المسلسل'))
        return end_dir()
    try:
        from . import meta_source as _meta_source
        if _is_virtual_meta_target(source_provider_id):
            meta = _meta_source.override_virtual_meta(source_provider_id, media_type, meta) or meta
        else:
            meta = _meta_source.override_meta(meta_provider or (providers[0] if providers else {}), media_type, meta) or meta
    except Exception:
        pass
    seasons = {}
    videos = meta.get('videos') or []
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id, json.dumps(videos))
    art_provider = meta_provider or (providers[0] if providers else {})
    provider_fb = _item_fallback_art(art_provider, media_type)
    series_art = _resolve_meta_art(art_provider, media_type, meta, fallback_art=provider_fb)
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.art', json.dumps(series_art))
    resolved_series_title = meta.get('name') or title or canonical_id
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.title', resolved_series_title)
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.media_type', media_type or 'series')
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id', source_provider_id if _is_virtual_meta_target(source_provider_id) else ((art_provider or {}).get('id') or source_provider_id or ''))
    xbmcgui.Window(WINDOW_ID).setProperty(SERIES_PROP_PREFIX + canonical_id + '.native_art', '1' if (_provider_prefers_native_art(art_provider) or _provider_uses_explicit_meta_art(art_provider)) else '0')
    ids = _merge_seed_ids(extract_ids(meta), _get_tmdbh_seed_ids(canonical_id))
    for video in videos:
        season_num = _video_season_num(video)
        seasons.setdefault(season_num, []).append(video)
    for season_num in sorted(seasons.keys()):
        _season_label = 'حلقات خاصة' if season_num == 0 else (tr('الموسم %s') % season_num)
        add_item(
            _season_label,
            build_url(action='season', media_type=media_type, canonical_id=canonical_id, season=season_num, title=resolved_series_title),
            info={'title': _season_label, 'tvshowtitle': resolved_series_title, 'mediatype': 'season'},
            art=dict(series_art, thumb=series_art.get('poster'), icon=series_art.get('poster')),
            ids=ids,
        )
    end_dir(content='seasons')


def season(canonical_id, season, title='', media_type=''):
    raw = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id)
    videos = []
    if raw:
        try:
            videos = json.loads(raw)
        except Exception:
            videos = []
    art_raw = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.art')
    series_art = {}
    if art_raw:
        try:
            series_art = json.loads(art_raw)
        except Exception:
            series_art = {}
    show_title = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.title') or title
    media_type = media_type or xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.media_type') or 'series'
    prefer_native_art = xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.native_art') == '1'
    season = int(season)
    # Compute once — canonical_id doesn't change across episodes.
    episode_ids = _merge_seed_ids(extract_ids({'id': canonical_id}), _get_tmdbh_seed_ids(canonical_id))
    # v5.10.214: Following: Episode names (TMDb for the numbered ones; with
    # «Episodes you started» only the begun ones are named)
    from . import episode_titles as _ET
    _show_ids = _ET.show_ids({'canonical_id': canonical_id, 'imdb_id': episode_ids.get('imdb_id') or ''})
    if not _show_ids[0] and str(episode_ids.get('tmdb_id') or '').isdigit():
        _show_ids = (str(episode_ids['tmdb_id']), _show_ids[1])
    if _ET.mode() != 'off' and any(_ET.generic(v.get('title')) for v in videos if _video_season_num(v) == season):
        _ET.warm([(_show_ids[0], _show_ids[1], season)])
    _begun = set()
    if _ET.mode() == 'started':
        try:
            for _row in playback_store.list_recent_items(limit=2000, include_watched=True):
                if _row.get('canonical_id') == canonical_id and int(_row.get('season') or 0) == season:
                    _begun.add(int(_row.get('episode') or 0))
        except Exception:
            pass
    for video in videos:
        if _video_season_num(video) != season:
            continue
        ep = int(video.get('episode') or 0)
        _shown = _ET.pick(video.get('title') or '', started=ep in _begun, tmdb_id=_show_ids[0],
                          imdb_id=_show_ids[1], season=season, episode=ep, cached_only=True)
        # v3.9.239: a video without an id used to fall back to the BARE series
        # id, but providers expect '<series>:<season>:<episode>' for episode
        # streams (Cinemeta convention) — a bare series id matches nothing.
        _ep_video_id = video.get('id') or ('%s:%s:%s' % (canonical_id, season, ep))
        vtitle = video.get('title') or ('S%02dE%02d' % (season, ep))
        label = ('S%02dE%02d — %s' % (season, ep, _shown)) if _shown else ('S%02dE%02d' % (season, ep))
        meta = {'id': video.get('id') or canonical_id, 'name': vtitle, 'poster': video.get('thumbnail') or '', 'background': video.get('thumbnail') or '', 'type': 'series'}
        episode_art = native_meta_art(meta, media_type if media_type in ('anime','series') else 'series', fallback_art=series_art) if prefer_native_art else enrich_meta_art(meta, media_type if media_type in ('anime','series') else 'series', fallback_art=series_art)
        episode_path, episode_is_folder = _content_click_path(media_type=media_type or 'series', canonical_id=canonical_id, video_id=_ep_video_id, season=season, episode=ep, title=vtitle, tmdb_id=episode_ids.get('tmdb_id') or '', imdb_id=episode_ids.get('imdb_id') or '', tvdb_id=episode_ids.get('tvdb_id') or '', source_provider_id=xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id') or '', ui_seed=episode_art)
        episode_menu = _build_source_picker_menu(media_type=media_type or 'series', canonical_id=canonical_id, title=vtitle, season=season, episode=ep, video_id=_ep_video_id, source_provider_id=xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id') or '') + _build_player_chooser_menu(media_type=media_type or 'series', canonical_id=canonical_id, title=vtitle, season=season, episode=ep, video_id=_ep_video_id)
        add_item(label, episode_path, is_folder=episode_is_folder, info={'title': _shown or (tr('الحلقة %d') % ep), 'episode': ep, 'season': season, 'tvshowtitle': show_title, 'mediatype': 'episode', 'plot': video.get('overview') or ''}, art=episode_art, context_menu=episode_menu)
    end_dir(content='episodes')


# v3.9.104: pre-cache the NEXT episode's stream sources while the current
# episode is still playing. Triggered ~60s into playback (long enough that the
# user is committed; short enough that the binge UX feels instant). Runs in a
# daemon thread, silently — no UI, no loader, no notifications. Result lands
# in precache_store and is consumed by episode_streams() on the next play.
def _precache_episode_async(canonical_id, video_id, season, episode, title='', media_type='series', delay_seconds=60):
    try:
        from . import precache_store as _pc
    except Exception:
        return
    try:
        season_i = int(season or 0)
        episode_i = int(episode or 0)
    except Exception:
        return
    if not canonical_id or season_i <= 0 or episode_i <= 0:
        return
    # Reserve the slot so a second trigger for the same episode (rare but
    # possible if the user replays) doesn't spin up a duplicate scrape.
    if not _pc.mark_inflight(canonical_id, season_i, episode_i):
        return

    def _worker():
        try:
            import time as _t
            if delay_seconds > 0:
                _t.sleep(delay_seconds)
            # Abort if Kodi is shutting down or the user already moved on to
            # something else mid-binge — no point scraping a stale next-up.
            try:
                if xbmc.Monitor().abortRequested():
                    return
            except Exception:
                pass
            try:
                xbmc.log('[DexHub] precache worker scraping s%se%s of %s'
                         % (season_i, episode_i, canonical_id), xbmc.LOGINFO)
            except Exception:
                pass
            # Replicate the early setup that episode_streams() does, but never
            # call into UI code (no loader, no picker open, no transient
            # property writes).
            providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id='')
            best_meta, _has = _fast_meta_for_sources(media_type, canonical_id, providers,
                                                     title=title or canonical_id, source_provider_id='')
            ids = _merge_seed_ids(extract_ids(best_meta), _get_tmdbh_seed_ids(canonical_id))
            ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id,
                                     title=title or best_meta.get('name') or best_meta.get('title') or '')
            stream_meta = _meta_with_seed_ids(best_meta, ids)
            direct_targets = []
            for provider in store.list_providers():
                if not _get_bool_setting('stremio_sources_enabled', True):
                    break
                if provider.get('enabled') is False or _source_left_out(provider):
                    continue
                if supports_resource(provider, 'stream', media_type=media_type, item_id=video_id):
                    direct_targets.append((provider, video_id))
            from .search.episode_route import merge_targets
            targets_all = merge_targets(_stream_provider_targets(
                media_type, canonical_id, meta=stream_meta, season=season_i, episode=episode_i),
                direct_targets)
            targets_all = _prioritize_provider_targets(targets_all, preferred_provider_name='')
            targets, fallback_targets = _split_targets_by_source_mode(targets_all,
                                                                       source_provider_id='', source_mode='')
            if not targets and not fallback_targets:
                return
            # Silent scrape: show_loader=False. stop_after_first=False so the
            # pre-cache has the FULL list (no point cutting short when no user
            # is waiting). Empty art dicts because we don't need to write to UI.
            entries = _collect_stream_entries(
                targets, media_type, canonical_id, best_meta, {}, '', ids,
                title=title or video_id, video_id=video_id, season=season_i, episode=episode_i,
                show_title=best_meta.get('name') or canonical_id,
                resume_seconds=0.0, resume_percent=0.0,
                show_loader=False, stop_after_first=False, processed_targets=None,
            )
            if not entries and fallback_targets:
                entries = _collect_stream_entries(
                    fallback_targets, media_type, canonical_id, best_meta, {}, '', ids,
                    title=title or video_id, video_id=video_id, season=season_i, episode=episode_i,
                    show_title=best_meta.get('name') or canonical_id,
                    resume_seconds=0.0, resume_percent=0.0,
                    show_loader=False, stop_after_first=False, processed_targets=None,
                )
            if entries:
                _pc.put(canonical_id, season_i, episode_i, entries, meta=best_meta)
                try:
                    xbmc.log('[DexHub] precache STORED %d entries for s%se%s'
                             % (len(entries), season_i, episode_i), xbmc.LOGINFO)
                except Exception:
                    pass
            else:
                try:
                    xbmc.log('[DexHub] precache worker found 0 entries for s%se%s'
                             % (season_i, episode_i), xbmc.LOGWARNING)
                except Exception:
                    pass
        except Exception as exc:
            try:
                xbmc.log('[DexHub] precache worker crashed: %s' % exc, xbmc.LOGWARNING)
            except Exception:
                pass
        finally:
            try:
                _pc.release_inflight(canonical_id, season_i, episode_i)
            except Exception:
                pass

    import threading as _th
    try:
        t = _th.Thread(target=_worker, name='DexHubPrecache-s%se%s' % (season_i, episode_i))
        t.daemon = True
        t.start()
    except RuntimeError as exc:
        try:
            xbmc.log('[DexHub] skipped next-episode precache: %s' % exc, xbmc.LOGWARNING)
        except Exception:
            pass


def _show_imdb_for_episode(canonical_id, video_id, ids):
    """(canonical_id, video_id, ids) with the show's IMDb id when the one
    given is not the show's (an episode's own id). Needs the show's TMDb id;
    one cached TMDb call per show."""
    canonical = str(canonical_id or '').strip()
    base = canonical.split(':')[0]
    tmdb = str((ids or {}).get('tmdb_id') or '').strip()
    if not re.match(r'^tt\d+$', base):
        return canonical_id, video_id, ids
    from . import tmdb_direct as _td
    if not tmdb.isdigit():
        # v5.10.229: no TMDb id known: TMDb's find says whether this IMDb id
        # is an episode's, and names its show
        tmdb = _td.show_tmdb_for_episode_imdb(base) or ''
        if not tmdb.isdigit():
            return canonical_id, video_id, ids
        ids = dict(ids or {}, tmdb_id=tmdb)
    show_imdb = str(_td.imdb_id_for(tmdb, 'tv', timeout=4) or '').strip()
    if not show_imdb.startswith('tt') or show_imdb == base:
        return canonical_id, video_id, ids
    xbmc.log('[DexHub] episode named by %s: the show (tmdb %s) is %s' % (base, tmdb, show_imdb), xbmc.LOGINFO)
    vid = str(video_id or '')
    if vid == canonical or vid.startswith(base + ':') or vid == base:
        vid = show_imdb + vid[len(base):]
    ids = dict(ids or {}, imdb_id=show_imdb)
    return show_imdb + canonical[len(base):], vid, ids


def episode_streams(canonical_id, video_id, season, episode, title='', media_type='', resume_seconds='0', resume_percent='', preferred_provider_name='', source_provider_id='', source_mode='', seed_ids=None, ui_seed=None):
    _prep_started = time.monotonic()
    from . import source_diagnostics
    source_diagnostics.reset()
    _clear_source_transient_props(clear_global=False)
    _mark_interactive_busy()
    media_type = media_type or xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.media_type') or 'series'
    source_provider_id = source_provider_id or xbmcgui.Window(WINDOW_ID).getProperty(SERIES_PROP_PREFIX + canonical_id + '.source_provider_id') or ''
    providers = _provider_order_for_id_with_context(media_type, canonical_id, source_provider_id=source_provider_id)
    best_meta, has_cached_meta = _fast_meta_for_sources(media_type, canonical_id, providers, title=title or canonical_id, source_provider_id=source_provider_id, seed_ids=seed_ids)
    best_meta = _merge_ui_seed_into_meta(best_meta, ui_seed)
    provider_fb = _item_fallback_art(providers[0] if providers else {}, media_type)
    art = _resolve_meta_art(providers[0] if providers else {}, media_type, best_meta, fallback_art=provider_fb,
                            lazy=bool((best_meta or {}).get('poster'))) if has_cached_meta else dict(provider_fb)
    art = _prefer_item_art(art, best_meta, media_type, fallback_art=provider_fb)
    art = _merge_ui_seed_into_art(art, ui_seed)
    art = _source_ui_art(art, provider_fb)
    ids = _merge_seed_ids(_merge_seed_ids(extract_ids(best_meta), seed_ids or {}), _get_tmdbh_seed_ids(canonical_id))
    ids = _enrich_stream_ids(ids, media_type, meta=best_meta, canonical_id=canonical_id, title=title or best_meta.get('name') or best_meta.get('title') or '')
    # v5.10.224: a row synced from Trakt or Nuvio can name an episode by the
    # EPISODE's IMDb id (MobLand S2E4 came as tt43338257, the show is
    # tt31510819): every add-on was asked for tt43338257:2:4 and found no
    # streams and no subtitles. The show's TMDb id names its real IMDb id.
    try:
        canonical_id, video_id, ids = _show_imdb_for_episode(canonical_id, video_id, ids)
    except Exception as exc:
        xbmc.log('[DexHub] show imdb check failed: %s' % exc, xbmc.LOGDEBUG)
    stream_meta = _meta_with_seed_ids(best_meta, ids)
    try:
        start_subtitle_prefetch(
            media_type, canonical_id, ids=ids,
            title=title or best_meta.get('name') or canonical_id,
            season=season, episode=episode,
        )
    except Exception as exc:
        xbmc.log('[DexHub] episode source-scan subtitle prefetch failed: %s' % exc,
                 xbmc.LOGDEBUG)
    _prime_best_meta_async(media_type, canonical_id, providers, source_provider_id=source_provider_id)
    win = xbmcgui.Window(WINDOW_ID)
    logo = art.get('clearlogo') or ''
    win.setProperty('clearlogo', logo)
    win.setProperty('tvshow.clearlogo', logo)
    bg = _content_background(art, provider_fb)
    win.setProperty('fanart', bg)
    win.setProperty('poster', art.get('poster') or '')
    direct_targets = []
    for provider in store.list_providers():
        if not _get_bool_setting('stremio_sources_enabled', True):
            break
        if provider.get('enabled') is False or _source_left_out(provider):
            continue
        if _stremio_provider.supports_stream(provider, media_type, item_id=video_id):
            direct_targets.append((provider, video_id))
    try:
        resume_seconds = float(resume_seconds or 0.0)
    except Exception:
        resume_seconds = 0.0
    try:
        resume_percent_val = float(resume_percent or 0.0)
    except Exception:
        resume_percent_val = 0.0
    from .search.episode_route import merge_targets
    targets_all = merge_targets(
        _stream_provider_targets(media_type, canonical_id, meta=stream_meta, season=season, episode=episode),
        direct_targets)
    xbmc.log('[DexHub timing] stage=episode-source-preparation ms=%.1f' % (
        (time.monotonic() - _prep_started) * 1000), xbmc.LOGINFO)
    targets_all = _prioritize_provider_targets(targets_all, preferred_provider_name=preferred_provider_name)
    if _WARM_ONLY:
        return _warm_source_targets(targets_all, media_type)
    targets, fallback_targets = _split_targets_by_source_mode(targets_all, source_provider_id=source_provider_id, source_mode=source_mode)

    # v3.9.65: same race strategy as movies — open the source picker
    # the moment the FIRST entry arrives (instead of waiting for every
    # provider). Especially valuable for NextUp/collection-driven
    # episode playback where the user wants to start watching ASAP.
    _quick = _quick_to_results_enabled()
    loading_art = _loading_art_fast(media_type, best_meta, art, bg, ids, title=title or best_meta.get('name') or canonical_id)
    art = _merge_ui_seed_into_art(art, loading_art)
    bg = loading_art.get('fanart') or bg

    # v3.9.104: pre-cache hit short-circuits the entire scrape. If the previous
    # episode's playback warmed sources for this one, we use them as-is and
    # the picker opens instantly. Cache miss falls through to the normal
    # network scrape unchanged.
    entries = None
    remaining_targets = []
    try:
        from . import precache_store as _pc
        _hit = _pc.consume(canonical_id, season, episode)
        if _hit:
            cached_entries, _cached_meta = _hit
            if cached_entries:
                entries = list(cached_entries)
                try:
                    xbmc.log('[DexHub] precache HIT for s%se%s (%d entries) — skipping live scrape'
                             % (season, episode, len(entries)), xbmc.LOGINFO)
                except Exception:
                    pass
    except Exception as _pc_exc:
        try:
            xbmc.log('[DexHub] precache lookup failed: %s' % _pc_exc, xbmc.LOGDEBUG)
        except Exception:
            pass

    processed_targets = []
    scan_state = {}
    if entries is None:
        entries = _collect_stream_entries(
            targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title or video_id, video_id=video_id, season=season, episode=episode,
            show_title=best_meta.get('name') or canonical_id, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
            stop_after_first=_quick, processed_targets=processed_targets,
            scan_state=scan_state,
        )
        _active_race = scan_state.get('race')
        if _active_race is not None:
            remaining_targets = _active_race.pending_items()
        else:
            processed_set = set((id(p), rid) for p, rid in processed_targets)
            remaining_targets = [t for t in targets if (id(t[0]), t[1]) not in processed_set]
        if not entries and fallback_targets:
            processed_targets = []
            try:
                if _active_race is not None:
                    _active_race.cancel()
            except Exception:
                pass
            scan_state = {}
            entries = _collect_stream_entries(
                fallback_targets, media_type, canonical_id, best_meta, art, bg, ids,
                title=title or video_id, video_id=video_id, season=season, episode=episode,
                show_title=best_meta.get('name') or canonical_id, resume_seconds=resume_seconds, resume_percent=resume_percent_val, show_loader=True,
                stop_after_first=_quick, processed_targets=processed_targets,
                scan_state=scan_state,
            )
            _active_race = scan_state.get('race')
            if _active_race is not None:
                remaining_targets = _active_race.pending_items()
            else:
                processed_set = set((id(p), rid) for p, rid in processed_targets)
                remaining_targets = [t for t in fallback_targets if (id(t[0]), t[1]) not in processed_set]
    if not entries:
        try:
            if entries is None or _active_race is not None:
                _active_race.cancel()
        except Exception:
            pass
        _clear_tmdbh_transient()
        _clear_source_transient_props(clear_global=True)
        if _source_scan_cancelled():
            xbmc.log('[DexHub] source scan cancelled by the user — no error', xbmc.LOGINFO)
            return end_dir(cache=False)
        error(tr('لم يتم العثور على روابط تشغيل للحلقة'))
        return end_dir()
    entries = _finalize_stream_entries(entries, media_type=media_type, canonical_id=canonical_id, video_id=video_id)
    # Pull plot/year/genre/rating from best_meta so the source window can
    # render the redesigned hero panel for the episode picker too.
    _ep_genres = best_meta.get('genres') or []
    if isinstance(_ep_genres, list):
        _ep_genre_str = ' / '.join([str(g) for g in _ep_genres[:3] if g])
    else:
        _ep_genre_str = str(_ep_genres or '')
    _ep_year_val = ''
    _ep_release = best_meta.get('releaseInfo') or best_meta.get('year') or ''
    if _ep_release:
        _ep_ymatch = YEAR_RE.search(str(_ep_release))
        if _ep_ymatch:
            _ep_year_val = _ep_ymatch.group(1)
    _ep_rating = best_meta.get('imdbRating') or ''
    try:
        if _ep_rating:
            _ep_rating = '%.1f' % float(_ep_rating)
    except Exception:
        _ep_rating = str(_ep_rating or '')
    _ep_info = _stream_meta_info_payload(best_meta, media_type=media_type, title=title or video_id, show_title=best_meta.get('name') or canonical_id, season=season, episode=episode)
    _ep_studio = _ep_info.get('studio') or ''
    if isinstance(_ep_studio, (list, tuple)):
        _ep_studio = ' / '.join([str(x) for x in _ep_studio if x])
    meta = {
        'title': title or video_id,
        'poster': art.get('poster') or provider_fb.get('poster') or provider_fb.get('thumb') or '',
        'fanart': _content_background(art, provider_fb),
        'clearlogo': art.get('clearlogo') or '',
        'plot': best_meta.get('description') or best_meta.get('overview') or '',
        'year': _ep_year_val,
        'genre': _ep_genre_str,
        'rating': _ep_rating,
        'studio': _ep_studio,
        'imdb_id': ids.get('imdb_id') or '',
        'tmdb_id': ids.get('tmdb_id') or '',
        'tvdb_id': ids.get('tvdb_id') or '',
        'media_type': media_type,
        'canonical_id': canonical_id,
        'season': season,
        'episode': episode,
    }
    session_key = ''
    if remaining_targets:
        session_key = source_session.create(entries, done=False, version=1)
        _start_stream_session_refresh(
            session_key, entries, remaining_targets, media_type, canonical_id, best_meta, art, bg, ids,
            title=title or video_id, video_id=video_id, season=season, episode=episode,
            show_title=best_meta.get('name') or canonical_id, resume_seconds=resume_seconds, resume_percent=resume_percent_val,
            scan_race=_active_race,
        )
    return _show_stream_window(entries, meta, session_key=session_key)

def _resolve_best_id(video_type, tmdb_id='', imdb_id='', tvdb_id='', title=''):
    if tmdb_id:
        return 'tmdb:%s' % tmdb_id
    if imdb_id:
        return imdb_id if str(imdb_id).startswith('tt') else 'imdb:%s' % imdb_id
    if tvdb_id:
        return 'tvdb:%s' % tvdb_id
    return title or ''


def _find_episode_video_id(canonical_id, season, episode):
    cached = _meta_mem_get('series', canonical_id) or {}
    for video in cached.get('videos') or []:
        try:
            if (int(video.get('season') or 0) == int(season) and
                    int(video.get('episode') or 0) == int(episode) and video.get('id')):
                return video['id'], cached.get('name') or cached.get('title') or ''
        except (TypeError, ValueError, AttributeError):
            continue
    providers = _provider_order_for_id('series', canonical_id)
    for provider in providers:
        try:
            data = fetch_meta(provider, 'series', canonical_id, timeout_override=fast_timeout('meta'))
            meta = data.get('meta') or data.get('metas')
            if isinstance(meta, list):
                meta = meta[0] if meta else None
            videos = (meta or {}).get('videos') or []
            if isinstance(meta, dict) and videos:
                _meta_mem_put('series', canonical_id, meta)
            for video in videos:
                if int(video.get('season') or 0) == int(season or 0) and int(video.get('episode') or 0) == int(episode or 0):
                    return video.get('id') or canonical_id, (meta or {}).get('name') or canonical_id
        except Exception:
            continue
    return canonical_id, ''



