def mdblist_menu():
    linked = mdblist.configured()
    account_info = {}
    account_error = ''
    if linked:
        try:
            account_info = mdblist.fetch_user_info(strict=True) or {}
        except Exception as exc:
            account_error = str(exc)
    account = (account_info.get('user')
               if isinstance(account_info.get('user'), dict)
               else account_info)
    account_name = str(
        (account or {}).get('username') or (account or {}).get('user_name') or
        (account or {}).get('name') or '').strip()
    verified = bool(linked and account_info and not account_error)
    if verified:
        status = '%s%s' % (tr('متصل ✓'), (' • %s' % account_name) if account_name else '')
    elif linked and account_error:
        status = tr('المفتاح محفوظ لكن الاتصال فشل')
    else:
        status = tr('يحتاج API Key')
    status_plot = tr('لستات وWatchlist حسابك في MDBList داخل Dex Hub. المفتاح من mdblist.com/preferences')
    if account_error:
        status_plot = '%s\n\n%s' % (status_plot, account_error)
