def _parse_trakt_list_url(raw_url):
    raw_url = (raw_url or '').strip()
    if not raw_url:
        return None
    try:
        parsed = urlparse(raw_url)
    except Exception:
        return None
    host = (parsed.netloc or '').lower()
    if 'trakt.tv' not in host:
        return None
    parts = [p for p in (parsed.path or '').split('/') if p]
    if len(parts) < 4 or parts[0] != 'users' or parts[2] != 'lists':
        return None
    username = parts[1].strip()
    slug = parts[3].strip()
    if not username or not slug:
        return None
    return {'username': username, 'slug': slug, 'name': _derive_name_from_slug(slug), 'url': 'https://trakt.tv/users/%s/lists/%s' % (username, slug)}


def _parse_mdblist_list_url(raw_url):
    parsed = mdblist.parse_list_url(raw_url)
    if not parsed:
        return None
    parsed['name'] = _derive_name_from_slug(parsed.get('slug') or '')
    return parsed



def _parse_tmdb_list_url(raw_url):
    raw_url = (raw_url or '').strip()
    if not raw_url:
        return None
    # Accept a bare public TMDb list id as a quick entry shortcut.
    if re.match(r'^\d+$', raw_url):
        return {'list_id': raw_url, 'name': 'TMDb List %s' % raw_url, 'url': 'https://www.themoviedb.org/list/%s' % raw_url}
    try:
        parsed = urlparse(raw_url)
    except Exception:
        return None
    host = (parsed.netloc or '').lower()
    if 'themoviedb.org' not in host and 'tmdb.org' not in host:
        return None
    parts = [p for p in (parsed.path or '').split('/') if p]
    if len(parts) < 2 or parts[0].lower() != 'list':
        return None
    token = parts[1].strip()
    m = re.match(r'^(\d+)', token)
    if not m:
        return None
    list_id = m.group(1)
    name = _derive_name_from_slug(token[len(list_id):].strip('-_') or ('TMDb List %s' % list_id))
    return {'list_id': list_id, 'name': name, 'url': 'https://www.themoviedb.org/list/%s' % list_id}


def _tmdbhelper_media_type(media_filter, fallback='both'):
    value = str(media_filter or fallback or 'both').strip().lower()
    if value in ('movie', 'movies', 'film'):
        return 'movie'
    if value in ('series', 'show', 'shows', 'tv', 'tvshow', 'tvshows', 'anime'):
        return 'tv'
    return 'both'


def _tmdbhelper_native_url(params):
    clean = {}
    for k, v in (params or {}).items():
        if v not in (None, ''):
            clean[k] = str(v)
    return 'plugin://plugin.video.themoviedb.helper/?' + urlencode(clean)


def _tmdbhelper_trakt_list_url(username, slug, media_filter='auto'):
    tmdbh_type = _tmdbhelper_media_type(media_filter)
    return _tmdbhelper_native_url({
        'info': 'trakt_userlist',
        'user_slug': username,
        'list_slug': slug,
        # Older TMDb Helper builds used type=, newer builds commonly use
        # tmdb_type=. Passing both keeps the shortcut native across versions.
        'type': tmdbh_type,
        'tmdb_type': tmdbh_type,
        'widget': 'True',
    })


def _tmdbhelper_mdblist_url(username, slug, media_filter='auto', raw_url=''):
    tmdbh_type = _tmdbhelper_media_type(media_filter)
    return _tmdbhelper_native_url({
        # Mirrors trakt_userlist naming. If a specific TMDb Helper build uses a
        # different MDBList endpoint, the user can still pick the exact path via
        # the widget picker; this route is only the fast automatic conversion.
        'info': 'mdblist_userlist',
        'user_slug': username,
        'list_slug': slug,
        'type': tmdbh_type,
        'tmdb_type': tmdbh_type,
        'url': raw_url,
        'widget': 'True',
    })


def _tmdbhelper_tmdb_list_url(list_id, media_filter='auto'):
    tmdbh_type = _tmdbhelper_media_type(media_filter)
    return _tmdbhelper_native_url({
        'info': 'tmdb_list',
        'list_id': list_id,
        'tmdb_type': tmdbh_type,
        'type': tmdbh_type,
        'widget': 'True',
    })


def _tmdbhelper_native_route_from_entry(entry):
    entry = entry or {}
    payload = entry.get('payload') or {}
    kind = (entry.get('kind') or '').strip()
    media_filter = payload.get('mediaFilter') or payload.get('catalogType') or 'auto'
    label = entry.get('name') or payload.get('listName') or payload.get('addonName') or 'TMDb Helper'

    if kind == 'traktList':
        username = str(payload.get('username') or payload.get('user_slug') or '').strip()
        slug = str(payload.get('listSlug') or payload.get('slug') or payload.get('list_slug') or '').strip()
        if username and slug:
            return _tmdbhelper_trakt_list_url(username, slug, media_filter), label

    if kind == 'mdblistList':
        username = str(payload.get('username') or payload.get('user_slug') or '').strip()
        slug = str(payload.get('listSlug') or payload.get('slug') or payload.get('list_slug') or '').strip()
        if username and slug:
            return _tmdbhelper_mdblist_url(username, slug, media_filter, raw_url=payload.get('url') or ''), label

    if kind == 'kodiPluginRoute':
        route = str(payload.get('route') or payload.get('url') or '').strip()
        if route and _plugin_route_is_tmdbhelper(route):
            return route, label

    # Advanced/manual entries may already carry a public TMDb list URL.
    raw_url = str(payload.get('url') or payload.get('route') or '').strip()
    parsed_tmdb = _parse_tmdb_list_url(raw_url)
    if parsed_tmdb:
        return _tmdbhelper_tmdb_list_url(parsed_tmdb.get('list_id'), media_filter), parsed_tmdb.get('name') or label

    return '', ''


def _tmdbhelper_native_payload(route_url, label='', media_filter='auto'):
    payload = _kodi_route_payload(route_url, label=label or 'TMDb Helper', media_filter=media_filter)
    payload['addonId'] = 'plugin.video.themoviedb.helper'
    payload['addonName'] = 'TMDb Helper'
    return payload

def _list_installed_video_addons():
    rows = []
    try:
        payload = {
            'jsonrpc': '2.0',
            'id': 1,
            'method': 'Addons.GetAddons',
            'params': {
                'type': 'xbmc.addon.video',
                'properties': ['name', 'summary', 'thumbnail', 'fanart', 'enabled'],
            },
        }
        raw = xbmc.executeJSONRPC(json.dumps(payload))
        data = json.loads(raw or '{}')
        for addon in ((data.get('result') or {}).get('addons') or []):
            addon_id = str(addon.get('addonid') or '').strip()
            if not addon_id or addon_id == ADDON.getAddonInfo('id'):
                continue
            if addon.get('enabled') is False:
                continue
            rows.append({
                'id': addon_id,
                'name': addon.get('name') or addon_id,
                'summary': addon.get('summary') or '',
                'thumbnail': addon.get('thumbnail') or '',
                'fanart': addon.get('fanart') or '',
            })
    except Exception as exc:
        xbmc.log('[DexHub] list installed video addons failed: %s' % exc, xbmc.LOGWARNING)
    rows.sort(key=lambda x: (str(x.get('name') or '')).lower(), reverse=False)
    return rows


def _pick_installed_video_addon():
    rows = _list_installed_video_addons()
    if not rows:
        error(tr('لا توجد إضافات فيديو مثبّتة'))
        return None
    labels = [row.get('name') or row.get('id') or 'Addon' for row in rows]
    choice = xbmcgui.Dialog().select(tr('اختر إضافة Kodi'), [tr(x) for x in labels])
    if choice < 0 or choice >= len(rows):
        return None
    return rows[choice]


def _normalize_plugin_route(addon_id, route_text=''):
    addon_id = str(addon_id or '').strip()
    route_text = str(route_text or '').strip()
    if not addon_id and not route_text.startswith('plugin://'):
        return ''
    if route_text.startswith('plugin://'):
        return route_text
    if not route_text:
        return 'plugin://%s/' % addon_id
    if route_text.startswith('?'):
        return 'plugin://%s/%s' % (addon_id, route_text)
    if route_text.startswith('/'):
        return 'plugin://%s%s' % (addon_id, route_text)
    return 'plugin://%s/%s' % (addon_id, route_text)


def _list_plugin_directory_items(directory):
    directory = str(directory or '').strip()
    if not directory:
        return []
    rows = []

    # v3.9.121: keep Kodi/TMDb Helper rows rich.  The old proxy only asked
    # JSON-RPC for title/thumbnail/fanart/plot, so every linked helper list lost
    # clearlogo, poster, ratings, genres, year, studio, unique IDs, etc.  Ask for
    # the same video fields Kodi exposes to skins, then fall back to the tiny
    # safe set if an older build rejects one of the rich properties.
    rich_props = [
        'title', 'originaltitle', 'thumbnail', 'fanart', 'art', 'plot', 'plotoutline',
        'tagline', 'genre', 'year', 'rating', 'userrating', 'ratings', 'votes',
        'runtime', 'duration', 'studio', 'mpaa', 'country', 'premiered', 'firstaired',
        'dateadded', 'trailer', 'playcount', 'lastplayed', 'director', 'writer',
        'cast', 'season', 'episode', 'showtitle', 'tvshowid', 'imdbnumber', 'uniqueid',
        'resume', 'streamdetails',
    ]
    minimal_props = ['title', 'thumbnail', 'fanart', 'plot']

    def _fetch(props):
        payload = {
            'jsonrpc': '2.0',
            'id': 1,
            'method': 'Files.GetDirectory',
            'params': {
                'directory': directory,
                'media': 'video',
                'properties': props,
            },
        }
        raw = xbmc.executeJSONRPC(json.dumps(payload))
        data = json.loads(raw or '{}')
        if data.get('error'):
            raise ValueError(str(data.get('error')))
        return (data.get('result') or {}).get('files') or []

    try:
        try:
            items = _fetch(rich_props)
        except Exception as rich_exc:
            xbmc.log('[DexHub] rich plugin directory read failed for %s: %s; falling back' % (directory, rich_exc), xbmc.LOGDEBUG)
            items = _fetch(minimal_props)
        for item in items:
            if not isinstance(item, dict):
                continue
            file_url = str(item.get('file') or '').strip()
            if not file_url.startswith('plugin://'):
                continue
            filetype = str(item.get('filetype') or '').strip().lower()
            label = str(item.get('label') or item.get('title') or item.get('label2') or file_url).strip()
            row = dict(item)
            row.update({
                'file': file_url,
                'label': label or file_url,
                'is_folder': filetype == 'directory',
                'thumbnail': item.get('thumbnail') or '',
                'fanart': item.get('fanart') or '',
                'plot': item.get('plot') or '',
            })
            rows.append(row)
    except Exception as exc:
        xbmc.log('[DexHub] list plugin directory failed for %s: %s' % (directory, exc), xbmc.LOGWARNING)
    return rows


def _normalize_tmdbhelper_route(route_url):
    """Return TMDb Helper/Kodi routes exactly as saved.

    v3.9.135: do not rewrite TMDb Helper paths.  The v3.9.132-134 repair
    normalized root/query paths (for example inserting a slash before ?info=),
    but some TMDb Helper/widget paths are only reliable when opened exactly as
    the skin saved them.  Keeping the raw route also matches the stable v3.9.119
    playback behaviour the user verified.
    """
    return html.unescape(str(route_url or '').strip().strip('"\''))


def _plugin_route_is_tmdbhelper(route_url):
    try:
        route_url = _normalize_tmdbhelper_route(route_url)
        parsed = urlparse(str(route_url or '').strip())
        return (parsed.scheme or '').lower() == 'plugin' and (parsed.netloc or '').lower() == 'plugin.video.themoviedb.helper'
    except Exception:
        return 'plugin.video.themoviedb.helper' in str(route_url or '').lower()



def _open_plugin_route_native(route_url):
    route_url = _extract_kodi_path_from_widget_value(route_url)
    # Keep the exact widget/plugin route.  Do not normalize TMDb Helper paths.
    if not route_url:
        return False
    try:
        if _is_kodi_builtin(route_url):
            xbmc.executebuiltin(route_url)
            return True
        if _is_kodi_native_uri(route_url):
            quoted = _kodi_builtin_arg(route_url) if '_kodi_builtin_arg' in globals() else route_url
            # This is only a fallback/explicit launcher.  The collection card
            # itself uses the raw plugin:// path because that is what worked in
            # v3.9.124 and is the same style Kodi uses for favourites/widgets.
            xbmc.executebuiltin('Container.Update(%s,replace)' % quoted)
            return True
    except Exception as exc:
        xbmc.log('[DexHub] native Kodi route open failed for %s: %s' % (route_url, exc), xbmc.LOGWARNING)
    return False


def _plugin_row_query(row):
    try:
        return parse_qs((urlparse(str((row or {}).get('file') or '')).query or ''), keep_blank_values=True)
    except Exception:
        return {}


def _first_query_value(qs, *keys):
    for key in keys:
        vals = (qs or {}).get(key) or (qs or {}).get(key.lower()) or (qs or {}).get(key.upper())
        if isinstance(vals, (list, tuple)) and vals:
            val = str(vals[0] or '').strip()
        else:
            val = str(vals or '').strip() if vals else ''
        if val:
            return val
    return ''


def _plugin_row_ids(row):
    row = row or {}
    unique = row.get('uniqueid') or {}
    if not isinstance(unique, dict):
        unique = {}
    qs = _plugin_row_query(row)
    imdb = str(unique.get('imdb') or unique.get('imdb_id') or row.get('imdbnumber') or _first_query_value(qs, 'imdb_id', 'imdb')).strip()
    tmdb = str(unique.get('tmdb') or unique.get('tmdb_id') or _first_query_value(qs, 'tmdb_id', 'tmdb')).strip()
    tvdb = str(unique.get('tvdb') or unique.get('tvdb_id') or _first_query_value(qs, 'tvdb_id', 'tvdb')).strip()
    if imdb and imdb.isdigit():
        imdb = 'tt%s' % imdb
    return {'imdb_id': imdb, 'tmdb_id': tmdb, 'tvdb_id': tvdb}


def _plugin_row_media_type(row):
    row = row or {}
    qs = _plugin_row_query(row)
    raw = str(row.get('mediatype') or row.get('type') or _first_query_value(qs, 'type', 'mediatype', 'media_type') or '').strip().lower()
    info = str(_first_query_value(qs, 'info') or '').strip().lower()
    if raw in ('tv', 'show', 'series', 'tvshow', 'tvshows'):
        return 'tvshow'
    if raw in ('episode', 'episodes') or info in ('play_episode', 'episode'):
        return 'episode'
    if raw in ('season', 'seasons'):
        return 'season'
    if raw in ('movie', 'movies', 'film'):
        return 'movie'
    if row.get('showtitle') or row.get('season') not in (None, '') or row.get('episode') not in (None, ''):
        return 'episode' if row.get('episode') not in (None, '') else 'tvshow'
    return 'movie'


def _plugin_row_info(row, label=''):
    row = row or {}
    media_type = _plugin_row_media_type(row)
    info = {
        'title': row.get('title') or label or row.get('label') or '',
        'plot': row.get('plot') or '',
        'plotoutline': row.get('plotoutline') or '',
        'tagline': row.get('tagline') or '',
        'originaltitle': row.get('originaltitle') or '',
        'mediatype': media_type,
    }
    if media_type == 'tvshow':
        info['tvshowtitle'] = info.get('title') or ''
    elif media_type == 'episode':
        info['tvshowtitle'] = row.get('showtitle') or row.get('tvshowtitle') or ''

    for key in ('year', 'playcount', 'season', 'episode'):
        if row.get(key) not in (None, ''):
            try:
                info[key] = int(row.get(key))
            except Exception:
                pass
    rating = row.get('rating') if row.get('rating') not in (None, '') else row.get('userrating')
    if rating not in (None, ''):
        try:
            info['rating'] = float(rating)
        except Exception:
            pass
    votes = row.get('votes')
    if votes not in (None, ''):
        try:
            info['votes'] = int(str(votes).replace(',', ''))
        except Exception:
            pass
    duration = row.get('runtime') if row.get('runtime') not in (None, '') else row.get('duration')
    if duration not in (None, ''):
        try:
            info['duration'] = int(float(duration))
        except Exception:
            pass
    for src_key, dst_key in (
        ('genre', 'genre'), ('studio', 'studio'), ('mpaa', 'mpaa'), ('country', 'country'),
        ('premiered', 'premiered'), ('firstaired', 'premiered'), ('trailer', 'trailer'),
        ('director', 'director'), ('writer', 'writer'), ('cast', 'cast'), ('streamdetails', 'streamdetails'),
    ):
        val = row.get(src_key)
        if val not in (None, '', [], {}):
            info[dst_key] = val
    ids = _plugin_row_ids(row)
    if ids.get('imdb_id'):
        info['imdbnumber'] = ids.get('imdb_id')
    return {k: v for k, v in info.items() if v not in (None, '', [], {})}


def _plugin_art_value(art, *keys):
    if not isinstance(art, dict):
        return ''
    lowered = {str(k).lower(): v for k, v in art.items()}
    for key in keys:
        val = art.get(key)
        if val:
            return str(val)
        val = lowered.get(str(key).lower())
        if val:
            return str(val)
    return ''


def _plugin_row_art(row, background=''):
    row = row or {}
    raw_art = row.get('art') if isinstance(row.get('art'), dict) else {}
    thumb = _wrap_tokenized_url(row.get('thumbnail') or _plugin_art_value(raw_art, 'thumb', 'icon'))
    poster = _wrap_tokenized_url(_plugin_art_value(raw_art, 'poster', 'tvshow.poster', 'season.poster', 'thumb', 'icon')) or thumb
    fanart = _wrap_tokenized_url(row.get('fanart') or _plugin_art_value(raw_art, 'fanart', 'tvshow.fanart', 'season.fanart', 'background')) or background or addon_fanart()
    landscape = _wrap_tokenized_url(_plugin_art_value(raw_art, 'landscape', 'tvshow.landscape', 'season.landscape', 'fanart')) or fanart or poster
    clearlogo = _wrap_tokenized_url(_plugin_art_value(raw_art, 'clearlogo', 'logo', 'tvshow.clearlogo', 'season.clearlogo'))
    clearart = _wrap_tokenized_url(_plugin_art_value(raw_art, 'clearart', 'tvshow.clearart'))
    banner = _wrap_tokenized_url(_plugin_art_value(raw_art, 'banner', 'tvshow.banner', 'season.banner'))
    if not poster:
        poster = thumb or landscape or fanart
    out = {
        'poster': poster,
        'tvshow.poster': _wrap_tokenized_url(_plugin_art_value(raw_art, 'tvshow.poster')) or poster,
        'season.poster': _wrap_tokenized_url(_plugin_art_value(raw_art, 'season.poster')) or poster,
        'thumb': thumb or poster,
        'icon': thumb or poster,
        'thumbnail': thumb or poster,
        'cover': poster,
        'image': poster,
        'tvshow.thumb': _wrap_tokenized_url(_plugin_art_value(raw_art, 'tvshow.thumb')) or thumb or poster,
        'fanart': fanart,
        'landscape': landscape,
        'banner': banner or landscape,
        'clearlogo': clearlogo,
        'logo': clearlogo,
        'tvshow.clearlogo': clearlogo,
        'clearart': clearart,
    }
    return {k: v for k, v in out.items() if v}


def _browse_kodi_plugin_route(addon_row, start_route=''):
    addon_id = str((addon_row or {}).get('id') or '').strip()
    addon_name = str((addon_row or {}).get('name') or addon_id or 'Kodi').strip()
    current = _normalize_plugin_route(addon_id, start_route or '')
    if not current:
        return '', ''
    root = _normalize_plugin_route(addon_id, '')
    history = []
    current_label = addon_name
    browse_steps = 0
    while browse_steps < 30:
        browse_steps += 1
        items = _list_plugin_directory_items(current)
        labels = []
        actions = []
        if history:
            labels.append('.. %s' % tr('السابق'))
            actions.append(('back', None))
        labels.append('[COLOR yellow]%s[/COLOR]' % tr('استخدم هذا المسار'))
        actions.append(('choose_current', {'file': current, 'label': current_label or addon_name}))
        labels.append('[COLOR grey]%s[/COLOR]' % tr('إدخال يدوي'))
        actions.append(('manual', {'file': current, 'label': current_label or addon_name}))
        for item in items:
            icon = '📁 ' if item.get('is_folder') else '▶ '
            labels.append('%s%s' % (icon, item.get('label') or item.get('file') or 'Item'))
            actions.append(('entry', item))
        title = '%s — %s' % (tr('اختر مسار من الإضافة'), addon_name)
        choice = xbmcgui.Dialog().select(title, labels)
        if choice < 0:
            return '', ''
        action, payload = actions[choice]
        if action == 'back':
            current, current_label = history.pop()
            continue
        if action == 'choose_current':
            return str((payload or {}).get('file') or current).strip(), str((payload or {}).get('label') or current_label or addon_name).strip()
        if action == 'manual':
            route_text = _prompt_text(str((payload or {}).get('file') or current), 'رابط أو مسار plugin://')
            if route_text is None:
                continue
            route_url = _normalize_plugin_route(addon_id, route_text)
            if route_url:
                return route_url, str((payload or {}).get('label') or addon_name).strip()
            error(tr('رابط plugin غير صالح'))
            continue
        item = payload or {}
        item_file = str(item.get('file') or '').strip()
        item_label = str(item.get('label') or item_file or addon_name).strip()
        if not item_file:
            continue
        if item.get('is_folder'):
            history.append((current, current_label or addon_name))
            current = item_file
            current_label = item_label or addon_name
            continue
        return item_file, item_label or addon_name
    return '', ''


def _pick_kodi_plugin_route(addon_row, default_route=''):
    addon_id = str((addon_row or {}).get('id') or '').strip()
    choices = [tr('استعراض الإضافة'), tr('إدخال يدوي')]
    default_idx = 0
    mode_idx = xbmcgui.Dialog().select(tr('طريقة اختيار المسار'), choices, preselect=default_idx)
    if mode_idx < 0:
        return '', ''
    if mode_idx == 0:
        return _browse_kodi_plugin_route(addon_row, start_route=default_route)
    route_text = _prompt_text(str(default_route or 'plugin://%s/' % addon_id), 'رابط أو مسار plugin://')
    if route_text is None:
        return '', ''
    route_url = _normalize_plugin_route(addon_id, route_text)
    if not route_url:
        error(tr('رابط plugin غير صالح'))
        return '', ''
    return route_url, str((addon_row or {}).get('name') or addon_id or 'Kodi').strip()



# ─────────────────────────────────────────────────────────────────────
# Collection Kodi path picker — skin/widget compatible
#
# v3.9.127: keep the fast native-shortcut behavior from 3.9.124, but stop
# trying to re-implement every add-on browser inside Dex Hub.  Kodi skins that
# use script.skinshortcuts already have a mature widget/path picker that can
# browse plugin://, videodb://, library:// and add-on nodes exactly like the
# skin editor.  We call Skin Shortcuts' "Just Select Widgets" mode, read the
# returned Skin.String(widgetPath/widgetName), and save that path verbatim as a
# Dex Hub collection shortcut.  This mirrors the skin workflow and fixes add-ons
# whose deeper sections do not expose well through Files.GetDirectory.
# ─────────────────────────────────────────────────────────────────────

_WIDGET_PICK_KEYS = {
    'widget': 'dexhub.tmp.widget',
    'type': 'dexhub.tmp.widget.type',
    'name': 'dexhub.tmp.widget.name',
    'target': 'dexhub.tmp.widget.target',
    'path': 'dexhub.tmp.widget.path',
}

_KODI_CONTAINER_SCHEMES = (
    'plugin://', 'videodb://', 'musicdb://', 'library://', 'addons://',
    'sources://', 'special://', 'pvr://', 'upnp://', 'smb://', 'nfs://',
    'ftp://', 'ftps://', 'http://', 'https://'
)


def _skin_string(name):
    try:
        return xbmc.getInfoLabel('Skin.String(%s)' % name).strip()
    except Exception:
        return ''


def _skin_reset(name):
    try:
        xbmc.executebuiltin('Skin.Reset(%s)' % name)
    except Exception:
        pass


def _is_kodi_native_uri(value):
    value = str(value or '').strip().lower()
    return bool(value and value.startswith(_KODI_CONTAINER_SCHEMES))


def _is_kodi_builtin(value):
    value = str(value or '').strip().lower()
    return value.startswith(('activatewindow(', 'container.update(', 'runplugin(', 'runscript('))


def _kodi_builtin_arg(value):
    # Kodi builtins split arguments on commas.  Widget paths from TMDb Helper
    # can contain commas, ampersands or encoded JSON, so quote every path that
    # we pass to ActivateWindow/Container.Update.  json.dumps produces a Kodi-
    # friendly quoted string and escapes embedded quotes safely.
    return json.dumps(str(value or '').strip())


def _split_builtin_args(arg_text):
    out, cur, depth, quote = [], [], 0, ''
    for ch in str(arg_text or ''):
        if quote:
            cur.append(ch)
            if ch == quote:
                quote = ''
            continue
        if ch in ('"', "'"):
            quote = ch
            cur.append(ch)
            continue
        if ch == '(':
            depth += 1
            cur.append(ch)
            continue
        if ch == ')':
            depth = max(0, depth - 1)
            cur.append(ch)
            continue
        if ch == ',' and depth == 0:
            out.append(''.join(cur).strip().strip('"\''))
            cur = []
            continue
        cur.append(ch)
    if cur:
        out.append(''.join(cur).strip().strip('"\''))
    return out


def _extract_kodi_path_from_widget_value(value):
    """Return the usable Kodi path from Skin Shortcuts/widget values.

    Skin Shortcuts may return a clean widgetPath (plugin://...), or an action
    string such as ActivateWindow(Videos,plugin://...,return).  Store the clean
    path when possible; otherwise store the builtin exactly so we can execute it.
    """
    value = html.unescape(str(value or '')).strip()
    if not value:
        return ''
    if value.startswith('"') and value.endswith('"'):
        value = value[1:-1].strip()
    lower = value.lower()
    if _is_kodi_native_uri(value):
        return value

    # Common skin action wrappers.
    for func in ('ActivateWindow', 'Container.Update', 'RunPlugin'):
        prefix = func.lower() + '('
        if lower.startswith(prefix) and value.endswith(')'):
            inner = value[value.find('(') + 1:-1]
            parts = _split_builtin_args(inner)
            if func == 'ActivateWindow':
                for part in parts[1:]:
                    if _is_kodi_native_uri(part):
                        return part
            else:
                for part in parts:
                    if _is_kodi_native_uri(part):
                        return part
            return value

    # Last resort: find a Kodi URI embedded inside a longer skin expression.
    m = re.search(r'((?:plugin|videodb|musicdb|library|addons|sources|special|pvr|upnp|smb|nfs|ftp|ftps|https?)://[^\s\)\]\}\"\']+)', value, re.I)
    if m:
        return m.group(1).strip()
    if _is_kodi_builtin(value):
        return value
    return value


def _addon_id_from_kodi_path(path):
    try:
        parsed = urlparse(str(path or '').strip())
        if (parsed.scheme or '').lower() == 'plugin':
            return (parsed.netloc or '').strip()
    except Exception:
        pass
    return ''


def _addon_meta_for_id(addon_id):
    addon_id = str(addon_id or '').strip()
    if not addon_id:
        return {}
    try:
        payload = {
            'jsonrpc': '2.0',
            'id': 1,
            'method': 'Addons.GetAddonDetails',
            'params': {
                'addonid': addon_id,
                'properties': ['name', 'thumbnail', 'fanart', 'summary', 'enabled'],
            },
        }
        raw = xbmc.executeJSONRPC(json.dumps(payload))
        data = json.loads(raw or '{}')
        addon = ((data.get('result') or {}).get('addon') or {})
        if addon:
            return {
                'id': addon_id,
                'name': addon.get('name') or addon_id,
                'thumbnail': addon.get('thumbnail') or '',
                'fanart': addon.get('fanart') or '',
                'summary': addon.get('summary') or '',
            }
    except Exception as exc:
        xbmc.log('[DexHub] addon meta lookup failed for %s: %s' % (addon_id, exc), xbmc.LOGDEBUG)
    return {'id': addon_id, 'name': addon_id, 'thumbnail': '', 'fanart': '', 'summary': ''}


def _pick_skin_widget_route(default_route='', default_label=''):
    """Use Skin Shortcuts' widget picker and return (path, label, addon_meta)."""
    try:
        if not xbmc.getCondVisibility('System.HasAddon(script.skinshortcuts)'):
            error(tr('إضافة Skin Shortcuts غير مثبتة، لذلك لا يمكن فتح صفحة الويدجت'))
            return '', '', {}
    except Exception:
        pass

    for key in _WIDGET_PICK_KEYS.values():
        _skin_reset(key)

    cmd = (
        'RunScript(script.skinshortcuts,'
        'type=widgets&showNone=false&grouping=default&'
        'skinWidget=%(widget)s&skinWidgetType=%(type)s&'
        'skinWidgetName=%(name)s&skinWidgetTarget=%(target)s&'
        'skinWidgetPath=%(path)s)'
    ) % _WIDGET_PICK_KEYS

    try:
        xbmc.executebuiltin(cmd)
    except Exception as exc:
        error(tr('تعذر فتح صفحة الويدجت: %s') % exc)
        return '', '', {}

    # The picker is modal in normal skins, but RunScript is asynchronous.  Poll
    # for the returned skin strings while the user selects a widget/path.
    selected_path = ''
    selected_name = ''
    selected_thumb = ''
    deadline = time.time() + 180.0
    while time.time() < deadline:
        selected_path = _skin_string(_WIDGET_PICK_KEYS['path'])
        selected_name = _skin_string(_WIDGET_PICK_KEYS['name']) or _skin_string(_WIDGET_PICK_KEYS['widget'])
        selected_thumb = _skin_string(_WIDGET_PICK_KEYS['widget'])
        if selected_path or selected_name:
            break
        xbmc.sleep(250)

    raw_candidates = [selected_path, _skin_string(_WIDGET_PICK_KEYS['target']), _skin_string(_WIDGET_PICK_KEYS['widget'])]
    route = ''
    for candidate in raw_candidates:
        route = _extract_kodi_path_from_widget_value(candidate)
        if route and (_is_kodi_native_uri(route) or _is_kodi_builtin(route)):
            break
    if not route:
        # Keep a manual escape hatch so the user does not lose the flow if the
        # skin returned an unusual custom widget action.
        typed = _prompt_text(str(default_route or ''), 'لم يرجع السكين مسارًا واضحًا. ألصق المسار يدويًا')
        route = _extract_kodi_path_from_widget_value(typed or '')
    if not route:
        return '', '', {}

    label = selected_name or default_label or _derive_name_from_slug(route.split('?', 1)[0].rstrip('/').rsplit('/', 1)[-1]) or 'Kodi'
    addon_id = _addon_id_from_kodi_path(route)
    addon_meta = _addon_meta_for_id(addon_id) if addon_id else {}
    if selected_thumb and not addon_meta.get('thumbnail') and _is_kodi_native_uri(selected_thumb):
        addon_meta['thumbnail'] = selected_thumb
    return route, label, addon_meta


def _kodi_route_payload(route_url, label='', media_filter='auto'):
    route_url = _extract_kodi_path_from_widget_value(route_url)
    # Keep the exact widget/plugin route.  Do not normalize TMDb Helper paths.
    addon_id = _addon_id_from_kodi_path(route_url)
    meta = _addon_meta_for_id(addon_id) if addon_id else {}
    return {
        'addonId': addon_id,
        'addonName': meta.get('name') or label or addon_id or 'Kodi',
        'route': route_url,
        'mediaFilter': media_filter or 'auto',
        'thumbnail': meta.get('thumbnail') or '',
        'fanart': meta.get('fanart') or '',
    }


def _prompt_local_json_file():
    try:
        path = xbmcgui.Dialog().browseSingle(1, tr('اختر ملف JSON محلي'), 'files', '.json|.txt', False, False, '')
    except Exception:
        path = ''
    path = str(path or '').strip()
    if path:
        return path
    return _prompt_text('', 'مسار ملف JSON محلي')


def _read_text_from_path(path):
    path = str(path or '').strip()
    if not path:
        raise ValueError('المسار فارغ')
    fh = None
    try:
        fh = xbmcvfs.File(path)
        data = fh.read()
    except Exception:
        translated = xbmcvfs.translatePath(path)
        with open(translated, 'rb') as fh2:
            data = fh2.read()
    finally:
        try:
            if fh:
                fh.close()
        except Exception:
            pass
    if isinstance(data, bytes):
        for enc in ('utf-8-sig', 'utf-8', 'cp1256', 'latin-1'):
            try:
                return data.decode(enc)
            except Exception:
                pass
        return data.decode('utf-8', 'replace')
    return str(data or '')


def _coerce_catalog_media_type(value, default='movie'):
    value = str(value or default).strip().lower()
    mapping = {
        'movie': 'movie', 'movies': 'movie', 'film': 'movie',
        'series': 'series', 'show': 'series', 'tv': 'series', 'tvshow': 'series', 'tvshows': 'series',
        'anime': 'anime',
        'episode': 'series', 'episodes': 'series',
    }
    return mapping.get(value, default or 'movie')


def _canonical_from_ids(media_type, title, year='', tmdb_id='', imdb_id='', tvdb_id=''):
    if tmdb_id:
        return 'tmdb:%s' % tmdb_id
    if imdb_id:
        return imdb_id
    if tvdb_id:
        return 'tvdb:%s' % tvdb_id
    # v3.9.45: was 'clean_title(...)', which raised NameError because
    # the helper is named _clean_title_for_key. Triggered only on Local
    # JSON Catalog items lacking external ids, which is why it sat
    # latent — but when it fired, the whole catalog load crashed.
    slug = _clean_title_for_key(title or '')
    if year:
        slug = '%s %s' % (slug, year)
    return slug or (title or 'item')


def _parse_local_json_catalog(text):
    try:
        data = json.loads(text)
    except Exception:
        try:
            data = json.loads((text or '').lstrip('﻿'))
        except Exception:
            raise ValueError('JSON غير صالح')
    meta = {}
    try:
        data = _collections_mod._flatten_fusion_widgets(data)
    except Exception:
        pass
    if isinstance(data, dict):
        for key in ('items', 'results', 'entries', 'videos', 'catalog', 'collections', 'widgets', 'folders'):
            if isinstance(data.get(key), list):
                meta = dict(data.get('meta') or {})
                data = data[key]
                break
        else:
            data = [data]
    try:
        data = _collections_mod._flatten_fusion_widgets(data)
    except Exception:
        pass
    if not isinstance(data, list):
        raise ValueError('الملف لا يحتوي على قائمة عناصر')
    return data, meta


def _render_local_json_catalog(entry, payload):
    file_path = str(payload.get('filePath') or payload.get('path') or '').strip()
    if not file_path:
        error(tr('مسار الملف غير موجود'))
        return end_dir()
    try:
        text = _read_text_from_path(file_path)
        rows, meta = _parse_local_json_catalog(text)
    except Exception as exc:
        error(tr('فشل قراءة ملف JSON: %s') % exc)
        return end_dir()
    if not rows:
        error(tr('الملف لا يحتوي على عناصر'))
        return end_dir()

    try:
        limit = max(0, int(payload.get('limit') or 0))
    except Exception:
        limit = 0
    if limit > 0:
        rows = rows[:limit]

    win = xbmcgui.Window(WINDOW_ID)
    bg = entry.get('background') or meta.get('fanart') or meta.get('background') or ''
    if bg:
        win.setProperty('fanart', bg)

    content_hint = _coerce_catalog_media_type(payload.get('mediaFilter') or meta.get('media_type') or 'movie')
    has_seriesish = False
    has_movies = False
    added = 0
    fallback_art = root_art('catalogs')

    for raw in rows:
        if not isinstance(raw, dict):
            continue
        title = str(raw.get('title') or raw.get('name') or '').strip()
        if not title:
            continue
        media_type = _coerce_catalog_media_type(raw.get('media_type') or raw.get('type') or raw.get('mediatype') or content_hint, content_hint)
        ids_raw = raw.get('ids') if isinstance(raw.get('ids'), dict) else {}
        tmdb_id = str(raw.get('tmdb_id') or ids_raw.get('tmdb') or '').strip()
        imdb_id = str(raw.get('imdb_id') or ids_raw.get('imdb') or '').strip()
        tvdb_id = str(raw.get('tvdb_id') or ids_raw.get('tvdb') or '').strip()
        year = str(raw.get('year') or raw.get('release_year') or '').strip()
        season = str(raw.get('season') or '').strip()
        episode = str(raw.get('episode') or '').strip()
        video_id = str(raw.get('video_id') or raw.get('id') or '').strip()
        canonical_id = str(raw.get('canonical_id') or raw.get('id') or '').strip()
        if not canonical_id or canonical_id == video_id:
            canonical_id = _canonical_from_ids(media_type, title, year=year, tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id)

        direct_path = str(raw.get('path') or raw.get('url') or raw.get('plugin_url') or '').strip()
        if direct_path:
            is_folder = bool(raw.get('is_folder')) if 'is_folder' in raw else direct_path.startswith('plugin://')
            path = direct_path
        else:
            path, is_folder = _content_click_path(media_type=media_type, canonical_id=canonical_id, title=title, tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id, season=season, episode=episode, video_id=video_id or canonical_id, ui_seed={
                'poster': raw.get('poster') or raw.get('thumb') or raw.get('image') or raw.get('poster_url') or '',
                'fanart': raw.get('fanart') or raw.get('background') or raw.get('backdrop') or raw.get('fanart_url') or '',
                'clearlogo': raw.get('clearlogo') or raw.get('logo') or '',
            })

        poster = str(raw.get('poster') or raw.get('thumb') or raw.get('image') or raw.get('poster_url') or '').strip()
        fanart = str(raw.get('fanart') or raw.get('background') or raw.get('backdrop') or raw.get('fanart_url') or '').strip()
        landscape = str(raw.get('landscape') or raw.get('banner') or '').strip()
        clearlogo = str(raw.get('clearlogo') or raw.get('logo') or '').strip()
        plot = str(raw.get('plot') or raw.get('description') or raw.get('overview') or '').strip()
        info = {'title': title, 'plot': plot, 'mediatype': 'tvshow' if media_type in ('series', 'anime') else 'movie'}
        if str(year).isdigit():
            info['year'] = int(year)
        if season.isdigit():
            info['season'] = int(season)
            has_seriesish = True
        if episode.isdigit():
            info['episode'] = int(episode)
            info['mediatype'] = 'episode'
            has_seriesish = True
        if media_type in ('series', 'anime'):
            has_seriesish = True
        elif media_type == 'movie':
            has_movies = True

        art = {'poster': poster or bg or fallback_art.get('poster') or '', 'thumb': poster or bg or fallback_art.get('thumb') or '', 'fanart': fanart or bg or fallback_art.get('fanart') or addon_fanart(), 'landscape': landscape or fanart or poster or bg or '', 'clearlogo': clearlogo or ''}
        ids = {'tmdb': tmdb_id or '', 'imdb': imdb_id or '', 'tvdb': tvdb_id or ''}
        ctx_menu = []
        if not direct_path:
            ctx_menu = _build_source_picker_menu(media_type=media_type, canonical_id=canonical_id, title=title, season=season, episode=episode, video_id=video_id or canonical_id) + _build_player_chooser_menu(media_type=media_type, canonical_id=canonical_id, title=title, tmdb_id=tmdb_id, imdb_id=imdb_id, tvdb_id=tvdb_id, season=season, episode=episode, video_id=video_id or canonical_id)
        add_item(title, path, is_folder=is_folder, info=info, art=art, ids=ids,
                 properties={'dexhub.tile_shape': 'poster', 'dexhub.work_item': '1',
                             'dexhub.clearlogo_as_title': '1'}, context_menu=ctx_menu)
        added += 1

    if added == 0:
        error(tr('الملف لا يحتوي على عناصر صالحة'))
        return end_dir()
    if has_seriesish and has_movies:
        return end_dir(content='videos')
    if has_seriesish:
        return end_dir(content='tvshows')
    return end_dir(content='movies')


def _collection_skip_gate_enabled(entry):
    entry = entry or {}
    raw = entry.get('open_mode')
    # Imported Nuvio/Fusion catalogSources behave like skin widgets. Opening
    # them through Dex Hub's filter-gate adds an extra folder and makes the
    # collection feel slow, so default multiCatalog to direct open unless the
    # user explicitly changed it back to normal.
    if raw in (None, '') and str(entry.get('kind') or '').strip() == 'multiCatalog':
        return True
    return str(raw or 'normal').strip().lower() == 'skip'


def _collection_entry_preview(entry):
    payload = entry.get('payload') or {}
    kind = (entry.get('kind') or '').strip()
    label = entry.get('name') or 'Collection'
    background = entry.get('background') or ''
    entry_poster = entry.get('poster') or ''
    preview = {'plot': '', 'poster': entry_poster or '', 'fanart': background or '', 'landscape': background or entry_poster or '', 'clearlogo': entry.get('clearlogo') or ''}
    open_mode_label = _collection_open_mode_label(entry.get('open_mode') or 'normal')
    if kind == 'nuvioGroup':
        folders = payload.get('folders') or []
        # v5.4.20: never steal artwork from the first child folder. A parent
        # collection called "Streaming Services" must not suddenly become
        # Netflix in AF3. Use only artwork owned by the group itself; callers
        # provide a packaged modern section icon when the export has no cover.
        preview['poster'] = entry_poster or ''
        preview['fanart'] = background or addon_fanart()
        preview['landscape'] = entry_poster or ''
        preview['clearlogo'] = entry.get('clearlogo') or ''
        preview['plot'] = tr('مجموعة Nuvio/Kaptain • %d مجلد') % len(folders)
        return preview
    if kind == 'nuvioFolder':
        sources = payload.get('sources') or []
        folder_art = root_art('catalogs')
        preview['poster'] = entry_poster or background or folder_art.get('poster') or folder_art.get('thumb') or ''
        preview['fanart'] = background or folder_art.get('fanart') or addon_fanart()
        preview['landscape'] = background or preview['poster'] or ''
        preview['plot'] = tr('مجلد Nuvio/Kaptain • %d مصدر') % len(sources)
        return preview
    if kind == 'addonCatalog':
        provider = _provider_for_addon_ref(payload.get('addonId') or '')
        catalog_id = (payload.get('catalogId') or '').strip()
        catalog_type = (payload.get('catalogType') or 'movie').strip()
        try:
            catalog_id, catalog_type = _collections_mod.normalize_catalog_id_and_type(catalog_id, catalog_type)
        except Exception:
            pass
        catalog_def = _catalog_definition(provider, catalog_id, catalog_type) if provider else {}
        art = catalog_art(label, catalog_type, (provider or {}).get('manifest') or {}, catalog_def or {})
        folder_art = root_art('catalogs')
        preview['poster'] = entry_poster or background or art.get('poster') or art.get('thumb') or folder_art.get('poster') or folder_art.get('thumb') or ''
        preview['fanart'] = background or art.get('fanart') or folder_art.get('fanart') or addon_fanart()
        preview['landscape'] = background or art.get('landscape') or art.get('fanart') or folder_art.get('landscape') or preview['poster'] or ''
        preview['clearlogo'] = preview.get('clearlogo') or art.get('clearlogo') or ''
        plot_lines = []
        if catalog_def.get('description'):
            plot_lines.append(str(catalog_def.get('description')))
        plot_lines.extend([tr('كتالوج: %s') % catalog_id, tr('النوع: %s') % catalog_type, tr('الفتح: %s') % open_mode_label])
        if provider:
            plot_lines.append(tr('من: %s') % (provider.get('name') or provider.get('id') or payload.get('addonId') or ''))
        elif payload.get('addonId'):
            plot_lines.append(tr('من: %s') % payload.get('addonId'))
        preview['plot'] = '\n'.join([x for x in plot_lines if x])
        return preview
    if kind == 'traktList':
        trakt_art = root_art('trakt')
        folder_art = root_art('catalogs')
        username = (payload.get('username') or '').strip()
        slug = (payload.get('listSlug') or payload.get('slug') or '').strip()
        preview['poster'] = entry_poster or background or trakt_art.get('poster') or trakt_art.get('thumb') or folder_art.get('poster') or folder_art.get('thumb') or ''
        preview['fanart'] = background or trakt_art.get('fanart') or folder_art.get('fanart') or addon_fanart()
        preview['landscape'] = background or trakt_art.get('landscape') or trakt_art.get('fanart') or folder_art.get('landscape') or preview['poster'] or ''
        preview['clearlogo'] = preview.get('clearlogo') or trakt_art.get('clearlogo') or ''
        plot_lines = [tr('قائمة Trakt: %s') % (payload.get('listName') or slug or label), tr('النوع: %s') % _collection_media_filter_label(payload.get('mediaFilter') or 'auto')]
        if username:
            plot_lines.append(tr('المستخدم: %s') % username)
        if slug:
            plot_lines.append(tr('المعرّف: %s') % slug)
        preview['plot'] = '\n'.join([x for x in plot_lines if x])
        return preview
    if kind == 'mdblistList':
        folder_art = root_art('catalogs')
        username = (payload.get('username') or '').strip()
        slug = (payload.get('listSlug') or payload.get('slug') or '').strip()
        preview['poster'] = entry_poster or background or folder_art.get('poster') or folder_art.get('thumb') or ''
        preview['fanart'] = background or folder_art.get('fanart') or addon_fanart()
        preview['landscape'] = background or folder_art.get('landscape') or preview['poster'] or ''
        plot_lines = [tr('قائمة MDBList: %s') % (payload.get('listName') or slug or label), tr('النوع: %s') % _collection_media_filter_label(payload.get('mediaFilter') or 'auto')]
        if username:
            plot_lines.append(tr('المستخدم: %s') % username)
        if slug:
            plot_lines.append(tr('المعرّف: %s') % slug)
        preview['plot'] = '\n'.join([x for x in plot_lines if x])
        return preview
    if kind == 'multiCatalog':
        folder_art = root_art('catalogs')
        sources = payload.get('sources') or []
        preview['poster'] = entry_poster or background or folder_art.get('poster') or folder_art.get('thumb') or ''
        preview['fanart'] = background or folder_art.get('fanart') or addon_fanart()
        preview['landscape'] = background or folder_art.get('landscape') or preview['poster'] or ''
        names = []
        for src in sources[:6]:
            if not isinstance(src, dict):
                continue
            aid = str(src.get('addonId') or '').strip()
            cid = str(src.get('catalogId') or '').strip()
            ctype = str(src.get('catalogType') or src.get('type') or '').strip()
            names.append('%s/%s %s' % (aid, cid, ctype))
        plot_lines = [tr('مصادر متعددة: %d') % len(sources), tr('الفتح: %s') % open_mode_label]
        if names:
            plot_lines.append('\n'.join(names))
        preview['plot'] = '\n'.join([x for x in plot_lines if x])
        return preview
    if kind == 'kodiPluginRoute':
        addon_id = str(payload.get('addonId') or '').strip()
        addon_name = str(payload.get('addonName') or addon_id or 'Kodi')
        preview['poster'] = entry_poster or background or payload.get('thumbnail') or root_art('catalogs').get('poster') or ''
        preview['fanart'] = background or payload.get('fanart') or addon_fanart()
        preview['landscape'] = background or payload.get('fanart') or preview['poster'] or ''
        route_url = str(payload.get('route') or payload.get('url') or '').strip()
        preview['plot'] = '\n'.join([x for x in [tr('إضافة Kodi: %s') % addon_name, tr('المسار: %s') % route_url, tr('الفتح: %s') % open_mode_label] if x])
        return preview
    if kind == 'localJsonCatalog':
        path = str(payload.get('filePath') or payload.get('path') or '').strip()
        media_filter = _collection_media_filter_label(payload.get('mediaFilter') or 'auto')
        preview['poster'] = entry_poster or background or root_art('catalogs').get('poster') or ''
        preview['fanart'] = background or addon_fanart()
        preview['landscape'] = background or preview['poster'] or ''
        preview['plot'] = '\n'.join([x for x in [tr('ملف محلي: %s') % os.path.basename(path or ''), tr('النوع: %s') % media_filter, tr('المسار: %s') % path] if x])
        return preview
    preview['plot'] = tr('نوع غير معروف: %s') % kind
    return preview

def _collection_content_type(entries):
    """Pick Kodi content type to match the layout the user wanted."""
    # If any entry has layout "Wide" or "Banner", use 'tvshows' which renders
    # landscape art nicely in most skins. Otherwise default to 'movies' which
    # renders poster art.
    for e in entries:
        lt = (e.get('layout') or '').lower()
        if lt in ('wide', 'banner', 'landscape'):
            return 'tvshows'
    return 'movies'




def collection_entry_meta_source(set_id, entry_id):
    row = _collections_mod.get_set(set_id)
    if not row:
        error(tr('المجموعة غير موجودة'))
        return
    entry = None
    for e in row.get('entries') or []:
        if e.get('id') == entry_id:
            entry = e
            break
    if not entry:
        error(tr('العنصر غير موجود'))
        return
    kind = (entry.get('kind') or '').strip()
    payload = entry.get('payload') or {}
    if kind in ('nuvioGroup', 'nuvioFolder'):
        target_key = 'virtual.collection.nuvio:%s:%s' % (str(set_id or ''), str(entry.get('id') or entry_id or 'root'))
        return _meta_pick_target(target_key, tr('مزود البوستر والميتاداتا • %s') % (entry.get('name') or 'Nuvio Collection'))
    if kind in ('traktList', 'mdblistList'):
        return _meta_pick_target('virtual.collection.trakt', 'الكوليكشن • عناصر Trakt')
    providers = []
    if kind == 'addonCatalog':
        provider = _provider_for_addon_ref(payload.get('addonId') or '')
        if provider:
            providers = [provider]
    elif kind == 'multiCatalog':
        seen = set()
        for src in payload.get('sources') or []:
            provider = _provider_for_addon_ref((src or {}).get('addonId') or '')
            if provider and provider.get('id') not in seen:
                seen.add(provider.get('id'))
                providers.append(provider)
    if not providers:
        error(tr('هذا العنصر لا يملك إضافة مرتبطة لتغيير الميتاداتا'))
        return
    if len(providers) == 1:
        return meta_pick_for_provider(providers[0].get('id') or '')
    labels = [p.get('name') or p.get('id') or 'Provider' for p in providers]
    choice = xbmcgui.Dialog().select(tr('اختر الإضافة'), [tr(x) for x in labels])
    if choice < 0:
        return
    return meta_pick_for_provider(providers[choice].get('id') or '')


def nuvio_home_media(media='movie'):
    """Lazy entry point for the canonical Nuvio Home renderer."""
    from . import nuvio_home_ui as _nuvio_home_ui
    return _nuvio_home_ui.render_media(media)


def nuvio_media_screen(media='movie'):
    """Compatibility alias for links created by 5.7.0.

    Always render through Kodi's native media container so Arctic Fuse 3 owns
    the page chrome, view mode and navigation.  A private WindowXMLDialog looks
    similar in screenshots but cannot inherit the user's live skin layout.
    """
    from . import nuvio_home_ui as _nuvio_home_ui
    return _nuvio_home_ui.render_media(media)


def _collection_entry_is_silo_navigation(entry):
    """Hide old Silo launcher shortcuts from media Collections.

    Some Nuvio/legacy exports saved Dex Hub's ``silo_menu`` as a collection
    card. Once Silo is a native always-on source that launcher is redundant
    and is exactly the large Silo-logo poster seen between real collections.
    Real Silo/media catalogs are not filtered; only Dex Hub navigation routes
    are removed.
    """
    entry = entry or {}
    payload = entry.get('payload') or {}
    values = []
    if isinstance(payload, dict):
        for key in ('route', 'url', 'path', 'plugin', 'pluginUrl', 'plugin_url'):
            if payload.get(key):
                values.append(str(payload.get(key)))
    route = ' '.join(values).lower()
    return ('plugin.video.dexhub' in route and
            any(token in route for token in ('action=silo_menu', 'action=silo_home',
                                             'action=silo_sections')))


def collections_media(media='movie'):
    """AF3-friendly virtual split of every saved Collection into Movies/TV.

    The built-in Dex Collection is flattened directly to its Nuvio groups, so
    the widget has no redundant "Collection -> Collection" click. Additional
    imports are folded into the same page and are filtered from their frozen
    metadata only; browsing this page never fetches TMDb/Trakt/addon content.
    """
    media_filter = 'series' if str(media or '').lower() in ('series','tv','show','shows','tvshow') else 'movie'
    rows = list(_collections_mod.list_sets() or [])
    cards = []
    for row in rows:
        entries = [e for e in (row.get('entries') or [])
                   if _collections_mod.entry_supports_media(e, media_filter)
                   and not _collection_entry_is_silo_navigation(e)]
        for entry in entries:
            cards.append((row, entry))
    if not cards:
        add_item('[COLOR grey]No collections[/COLOR]', build_url(action='collection_settings_hub'),
                 is_folder=False, art=root_art('catalogs'), info={'title': 'Collections'})
        return end_dir(content='files', cache=True)

    name_counts = {}
    for _row, entry in cards:
        name = str(entry.get('name') or 'Collection')
        name_counts[name.lower()] = name_counts.get(name.lower(), 0) + 1

    first_fanart = ''
    for row, entry in cards:
        label = str(entry.get('name') or 'Collection')
        if name_counts.get(label.lower(), 0) > 1:
            label = '%s • %s' % (row.get('name') or 'Collection', label)
        preview = _collection_entry_preview(entry)
        # v5.4.17: keep Nuvio's CARD artwork separate from its HERO backdrop.
        # AF3 widgets prefer landscape/banner/thumb for the visible tile and
        # fanart for the focused background. 5.4.16 incorrectly put the hero
        # backdrop into landscape/banner, so the background became the card.
        fanart = _wrap_tokenized_url(entry.get('background') or preview.get('fanart') or '')
        explicit_card = _wrap_tokenized_url(entry.get('poster') or '')
        clearlogo = _wrap_tokenized_url(entry.get('clearlogo') or preview.get('clearlogo') or '')
        # v5.4.20: a Nuvio top-level group without its own cover should look
        # like a navigation section, not borrow the first child (Netflix,
        # etc.) as its widget card. User-supplied collection covers still win.
        if (entry.get('kind') or '') == 'nuvioGroup' and not explicit_card:
            # v5.4.21: top-level Collections are true 16:9 banner cards in
            # Home/AF3. Folder/category nodes remain square later inside the
            # collection. This keeps the hierarchy visually obvious:
            # Collection=Banner -> Folder=Icon/optional banner -> Work=Poster.
            art = collection_banner_art(label, fanart=fanart or addon_fanart())
            tile_shape = 'landscape'
            if clearlogo:
                art['clearlogo'] = clearlogo; art['logo'] = clearlogo; art['tvshow.clearlogo'] = clearlogo
        else:
            card = explicit_card or _wrap_tokenized_url(preview.get('poster') or preview.get('landscape') or '')
            card = card or fanart or root_art('catalogs').get('poster') or ''
            art = {
                'icon': card, 'thumb': card, 'poster': card,
                'landscape': card, 'banner': card,
                'fanart': fanart or addon_fanart(), 'clearlogo': clearlogo,
            }
            if clearlogo:
                art['logo'] = clearlogo; art['tvshow.clearlogo'] = clearlogo
            tile_shape = 'landscape' if str(entry.get('layout') or '').lower() in ('wide','banner','landscape') else 'poster'
        if fanart and not first_fanart:
            first_fanart = fanart
        add_item(
            '' if (_clean_collection_view_enabled() and entry.get('hide_title')) else label,
            build_url(action='collection_entry_open', set_id=row.get('id') or '', entry_id=entry.get('id') or '', media_filter=media_filter),
            info={'title': label, 'plot': preview.get('plot') or '', 'mediatype': 'video'},
            art=art,
            properties={'dexhub.tile_shape': tile_shape, 'dexhub.collection_root': '1',
                        'dexhub.collection_media': media_filter, 'dexhub.clearlogo_as_title': '1'},
        )
    if first_fanart:
        try: xbmcgui.Window(WINDOW_ID).setProperty('fanart', first_fanart)
        except Exception: pass
    # v5.4.22: keep collection rails on their own Kodi content bucket.
    # Arctic Fuse 3 remembers view types per add-on/content combination.
    # Using movies/tvshows here made the Collection rail and the real works
    # fight over the same saved view (Row Landscape vs Row Poster). `videos`
    # is intentionally reserved for top-level collection cards; real works
    # keep movies/tvshows in the leaf renderers.
    return end_dir(content='videos', cache=True)


def collection_set_browse(set_id, media_filter=''):
    """List the entries inside one collection set as folders.

    Respects each entry's layout field (Poster | Wide) and enriches collection
    cards with Trakt/addon metadata when available.
    """
    row = _collections_mod.get_set(set_id)
    if not row:
        error(tr('المجموعة غير موجودة'))
        return end_dir()
    entries = [e for e in (row.get('entries') or [])
               if _collections_mod.entry_supports_media(e, media_filter)
               and not _collection_entry_is_silo_navigation(e)]
    win = xbmcgui.Window(WINDOW_ID)
    first_fanart = ''


    if not entries:
        if not row.get('builtin') and not media_filter:
            add_item(
                '[COLOR yellow]+ إضافة عنصر يدويًا[/COLOR]',
                build_url(action='collection_entry_add', set_id=set_id),
                is_folder=False,
                info={'title': 'إضافة عنصر', 'plot': 'أضف اختصارًا (كتالوج أو قائمة Trakt) يدويًا'},
                art=root_art('add'),
            )
        add_item(tr('[COLOR grey]لا توجد عناصر بعد داخل هذه المجموعة[/COLOR]'), build_url(action='collection_set_browse', set_id=set_id, media_filter=media_filter), is_folder=False, info={'title': tr('فارغ')})
        return end_dir(content='files')

    # Hide entries that have no real poster/background — otherwise Kodi
    # shows empty tiles that can't be rescued (we have no fallback IDs
    # because these are virtual shortcuts, not real meta items).
    hide_empty = True
    try:
        hide_empty = (ADDON.getSetting('hide_empty_collection_entries') or 'true').lower() not in ('false', '0', 'no')
    except Exception:
        pass

    for entry in entries:
        label = entry.get('name') or 'Collection'
        kind = (entry.get('kind') or '').strip()
        layout = (entry.get('layout') or 'Poster').strip()
        is_wide = layout.lower() in ('wide', 'banner', 'landscape')
        hide_title = bool(entry.get('hide_title'))
        preview = _collection_entry_preview(entry)
        # Card/cover drives widget art; hero/backdrop is fanart only.
        bg = _wrap_tokenized_url(entry.get('background') or preview.get('fanart') or '')
        explicit_poster = _wrap_tokenized_url(entry.get('poster') or '')
        poster = explicit_poster or _wrap_tokenized_url(preview.get('poster') or preview.get('landscape') or '') or bg or root_art('catalogs').get('poster') or ''
        use_section_icon = kind in ('nuvioGroup', 'nuvioFolder') and not explicit_poster

        # Nuvio navigation nodes always have a packaged modern icon fallback,
        # so they should never disappear just because the export omitted art.
        if hide_empty and not use_section_icon and not (entry.get('background') or preview.get('poster') or preview.get('fanart') or preview.get('landscape')):
            xbmc.log('[DexHub] skipping empty collection entry: %s' % label, xbmc.LOGDEBUG)
            continue

        if bg and not first_fanart:
            first_fanart = bg

        kind_tag = {'addonCatalog': 'كتالوج', 'multiCatalog': 'مصادر', 'traktList': 'Trakt', 'mdblistList': 'MDBList', 'kodiPluginRoute': 'Kodi', 'localJsonCatalog': 'JSON', 'nuvioGroup': 'Nuvio', 'nuvioFolder': 'Folder'}.get(kind, kind or 'أخرى')
        # Nuvio/Kaptain folders are normal navigation to the user, not
        # implementation types. Keep labels clean regardless of the legacy
        # catalog-management switch.
        if kind in ('nuvioGroup', 'nuvioFolder'):
            display_label = '' if hide_title else label
        elif _clean_collection_view_enabled():
            display_label = '' if hide_title else label
        elif hide_title:
            display_label = label
        else:
            display_label = label

        if use_section_icon:
            art = section_art(label, media_type=media_filter or 'movie', fanart=bg or addon_fanart())
            tile_shape = 'square'
            if preview.get('clearlogo'):
                art['clearlogo'] = preview.get('clearlogo') or ''
        elif is_wide:
            art = {
                'icon': poster or bg or '',
                'thumb': poster or bg or '',
                'poster': poster or bg or '',
                'landscape': poster or bg or '',
                'banner': poster or bg or '',
                'fanart': bg or addon_fanart(),
                'clearlogo': preview.get('clearlogo') or '',
            }
            tile_shape = 'landscape'
        else:
            art = {
                'thumb': poster or bg or '',
                'poster': poster or bg or '',
                'fanart': bg or addon_fanart(),
                'landscape': bg or preview.get('landscape') or poster or '',
                'clearlogo': preview.get('clearlogo') or '',
            }
            tile_shape = 'poster'
        if art.get('clearlogo'):
            art['logo'] = art.get('clearlogo')
            art['tvshow.clearlogo'] = art.get('clearlogo')

        # Kodi-plugin-route collection cards use the stable v3.9.124
        # shortcut path: raw plugin:// only, exactly as saved.  Do not repair,
        # normalize, or convert TMDb Helper routes on the visible card because
        # that can make Kodi treat the shortcut as playback instead of a folder.
        path = build_url(action='collection_entry_open', set_id=set_id, entry_id=entry.get('id') or '', media_filter=media_filter)
        if kind == 'kodiPluginRoute':
            try:
                payload = entry.get('payload') or {}
                route_url = str(payload.get('route') or payload.get('url') or '').strip()
            except Exception:
                route_url = ''
            if route_url.lower().startswith('plugin://'):
                path = route_url

        # Keep the row context menu TV-friendly. Creation/import belongs to
        # Settings -> Nuvio & Collections, not repeated on every card.
        ctx_menu = [
            (tr('تغيير الاسم'), 'RunPlugin(%s)' % build_url(action='collection_entry_edit_name', set_id=set_id, entry_id=entry.get('id') or '')),
            (tr('تغيير الصورة'), 'RunPlugin(%s)' % build_url(action='collection_entry_edit_bg', set_id=set_id, entry_id=entry.get('id') or '')),
            (tr('تبديل التخطيط (Poster / Wide)'), 'RunPlugin(%s)' % build_url(action='collection_entry_toggle_layout', set_id=set_id, entry_id=entry.get('id') or '')),
            (tr('تعديل الرابط/المصدر المتقدم'), 'RunPlugin(%s)' % build_url(action='collection_entry_edit_source', set_id=set_id, entry_id=entry.get('id') or '')),
            (tr('إزالة العنصر'), 'RunPlugin(%s)' % build_url(action='collection_entry_remove', set_id=set_id, entry_id=entry.get('id') or '')),
        ]
        if row.get('builtin'):
            ctx_menu = [('إدارة Collections', 'ActivateWindow(Videos,%s,return)' % build_url(action='collection_settings_hub'))]
        elif kind in ('addonCatalog', 'multiCatalog', 'traktList', 'mdblistList', 'nuvioGroup', 'nuvioFolder'):
            ctx_menu.insert(3, (tr('تغيير مزود البوستر والميتاداتا'), 'RunPlugin(%s)' % build_url(action='collection_entry_meta_source', set_id=set_id, entry_id=entry.get('id') or '')))
        info = {
            'title': label,
            'plot': preview.get('plot') or '',
            'mediatype': 'video',
        }
        add_item(display_label, path, info=info, art=art, context_menu=ctx_menu)

    if first_fanart:
        win.setProperty('fanart', first_fanart)
    end_dir(content=_collection_content_type(entries))


