def simkl_list_browse(kind='shows', status='watching', media_filter='auto', page='0', title='', background='', force_remote=''):
    """One Simkl status shelf (watching / plantowatch / …) as a catalog (v4.1.0).

    Simkl's all-items endpoint returns the full shelf in one response, so
    paging is local via _page_slice — same UX as the Trakt list browse.
    """
    if not simkl.authorized():
        error(tr('حساب Simkl غير مرتبط'))
        return end_dir()
    force_remote = _force_remote_posters_enabled(force_remote)
    try:
        all_rows = simkl.fetch_all_items(kind, status) or []
    except Exception as exc:
        error(tr('فشل قراءة قائمة Simkl: %s') % exc)
        return end_dir()
    if media_filter in ('movie', 'movies'):
        all_rows = [r for r in all_rows if (r.get('_type') or '') == 'movie']
    elif media_filter in ('show', 'shows', 'series', 'tv', 'anime'):
        all_rows = [r for r in all_rows if (r.get('_type') or '') == 'show']
    page_num, _page_size_v, visible_rows, has_more = _page_slice(all_rows, page)
    more_url = ''
    if has_more:
        more_url = build_url(action='simkl_list_browse', kind=kind, status=status, media_filter=media_filter, page=str(page_num + 1), title=title, background=background, **_force_remote_query(force_remote))
    return _render_idlist_rows(visible_rows, more_url=more_url, title=title, background=background, media_filter=media_filter, force_remote=force_remote)


