def people_filmography_view(person_id='', name=''):
    """List a person's films and TV shows."""
    try:
        from . import people as _people
    except Exception:
        return end_dir()
    if not person_id:
        return end_dir()
    data = _people.person_filmography(person_id)
    sections = [
        (tr('كممثل'),     data.get('as_actor', [])),
        (tr('كمخرج'),     data.get('as_director', [])),
        (tr('ككاتب'),     data.get('as_writer', [])),
    ]
    any_added = False
    for section_label, items in sections:
        if not items:
            continue
        for entry in items[:80]:
            title = entry.get('title') or ''
            if not title:
                continue
            year = entry.get('year') or 0
            label = '%s (%d)' % (title, year) if year else title
            mt = 'series' if entry.get('media_type') == 'tv' else 'movie'
            poster = _people.poster_url(entry.get('poster_path') or '')
            info = {
                'title': title,
                'year': year or 0,
                'mediatype': 'tvshow' if mt == 'series' else 'movie',
                'plot': '%s — %s' % (section_label, entry.get('role') or ''),
                'rating': entry.get('vote_average') or 0,
            }
            art = {
                'poster': poster or addon_fanart(),
                'thumb':  poster or addon_fanart(),
                'fanart': addon_fanart(),
            }
            ids = {'tmdb_id': str(entry.get('id') or ''), 'imdb_id': '', 'tvdb_id': ''}
            cid = 'tmdb:%s' % entry.get('id') if entry.get('id') else ''
            click_path, is_folder = _content_click_path(media_type=mt, canonical_id=cid, title=title)
            add_item(label, click_path, is_folder=is_folder,
                     info=info, art=art, ids=ids,
                     context_menu=_build_source_picker_menu(media_type=mt, canonical_id=cid, title=title))
            any_added = True
    if not any_added:
        notify(tr('لا توجد أعمال لعرضها'))
    return end_dir(content=None, cache=False)


def calendar_view(scope='my', days='14'):
    """Show upcoming episodes (next 14 days by default)."""
    try:
        from . import calendar_view as _cal
    except Exception:
        return end_dir()
    try:
        days_int = int(days)
    except Exception:
        days_int = 14
    if scope == 'all':
        rows = _cal.public_shows_calendar(days=days_int)
    else:
        rows = _cal.my_shows_calendar(days=days_int)
    if not rows:
        if scope == 'my':
            notify(tr('لا توجد حلقات قادمة. تحقق من قائمة المتابعة في Trakt'))
        else:
            notify(tr('لا توجد حلقات في التقويم'))
        return end_dir(content=None)
    last_date = ''
    for r in rows:
        d = r.get('first_aired') or ''
        if d != last_date and d:
            # Add a date header as a separator (non-folder, non-playable)
            try:
                from datetime import datetime
                dt = datetime.strptime(d, '%Y-%m-%d').strftime('%A %d %b')
            except Exception:
                dt = d
            add_item('— %s —' % dt, build_url(action='calendar', scope=scope, days=days),
                     is_folder=False, info={'title': dt})
            last_date = d
        title = r.get('title') or ''
        season = r.get('season') or 0
        episode = r.get('episode') or 0
        ep_title = r.get('episode_title') or ''
        days_until = r.get('days_until')
        when = ''
        if days_until == 0:
            when = tr('اليوم')
        elif days_until == 1:
            when = tr('غداً')
        elif isinstance(days_until, int) and days_until > 0:
            when = tr('بعد %d أيام') % days_until
        elif isinstance(days_until, int) and days_until < 0:
            when = tr('قبل %d أيام') % abs(days_until)
        label = '%s — S%02dE%02d' % (title, season, episode)
        if ep_title:
            label = '%s — %s' % (label, ep_title)
        info = {
            'title': label,
            'tvshowtitle': title,
            'season': season,
            'episode': episode,
            'mediatype': 'episode',
            'plot': r.get('overview') or when,
            'premiered': r.get('first_aired') or '',
        }
        ids = {
            'imdb_id': r.get('imdb_id') or '',
            'tmdb_id': r.get('tmdb_id') or '',
            'tvdb_id': r.get('tvdb_id') or '',
        }
        art = {'poster': addon_fanart(), 'fanart': addon_fanart()}
        cid = r.get('canonical_id') or ''
        click_path, is_folder = _content_click_path(media_type='series', canonical_id=cid, title=title)
        add_item(label, click_path, is_folder=is_folder, info=info, art=art, ids=ids)
    return end_dir(content=None, cache=False)


