def diagnose_sources():
    """Health check for every configured Stremio provider.

    Hits each manifest URL in parallel with a 4s timeout, measures response
    time, and renders a colored, sortable list:
        ✓ green   < 1s    healthy
        ⚠ yellow  1-3s    slow but usable
        ✗ red     >3s/err timed out or HTTP error

    Lets the user spot which catalog is dragging folder-open speed without
    needing to read logs. Each row exposes a context menu to open the source
    settings or remove it outright.
    """
    rows = store.list_providers()
    if not rows:
        add_item('[COLOR yellow]%s[/COLOR]' % tr('لا توجد مصادر مضافة'),
                 build_url(action='add_provider'),
                 art=root_art('add'),
                 info={'title': tr('لا توجد مصادر مضافة'),
                       'plot': tr('أضف رابط Manifest أولاً')})
        return end_dir(content='files', cache=False)

    notify(tr('جاري فحص المصادر…'))

    def _probe(row):
        url = (row.get('manifest_url') or '').strip()
        if not url:
            return (row, None, 'no-url')
        t0 = time.time()
        try:
            from urllib.request import Request, urlopen
            req = Request(url, headers={'User-Agent': 'DexHub/health-probe'})
            with urlopen(req, timeout=4) as resp:
                code = resp.getcode()
                # Read a small chunk so we know body is reachable, not just headers.
                resp.read(2048)
            elapsed_ms = int((time.time() - t0) * 1000)
            if 200 <= code < 400:
                return (row, elapsed_ms, 'ok')
            return (row, elapsed_ms, 'http-%d' % code)
        except Exception as exc:
            elapsed_ms = int((time.time() - t0) * 1000)
            return (row, elapsed_ms, str(exc.__class__.__name__))

    results = []
    for row, result in iter_parallel(_probe, rows, workers=min(8, len(rows)),
                                       timeout=6.0):
        if isinstance(result, Exception):
            results.append((row, None, 'exception'))
        else:
            results.append(result)

    # Sort: failures first, then slowest → fastest, so user sees the
    # culprits at the top of the list.
    def _sort_key(r):
        _row, ms, status = r
        if status != 'ok':
            return (0, -1 * (ms or 99999))   # failures top, slowest first
        return (1, -1 * (ms or 0))          # successes after, slowest first

    results.sort(key=_sort_key)

    healthy = sum(1 for _r, _ms, s in results if s == 'ok')
    slow    = sum(1 for _r, ms, s in results if s == 'ok' and ms and ms >= 1000)
    failed  = len(results) - healthy

    summary = '[COLOR cyan]%s: %d %s · %d %s · %d %s[/COLOR]' % (
        tr('ملخص'), healthy, tr('سليم'), slow, tr('بطيء'), failed, tr('فشل')
    )
    add_item(summary, build_url(action='diagnose_sources'),
             art=root_art('catalogs'), is_folder=False,
             info={'title': tr('تشخيص المصادر'),
                   'plot': tr('اضغط لإعادة الفحص')})

    for row, ms, status in results:
        name = row.get('name') or row.get('id') or '?'
        url  = row.get('manifest_url') or ''
        if status == 'ok':
            if ms is None or ms < 1000:
                color = 'lime'
                icon  = '✓'
                label_status = tr('سليم')
            elif ms < 3000:
                color = 'yellow'
                icon  = '⚠'
                label_status = tr('بطيء')
            else:
                color = 'orange'
                icon  = '⚠'
                label_status = tr('بطيء جداً')
        else:
            color = 'red'
            icon  = '✗'
            label_status = tr('فشل')

        timing = ('%d ms' % ms) if ms is not None else (tr('انتهت المهلة'))
        label = '[COLOR %s]%s  %s[/COLOR]   [COLOR grey]%s · %s[/COLOR]' % (
            color, icon, name, label_status, timing
        )

        ctx = [
            (tr('إعدادات هذا المصدر'),
             'Container.Update(%s)' % build_url(action='provider_menu',
                                                  provider_id=row.get('id', ''))),
            (tr('حذف هذا المصدر'),
             'RunPlugin(%s)' % build_url(action='provider_remove',
                                          provider_id=row.get('id', ''))),
        ]
        plot = '%s\n%s\n%s: %s' % (
            url, name,
            tr('الحالة'),
            status if status != 'ok' else (tr('استجاب في %d ms') % (ms or 0))
        )
        add_item(label,
                 build_url(action='provider_menu', provider_id=row.get('id', '')),
                 art=root_art('catalogs'),
                 info={'title': name, 'plot': plot},
                 context_menu=ctx)

    return end_dir(content='files', cache=False)


# ───────────────────────────────────────────────────────────────────
# v3.9.47: Widget endpoints + Kodi library integration
# ───────────────────────────────────────────────────────────────────
# These endpoints exist primarily to be embedded in Kodi skin widgets.
# Most modern skins (Arctic Horizon, Aura, Estuary Mod, AuraMod) allow
# the user to point a home-screen widget at any plugin URL. The three
# widgets we expose here cover the most useful surfaces: Continue
# Watching, Favourites, and Recently Added. Each is a thin wrapper that
# reuses the existing listing code but ensures the directory ends with
# the right content-type metadata that skins expect for widget
# consumption.
#
# The skin then renders the content directly on the home screen without
# the user having to enter DexHub.

def widget_continue():
    """Continue Watching as a skin widget. Identical content to the
    main listing, but ends with episodes content-type so the skin
    knows to render it as a horizontal video row."""
    return continue_watching(page='0')


def widget_favorites(source=''):
    """Favourites as a skin widget."""
    return favorites(source=source, view='merged')


def widget_recent(media_type='movie'):
    """Recently-added items from the Index Engine. Returns the newest
    items the user's pinned catalogs have produced over the last
    sync cycles, ordered by added_date descending. Empty when the
    index has not yet populated."""
    try:
        from . import index_render
        metas = index_render.query_bucket_metas(
            bucket='movies' if media_type == 'movie' else 'series',
            sort='added_date',
            media_type=media_type,
            limit=20, offset=0,
        )
    except Exception:
        metas = None
    if not metas:
        return end_dir(content='files', cache=False)
    for meta in metas:
        if not isinstance(meta, dict):
            continue
        meta_id = meta.get('id') or meta.get('imdb_id')
        if not meta_id:
            continue
        title = meta.get('name') or meta.get('title') or meta_id
        path, is_folder = _content_click_path(
            media_type=media_type, canonical_id=meta_id, title=title)
        try:
            art = native_meta_art(meta, extract_ids(meta))
        except Exception:
            art = catalog_art('recent', media_type)
        add_item(title, path, is_folder=is_folder,
                 info={'title': title, 'plot': meta.get('description') or '',
                       'mediatype': 'movie' if media_type == 'movie' else 'tvshow'},
                 art=art)
    return end_dir(content='movies' if media_type == 'movie' else 'tvshows', cache=True)


# ── Kodi library export ────────────────────────────────────────────
# Foundation for synchronising DexHub content into Kodi's native
# library. The library_export action creates a virtual STRM file plus
# matching NFO metadata in a user-chosen folder. After the user adds
# that folder to Kodi as a video source and triggers a library scan,
# the item appears in Kodi's native Movies or TV Shows section with
# the proper artwork and metadata, indistinguishable from a real local
# file. Playback from the library entry routes back through DexHub's
# source picker because the STRM contains a plugin:// URL.

def _library_export_root():
    """Return the configured library export folder, falling back to
    a sensible default under the profile directory if unset."""
    try:
        configured = (ADDON.getSetting('library_export_root') or '').strip()
    except Exception:
        configured = ''
    if configured and xbmcvfs.exists(configured):
        return configured
    # Default to a folder under the addon profile so it always exists.
    root = os.path.join(_profile_path(), 'kodi_library')
    if not xbmcvfs.exists(root):
        try:
            xbmcvfs.mkdirs(root)
        except Exception:
            pass
    return root


def library_export(media_type='', canonical_id='', title='', year=''):
    """Create a STRM + NFO pair for one item so it appears in Kodi's
    native library after a library scan."""
    media_type = (media_type or 'movie').strip().lower()
    title = title or canonical_id
    if not title or not canonical_id:
        error(tr('بيانات العنصر ناقصة'))
        return
    root = _library_export_root()
    # Sanitize the title for a filesystem-friendly folder name.
    safe_title = re.sub(r'[^\w\s\-\.\(\)\u0600-\u06FF]+', '', title).strip()
    if year:
        folder_name = '%s (%s)' % (safe_title, year)
    else:
        folder_name = safe_title
    sub_root = os.path.join(root, 'Movies' if media_type == 'movie' else 'TV Shows')
    if not xbmcvfs.exists(sub_root):
        try:
            xbmcvfs.mkdirs(sub_root)
        except Exception:
            pass
    item_folder = os.path.join(sub_root, folder_name)
    if not xbmcvfs.exists(item_folder):
        try:
            xbmcvfs.mkdirs(item_folder)
        except Exception as exc:
            error(tr('فشل إنشاء المجلد: %s') % exc)
            return
    # Build the playback URL that goes inside the STRM file. This is
    # a normal plugin:// URL that routes back through DexHub's source
    # picker, so library playback uses the same provider chain as
    # in-app playback.
    play_url = build_url(action='play_item',
                         media_type=media_type,
                         canonical_id=canonical_id,
                         title=title)
    strm_path = os.path.join(item_folder, folder_name + '.strm')
    nfo_path  = os.path.join(item_folder, folder_name + '.nfo')
    try:
        with xbmcvfs.File(strm_path, 'w') as fh:
            fh.write(play_url)
        # Minimal NFO — Kodi's scraper will enrich from TMDb when the
        # user runs a library scan, so we just need to seed the title
        # and unique id.
        nfo_xml = '<?xml version="1.0" encoding="UTF-8"?>\n'
        if media_type == 'movie':
            nfo_xml += '<movie>\n  <title>%s</title>\n' % _xml_escape(title)
            if year:
                nfo_xml += '  <year>%s</year>\n' % _xml_escape(str(year))
            if canonical_id.startswith('tt'):
                nfo_xml += '  <uniqueid type="imdb" default="true">%s</uniqueid>\n' % _xml_escape(canonical_id)
            elif canonical_id.startswith('tmdb:'):
                nfo_xml += '  <uniqueid type="tmdb" default="true">%s</uniqueid>\n' % _xml_escape(canonical_id.split(':', 1)[1])
            nfo_xml += '</movie>\n'
        else:
            nfo_xml += '<tvshow>\n  <title>%s</title>\n' % _xml_escape(title)
            if year:
                nfo_xml += '  <year>%s</year>\n' % _xml_escape(str(year))
            if canonical_id.startswith('tt'):
                nfo_xml += '  <uniqueid type="imdb" default="true">%s</uniqueid>\n' % _xml_escape(canonical_id)
            elif canonical_id.startswith('tmdb:'):
                nfo_xml += '  <uniqueid type="tmdb" default="true">%s</uniqueid>\n' % _xml_escape(canonical_id.split(':', 1)[1])
            nfo_xml += '</tvshow>\n'
        with xbmcvfs.File(nfo_path, 'w') as fh:
            fh.write(nfo_xml)
        # v3.9.237: a SERIES needs per-episode strm files. Kodi's library
        # scanner cannot turn one show-level .strm into episodes, so a series
        # export used to produce an entry that never scanned properly — which
        # broke the whole "appears like local files on the phone" flow for TV.
        _episodes_written = 0
        if media_type != 'movie':
            _episodes_written = _library_export_episodes(
                item_folder, canonical_id, title)
        if media_type != 'movie' and not _episodes_written:
            notify(tr('تم التصدير (بدون حلقات — لم يُعثر على قائمة الحلقات)'))
        else:
            notify(tr('تم التصدير: %s') % folder_name)
        # Ask Kodi to pick the new files up. Scans are incremental and cheap;
        # without this the item does not appear until the user remembers to
        # run a scan manually.
        try:
            xbmc.executebuiltin('UpdateLibrary(video)')
        except Exception:
            pass
    except Exception as exc:
        error(tr('فشل التصدير: %s') % exc)


def _library_export_episodes(show_folder, canonical_id, show_title):
    """Write Season NN/Show SxxEyy.strm files for every known episode.

    The episode list comes from the first provider whose meta carries a
    Stremio 'videos' array (Cinemeta does for practically everything). Each
    strm routes back through play_item with season/episode, so library
    playback uses the exact same source chain as in-app playback.
    """
    meta = {}
    try:
        from .dexhub.client import fetch_meta
        for _prov in (store.list_providers() or []):
            try:
                _m = fetch_meta(_prov, 'series', canonical_id,
                                timeout_override=fast_timeout('meta')) or {}
                _m = _m.get('meta') or _m
                if _m.get('videos'):
                    meta = _m
                    break
            except Exception:
                continue
    except Exception:
        return 0
    videos = meta.get('videos') or []
    written = 0
    for vid in videos:
        try:
            season = int(vid.get('season') or 0)
            episode = int(vid.get('episode') or vid.get('number') or 0)
        except Exception:
            continue
        if episode <= 0 or season < 0:
            continue
        if season == 0:
            continue    # skip specials: they confuse the scraper's ordering
        season_dir = os.path.join(show_folder, 'Season %02d' % season)
        if not xbmcvfs.exists(season_dir):
            try:
                xbmcvfs.mkdirs(season_dir)
            except Exception:
                continue
        ep_url = build_url(action='play_item', media_type='series',
                           canonical_id=canonical_id, title=show_title,
                           season=str(season), episode=str(episode))
        ep_name = '%s S%02dE%02d.strm' % (
            re.sub(r'[^\w\s\-\.\(\)\u0600-\u06FF]+', '', show_title).strip() or 'Episode',
            season, episode)
        try:
            with xbmcvfs.File(os.path.join(season_dir, ep_name), 'w') as fh:
                fh.write(ep_url)
            written += 1
        except Exception:
            continue
    return written


def _xml_escape(text):
    """Minimal XML escaping for NFO writes."""
    return str(text).replace('&', '&amp;').replace('<', '&lt;').replace('>', '&gt;')


def library_setup_help():
    """Show the user how to configure Kodi to use the export folder."""
    root = _library_export_root()
    msg = (
        tr('مجلد مكتبة DexHub:\n%s\n\n'
        'لإضافته كمصدر فيديو في Kodi:\n'
        '1. اذهب إلى الإعدادات → الوسائط → المكتبة\n'
        '2. اختر "إضافة مصدر فيديو"\n'
        '3. وجّه إلى المجلد أعلاه\n'
        '4. اختر نوع المحتوى (أفلام أو مسلسلات)\n'
        '5. حدّد TMDb كمصدر للميتاداتا\n'
        '6. شغّل "تحديث المكتبة"\n\n'
        'بعد ذلك، أي عنصر تُصدّره من DexHub سيظهر في مكتبة Kodi مع البوسترات والوصف، '
        'ويتم تشغيله عبر مُختار المصادر الخاص بـ DexHub تلقائياً.')
    ) % root
    xbmcgui.Dialog().textviewer(tr('Dex Hub — إعداد المكتبة'), msg)


def _reset_invocation_state():
    """Clear state that must NOT survive from a previous plugin invocation.

    v3.9.235: addon.xml sets reuselanguageinvoker=true, so the Python VM (and
    every module-level global) stays alive between invocations. `_PENDING_ITEMS`
    is the buffer that add_item() appends to and that _flush_pending_items()
    drains on end_dir(). If an action raises BETWEEN those two points — an
    upstream error, a user backing out mid-render — the buffer is never drained
    and the leftovers stay resident. The NEXT screen then flushes them together
    with its own rows: ghost entries and stale art from the previous directory.

    run() already swallows the exception so Kodi shows a dialog rather than
    dying, which means the leak is silent and reproducible. Clearing at the
    START of every dispatch is the only place guaranteed to run.
    """
    global _PENDING_ITEMS
    from .runtime_binding import bind
    bind(sys.modules[__name__])
    if _PENDING_ITEMS:
        try:
            xbmc.log('[DexHub] dropping %d stale buffered item(s) from a previous '
                     'invocation (reuselanguageinvoker warm VM)' % len(_PENDING_ITEMS),
                     xbmc.LOGWARNING)
        except Exception:
            pass
    _PENDING_ITEMS = []
    # v4.6.4: `from .context import *` COPIES HANDLE into this module's
    # namespace at import time, and the warm VM keeps that copy across
    # invocations — a RunPlugin invocation (handle -1) then poisoned every
    # later folder render in the same VM (empty ".." directory, dead
    # endOfDirectory). Refresh the source of truth AND this module's copy
    # at the start of every dispatch.
    global HANDLE
    try:
        from . import context as _ctx_mod
        HANDLE = _ctx_mod.refresh_invocation()
    except Exception:
        try:
            HANDLE = int(sys.argv[1])
        except Exception:
            HANDLE = -1
    # v4.6.9: ui_core captures its OWN module-level HANDLE at import time
    # and end_dir()/setContent() run on it — the third frozen copy of the
    # same warm-VM bug 4.6.4 fixed in context/plugin. Rebind it too.
    try:
        from . import ui_core as _ui_mod
        _ui_mod.HANDLE = HANDLE
    except Exception:
        pass


_REAL_PLAY_ACTIONS = frozenset(('play', 'streams', 'episode_streams', 'cw_resume', 'cw_play_from_start',
                                'play_item', 'tmdb_player', 'plex_play', 'emby_play', 'jellyfin_play', 'silo_play'))


def run():
    # v3.9.53: defensive wrapper around the entire dispatcher. If ANY
    # action fails with an uncaught exception, the traceback is logged
    # before re-raising. Previously a silent error in a handler could
    # make a home button appear to "do nothing", with no diagnostic
    # trace in kodi.log. Now every failure leaves a full traceback that
    # identifies the failing function and line.
    #
    # v3.9.71: also surface the traceback in a textviewer dialog so the
    # user can read and screenshot it on TV/mobile without diving into
    # kodi.log. Crash before playback is the canonical case where this
    # is critical — silent failures here just look like "nothing
    # happens" to the user.
    _reset_invocation_state()
    try:
        return _dispatch()
    except Exception as _exc:
        try:
            import traceback as _tb
            _trace = _tb.format_exc()
            xbmc.log('[DexHub] DISPATCHER ERROR: %s\n%s' % (_exc, _trace),
                     xbmc.LOGERROR)
        except Exception:
            _trace = str(_exc)
        try:
            _action_for_dialog = ''
            try:
                _action_for_dialog = dict(parse_qsl(sys.argv[2].lstrip('?'))).get('action', '')
            except Exception:
                pass
            xbmcgui.Dialog().textviewer(
                tr('Dex Hub — حدث خطأ غير متوقع'),
                ('Action: %s\nArgv: %s\n\nError:\n%s\n\n%s') % (
                    _action_for_dialog or '?',
                    sys.argv[2] if len(sys.argv) > 2 else '?',
                    str(_exc),
                    _trace,
                ),
            )
        except Exception:
            pass
        # Don't re-raise — the user has seen the diagnostic dialog
        # already, and re-raising adds Kodi's own less-useful crash
        # notification on top. Returning None keeps the addon alive so
        # the next click works.
        return


def _streams_item_key(canonical_id, season, episode):
    def _n(v):
        t = str(v).strip() if v is not None else ''
        return str(int(t)) if t.isdigit() else t
    return '%s|%s|%s' % (_n(canonical_id), _n(season), _n(episode))


def _entry_second_line(e):
    """Small provider-first line: addon site size quality."""
    parts = []
    prov = str(e.get('provider_name_raw') or e.get('addon') or '').strip()
    if prov:
        parts.append(prov)
    site = str(e.get('source_site') or '').strip()
    if site and site.lower() != prov.lower():
        parts.append(site)
    size = str(e.get('size_label') or '').strip()
    if size and size != '--':
        parts.append(size)
    q = str(e.get('quality') or '').strip()
    if q:
        parts.append(q)
    return ' \u00b7 '.join(parts)


def _publish_last_streams_index(canonical_id, season, episode, entries, poster=''):
    """Keep a one-slot index of the LAST rendered source list (v3.9.151).

    Written after every row append so live-filling providers are captured;
    last-writer-wins on a single Window(10000) property, so memory stays
    bounded to one item.  switch_source() reads this to offer an instant
    overlay of the previous search instead of re-scraping.
    """
    rows = []
    for e in entries:
        k = e.get('stream_key')
        if not k:
            continue
        rows.append({'k': k,
                     'l': e.get('name') or e.get('stream_title') or '?',
                     'l2': _entry_second_line(e),
                     # v5.10.294: what the sources window shows on the row, so
                     # the player's Sources panel reads the same
                     'id': str(e.get('source_identity_line') or e.get('origin_line')
                               or e.get('provider') or ''),
                     # v5.10.296: the add-on name the sources window shows
                     'p': str(e.get('provider') or e.get('provider_name_raw') or ''),
                     's': str(e.get('size_label') or ''),
                     # v5.10.297: Nuvio-style row and sort keys
                     'n': str(e.get('stream_name_raw') or ''),
                     'd': str(e.get('stream_desc_raw') or ''),
                     'q': str(e.get('quality') or ''),
                     'c': e.get('cached') if e.get('cached') in (True, False) else None,
                     'lib': bool(e.get('in_library'))})
    payload = {
        'item': _streams_item_key(canonical_id, season, episode),
        'poster': poster or '',
        'rows': rows,
        'ts': int(time.time()),
    }
    data = json.dumps(payload)
    xbmcgui.Window(WINDOW_ID).setProperty('dexhub.last_streams', data)
    # Window properties can disappear when Kodi replaces the player or starts a
    # fresh plugin invocation. Keep the exact same list in the lightweight
    # SQLite cache so source switching never needs to scrape providers again.
    try:
        cache_store.update('source_index', payload['item'], payload)
    except Exception:
        pass


_SOURCE_SWITCH_HANDOFF_PROP = 'dexhub.source_switch_handoff.v2'


def _source_switch_handoff_write(payload):
    try:
        xbmcgui.Window(10000).setProperty(
            _SOURCE_SWITCH_HANDOFF_PROP,
            json.dumps(dict(payload or {}), separators=(',', ':')),
        )
        return True
    except Exception:
        return False


def _source_switch_handoff_read():
    try:
        raw = xbmcgui.Window(10000).getProperty(_SOURCE_SWITCH_HANDOFF_PROP) or ''
        data = json.loads(raw) if raw else {}
        if not isinstance(data, dict):
            return {}
        expires = float(data.get('expires_at') or 0.0)
        if expires and time.time() > expires:
            xbmcgui.Window(10000).clearProperty(_SOURCE_SWITCH_HANDOFF_PROP)
            return {}
        return data
    except Exception:
        return {}


def _source_switch_begin_handoff(ctx, position, duration, resume_percent):
    try:
        import uuid
        token = uuid.uuid4().hex
    except Exception:
        token = '%d' % int(time.time() * 1000)
    payload = {
        'token': token,
        'old_uid': str((ctx or {}).get('playback_uid') or ''),
        'position': float(position or 0.0),
        'duration': float(duration or 0.0),
        'resume_percent': float(resume_percent or 0.0),
        'created_at': time.time(),
        'expires_at': time.time() + 8.0,
        'ack': False,
    }
    _source_switch_handoff_write(payload)
    return token


def _source_switch_wait_for_ack(token, player, timeout_ms=3200):
    """Wait until Companion acknowledges the OLD stop callback.

    This replaces fixed sleeps. Kodi 22 and adaptive streams can dispatch Stop
    anywhere from a few milliseconds to multiple seconds after Player.stop().
    Starting the replacement before that callback completes lets the old event
    clear or report against the new session and can crash some builds.
    """
    deadline = time.time() + max(0.5, float(timeout_ms or 0) / 1000.0)
    inactive_since = 0.0
    while time.time() < deadline:
        data = _source_switch_handoff_read()
        if data.get('token') == token and data.get('ack'):
            return True
        try:
            active = bool(player.isPlaying())
        except Exception:
            active = False
        if not active:
            if not inactive_since:
                inactive_since = time.time()
            # Service may be disabled. A quiet inactive period is the safe
            # fallback, but acknowledgement remains preferred.
            if time.time() - inactive_since >= 0.75:
                return False
        else:
            inactive_since = 0.0
        xbmc.sleep(100)
    return False

def _stop_player_for_source_switch(player):
    """Use the known-good stop handoff before starting the replacement."""
    try:
        if player.isPlaying():
            player.stop()
            # Keep this short fixed handoff.  Polling here holds Kodi's plugin
            # action while the player lifecycle is still dispatching and can
            # prevent a replacement stream from starting on some builds.
            xbmc.sleep(250)
    except Exception:
        pass


def _jsonrpc_call(method, params=None):
    from .kodi_rpc import call
    return call(method, params)


def _launch_replacement_source(stream_key, resume_seconds='', resume_percent='', fallback_keys=None, subtitle_path='', subtitle_enabled=None, subtitle_name=''):
    """Start the replacement in a fresh plugin invocation after handoff."""
    _mark_in_place_switch()
    params = {'action': 'play', 'stream_key': str(stream_key or '')}
    if resume_seconds not in (None, '', 0, '0'):
        params['resume_seconds'] = str(resume_seconds)
    if resume_percent not in (None, '', 0, '0'):
        params['resume_percent'] = str(resume_percent)
    if subtitle_path:
        params['switch_subtitle_path'] = str(subtitle_path)
        params['switch_subtitle_enabled'] = '1' if subtitle_enabled is not False else '0'
        if subtitle_name:
            params['switch_subtitle_name'] = str(subtitle_name)
    # ``fallback_keys`` is accepted only so stale cached URLs still dispatch;
    # it is never forwarded to the new playback session.
    xbmc.executebuiltin('RunPlugin(plugin://plugin.video.dexhub/?%s)' % urlencode(params))
    return True


def _mark_in_place_switch():
    """v5.10.248: the next play is a source switch: it starts where the
    old source was, even under 30 seconds (playback_engine reads this)."""
    try:
        xbmcgui.Window(WINDOW_ID).setProperty('dexhub.switch.inplace', str(int(time.time())))
    except Exception:
        pass


def switch_source(pick='', rescan=''):
    """Switch the source while a video is playing (v3.9.152).

    Preferred path: show the LAST search's cached rows in the skin's own
    DialogSelect (useDetails: poster + provider/size line) floating OVER the
    still-playing video — cancel touches nothing; picking stops and replays
    the chosen cached stream from the same position via
    play(stream_key, resume_seconds).  Resilient to the replace-race: when
    the session was wiped but a video is playing and a cached index exists,
    the index itself is authoritative (it IS the last search).
    Fallback (no cached index): stop + fresh picker with resume carried.
    Trigger: RunPlugin(plugin://plugin.video.dexhub/?action=switch_source)
    """
    if pick == 'none':
        return      # a status row of the player's Sources panel
    try:
        from .playback.session import load_session
        ctx = load_session() or {}
    except Exception:
        ctx = {}
    if not isinstance(ctx, dict):
        ctx = {}
    has_ids = bool(ctx.get('canonical_id') or ctx.get('video_id'))

    player = xbmc.Player()
    playing = False
    pos = 0.0
    duration = 0.0
    resume_percent = 0.0
    try:
        playing = bool(player.isPlaying())
        if playing:
            pos = float(player.getTime() or 0.0)
            try:
                duration = float(player.getTotalTime() or 0.0)
            except Exception:
                duration = 0.0
    except Exception:
        playing, pos, duration = False, 0.0, 0.0
    if duration > 1.0 and pos > 1.0:
        resume_percent = max(0.0, min(100.0, (pos / duration) * 100.0))
    resume = ('%.3f' % pos) if pos > 1.0 else ''
    resume_pct = ('%.2f' % resume_percent) if 1.0 < resume_percent < 95.0 else ''

    subtitle_snapshot = _capture_external_subtitle_for_switch(player) if playing else {}

    # Persist the exact switch point BEFORE stopping the old player. Kodi may
    # dispatch onPlayBackStopped late (or after the replacement session is
    # already written), so relying on that callback can wipe/overwrite the new
    # source context. Keeping seconds + percent lets the replacement use exact
    # time for equal cuts and fall back to relative progress for different cuts.
    if playing and pos > 1.0:
        try:
            from .playback.session import save_session
            snap = dict(ctx or {})
            snap['resume_seconds'] = float(pos)
            if duration > 1.0:
                snap['duration'] = float(duration)
                snap['resume_percent'] = float(resume_percent)
            snap['source_switch_pending'] = True
            snap['source_switch_captured_at'] = int(time.time())
            if subtitle_snapshot:
                snap.update(subtitle_snapshot)
            save_session(snap)
            ctx = snap
            _monitor_playback('source-switch-captured',
                              title=ctx.get('title') or '',
                              canonical_id=ctx.get('canonical_id') or '',
                              position_seconds='%.1f' % pos,
                              duration_seconds='%.1f' % duration,
                              resume_percent='%.2f' % resume_percent)
        except Exception as exc:
            try:
                xbmc.log('[DexHub] source-switch snapshot failed: %s' % exc, xbmc.LOGWARNING)
            except Exception:
                pass

    rows, poster = [], ''
    try:
        raw = xbmcgui.Window(WINDOW_ID).getProperty('dexhub.last_streams')
        data = json.loads(raw) if raw else {}
        idx_rows = [r for r in (data.get('rows') or []) if r.get('k')]
        if idx_rows:
            if has_ids:
                want = _streams_item_key(ctx.get('canonical_id'), ctx.get('season'), ctx.get('episode'))
                if data.get('item') == want:
                    rows = idx_rows
            elif playing:
                # Session lost (e.g. replace-race) but a video IS playing:
                # the last rendered picker is authoritative for it.
                rows = idx_rows
            poster = data.get('poster') or ''
    except Exception:
        rows, poster = [], ''
    # Kodi may clear Window(10000) properties during a player replacement. The
    # disk-backed index is authoritative for the same item and avoids a full
    # Plex/Emby/Stremio search on every source switch.
    if not rows and has_ids:
        try:
            want = _streams_item_key(ctx.get('canonical_id'), ctx.get('season'), ctx.get('episode'))
            cached_index = cache_store.get('source_index', want) or {}
            if cached_index.get('item') == want:
                rows = [r for r in (cached_index.get('rows') or []) if r.get('k')]
                poster = cached_index.get('poster') or poster
        except Exception:
            pass
    if not poster:
        poster = ctx.get('poster') or ''

    if rescan and playing:
        # v5.10.252: "Search again" searches in the panel itself: the panel
        # stays open over the playing video and says it is searching, then
        # lists what was found (or says nothing was); no source window
        from .skinui import osd_sources
        if osd_sources.searching():
            return
        _monitor_playback('source-switch-rescan', title=ctx.get('title') or '', playback_uid=ctx.get('playback_uid') or '')
        osd_sources.set_state('searching')
        found = []
        last = {'v': ''}

        def _progress(done, total, count):
            # the panel's counter and its rows, as each provider answers
            value = 'searching:%d/%d' % (done, total)
            if value != last['v']:
                last['v'] = value
                osd_sources.set_state(value)
        try:
            from . import player_runtime as _pr
            found = _pr.osd_rescan(ctx, on_progress=_progress) or []
        except Exception as exc:
            xbmc.log('[DexHub] panel search failed: %s' % exc, xbmc.LOGWARNING)
        osd_sources.set_state('done:%d' % len(found))
        return
    if str(pick).isdigit():
        # v5.10.243: a row of the player's Sources panel (skinui/osd_sources,
        # same list and order): no dialog, it plays from the same point
        from .skinui import osd_sources
        listed, has_current = osd_sources.rows()
        index = int(pick)
        if index >= len(listed):
            return
        if has_current and index == 0:
            notify(tr('هذا المصدر يشتغل حالياً'))
            return
        xbmc.executebuiltin('Dialog.Close(1149,true)')
        xbmc.executebuiltin('Dialog.Close(videoosd,true)')
        key = listed[index].get('k')
        # v5.10.246: the player is not stopped: the new source replaces the
        # playing one in place, so Kodi stays in the full-screen player (a
        # replaced item sends no Stop, only the new item's Play, so there is
        # no old stop for the companion to tell apart)
        _mark_in_place_switch()
        _monitor_playback('source-switch-in-place', title=ctx.get('title') or '', playback_uid=ctx.get('playback_uid') or '')
        return _launch_replacement_source(key, resume_seconds=resume, resume_percent=resume_pct, fallback_keys=[], subtitle_path=subtitle_snapshot.get('switch_subtitle_path', ''), subtitle_enabled=subtitle_snapshot.get('switch_subtitle_enabled'), subtitle_name=subtitle_snapshot.get('switch_subtitle_name', ''))

    if rows:
        from .playback.switch_rows import rows_with_current_first
        rows, has_current = rows_with_current_first(rows, str(ctx.get('stream_key') or ''))
        try:
            items = []
            for r in rows:
                li = xbmcgui.ListItem(r.get('l') or '?')
                try:
                    li.setLabel2(r.get('l2') or '')
                    if poster:
                        li.setArt({'icon': poster, 'thumb': poster, 'poster': poster})
                except Exception:
                    pass
                items.append(li)
            choice = xbmcgui.Dialog().select(tr('تبديل السورس'), items, useDetails=True)
        except Exception:
            choice = xbmcgui.Dialog().select(tr('تبديل السورس'), [r.get('l') or '?' for r in rows])
        if choice < 0:
            return  # cancelled: playback untouched
        if has_current and choice == 0:
            # v5.4.8: the top row IS the live source. Stopping and replaying
            # it would interrupt playback for nothing — same contract as
            # cancel, with a hint so the press doesn't feel ignored.
            notify(tr('هذا المصدر يشتغل حالياً'))
            return
        key = rows[choice].get('k')
        handoff_token = _source_switch_begin_handoff(ctx, pos, duration, resume_percent)
        _stop_player_for_source_switch(player)
        acked = _source_switch_wait_for_ack(handoff_token, player)
        _monitor_playback('source-switch-handoff-ready', title=ctx.get('title') or '', playback_uid=ctx.get('playback_uid') or '', acknowledged=bool(acked))
        return _launch_replacement_source(key, resume_seconds=resume, resume_percent=resume_pct, fallback_keys=[], subtitle_path=subtitle_snapshot.get('switch_subtitle_path', ''), subtitle_enabled=subtitle_snapshot.get('switch_subtitle_enabled'), subtitle_name=subtitle_snapshot.get('switch_subtitle_name', ''))

    if not has_ids:
        notify('Nothing to switch - play something first')
        return

    # No cached index for this item — fall back to a fresh picker.
    url = _source_picker_url_from_ctx(ctx, resume_seconds=resume, resume_percent=resume_pct)
    if not url:
        notify('Source picker unavailable for this item')
        return
    handoff_token = _source_switch_begin_handoff(ctx, pos, duration, resume_percent)
    _stop_player_for_source_switch(player)
    _source_switch_wait_for_ack(handoff_token, player)
    xbmc.executebuiltin('ActivateWindow(Videos,"%s",return)' % url)


def shortcut_configure():
    """Create/update the user's fullscreen-video source-switch keymap."""
    try:
        from . import shortcut_manager
        return shortcut_manager.configure()
    except Exception as exc:
        xbmc.log('[DexHub] shortcut configure failed: %s' % exc, xbmc.LOGERROR)
        notify(tr('تعذر حفظ اختصار تبديل المصدر'))
        return False


def shortcut_status():
    try:
        from . import shortcut_manager
        return shortcut_manager.show_status()
    except Exception as exc:
        xbmc.log('[DexHub] shortcut status failed: %s' % exc, xbmc.LOGWARNING)


def shortcut_remove():
    try:
        from . import shortcut_manager
        if shortcut_manager.remove_binding():
            notify(tr('تمت إزالة اختصار تبديل المصدر'))
            return True
    except Exception as exc:
        xbmc.log('[DexHub] shortcut removal failed: %s' % exc, xbmc.LOGWARNING)
    notify(tr('تعذر إزالة اختصار تبديل المصدر'))
    return False


def shortcut_settings_dialog():
    """One entry replaces three repetitive native-settings rows."""
    _close_native_settings_dialog()
    while True:
        choice = xbmcgui.Dialog().select(
            tr('اختصار تبديل المصدر'),
            [tr('إعداد أو تغيير الاختصار'), tr('عرض الاختصار الحالي'),
             tr('إزالة الاختصار'), tr('رجوع')])
        if choice < 0 or choice == 3:
            return True
        if choice == 0:
            shortcut_configure()
        elif choice == 1:
            shortcut_status()
        elif choice == 2:
            shortcut_remove()


def _dispatch(params=None):
    # v5.10.96: explicit params let the Home window capture any route from a
    # worker thread without rewriting the process-wide sys.argv.
    if params is None:
        params = dict(parse_qsl(sys.argv[2].lstrip('?')))
    else:
        params = dict(params)
    action = params.get('action')
    if action in _REAL_PLAY_ACTIONS:
        # v5.10.156 (issue #5): a trailer turned refresh switching off; real
        # playback gets the user's setting back before it starts
        from . import refresh_guard
        refresh_guard.restore()
    # v3.9.53: log the incoming dispatch to make routing issues
    # transparent. The line appears in kodi.log on every click.
    try:
        xbmc.log('[DexHub] dispatch action=%r argv=%r' % (
            action, sys.argv[2] if len(sys.argv) > 2 else ''), xbmc.LOGINFO)
    except Exception:
        pass
    if not action:
        # Native Kodi directory only. It follows the active skin, avoids a
        # stacked WindowXML lifecycle, and remains a dependable BACK target.
        return home()
    if action == 'tmdb_player':
        # Helper no longer loads/scans the unrelated account/catalog dispatcher.
        # The supplied runtime remains explicit until source adapters are split.
        from .helper_entry import dispatch as _helper_dispatch
        return _helper_dispatch(params, sys.modules[__name__])
    # v3.9.273: common routes use a compact O(1) dispatcher. The legacy
    # chain remains below as a safe compatibility fallback while modules
    # continue moving out of this file.
    _fast = _fast_dispatch_mod.dispatch(action, params, sys.modules[__name__])
    if _fast is not _fast_dispatch_mod._NOT_HANDLED:
        return _fast
    if action == 'add_provider':
        return add_provider(manifest_url=params.get('manifest_url', ''))
    if action == 'first_run_wizard':
        return first_run_wizard()
    if action == 'dexworld_info':
        return dexworld_info()
    if action == 'providers':
        return providers()
    # v3.9.39: numeric-position reorder. The user invokes "📝 ترتيب
    # الموقع بالرقم" from the context menu of any provider, types the
    # desired position (1 through total), and the provider jumps to
    # that exact slot. Faster than nudging up and down repeatedly,
    # keeps the Sources page uncluttered.
    if action == 'provider_set_position':
        provider_id = params.get('provider_id', '')
        rows = store.list_providers() or []
        total = len(rows)
        if total < 2:
            notify(tr('تحتاج مصدرين على الأقل للترتيب'))
            return
        current_idx = None
        for i, r in enumerate(rows):
            if r.get('id') == provider_id:
                current_idx = i
                break
        if current_idx is None:
            notify(tr('لم يُعثر على المصدر'))
            return
        provider_name = rows[current_idx].get('name') or provider_id
        raw = xbmcgui.Dialog().numeric(
            0,
            tr('ضع %s في الموقع رقم (1 إلى %d)  •  الموقع الحالي: %d')
                % (provider_name, total, current_idx + 1),
            str(current_idx + 1))
        if not raw:
            return
        try:
            new_pos_1based = int(str(raw).strip())
        except Exception:
            notify(tr('قيمة غير صالحة'))
            return
        new_pos_1based = max(1, min(new_pos_1based, total))
        new_idx = new_pos_1based - 1
        if new_idx == current_idx:
            notify(tr('%s موجود أصلاً في الموقع %d') % (provider_name, new_pos_1based))
            return
        store.move_provider_to(provider_id, new_idx)
        notify(tr('%s ⟵ الموقع %d') % (provider_name, new_pos_1based))
        xbmc.executebuiltin('Container.Refresh')
        return
    if action == 'diagnose_sources':
        return diagnose_sources()
    # ─── v3.9.27: index actions ─────────────────────────────────────
    if action == 'index_status':
        return index_status()
    if action == 'index_refresh_all':
        return index_refresh_all()
    if action == 'index_refresh_bucket':
        return index_refresh_bucket(params.get('bucket', ''))
    if action == 'index_clear':
        return index_clear()
    # ────────────────────────────────────────────────────────────────
