# Native Nuvio / Stremio account sync (replaces the old web Hub).
# ─────────────────────────────────────────────────────────────────────────
def _cloud_qr_login(service):
    if service == 'nuvio':
        return _accounts_route_mod.connect_nuvio(ADDON, tr)
    return _accounts_route_mod.qr_login(service)

def _cloud_login(service):
    if service == 'nuvio':
        return _accounts_route_mod.connect_nuvio(ADDON, tr)
    return _accounts_route_mod.login(service, ADDON, tr)

def _cloud_logout(service):
    return _accounts_route_mod.logout(service, tr)


def cloud_sync_now():
    return _accounts_route_mod.sync_now(ADDON, tr)
